    fn validate_npsp_allocation_percent_bounds(
        self: *Evaluator,
        allocation: *types.SObject,
    ) !void {
        if (!self.fixture_relaxed_exceptions) return;
        if (!std.ascii.eqlIgnoreCase(allocation.type_name, "Allocation__c")) return;
