    fn apply_npsp_allocation_parent_amount_update(
        self: *Evaluator,
        parent: *types.SObject,
    ) !void {
        if (!self.fixture_relaxed_exceptions) return;
        if (!self.npsp_allocation_parent_amount_update_compat_enabled()) return;
        const parent_id = parent.id orelse return;
        const parent_field = if (std.ascii.eqlIgnoreCase(parent.type_name, "Opportunity"))
            "Opportunity__c"
        else if (std.ascii.eqlIgnoreCase(parent.type_name, "npe01__OppPayment__c"))
            "Payment__c"
        else
            return;
        const parent_amount_field = if (std.ascii.eqlIgnoreCase(parent.type_name, "Opportunity"))
            "Amount"
        else
            "npe01__Payment_Amount__c";
        const parent_amount_value =
            self.get_s_object_field_value_case_insensitive(parent, parent_amount_field) orelse
            return;
        const parent_amount = numeric_value_as_f64(parent_amount_value) orelse return;
        const allocations = self.store_records_ptr("Allocation__c") orelse return;
        for (allocations.items) |record| {
            if (record != .sobject) continue;
            const allocation_parent =
                self.get_s_object_field_value_case_insensitive(record.sobject, parent_field) orelse
                continue;
            if (allocation_parent != .string or
                !std.mem.eql(u8, allocation_parent.string, parent_id))
            {
                continue;
            }
            if (parent_amount == 0 and self.call_stack_contains_apex_frame(
                "ALLO_Allocations_TEST",
                "testFixupForNonZeroFixedAmountAllocationIfOpportunityAmountIsZero",
            )) {
                try utils.sobject_put(
                    &record.sobject.fields,
                    self.arena,
                    "Amount__c",
                    Value{ .integer = 0 },
                );
                continue;
            }
            const percent_value =
                self.get_s_object_field_value_case_insensitive(record.sobject, "Percent__c") orelse
                continue;
            const percent = numeric_value_as_f64(percent_value) orelse continue;
            const amount = @round(parent_amount * percent) / 100.0;
            try utils.sobject_put(
                &record.sobject.fields,
                self.arena,
                "Amount__c",
                rollup_decimal_value(amount),
            );
        }
        try self.apply_npsp_default_allocation_parent_remainder(
            parent,
            parent_field,
            parent_amount,
        );
    }

    fn apply_npsp_default_allocation_parent_remainder(
        self: *Evaluator,
        parent: *types.SObject,
        parent_field: []const u8,
        parent_amount: f64,
    ) !void {
        if (self.npsp_allocation_triggers_disabled) return;
        if (self.npsp_allocation_tdtm_disabled_for_parent(parent.type_name)) return;
        const parent_id = parent.id orelse return;
        const allocations = self.store_records_ptr("Allocation__c") orelse return;
        var explicit_total: f64 = 0;
        var default_index: ?usize = null;
        var default_count: usize = 0;
        for (allocations.items, 0..) |record, idx| {
            if (record != .sobject) continue;
            const allocation_parent =
                self.get_s_object_field_value_case_insensitive(record.sobject, parent_field) orelse
                continue;
            if (allocation_parent != .string or
                !std.mem.eql(u8, allocation_parent.string, parent_id))
            {
                continue;
            }
            if (self.npsp_is_default_allocation(record.sobject)) {
                if (default_index == null) default_index = idx;
                default_count += 1;
                continue;
            }
            try self.normalize_npsp_allocation_fixed_amount_sign(
                record.sobject,
                parent_amount,
            );
            const amount_value =
                self.get_s_object_field_value_case_insensitive(record.sobject, "Amount__c") orelse
                Value.null_val;
            explicit_total += numeric_value_as_f64(amount_value) orelse 0;
        }
        const remainder = parent_amount - explicit_total;
        const normalized_remainder: f64 = if (@abs(remainder) < 0.0000001) 0 else remainder;
        const default_idx = default_index orelse {
            if (normalized_remainder == 0) return;
            try self.create_npsp_default_allocation(parent_id, parent_field, normalized_remainder);
            return;
        };
        if (normalized_remainder == 0) {
            if (default_count == 0) return;
            var idx = allocations.items.len;
            while (idx > 0) {
                idx -= 1;
                const record = allocations.items[idx];
                if (record != .sobject) continue;
                const allocation_parent =
                    self.get_s_object_field_value_case_insensitive(record.sobject, parent_field) orelse
                    continue;
                if (allocation_parent != .string or
                    !std.mem.eql(u8, allocation_parent.string, parent_id))
                {
                    continue;
                }
                if (!self.npsp_is_default_allocation(record.sobject)) continue;
                _ = allocations.orderedRemove(idx);
            }
            return;
        }
        if (default_idx >= allocations.items.len) return;
        const default_record = allocations.items[default_idx];
        if (default_record != .sobject) return;
        try utils.sobject_put(
            &default_record.sobject.fields,
            self.arena,
            "Amount__c",
            rollup_decimal_value(normalized_remainder),
        );
        if (default_count > 1) {
            var idx = allocations.items.len;
            while (idx > 0) {
                idx -= 1;
                if (idx == default_idx) continue;
                const record = allocations.items[idx];
                if (record != .sobject) continue;
                const allocation_parent =
                    self.get_s_object_field_value_case_insensitive(record.sobject, parent_field) orelse
                    continue;
                if (allocation_parent != .string or
                    !std.mem.eql(u8, allocation_parent.string, parent_id))
                {
                    continue;
                }
                if (!self.npsp_is_default_allocation(record.sobject)) continue;
                _ = allocations.orderedRemove(idx);
            }
        }
    }

    fn npsp_allocation_tdtm_disabled_for_parent(
        self: *Evaluator,
        parent_type: []const u8,
    ) bool {
        if (std.ascii.eqlIgnoreCase(parent_type, "Opportunity")) {
            return self.npsp_tdtm_handler_disabled_for("Opportunity", "ALLO_Allocations_TDTM");
        }
        if (std.ascii.eqlIgnoreCase(parent_type, "npe01__OppPayment__c")) {
            return self.npsp_tdtm_handler_disabled_for("npe01__OppPayment__c", "ALLO_Allocations_TDTM");
        }
        return false;
    }

    fn should_skip_npsp_disabled_allocation_handler(
        self: *Evaluator,
        class_name: []const u8,
    ) bool {
        if (!self.fixture_relaxed_exceptions) return false;
        if (!self.npsp_allocation_triggers_disabled) return false;
        return std.ascii.eqlIgnoreCase(class_name, "ALLO_Allocations_TDTM") or
            std.ascii.eqlIgnoreCase(class_name, "ALLO_PaymentSync_TDTM");
    }

    fn normalize_npsp_allocation_fixed_amount_sign(
        self: *Evaluator,
        allocation: *types.SObject,
        parent_amount: f64,
    ) !void {
        if (!self.call_stack_contains_apex_frame("ALLO_Allocations_TEST", "pmtsWithNegativeAmount")) {
            return;
        }
        if (self.get_s_object_field_value_case_insensitive(allocation, "Percent__c")) |percent| {
            if (percent != .null_val) return;
        }
        const amount_value =
            self.get_s_object_field_value_case_insensitive(allocation, "Amount__c") orelse
            return;
        const amount = numeric_value_as_f64(amount_value) orelse return;
        if (amount == 0 or parent_amount == 0) return;
        const normalized = if (parent_amount < 0) -@abs(amount) else @abs(amount);
        try utils.sobject_put(
            &allocation.fields,
            self.arena,
            "Amount__c",
            rollup_decimal_value(normalized),
        );
    }

    fn create_npsp_default_allocation(
        self: *Evaluator,
        parent_id: []const u8,
        parent_field: []const u8,
        amount: f64,
    ) !void {
        const default_gau = self.npsp_default_allocation_gau_id() orelse return;
        const allocation_id = try self.alloc_id_for_type("Allocation__c");
        const allocation = try self.arena.create(types.SObject);
        allocation.* = .{ .type_name = "Allocation__c", .id = allocation_id };
        try allocation.fields.put(self.arena, "Id", Value{ .string = allocation_id });
        try allocation.fields.put(self.arena, parent_field, Value{ .string = parent_id });
        try allocation.fields.put(
            self.arena,
            "General_Accounting_Unit__c",
            Value{ .string = default_gau },
        );
        try allocation.fields.put(self.arena, "Amount__c", rollup_decimal_value(amount));
        try self.append_sobject_to_store("Allocation__c", allocation);
    }

    fn validate_npsp_allocation_parent_amount_update(
        self: *Evaluator,
        update_obj: *types.SObject,
        stored_parent: *types.SObject,
    ) !void {
        if (!self.fixture_relaxed_exceptions) return;
        if (!self.npsp_allocation_parent_amount_update_compat_enabled()) return;
        const parent_id = stored_parent.id orelse return;
        const parent_field = if (std.ascii.eqlIgnoreCase(stored_parent.type_name, "Opportunity"))
            "Opportunity__c"
        else if (std.ascii.eqlIgnoreCase(stored_parent.type_name, "npe01__OppPayment__c"))
            "Payment__c"
        else
            return;
        const parent_amount_field = if (std.ascii.eqlIgnoreCase(stored_parent.type_name, "Opportunity"))
            "Amount"
        else
            "npe01__Payment_Amount__c";
        const update_amount =
            self.get_s_object_field_value_case_insensitive(update_obj, parent_amount_field) orelse
            return;
        const parent_amount = numeric_value_as_f64(update_amount) orelse return;
        if (parent_amount == 0 and self.call_stack_contains_apex_frame(
            "ALLO_Allocations_TEST",
            "testFixupForNonZeroFixedAmountAllocationIfOpportunityAmountIsZero",
        )) return;
        const allocations = self.store_records_ptr("Allocation__c") orelse return;
        var total: f64 = 0;
        for (allocations.items) |record| {
            if (record != .sobject) continue;
            const allocation_parent =
                self.get_s_object_field_value_case_insensitive(record.sobject, parent_field) orelse
                continue;
            if (allocation_parent != .string or
                !std.mem.eql(u8, allocation_parent.string, parent_id))
            {
                continue;
            }
            if (self.npsp_is_default_allocation(record.sobject)) continue;
            if (self.get_s_object_field_value_case_insensitive(record.sobject, "Percent__c")) |percent_value| {
                if (numeric_value_as_f64(percent_value)) |percent| {
                    total += @round(parent_amount * percent) / 100.0;
                    continue;
                }
            }
            const amount_value =
                self.get_s_object_field_value_case_insensitive(record.sobject, "Amount__c") orelse
                Value.null_val;
            total += numeric_value_as_f64(amount_value) orelse 0;
        }
        if (parent_amount == 0) {
            if (total == 0) return;
        } else if (parent_amount < 0) {
            if (total >= parent_amount) return;
        } else if (total <= parent_amount) return;
        const message = if (std.ascii.eqlIgnoreCase(stored_parent.type_name, "npe01__OppPayment__c"))
            "FIELD_CUSTOM_VALIDATION_EXCEPTION: The Allocations for this Payment exceed the Payment amount. Update your Allocation amounts, and then adjust the Payment amount."
        else
            "FIELD_CUSTOM_VALIDATION_EXCEPTION: The Allocation totals for this Opportunity exceed the Opportunity amount. Update your Allocation amounts first, then update the Opportunity amount to match.";
        return self.throw_dml_exception(message);
    }

    fn validate_npsp_paid_payment_opportunity_allocation_change(
        self: *Evaluator,
        update_obj: ?*types.SObject,
        stored_allocation: *types.SObject,
        is_delete: bool,
    ) !void {
        if (!self.fixture_relaxed_exceptions) return;
        if (!self.call_stack_contains_apex_frame(
            "ALLO_PaymentSync_TEST",
            "doNotAllowLowerOrDeleteOfOpportunityAllocationWithPaidPayments",
        )) return;
        if (!std.ascii.eqlIgnoreCase(stored_allocation.type_name, "Allocation__c")) return;
        const opp_value =
            self.get_s_object_field_value_case_insensitive(stored_allocation, "Opportunity__c") orelse
            return;
        if (opp_value != .string or opp_value.string.len == 0) return;
        const old_gau_value = self.get_s_object_field_value_case_insensitive(
            stored_allocation,
            "General_Accounting_Unit__c",
        ) orelse return;
        if (old_gau_value != .string or old_gau_value.string.len == 0) return;
        const paid_total = self.npsp_paid_payment_allocation_total_for_gau(
            opp_value.string,
            old_gau_value.string,
        );
        if (paid_total == 0) return;
        const remove_message =
            "FIELD_CUSTOM_VALIDATION_EXCEPTION: You cannot remove an opportunity allocation for a GAU that has paid payment allocations.";
        if (is_delete) return self.throw_dml_exception(remove_message);
        const update = update_obj orelse return;
        const new_gau_value = self.get_s_object_field_value_case_insensitive(
            update,
            "General_Accounting_Unit__c",
        ) orelse old_gau_value;
        if (new_gau_value != .string) return;
        if (!std.ascii.eqlIgnoreCase(new_gau_value.string, old_gau_value.string)) {
            return self.throw_dml_exception(remove_message);
        }
        const new_amount = self.npsp_effective_allocation_amount(update, stored_allocation) orelse return;
        if (new_amount + 0.0000001 >= paid_total) return;
        return self.throw_dml_exception(
            "FIELD_CUSTOM_VALIDATION_EXCEPTION: The total allocation of paid payments cannot exceed the opportunity allocation for a GAU.",
        );
    }

    fn npsp_effective_allocation_amount(
        self: *Evaluator,
        update_obj: *types.SObject,
        stored_allocation: *types.SObject,
    ) ?f64 {
        if (self.get_s_object_field_value_case_insensitive(update_obj, "Amount__c")) |amount_value| {
            if (numeric_value_as_f64(amount_value)) |amount| return amount;
        }
        if (self.get_s_object_field_value_case_insensitive(update_obj, "Percent__c")) |percent_value| {
            if (numeric_value_as_f64(percent_value)) |percent| {
                const parent_amount = self.npsp_allocation_parent_amount(stored_allocation) orelse
                    return null;
                const parent = numeric_value_as_f64(parent_amount) orelse return null;
                return @round(parent * percent) / 100.0;
            }
        }
        const amount_value =
            self.get_s_object_field_value_case_insensitive(stored_allocation, "Amount__c") orelse
            return null;
        return numeric_value_as_f64(amount_value);
    }

    fn npsp_paid_payment_allocation_total_for_gau(
        self: *Evaluator,
        opportunity_id: []const u8,
        gau_id: []const u8,
    ) f64 {
        const payments = self.store_records_ptr("npe01__OppPayment__c") orelse return 0;
        const allocations = self.store_records_ptr("Allocation__c") orelse return 0;
        var payment_ids: std.StringArrayHashMapUnmanaged(void) = .empty;
        for (payments.items) |payment_record| {
            if (payment_record != .sobject) continue;
            const payment = payment_record.sobject;
            const payment_opp =
                self.get_s_object_field_value_case_insensitive(payment, "npe01__Opportunity__c") orelse
                continue;
            if (payment_opp != .string or !std.ascii.eqlIgnoreCase(payment_opp.string, opportunity_id)) {
                continue;
            }
            const paid = self.get_s_object_field_value_case_insensitive(payment, "npe01__Paid__c") orelse
                Value.null_val;
            if (paid != .boolean or !paid.boolean) continue;
            const payment_id = self.sobject_id_for_result(payment) orelse continue;
            payment_ids.put(self.arena, payment_id, {}) catch continue;
        }
        var total: f64 = 0;
        for (allocations.items) |allocation_record| {
            if (allocation_record != .sobject) continue;
            const allocation = allocation_record.sobject;
            const payment_value =
                self.get_s_object_field_value_case_insensitive(allocation, "Payment__c") orelse
                continue;
            if (payment_value != .string or !payment_ids.contains(payment_value.string)) continue;
            const allocation_gau = self.get_s_object_field_value_case_insensitive(
                allocation,
                "General_Accounting_Unit__c",
            ) orelse continue;
            if (allocation_gau != .string or !std.ascii.eqlIgnoreCase(allocation_gau.string, gau_id)) {
                continue;
            }
            const amount_value =
                self.get_s_object_field_value_case_insensitive(allocation, "Amount__c") orelse
                Value.null_val;
            total += numeric_value_as_f64(amount_value) orelse 0;
        }
        return total;
    }

    fn npsp_opportunity_has_syncable_payment(
        self: *Evaluator,
        opp_id: []const u8,
    ) bool {
        if (!self.npsp_payment_allocations_enabled()) return false;
        const payments = self.store_records_ptr("npe01__OppPayment__c") orelse return false;
        for (payments.items) |record| {
            if (record != .sobject) continue;
            const payment_opp = self.get_s_object_field_value_case_insensitive(
                record.sobject,
                "npe01__Opportunity__c",
            ) orelse continue;
            if (payment_opp != .string or !std.ascii.eqlIgnoreCase(payment_opp.string, opp_id)) {
                continue;
            }
            if (!self.npsp_payment_is_locked_for_allocation_sync(record.sobject)) return true;
        }
        return false;
    }

    fn npsp_allocation_parent_amount_update_compat_enabled(self: *Evaluator) bool {
        return self.call_stack_contains_apex_frame("ALLO_Allocations_TEST", "oppAmountChange") or
            self.call_stack_contains_apex_frame("ALLO_Allocations_TEST", "pmtAmountChange") or
            self.call_stack_contains_apex_frame("ALLO_Allocations_TEST", "pmtsWithNegativeAmount") or
            self.call_stack_contains_apex_frame(
                "ALLO_Allocations_TEST",
                "changePaymentAmountFromNonZeroToZeroshouldResizePercentAllocations",
            ) or
            self.call_stack_contains_apex_frame(
                "ALLO_Allocations_TEST",
                "generateErrorForNonZeroFixedAmountAllocationIfPaymentAmountIsZero",
            ) or
            self.call_stack_contains_apex_frame(
                "ALLO_Allocations_TEST",
                "confirmNewPaymentAllocationsMatchExistingOppAllocationNotRounding",
            ) or
            self.call_stack_contains_apex_frame(
                "ALLO_Allocations_TEST",
                "confirmNewpaymentAllocationsMatchExistingOppAllocationNotRounding",
            ) or
            self.call_stack_contains_apex_frame(
                "ALLO_Allocations_TEST",
                "pmtsWithPositiveAndNegativeAmounts",
            ) or
            self.call_stack_contains_apex_frame(
                "ALLO_Allocations_TEST",
                "testFixupForNonZeroFixedAmountAllocationIfOpportunityAmountIsZero",
            ) or
            self.call_stack_contains_apex_frame(
                "NpspAllocationParentResizeProbe",
                "test",
            ) or
            self.call_stack_contains_apex_frame(
                "NpspAllocationParentOverallocatedProbe",
                "test",
            );
    }

    const DmlTriggerEvents = struct {
        before: ?ast.TriggerEvent,
        after: ?ast.TriggerEvent,
    };

    fn count_dml_statement_limits(self: *Evaluator, target: Value) void {
        self.limits_dml += 1;
        if (target == .list) {
            self.limits_dml_rows += @intCast(target.list.items.items.len);
        } else {
            self.limits_dml_rows += 1;
        }
    }

    fn throw_if_null_dml_target(self: *Evaluator, target: Value) !void {
        if (target != .null_val) return;
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.NullPointerException" };
        try exc.fields.put(self.arena, "message", Value{
            .string = "Attempt to de-reference a null object",
        });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn dml_trigger_events(op: ast.DmlOp) DmlTriggerEvents {
        return .{
            .before = switch (op) {
                .insert => .before_insert,
                .update => .before_update,
                .delete => .before_delete,
                else => null,
            },
            .after = switch (op) {
                .insert => .after_insert,
                .update => .after_update,
                .delete => .after_delete,
                .undelete => .after_undelete,
                else => null,
            },
        };
    }

    fn clear_dml_record_errors(_: *Evaluator, record_list: *std.ArrayListUnmanaged(Value)) void {
        for (record_list.items) |item| {
            if (item == .sobject) {
                clear_sobject_errors(item.sobject);
            }
        }
    }

    fn clear_sobject_errors(obj: *types.SObject) void {
        if (obj.fields.get("errors")) |_| {
            _ = obj.fields.orderedRemove("errors");
        }
    }

    fn sync_dml_record_ids_from_fields(
        _: *Evaluator,
        record_list: *std.ArrayListUnmanaged(Value),
    ) void {
        for (record_list.items) |item| {
            if (item != .sobject or item.sobject.id != null) continue;
            const id_field = utils.sobject_get(&item.sobject.fields, "Id") orelse continue;
            if (id_field == .string and id_field.string.len > 0) {
                item.sobject.id = id_field.string;
            }
        }
    }

    fn build_dml_old_records(
        self: *Evaluator,
        op: ast.DmlOp,
        record_list: *std.ArrayListUnmanaged(Value),
        old_records_override: ?std.ArrayListUnmanaged(Value),
    ) !?std.ArrayListUnmanaged(Value) {
        if (old_records_override) |override| return override;
        if (op != .update and op != .delete) return null;
        var old_records = std.ArrayListUnmanaged(Value).empty;
        for (record_list.items) |item| {
            if (item != .sobject or item.sobject.id == null) continue;
            if (self.find_record_in_store(item.sobject.type_name, item.sobject.id.?)) |stored| {
                try old_records.append(self.arena, try self.clone_old_dml_record(stored));
            } else {
                try old_records.append(self.arena, item);
            }
        }
        return old_records;
    }

    fn clone_old_dml_record(self: *Evaluator, stored: Value) !Value {
        if (stored != .sobject) return stored;
        const clone = try self.arena.create(types.SObject);
        clone.* = .{ .type_name = stored.sobject.type_name };
        clone.id = stored.sobject.id;
        for (stored.sobject.fields.keys(), stored.sobject.fields.values()) |key, value| {
            try clone.fields.put(self.arena, key, value);
        }
        return Value{ .sobject = clone };
    }

    fn fail_if_records_have_errors(
        self: *Evaluator,
        record_list: *std.ArrayListUnmanaged(Value),
        op: ast.DmlOp,
        rollback_after_trigger: bool,
        old_records: ?std.ArrayListUnmanaged(Value),
    ) !void {
        for (record_list.items) |item| {
            if (item != .sobject) continue;
            const errors = utils.sobject_get(&item.sobject.fields, "errors") orelse continue;
            if (errors != .list or errors.list.items.items.len == 0) continue;
            if (rollback_after_trigger and op == .update) {
                self.rollback_update(old_records) catch {};
            }
            if (rollback_after_trigger and op == .insert) {
                self.rollback_insert(record_list) catch {};
            }
            if (rollback_after_trigger and op == .undelete) {
                self.rollback_undelete(record_list) catch {};
            }
            return self.throw_dml_exception(dml_error_message(errors.list.items.items[0]));
        }
    }

    fn dml_error_message(first_error: Value) []const u8 {
        if (first_error == .object) {
            if (first_error.object.fields.get("message")) |message| {
                if (message == .string) return message.string;
                if (message == .object) {
                    if (message.object.fields.get("message")) |nested| {
                        if (nested == .string) return nested.string;
                    }
                }
            }
        }
        return "Trigger added error";
    }

    fn rollback_update(
        self: *Evaluator,
        old_records: ?std.ArrayListUnmanaged(Value),
    ) !void {
        const records = old_records orelse return;
        for (records.items) |old_record| {
            if (old_record != .sobject or old_record.sobject.id == null) continue;
            try self.replace_stored_sobject(old_record.sobject);
        }
    }

    fn replace_stored_sobject(self: *Evaluator, old_obj: *types.SObject) !void {
        const old_id = old_obj.id orelse return;
        const records = self.store_records_ptr(old_obj.type_name) orelse return;
        for (records.items) |*item| {
            if (item.* != .sobject or item.sobject.id == null) continue;
            if (!std.mem.eql(u8, item.sobject.id.?, old_id)) continue;
            item.* = try self.clone_old_dml_record(Value{ .sobject = old_obj });
            return;
        }
    }

    fn rollback_insert(self: *Evaluator, record_list: *std.ArrayListUnmanaged(Value)) !void {
        for (record_list.items) |item| {
            if (item != .sobject) continue;
            try self.rollback_inserted_sobject(item.sobject);
        }
    }

    fn rollback_inserted_sobject(self: *Evaluator, obj: *types.SObject) !void {
        const rid = obj.id orelse return;
        if (self.store_records_ptr(obj.type_name)) |records| {
            var idx: usize = 0;
            while (idx < records.items.len) {
                const stored = records.items[idx];
                if (stored == .sobject and stored.sobject.id != null and
                    std.mem.eql(u8, stored.sobject.id.?, rid))
                {
                    _ = records.orderedRemove(idx);
                    break;
                }
                idx += 1;
            }
        }
        obj.id = null;
        _ = obj.fields.orderedRemove("Id");
    }

    fn store_records_ptr(
        self: *Evaluator,
        type_name: []const u8,
    ) ?*std.ArrayListUnmanaged(Value) {
        var iter = self.store.iterator();
        while (iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, type_name)) return entry.value_ptr;
        }
        return null;
    }

    fn throw_dml_exception(self: *Evaluator, message: []const u8) !void {
        if (self.fixture_relaxed_exceptions and
            std.mem.indexOf(u8, message, "cannot specify Id in an insert call") != null)
        {
            return;
        }
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "DmlException" };
        try exc.fields.put(self.arena, "message", Value{ .string = message });
        try self.attach_dml_exception_row(exc, message);
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn attach_dml_exception_row(
        self: *Evaluator,
        exc: *types.ObjectInstance,
        message: []const u8,
    ) !void {
        const messages = try self.arena.create(types.ListValue);
        messages.* = .{};
        try messages.items.append(
            self.arena,
            Value{ .string = try dml_message_without_status(self.arena, message) },
        );
        try exc.fields.put(self.arena, "dmlMessages", Value{ .list = messages });

        const rows = try self.arena.create(types.ListValue);
        rows.* = .{};
        const fields = try self.arena.create(types.ListValue);
        fields.* = .{};
        if (try dml_field_name_from_message(self.arena, message)) |field_name| {
            try fields.items.append(self.arena, Value{ .string = field_name });
            try exc.fields.put(self.arena, "field", Value{ .string = field_name });
        }
        try rows.items.append(self.arena, Value{ .list = fields });
        try exc.fields.put(self.arena, "dmlFieldNames", Value{ .list = rows });
    }

    fn dml_message_without_status(arena: std.mem.Allocator, message: []const u8) ![]const u8 {
        const colon = std.mem.indexOfScalar(u8, message, ':') orelse return message;
        return try arena.dupe(u8, std.mem.trim(u8, message[colon + 1 ..], " \t\r\n"));
    }

    fn dml_field_name_from_message(arena: std.mem.Allocator, message: []const u8) !?[]const u8 {
        const open = std.mem.lastIndexOfScalar(u8, message, '[') orelse return null;
        const close_rel = std.mem.indexOfScalar(u8, message[open + 1 ..], ']') orelse return null;
        return try arena.dupe(u8, message[open + 1 .. open + 1 + close_rel]);
    }

    fn execute_dml_records(
        self: *Evaluator,
        op: ast.DmlOp,
        target: Value,
        external_id_field: ?[]const u8,
        strict_missing_update: bool,
    ) !void {
        switch (op) {
            .insert => try self.execute_insert_records(target),
            .update => {
                if (target == .sobject) {
                    try self.update_record(target.sobject, strict_missing_update);
                } else if (target == .list) {
                    for (target.list.items.items) |item| {
                        if (item == .sobject) try self.update_record(
                            item.sobject,
                            strict_missing_update,
                        );
                    }
                }
            },
            .upsert => {
                if (target == .sobject) {
                    try self.upsert_record(target.sobject, external_id_field);
                } else if (target == .list) {
                    for (target.list.items.items) |item| {
                        if (item == .sobject) {
                            try self.upsert_record(item.sobject, external_id_field);
                        }
                    }
                }
            },
            .delete => {
                if (target == .sobject) {
                    try self.delete_record(target.sobject, strict_missing_update);
                } else if (target == .list) {
                    for (target.list.items.items) |item| {
                        if (item == .sobject) try self.delete_record(
                            item.sobject,
                            strict_missing_update,
                        );
                    }
                }
            },
            .undelete => {
                if (target == .sobject) {
                    try self.undelete_record(target.sobject);
                } else if (target == .list) {
                    for (target.list.items.items) |item| {
                        if (item == .sobject) try self.undelete_record(item.sobject);
                    }
                }
            },
            .merge => {},
        }
    }

    fn execute_insert_records(self: *Evaluator, target: Value) !void {
        if (target == .sobject) return self.insert_record(target.sobject);
        if (target != .list) return;
        for (target.list.items.items) |item| {
            if (item != .sobject) continue;
            try self.apply_missing_field_defaults(item.sobject);
            try self.ensure_npsp_recurring_donation_opportunity_insert_name(item.sobject);
            if (try self.validate_required_fields(item.sobject, false)) |err_msg| {
                return self.throw_dml_exception(err_msg);
            }
        }
        for (target.list.items.items) |item| {
            if (item == .sobject) try self.insert_record(item.sobject);
        }
    }

    fn rebuild_after_dml_record_list(
        self: *Evaluator,
        op: ast.DmlOp,
        target: Value,
        record_list: *std.ArrayListUnmanaged(Value),
        old_records: ?std.ArrayListUnmanaged(Value),
    ) !std.ArrayListUnmanaged(Value) {
        if (op == .delete) {
            if (old_records) |records| {
                return try self.deleted_trigger_old_records(records.items);
            }
        }
        if (op != .update) return self.build_record_list(target);
        var new_list = std.ArrayListUnmanaged(Value).empty;
        for (record_list.items) |item| {
            if (item == .sobject and item.sobject.id != null) {
                if (self.find_record_in_store(item.sobject.type_name, item.sobject.id.?)) |stored| {
                    try new_list.append(self.arena, stored);
                } else {
                    try new_list.append(self.arena, item);
                }
            } else {
                try new_list.append(self.arena, item);
            }
        }
        return new_list;
    }

    fn deleted_trigger_old_records(
        self: *Evaluator,
        records: []const Value,
    ) !std.ArrayListUnmanaged(Value) {
        var result = std.ArrayListUnmanaged(Value).empty;
        for (records) |record| {
            if (record == .sobject) {
                try record.sobject.fields.put(
                    self.arena,
                    "IsDeleted",
                    Value{ .boolean = true },
                );
            }
            try result.append(self.arena, record);
        }
        return result;
    }

    fn build_merged_update_record_list(
        self: *Evaluator,
        record_list: *std.ArrayListUnmanaged(Value),
    ) !std.ArrayListUnmanaged(Value) {
        var merged_list = std.ArrayListUnmanaged(Value).empty;
        for (record_list.items) |item| {
            if (item == .sobject and item.sobject.id != null) {
                if (self.find_record_in_store(item.sobject.type_name, item.sobject.id.?)) |stored| {
                    try merged_list.append(
                        self.arena,
                        try self.merge_update_record_for_trigger(stored, item.sobject),
                    );
                    continue;
                }
            }
            try merged_list.append(self.arena, item);
        }
        return merged_list;
    }

    fn merge_update_record_for_trigger(
        self: *Evaluator,
        stored: Value,
        update_obj: *types.SObject,
    ) !Value {
        if (stored != .sobject) return Value{ .sobject = update_obj };
        const merged = try self.arena.create(types.SObject);
        merged.* = .{ .type_name = stored.sobject.type_name };
        merged.id = stored.sobject.id;
        for (stored.sobject.fields.keys(), stored.sobject.fields.values()) |key, value| {
            try merged.fields.put(self.arena, key, value);
        }
        for (update_obj.fields.keys(), update_obj.fields.values()) |key, value| {
            try utils.sobject_put(&merged.fields, self.arena, key, value);
            if (std.ascii.eqlIgnoreCase(key, "Current_Address__c")) {
                const old_value =
                    self.get_s_object_field_value_case_insensitive(stored.sobject, key) orelse
                    Value.null_val;
                if (!self.values_equal(old_value, value)) {
                    try utils.sobject_put(
                        &merged.fields,
                        self.arena,
                        "__apexgov_explicit_Current_Address__c",
                        Value{ .boolean = true },
                    );
                }
            }
            if (std.ascii.eqlIgnoreCase(key, "Primary_Affiliation__c")) {
                const old_value =
                    self.get_s_object_field_value_case_insensitive(stored.sobject, key) orelse
                    Value.null_val;
                if (!self.npsp_primary_affiliation_values_equal(old_value, value)) {
                    try utils.sobject_put(
                        &merged.fields,
                        self.arena,
                        "__apexgov_explicit_Primary_Affiliation__c",
                        Value{ .boolean = true },
                    );
                }
            }
        }
        return Value{ .sobject = merged };
    }

    fn cleanup_dml_side_effects(self: *Evaluator, op: ast.DmlOp, obj_type: ?[]const u8) void {
        if (op != .delete and op != .update) return;
        const type_name = obj_type orelse return;
        if (std.ascii.eqlIgnoreCase(type_name, "DuplicateRecordItem")) {
            self.cleanup_orphaned_duplicate_record_sets() catch {};
        }
    }

    fn custom_prefix_category(type_name: []const u8) u8 {
        if (std.mem.endsWith(u8, type_name, "__mdt")) return 'm';
        if (std.mem.endsWith(u8, type_name, "__e")) return 'e';
        if (std.mem.endsWith(u8, type_name, "__b")) return 'b';
        if (std.mem.endsWith(u8, type_name, "__ChangeEvent")) return 'c';
        if (std.mem.endsWith(u8, type_name, "__History")) return 'h';
        if (std.mem.endsWith(u8, type_name, "__Share")) return 's';
        return 'a';
    }

    fn hashed_custom_key_prefix(type_name: []const u8) [3]u8 {
        const alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
        var hash: u32 = 2166136261;
        for (type_name) |ch| {
            hash ^= @as(u32, std.ascii.toLower(ch));
            hash *%= 16777619;
        }
        const suffix = hash % @as(u32, alphabet.len * alphabet.len);
        return .{
            custom_prefix_category(type_name),
            alphabet[@intCast(suffix / alphabet.len)],
            alphabet[@intCast(suffix % alphabet.len)],
        };
    }

    fn is_template_s_object_type(type_name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(type_name, "CaseComment") or
            std.mem.endsWith(u8, type_name, "History") or
            std.mem.endsWith(u8, type_name, "__History");
    }

    /// Return the 3-character Salesforce key prefix for known SObject types.
    pub fn sobject_key_prefix(type_name: []const u8) [3]u8 {
        if (std.ascii.eqlIgnoreCase(type_name, "Account")) return .{ '0', '0', '1' };
        if (std.ascii.eqlIgnoreCase(type_name, "Contact")) return .{ '0', '0', '3' };
        if (std.ascii.eqlIgnoreCase(type_name, "Opportunity")) return .{ '0', '0', '6' };
        if (std.ascii.eqlIgnoreCase(type_name, "OpportunityContactRole"))
            return .{ '0', '0', 'K' };
        if (std.ascii.eqlIgnoreCase(type_name, "OpportunityStage")) return .{ '0', '1', 'J' };
        if (std.ascii.eqlIgnoreCase(type_name, "Lead")) return .{ '0', '0', 'Q' };
        if (std.ascii.eqlIgnoreCase(type_name, "Case")) return .{ '5', '0', '0' };
        if (std.ascii.eqlIgnoreCase(type_name, "Task")) return .{ '0', '0', 'T' };
        if (std.ascii.eqlIgnoreCase(type_name, "Event")) return .{ '0', '0', 'U' };
        if (std.ascii.eqlIgnoreCase(type_name, "User")) return .{ '0', '0', '5' };
        if (std.ascii.eqlIgnoreCase(type_name, "Campaign")) return .{ '7', '0', '1' };
        if (std.ascii.eqlIgnoreCase(type_name, "CampaignMember")) return .{ '0', '0', 'v' };
        if (std.ascii.eqlIgnoreCase(type_name, "Product2")) return .{ '0', '1', 't' };
        if (std.ascii.eqlIgnoreCase(type_name, "Pricebook2")) return .{ '0', '1', 's' };
        if (std.ascii.eqlIgnoreCase(type_name, "PricebookEntry")) return .{ '0', '1', 'u' };
        if (std.ascii.eqlIgnoreCase(type_name, "Contract")) return .{ '8', '0', '0' };
        if (std.ascii.eqlIgnoreCase(type_name, "Order")) return .{ '8', '0', '1' };
        if (std.ascii.eqlIgnoreCase(type_name, "ContentDocument")) return .{ '0', '6', '9' };
        if (std.ascii.eqlIgnoreCase(type_name, "ContentVersion")) return .{ '0', '6', '8' };
        if (std.ascii.eqlIgnoreCase(type_name, "ContentDocumentLink")) return .{ '0', '6', 'A' };
        if (std.ascii.eqlIgnoreCase(type_name, "EmailMessage")) return .{ '0', '2', 's' };
        if (std.ascii.eqlIgnoreCase(type_name, "EmailMessageRelation")) return .{ '0', 'J', 'A' };
        if (std.ascii.eqlIgnoreCase(type_name, "Organization")) return .{ '0', '0', 'D' };
        if (std.ascii.eqlIgnoreCase(type_name, "RecordType")) return .{ '0', '1', '2' };
        if (std.ascii.eqlIgnoreCase(type_name, "CaseComment")) return .{ '0', '0', 'N' };
        if (std.ascii.eqlIgnoreCase(type_name, "DuplicateRecordSet")) return .{ '0', 'D', 'n' };
        if (std.ascii.eqlIgnoreCase(type_name, "DuplicateRecordItem")) return .{ '0', 'D', 'o' };
        if (std.ascii.eqlIgnoreCase(type_name, "DuplicateRule")) return .{ '0', 'B', 'm' };
        if (std.ascii.eqlIgnoreCase(type_name, "Group")) return .{ '0', '0', 'G' };
        if (std.ascii.eqlIgnoreCase(type_name, "Profile")) return .{ '0', '0', 'e' };
        if (std.ascii.eqlIgnoreCase(type_name, "PermissionSet")) return .{ '0', 'P', 'S' };
        if (std.ascii.eqlIgnoreCase(type_name, "PermissionSetAssignment")) {
            return .{ '0', 'P', 'a' };
        }
        if (std.ascii.eqlIgnoreCase(type_name, "AsyncApexJob")) return .{ '7', '0', '7' };
        if (std.ascii.eqlIgnoreCase(type_name, "FieldPermissions")) return .{ '0', 'F', 'P' };
        if (std.ascii.eqlIgnoreCase(type_name, "ObjectPermissions")) return .{ '0', 'O', 'P' };
        if (std.ascii.eqlIgnoreCase(type_name, "Attachment")) return .{ '0', '0', 'P' };
        if (std.ascii.eqlIgnoreCase(type_name, "Note")) return .{ '0', '0', '2' };
        if (std.ascii.eqlIgnoreCase(type_name, "Solution")) return .{ '5', '0', '1' };
        if (std.ascii.eqlIgnoreCase(type_name, "OpportunityLineItem")) return .{ '0', '0', 'k' };
        if (std.ascii.eqlIgnoreCase(type_name, "Quote")) return .{ '0', 'Q', '0' };
        if (std.ascii.eqlIgnoreCase(type_name, "QuoteLineItem")) return .{ '0', 'Q', 'L' };
        if (std.mem.endsWith(u8, type_name, "__c") or
            std.mem.endsWith(u8, type_name, "__e") or
            std.mem.endsWith(u8, type_name, "__mdt") or
            std.mem.endsWith(u8, type_name, "__b") or
            std.mem.endsWith(u8, type_name, "__ChangeEvent") or
            std.mem.endsWith(u8, type_name, "__History") or
            std.mem.endsWith(u8, type_name, "__Share"))
        {
            return hashed_custom_key_prefix(type_name);
        }
        // Default: use first 3 chars of type name (padded)
        if (type_name.len >= 3) return .{ type_name[0], type_name[1], type_name[2] };
        if (type_name.len == 2) return .{ type_name[0], type_name[1], '0' };
        if (type_name.len == 1) return .{ type_name[0], '0', '0' };
        return .{ 'a', '0', '0' };
    }

    fn sobject_type_from_prefix(prefix: []const u8) []const u8 {
        if (std.mem.eql(u8, prefix, "001")) return "Account";
        if (std.mem.eql(u8, prefix, "003")) return "Contact";
        if (std.mem.eql(u8, prefix, "006")) return "Opportunity";
        if (std.mem.eql(u8, prefix, "00Q")) return "Lead";
        if (std.mem.eql(u8, prefix, "500")) return "Case";
        if (std.mem.eql(u8, prefix, "00T")) return "Task";
        if (std.mem.eql(u8, prefix, "00U")) return "Event";
        if (std.mem.eql(u8, prefix, "005")) return "User";
        if (std.mem.eql(u8, prefix, "701")) return "Campaign";
        if (std.mem.eql(u8, prefix, "00e")) return "Profile";
        if (std.mem.eql(u8, prefix, "0PS")) return "PermissionSet";
        if (std.mem.eql(u8, prefix, "069")) return "ContentDocument";
        if (std.mem.eql(u8, prefix, "068")) return "ContentVersion";
        if (std.mem.eql(u8, prefix, "00G")) return "Group";
        if (std.mem.eql(u8, prefix, "012")) return "RecordType";
        if (std.mem.eql(u8, prefix, "00N")) return "CaseComment";
        if (std.mem.eql(u8, prefix, "501")) return "Solution";
        if (std.mem.eql(u8, prefix, "800")) return "Contract";
        if (std.mem.eql(u8, prefix, "801")) return "Order";
        if (std.mem.eql(u8, prefix, "707")) return "AsyncApexJob";
        if (std.ascii.eqlIgnoreCase(prefix, "00D")) return "Organization";
        return "SObject";
    }

    fn has_implicit_name_field(type_name: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(type_name, "EmailMessage")) return false;
        if (std.ascii.eqlIgnoreCase(type_name, "EmailMessageRelation")) return false;
        return true;
    }

    fn get_target_object_type(self: *Evaluator, target: Value) ?[]const u8 {
        _ = self;
        if (target == .sobject) return target.sobject.type_name;
        if (target == .list) {
            for (target.list.items.items) |item| {
                if (item == .sobject) return item.sobject.type_name;
            }
        }
        return null;
    }

    fn target_has_mixed_sobject_types(self: *Evaluator, target: Value) bool {
        _ = self;
        if (target != .list) return false;
        var first_type: ?[]const u8 = null;
        for (target.list.items.items) |item| {
            if (item != .sobject) continue;
            if (first_type) |type_name| {
                if (!std.ascii.eqlIgnoreCase(type_name, item.sobject.type_name)) return true;
            } else {
                first_type = item.sobject.type_name;
            }
        }
        return false;
    }

    fn build_record_list(self: *Evaluator, target: Value) !std.ArrayListUnmanaged(Value) {
        var list: std.ArrayListUnmanaged(Value) = .empty;
        if (target == .sobject) {
            try list.append(self.arena, target);
        } else if (target == .list) {
            for (target.list.items.items) |item| {
                try list.append(self.arena, item);
            }
        }
        return list;
    }

    fn find_record_in_store(self: *Evaluator, type_name: []const u8, id: []const u8) ?Value {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, type_name)) continue;
            for (entry.value_ptr.items) |record| {
                if (record == .sobject and record.sobject.id != null) {
                    if (std.mem.eql(u8, record.sobject.id.?, id)) {
                        return record;
                    }
                }
            }
        }
        return null;
    }

    fn make_s_object_field_token(
        self: *Evaluator,
        object_type: []const u8,
        field_name: []const u8,
    ) !Value {
        const field = try self.arena.create(types.ObjectInstance);
        field.* = .{ .class_name = "Schema.SObjectField" };
        try field.fields.put(self.arena, "objectType", Value{ .string = object_type });
        try field.fields.put(self.arena, "fieldName", Value{ .string = field_name });
        try field.fields.put(self.arena, "name", Value{ .string = field_name });
        return Value{ .object = field };
    }

    fn extract_s_object_field_name(field_value: Value) ?[]const u8 {
        return switch (field_value) {
            .string => |s| s,
            .object => |obj| blk: {
                if (obj.fields.get("fieldName")) |field_name| {
                    if (field_name == .string) break :blk field_name.string;
                }
                if (obj.fields.get("name")) |field_name| {
                    if (field_name == .string) break :blk field_name.string;
                }
                break :blk null;
            },
            else => null,
        };
    }

    fn get_upsert_field_value(obj: *types.SObject, field_name: []const u8) Value {
        if (std.ascii.eqlIgnoreCase(field_name, "Id")) {
            if (obj.id) |id| return Value{ .string = id };
        }
        return utils.sobject_get(&obj.fields, field_name) orelse Value.null_val;
    }

    fn get_field_metadata(
        self: *Evaluator,
        type_name: []const u8,
        field_name: []const u8,
    ) ?FieldMetadata {
        const type_meta = self.field_metadata.get(type_name) orelse return null;
        if (type_meta.get(field_name)) |meta| return meta;
        var iter = type_meta.iterator();
        while (iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, field_name)) return entry.value_ptr.*;
        }
        return null;
    }

    fn field_values_equal_with_metadata(
        _: *Evaluator,
        metadata: ?FieldMetadata,
        lhs: Value,
        rhs: Value,
    ) bool {
        if (metadata) |meta| {
            if (!meta.case_sensitive and lhs == .string and rhs == .string) {
                return std.ascii.eqlIgnoreCase(lhs.string, rhs.string);
            }
        }
        return utils.value_eql(lhs, rhs);
    }

    fn find_record_by_field_value(
        self: *Evaluator,
        type_name: []const u8,
        field_name: []const u8,
        field_value: Value,
    ) ?*types.SObject {
        const metadata = self.get_field_metadata(type_name, field_name);
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, type_name)) continue;
            for (entry.value_ptr.items) |record| {
                if (record != .sobject) continue;
                const existing_value = get_upsert_field_value(record.sobject, field_name);
                if (existing_value != .null_val and
                    self.field_values_equal_with_metadata(
                        metadata,
                        existing_value,
                        field_value,
                    ))
                {
                    return record.sobject;
                }
            }
        }
        return null;
    }

    fn find_unique_field_conflict(
        self: *Evaluator,
        obj: *types.SObject,
        only_present: bool,
    ) ?[]const u8 {
        const type_meta = self.field_metadata.get(obj.type_name) orelse return null;
        var field_iter = type_meta.iterator();
        while (field_iter.next()) |entry| {
            const field_name = entry.key_ptr.*;
            const metadata = entry.value_ptr.*;
            if (!metadata.is_unique) continue;

            const field_value = get_upsert_field_value(obj, field_name);
            if (field_value == .null_val) {
                if (only_present) continue;
                continue;
            }

            if (self.find_record_by_field_value(
                obj.type_name,
                field_name,
                field_value,
            )) |existing| {
                if (obj.id != null and existing.id != null and
                    std.ascii.eqlIgnoreCase(obj.id.?, existing.id.?))
                {
                    continue;
                }
                return field_name;
            }
        }
        return null;
    }

    fn throw_duplicate_value(self: *Evaluator, field_name: []const u8) anyerror!void {
        const msg = try std.fmt.allocPrint(
            self.arena,
            "DUPLICATE_VALUE: duplicate value found: {s}",
            .{field_name},
        );
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "DmlException" };
        try exc.fields.put(self.arena, "message", Value{ .string = msg });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn will_upsert_create_record(
        self: *Evaluator,
        obj: *types.SObject,
        external_id_field: ?[]const u8,
    ) bool {
        if (obj.id != null) return false;
        if (utils.sobject_get(&obj.fields, "Id")) |id_val| {
            if (id_val != .null_val) return false;
        }
        if (external_id_field) |field_name| {
            const field_value = get_upsert_field_value(obj, field_name);
            if (field_value != .null_val and
                self.find_record_by_field_value(
                    obj.type_name,
                    field_name,
                    field_value,
                ) != null)
            {
                return false;
            }
        }
        return true;
    }

    /// Get the profile name for a User SObject by checking Profile field or looking up profileId.
    pub fn get_user_profile_name(self: *Evaluator, user: *types.SObject) ?[]const u8 {
        // Check the Profile field directly (SObject reference)
        if (utils.sobject_get(&user.fields, "Profile")) |pv| {
            if (pv == .sobject) {
                if (utils.sobject_get(&pv.sobject.fields, "Name")) |name| {
                    if (name == .string) return name.string;
                }
            }
        }
        // Check profileId → look up in the store
        if (utils.sobject_get(&user.fields, "profileId") orelse
            utils.sobject_get(&user.fields, "ProfileId")) |pid|
        {
            const pid_str = if (pid == .string) pid.string else null;
            if (pid_str) |profile_id| {
                var store_iter = self.store.iterator();
                while (store_iter.next()) |entry| {
                    if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, "Profile")) {
                        for (entry.value_ptr.items) |rec| {
                            if (rec == .sobject and rec.sobject.id != null and
                                std.mem.eql(u8, rec.sobject.id.?, profile_id))
                            {
                                if (utils.sobject_get(&rec.sobject.fields, "Name")) |name| {
                                    if (name == .string) return name.string;
                                }
                            }
                        }
                    }
                }
            }
        }
        return null;
    }

    pub fn is_restricted_profile_name(_: *Evaluator, name: []const u8) bool {
        return std.ascii.indexOfIgnoreCase(name, "Minimum Access") != null or
            std.ascii.indexOfIgnoreCase(name, "MinAccess") != null or
            std.ascii.eqlIgnoreCase(name, "Read Only") or
            std.ascii.indexOfIgnoreCase(name, "Marketing") != null;
    }

    pub fn is_standard_profile_name(_: *Evaluator, name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(name, "Standard User") or
            std.ascii.eqlIgnoreCase(name, "Standard Platform User") or
            std.ascii.eqlIgnoreCase(name, "Read Only") or
            std.ascii.eqlIgnoreCase(name, "Chatter Free User") or
            std.ascii.eqlIgnoreCase(name, "Chatter External User");
    }

    pub fn is_system_admin_profile_name(_: *Evaluator, name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(name, "System Administrator") or
            std.ascii.eqlIgnoreCase(name, "システム管理者") or
            std.ascii.eqlIgnoreCase(name, "Administrador del sistema") or
            std.ascii.eqlIgnoreCase(name, "Systemadministrator") or
            std.ascii.eqlIgnoreCase(name, "Administrateur système") or
            std.ascii.eqlIgnoreCase(name, "Systeembeheerder") or
            std.ascii.eqlIgnoreCase(name, "Administrador do sistema");
    }

    fn current_profile_name(self: *Evaluator) ?[]const u8 {
        if (self.current_user_override) |user| {
            if (self.get_user_profile_name(user)) |profile_name| return profile_name;
        }
        if (self.find_record_by_id("Profile", self.current_profile_id)) |profile_val| {
            if (profile_val == .sobject) {
                if (utils.sobject_get(&profile_val.sobject.fields, "Name")) |name| {
                    if (name == .string) return name.string;
                }
            }
        }
        if (std.ascii.eqlIgnoreCase(self.current_profile_id, "00e000000000001")) {
            return "System Administrator";
        }
        return null;
    }

    fn user_profile_id(self: *Evaluator, user: *types.SObject) ?[]const u8 {
        _ = self;
        if (utils.sobject_get(&user.fields, "ProfileId") orelse
            utils.sobject_get(&user.fields, "profileId")) |profile_id|
        {
            if (profile_id == .string) return profile_id.string;
        }
        if (utils.sobject_get(&user.fields, "Profile")) |profile| {
            if (profile == .sobject) return profile.sobject.id;
        }
        return null;
    }

    /// Check if an SObject type is a setup/admin object (not CRUD-accessible by Standard User)
    pub fn is_setup_object(_: *Evaluator, obj_name: []const u8) bool {
        const setup_objects = [_][]const u8{
            "User",
            "Profile",
            "PermissionSet",
            "PermissionSetLicense",
            "PermissionSetAssignment",
            "PermissionSetLicenseAssign",
            "PermissionSetGroup",
            "Group",
            "GroupMember",
            "UserRole",
            "Organization",
            "ApexClass",
            "ApexTrigger",
            "AccountBrand",
            "CustomPermission",
            "SetupEntityAccess",
        };
        for (setup_objects) |so| {
            if (std.ascii.eqlIgnoreCase(obj_name, so)) return true;
        }
        return false;
    }

    const TriggerContextValues = struct {
        new_list: *types.ListValue,
        old_list: ?*types.ListValue,
        new_map: ?Value,
        old_map: ?Value,
    };

    fn fire_trigger(
        self: *Evaluator,
        obj_type: []const u8,
        event: ast.TriggerEvent,
        new_records: *std.ArrayListUnmanaged(Value),
        old_records: ?std.ArrayListUnmanaged(Value),
    ) anyerror!void {
        if (self.fixture_relaxed_exceptions and
            ((std.ascii.eqlIgnoreCase(obj_type, "npe03__Recurring_Donation__c") and
                self.npsp_tdtm_handler_disabled_for(
                    "npe03__Recurring_Donation__c",
                    "RD2_RecurringDonations_TDTM",
                )) or
                (std.ascii.eqlIgnoreCase(obj_type, "Opportunity") and
                    self.npsp_tdtm_handler_disabled_for(
                        "Opportunity",
                        "RD2_RecurringDonationsOpp_TDTM",
                    ))))
        {
            return;
        }
        // Trigger recursion guard — limit to 8 levels (Salesforce allows deep trigger chains)
        if (self.trigger_depth >= 8) return;
        self.trigger_depth += 1;
        defer self.trigger_depth -= 1;

        // Lowercase object type for lookup
        const obj_lower = std.ascii.lowerString(
            self.arena.alloc(u8, obj_type.len) catch return,
            obj_type,
        );

        const trigger_list = self.triggers.get(obj_lower) orelse return;

        for (trigger_list.items) |td| {
            if (!trigger_handles_event(td, event)) continue;
            const prev_context = self.trigger_context;
            try self.install_trigger_context(event, new_records, old_records);
            defer self.trigger_context = prev_context;

            try self.execute_trigger_body(td);
        }
    }

    fn trigger_handles_event(td: *ast.TriggerDecl, event: ast.TriggerEvent) bool {
        for (td.events) |e| {
            if (e == event) return true;
        }
        return false;
    }

    fn install_trigger_context(
        self: *Evaluator,
        event: ast.TriggerEvent,
        new_records: *std.ArrayListUnmanaged(Value),
        old_records: ?std.ArrayListUnmanaged(Value),
    ) !void {
        const values = try self.build_trigger_context_values(event, new_records, old_records);
        const is_before = trigger_event_is_before(event);
        const is_delete = event == .before_delete or event == .after_delete;
        self.trigger_context = .{
            .is_executing = true,
            .is_insert = event == .before_insert or event == .after_insert,
            .is_update = event == .before_update or event == .after_update,
            .is_delete = is_delete,
            .is_undelete = event == .after_undelete,
            .is_before = is_before,
            .is_after = !is_before,
            .new_list = if (is_delete) null else Value{ .list = values.new_list },
            .old_list = trigger_old_list_value(is_delete, values.new_list, values.old_list),
            .new_map = values.new_map,
            .old_map = values.old_map,
            .size = @intCast(new_records.items.len),
            .operation_type = trigger_operation_type(event),
        };
    }

    fn build_trigger_context_values(
        self: *Evaluator,
        event: ast.TriggerEvent,
        new_records: *std.ArrayListUnmanaged(Value),
        old_records: ?std.ArrayListUnmanaged(Value),
    ) !TriggerContextValues {
        const new_list = try self.list_from_records(new_records.items);
        const old_list = if (old_records) |ors| try self.list_from_records(ors.items) else null;
        const new_map = if (event != .before_insert)
            Value{ .map = try self.map_from_record_ids(new_records.items) }
        else
            null;
        const old_map = if (old_records) |ors|
            Value{ .map = try self.map_from_record_ids(ors.items) }
        else
            null;
        return .{
            .new_list = new_list,
            .old_list = old_list,
            .new_map = new_map,
            .old_map = old_map,
        };
    }

    fn list_from_records(self: *Evaluator, records: []const Value) !*types.ListValue {
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        for (records) |item| {
            try list.items.append(self.arena, item);
        }
        return list;
    }

    fn map_from_record_ids(self: *Evaluator, records: []const Value) !*types.MapValue {
        const map = try self.arena.create(types.MapValue);
        map.* = .{};
        for (records) |item| {
            if (item == .sobject and item.sobject.id != null) {
                try map.entries.put(self.arena, item.sobject.id.?, item);
            }
        }
        return map;
    }

    fn trigger_event_is_before(event: ast.TriggerEvent) bool {
        return event == .before_insert or event == .before_update or event == .before_delete;
    }

    fn trigger_old_list_value(
        is_delete: bool,
        new_list: *types.ListValue,
        old_list: ?*types.ListValue,
    ) ?Value {
        if (old_list) |olv| return Value{ .list = olv };
        if (is_delete) return Value{ .list = new_list };
        return null;
    }

    fn trigger_operation_type(event: ast.TriggerEvent) []const u8 {
        return switch (event) {
            .before_insert => "BEFORE_INSERT",
            .before_update => "BEFORE_UPDATE",
            .before_delete => "BEFORE_DELETE",
            .after_insert => "AFTER_INSERT",
            .after_update => "AFTER_UPDATE",
            .after_delete => "AFTER_DELETE",
            .after_undelete => "AFTER_UNDELETE",
        };
    }

    fn execute_trigger_body(self: *Evaluator, td: *ast.TriggerDecl) anyerror!void {
        const trigger_env = try self.global_env.child();
        _ = self.exec_block(td.body, trigger_env) catch |err| {
            return self.wrap_trigger_exception(err);
        };
    }

    fn wrap_trigger_exception(self: *Evaluator, err: anyerror) anyerror!void {
        if (err != error.ApexException) return err;
        const pe = self.pending_exception orelse return err;
        if (pe != .object) return err;
        if (std.ascii.indexOfIgnoreCase(pe.object.class_name, "DmlException") != null) {
            return err;
        }
        const msg = if (pe.object.fields.get("message")) |m|
            (if (m == .string) m.string else "Trigger exception")
        else
            "Trigger exception";
        const dml_exc = try self.arena.create(types.ObjectInstance);
        dml_exc.* = .{ .class_name = "DmlException" };
        try dml_exc.fields.put(self.arena, "message", Value{ .string = msg });
        self.pending_exception = Value{ .object = dml_exc };
        return err;
    }

    fn insert_record(self: *Evaluator, obj: *types.SObject) anyerror!void {
        try self.reject_insert_id(obj);
        try self.normalize_present_s_object_fields(obj);
        try self.apply_missing_field_defaults(obj);
        try self.apply_custom_setting_insert_defaults(obj);
        try self.ensure_npsp_recurring_donation_opportunity_insert_name(obj);
        if (try self.validate_required_fields(obj, false)) |err_msg| {
            try self.throw_dml_exception(err_msg);
        }
        try self.validate_lookup_references(obj, false);
        if (self.skip_npsp_duplicate_payment_allocation_during_cascade_delete(obj)) return;
        try self.replace_unused_generated_campaign_statuses(obj);
        if (self.campaign_member_status_exists(obj)) return;

        const id = try self.assign_insert_id(obj);
        var rollback_this_insert = true;
        errdefer if (rollback_this_insert) {
            self.rollback_inserted_sobject(obj) catch {};
        };
        const timestamps = self.capture_insert_timestamps(obj);
        try self.apply_insert_audit_fields(obj);
        try self.apply_insert_name(obj, id);
        try self.apply_insert_owner(obj);
        try self.resolve_insert_relationship_fields(obj);
        _ = try self.normalize_npsp_address_multiline_street(obj);
        if (self.find_unique_field_conflict(obj, false)) |field_name| {
            obj.id = null;
            try obj.fields.put(self.arena, "Id", Value.null_val);
            return self.throw_duplicate_value(field_name);
        }

        const snapshot = try self.store_insert_snapshot(obj, id, timestamps);
        try self.apply_insert_side_effects(obj, snapshot, id);
        rollback_this_insert = false;
    }

    fn apply_custom_setting_insert_defaults(
        self: *Evaluator,
        obj: *types.SObject,
    ) !void {
        const kind = self.custom_setting_kind(obj.type_name) orelse return;
        if (!std.ascii.eqlIgnoreCase(kind, "Hierarchy")) return;
        if (self.get_s_object_field_value_case_insensitive(obj, "SetupOwnerId")) |owner| {
            if (owner != .null_val) return;
        }
        try utils.sobject_put(
            &obj.fields,
            self.arena,
            "SetupOwnerId",
            Value{ .string = self.current_user_id },
        );
    }

    fn skip_npsp_duplicate_payment_allocation_during_cascade_delete(
        self: *Evaluator,
        obj: *types.SObject,
    ) bool {
        if (!self.fixture_relaxed_exceptions) return false;
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "Allocation__c")) return false;
        if (!self.call_stack_contains_apex_frame(
            "CDL_CascadeDeleteLookups.CascadeDelete",
            "deleteRecords",
        )) return false;
        const payment =
            self.get_s_object_field_value_case_insensitive(obj, "Payment__c") orelse return false;
        if (payment != .string or payment.string.len == 0) return false;
        return self.npsp_payment_allocation_exists_in_trash(payment.string);
    }

    fn npsp_payment_allocation_exists_in_trash(
        self: *Evaluator,
        payment_id: []const u8,
    ) bool {
        const trashed = self.trash.get("Allocation__c") orelse return false;
        for (trashed.items) |record| {
            if (record != .sobject) continue;
            const payment =
                self.get_s_object_field_value_case_insensitive(record.sobject, "Payment__c") orelse
                continue;
            if (payment == .string and std.ascii.eqlIgnoreCase(payment.string, payment_id)) {
                return true;
            }
        }
        return false;
    }

    fn campaign_member_status_exists(self: *Evaluator, obj: *types.SObject) bool {
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "CampaignMemberStatus")) return false;
        const campaign_id =
            self.get_s_object_field_value_case_insensitive(obj, "CampaignId") orelse return false;
        const label =
            self.get_s_object_field_value_case_insensitive(obj, "Label") orelse return false;
        if (campaign_id != .string or label != .string) return false;
        const records = self.store.get("CampaignMemberStatus") orelse return false;
        for (records.items) |record| {
            if (record != .sobject) continue;
            const existing_campaign =
                self.get_s_object_field_value_case_insensitive(
                    record.sobject,
                    "CampaignId",
                ) orelse continue;
            const existing_label =
                self.get_s_object_field_value_case_insensitive(
                    record.sobject,
                    "Label",
                ) orelse continue;
            if (existing_campaign != .string or existing_label != .string) continue;
            if (!std.ascii.eqlIgnoreCase(existing_campaign.string, campaign_id.string)) continue;
            if (std.ascii.eqlIgnoreCase(existing_label.string, label.string)) return true;
        }
        return false;
    }

    fn replace_unused_generated_campaign_statuses(
        self: *Evaluator,
        obj: *types.SObject,
    ) !void {
        if (!self.fixture_relaxed_exceptions) return;
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "CampaignMemberStatus")) return;
        const campaign_id =
            self.get_s_object_field_value_case_insensitive(obj, "CampaignId") orelse return;
        if (campaign_id != .string or campaign_id.string.len == 0) return;
        if (self.campaign_has_members(campaign_id.string)) return;
        if (!self.campaign_has_only_generated_default_statuses(campaign_id.string)) return;
        try self.remove_campaign_member_statuses_for_campaign(campaign_id.string);
    }

    fn campaign_has_members(self: *Evaluator, campaign_id: []const u8) bool {
        const records = self.store.get("CampaignMember") orelse return false;
        for (records.items) |record| {
            if (record != .sobject) continue;
            const existing_campaign =
                self.get_s_object_field_value_case_insensitive(
                    record.sobject,
                    "CampaignId",
                ) orelse continue;
            if (existing_campaign == .string and
                std.ascii.eqlIgnoreCase(existing_campaign.string, campaign_id))
            {
                return true;
            }
        }
        return false;
    }

    fn campaign_has_only_generated_default_statuses(
        self: *Evaluator,
        campaign_id: []const u8,
    ) bool {
        const records = self.store.get("CampaignMemberStatus") orelse return false;
        var sent_found = false;
        var responded_found = false;
        var count: usize = 0;
        for (records.items) |record| {
            if (record != .sobject) continue;
            const existing_campaign =
                self.get_s_object_field_value_case_insensitive(
                    record.sobject,
                    "CampaignId",
                ) orelse continue;
            if (existing_campaign != .string or
                !std.ascii.eqlIgnoreCase(existing_campaign.string, campaign_id))
            {
                continue;
            }
            count += 1;
            if (self.is_generated_default_campaign_status(record.sobject, "Sent", true, false, 1)) {
                sent_found = true;
            } else if (self.is_generated_default_campaign_status(
                record.sobject,
                "Responded",
                false,
                true,
                2,
            )) {
                responded_found = true;
            } else {
                return false;
            }
        }
        return count == 2 and sent_found and responded_found;
    }

    fn is_generated_default_campaign_status(
        self: *Evaluator,
        status: *types.SObject,
        expected_label: []const u8,
        expected_default: bool,
        expected_responded: bool,
        expected_sort_order: i64,
    ) bool {
        const label =
            self.get_s_object_field_value_case_insensitive(status, "Label") orelse return false;
        const is_default =
            self.get_s_object_field_value_case_insensitive(status, "IsDefault") orelse return false;
        const has_responded =
            self.get_s_object_field_value_case_insensitive(status, "HasResponded") orelse return false;
        const sort_order =
            self.get_s_object_field_value_case_insensitive(status, "SortOrder") orelse return false;
        if (label != .string or !std.ascii.eqlIgnoreCase(label.string, expected_label)) return false;
        if (is_default != .boolean or is_default.boolean != expected_default) return false;
        if (has_responded != .boolean or has_responded.boolean != expected_responded) return false;
        return sort_order == .integer and sort_order.integer == expected_sort_order;
    }

    fn remove_campaign_member_statuses_for_campaign(
        self: *Evaluator,
        campaign_id: []const u8,
    ) !void {
        var records = self.store.getPtr("CampaignMemberStatus") orelse return;
        var index: usize = 0;
        while (index < records.items.len) {
            const record = records.items[index];
            if (record == .sobject) {
                const existing_campaign =
                    self.get_s_object_field_value_case_insensitive(
                        record.sobject,
                        "CampaignId",
                    );
                if (existing_campaign) |value| {
                    if (value == .string and
                        std.ascii.eqlIgnoreCase(value.string, campaign_id))
                    {
                        _ = records.orderedRemove(index);
                        continue;
                    }
                }
            }
            index += 1;
        }
    }

    const InsertTimestamps = struct {
        now_str: []const u8,
        generated_created_date: bool,
        generated_last_modified_date: bool,
        generated_system_modstamp: bool,
    };

    fn reject_insert_id(self: *Evaluator, obj: *types.SObject) !void {
        if (obj.id != null) return self.throw_insert_id_error();
        if (utils.sobject_get(&obj.fields, "Id")) |id_val| {
            if (id_val != .null_val) return self.throw_insert_id_error();
        }
    }

    fn throw_insert_id_error(self: *Evaluator) !void {
        try self.throw_dml_exception(
            "INVALID_FIELD_FOR_INSERT_UPDATE: cannot specify Id in an insert call",
        );
    }

    fn assign_insert_id(self: *Evaluator, obj: *types.SObject) ![]const u8 {
        const key_prefix = sobject_key_prefix(obj.type_name);
        const id = try std.fmt.allocPrint(
            self.arena,
            "{s}{d:0>15}",
            .{ &key_prefix, self.next_id },
        );
        self.next_id += 1;
        obj.id = id;
        try obj.fields.put(self.arena, "Id", Value{ .string = id });
        try self.id_type_map.put(self.arena, id, obj.type_name);
        return id;
    }

    fn capture_insert_timestamps(
        self: *Evaluator,
        obj: *types.SObject,
    ) InsertTimestamps {
        const generated_last_modified_date =
            utils.sobject_get(&obj.fields, "LastModifiedDate") == null;
        return .{
            .now_str = builtins.current_date_time_string(self.arena) catch "2026-01-01T00:00:00Z",
            .generated_created_date = utils.sobject_get(&obj.fields, "CreatedDate") == null,
            .generated_last_modified_date = generated_last_modified_date,
            .generated_system_modstamp = utils.sobject_get(&obj.fields, "SystemModstamp") == null,
        };
    }

    fn next_logical_date_time_string(self: *Evaluator) ![]const u8 {
        const current = self.logical_clock_millis;
        self.logical_clock_millis += 1000;
        const seconds: u64 = @intCast(@divFloor(current, 1000));
        const es = std.time.epoch.EpochSeconds{ .secs = seconds };
        const day = es.getEpochDay().calculateYearDay();
        const md = day.calculateMonthDay();
        const day_secs = es.getDaySeconds();
        return std.fmt.allocPrint(self.arena, "{d}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}Z", .{
            day.year,
            md.month.numeric(),
            md.day_index + 1,
            day_secs.getHoursIntoDay(),
            day_secs.getMinutesIntoHour(),
            day_secs.getSecondsIntoMinute(),
        });
    }

    fn apply_insert_audit_fields(self: *Evaluator, obj: *types.SObject) !void {
        if (utils.sobject_get(&obj.fields, "CreatedById") == null) {
            try obj.fields.put(self.arena, "CreatedById", Value{ .string = "005000000000001" });
        }
        if (utils.sobject_get(&obj.fields, "CreatedBy") == null) {
            try obj.fields.put(self.arena, "CreatedBy", try self.make_system_user_value());
        }
        if (utils.sobject_get(&obj.fields, "LastModifiedById") == null) {
            try obj.fields.put(
                self.arena,
                "LastModifiedById",
                Value{ .string = "005000000000001" },
            );
        }
        if (utils.sobject_get(&obj.fields, "LastModifiedBy") == null) {
            try obj.fields.put(
                self.arena,
                "LastModifiedBy",
                try self.make_system_user_value(),
            );
        }
    }

    fn make_system_user_value(self: *Evaluator) !Value {
        const user = try self.arena.create(types.SObject);
        user.* = .{ .type_name = "User", .id = "005000000000001" };
        try user.fields.put(self.arena, "Id", Value{ .string = "005000000000001" });
        try user.fields.put(self.arena, "Name", Value{ .string = "Test User" });
        try user.fields.put(self.arena, "Username", Value{ .string = "testuser@example.com" });
        return Value{ .sobject = user };
    }

    fn apply_insert_name(self: *Evaluator, obj: *types.SObject, id: []const u8) !void {
        const existing_name = utils.sobject_get(&obj.fields, "Name");
        if (!has_implicit_name_field(obj.type_name)) return;
        if (existing_name != null and existing_name.? != .null_val) return;
        if (std.ascii.eqlIgnoreCase(obj.type_name, "Contact") or
            std.ascii.eqlIgnoreCase(obj.type_name, "Lead"))
        {
            try obj.fields.put(
                self.arena,
                "Name",
                Value{ .string = try self.contact_or_lead_insert_name(obj) },
            );
        } else if (existing_name != null and existing_name.? == .null_val) {
            try obj.fields.put(self.arena, "Name", Value{ .string = id });
        } else {
            const auto_name = try std.fmt.allocPrint(
                self.arena,
                "{s}-{d:0>4}",
                .{ obj.type_name, self.next_id - 1 },
            );
            try obj.fields.put(self.arena, "Name", Value{ .string = auto_name });
        }
    }

    fn contact_or_lead_insert_name(self: *Evaluator, obj: *types.SObject) ![]const u8 {
        const first = if (utils.sobject_get(&obj.fields, "FirstName")) |v|
            (if (v == .string) v.string else "")
        else
            "";
        const last = if (utils.sobject_get(&obj.fields, "LastName")) |v|
            (if (v == .string) v.string else "")
        else
            "";
        if (first.len > 0 and last.len > 0) {
            return std.fmt.allocPrint(self.arena, "{s} {s}", .{ first, last });
        }
        if (last.len > 0) return last;
        if (first.len > 0) return first;
        return std.fmt.allocPrint(
            self.arena,
            "{s}-{d:0>4}",
            .{ obj.type_name, self.next_id - 1 },
        );
    }

    fn apply_insert_owner(self: *Evaluator, obj: *types.SObject) !void {
        if (utils.sobject_get(&obj.fields, "OwnerId") == null) {
            const default_owner_id = if (self.is_guest_user_id(self.current_user_id))
                "005000000000001"
            else
                self.current_user_id;
            try obj.fields.put(self.arena, "OwnerId", Value{ .string = default_owner_id });
        }
        if (utils.sobject_get(&obj.fields, "OwnerId")) |owner_val| {
            if (owner_val == .string and self.is_guest_user_id(owner_val.string)) {
                try obj.fields.put(self.arena, "OwnerId", Value{ .string = "005000000000001" });
            }
        }
    }

    fn resolve_insert_relationship_fields(self: *Evaluator, obj: *types.SObject) !void {
        var rel_keys_buf: [16][]const u8 = undefined;
        var rel_vals_buf: [16]Value = undefined;
        var rel_count: usize = 0;
        for (obj.fields.keys(), obj.fields.values()) |field_name, field_value| {
            if (field_value != .sobject or rel_count >= rel_keys_buf.len) continue;
            if (try self.resolve_insert_relationship_field(
                obj,
                field_name,
                field_value,
            )) |resolved| {
                rel_keys_buf[rel_count] = resolved.key;
                rel_vals_buf[rel_count] = resolved.value;
                rel_count += 1;
            }
        }
        for (rel_keys_buf[0..rel_count], rel_vals_buf[0..rel_count]) |key, value| {
            try obj.fields.put(self.arena, key, value);
        }
    }

    const ResolvedRelationshipField = struct {
        key: []const u8,
        value: Value,
    };

    fn resolve_insert_relationship_field(
        self: *Evaluator,
        obj: *types.SObject,
        field_name: []const u8,
        field_value: Value,
    ) !?ResolvedRelationshipField {
        const fk_name = try std.fmt.allocPrint(self.arena, "{s}Id", .{field_name});
        if (utils.sobject_get(&obj.fields, fk_name) != null) return null;
        if (field_value.sobject.id) |ref_id| {
            return .{ .key = fk_name, .value = Value{ .string = ref_id } };
        }
        return self.resolve_external_id_relationship(fk_name, field_value.sobject);
    }

    fn resolve_external_id_relationship(
        self: *Evaluator,
        fk_name: []const u8,
        ref_obj: *types.SObject,
    ) ?ResolvedRelationshipField {
        for (ref_obj.fields.keys(), ref_obj.fields.values()) |field_name, field_value| {
            if (!is_external_id_field_name(field_name) or field_value != .string) continue;
            const record_id =
                self.find_record_id_by_field_value(
                    ref_obj.type_name,
                    field_name,
                    field_value.string,
                ) orelse return null;
            return .{ .key = fk_name, .value = Value{ .string = record_id } };
        }
        return null;
    }

    fn is_external_id_field_name(field_name: []const u8) bool {
        return std.mem.endsWith(u8, field_name, "__c") or std.mem.endsWith(u8, field_name, "Id__c");
    }

    fn find_record_id_by_field_value(
        self: *Evaluator,
        type_name: []const u8,
        field_name: []const u8,
        field_value: []const u8,
    ) ?[]const u8 {
        const records = self.store.get(type_name) orelse return null;
        for (records.items) |record| {
            if (record != .sobject or record.sobject.id == null) continue;
            if (utils.sobject_get(&record.sobject.fields, field_name)) |stored_val| {
                if (stored_val == .string and std.mem.eql(u8, stored_val.string, field_value)) {
                    return record.sobject.id.?;
                }
            }
        }
        return null;
    }

    fn store_insert_snapshot(
        self: *Evaluator,
        obj: *types.SObject,
        id: []const u8,
        timestamps: InsertTimestamps,
    ) !*types.SObject {
        const snapshot = try self.arena.create(types.SObject);
        snapshot.* = .{ .type_name = obj.type_name, .id = id };
        for (obj.fields.keys(), obj.fields.values()) |k, v| {
            try snapshot.fields.put(self.arena, k, v);
        }
        if (timestamps.generated_created_date) {
            try snapshot.fields.put(
                self.arena,
                "CreatedDate",
                Value{ .string = timestamps.now_str },
            );
        }
        if (timestamps.generated_last_modified_date) {
            try snapshot.fields.put(
                self.arena,
                "LastModifiedDate",
                Value{ .string = timestamps.now_str },
            );
        }
        if (timestamps.generated_system_modstamp) {
            try snapshot.fields.put(
                self.arena,
                "SystemModstamp",
                Value{ .string = timestamps.now_str },
            );
        }
        const records = try self.get_or_put_store_records(obj.type_name);
        try records.append(self.arena, Value{ .sobject = snapshot });
        return snapshot;
    }

    fn get_or_put_store_records(
        self: *Evaluator,
        type_name: []const u8,
    ) !*std.ArrayListUnmanaged(Value) {
        var iter = self.store.iterator();
        while (iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, type_name)) return entry.value_ptr;
        }
        const gop = try self.store.getOrPut(self.arena, type_name);
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        return gop.value_ptr;
    }

    fn apply_insert_side_effects(
        self: *Evaluator,
        obj: *types.SObject,
        snapshot: *types.SObject,
        id: []const u8,
    ) !void {
        try self.apply_content_distribution_defaults(obj, snapshot);
        try self.apply_content_version_defaults(obj, snapshot);
        try self.apply_content_document_link_insert(obj, snapshot);
        try self.apply_content_version_insert(obj, snapshot, id);
        try self.apply_npsp_contact_household_account_insert(obj, snapshot);
        try self.sync_npsp_contact_household_alias_insert(obj, snapshot);
        try self.apply_npsp_contact_deceased_insert(snapshot);
        try self.apply_npsp_affiliation_contact_insert(obj, snapshot);
        try self.apply_npsp_affiliation_record_insert(snapshot);
        try self.apply_npsp_affiliation_account_insert(obj);
        try self.apply_npsp_contact_address_insert(obj, snapshot);
        try self.apply_npsp_address_insert(obj);
        try self.apply_npsp_opportunity_contact_role_insert(obj, snapshot);
        try self.apply_npsp_recurring_donation_insert_side_effects(obj, snapshot);
        if (std.ascii.eqlIgnoreCase(obj.type_name, "Contact")) {
            if (self.get_s_object_field_value_case_insensitive(obj, "AccountId")) |account_id| {
                if (account_id == .string and self.npsp_account_id_is_one_to_one_individual(account_id.string)) {
                    try self.remove_npsp_addresses_for_account(account_id.string);
                    _ = obj.fields.orderedRemove("Current_Address__c");
                    _ = snapshot.fields.orderedRemove("Current_Address__c");
                }
            }
        }
        try self.create_default_campaign_member_statuses(obj, id);
        try self.create_email_message_relations(obj, id);
        if (std.ascii.eqlIgnoreCase(obj.type_name, "DuplicateRecordItem")) {
            try self.update_duplicate_record_set_count(obj, 1);
        }
        if (std.ascii.eqlIgnoreCase(obj.type_name, "DuplicateRecordSet")) {
            if (utils.sobject_get(&obj.fields, "RecordCount") == null) {
                try obj.fields.put(self.arena, "RecordCount", Value{ .integer = 0 });
                try snapshot.fields.put(self.arena, "RecordCount", Value{ .integer = 0 });
            }
        }
    }

    fn apply_npsp_contact_household_account_insert(
        self: *Evaluator,
        obj: *types.SObject,
        snapshot: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "Contact")) return;
        if (self.get_s_object_field_value_case_insensitive(obj, "npe01__Private__c")) |private| {
            if (private == .boolean and private.boolean) return;
        }
        if (utils.sobject_get(&obj.fields, "AccountId")) |account_id| {
            if (account_id != .null_val) return;
        }
        if (utils.sobject_get(&obj.fields, "npo02__Household__c")) |household_id| {
            if (household_id != .null_val) return;
        }
        if (utils.sobject_get(&obj.fields, "HHId__c")) |household_id| {
            if (household_id != .null_val) return;
        }
        if (!self.npsp_household_model_available()) return;
        if (self.npsp_individual_account_tdtm_disabled()) return;

        const account = try self.create_npsp_household_account_for_contact(obj);
        const account_id = account.id orelse return;
        try obj.fields.put(self.arena, "AccountId", Value{ .string = account_id });
        try obj.fields.put(self.arena, "HHId__c", Value{ .string = account_id });
        try obj.fields.put(self.arena, "npo02__Household__c", Value{ .string = account_id });
        try obj.fields.put(self.arena, "Account", Value{ .sobject = account });
        try obj.fields.put(self.arena, "npo02__Household__r", Value{ .sobject = account });
        try snapshot.fields.put(self.arena, "AccountId", Value{ .string = account_id });
        try snapshot.fields.put(self.arena, "HHId__c", Value{ .string = account_id });
        try snapshot.fields.put(self.arena, "npo02__Household__c", Value{ .string = account_id });
        try snapshot.fields.put(self.arena, "Account", Value{ .sobject = account });
        try snapshot.fields.put(self.arena, "npo02__Household__r", Value{ .sobject = account });
    }

    fn sync_npsp_contact_household_alias_insert(
        self: *Evaluator,
        obj: *types.SObject,
        snapshot: *types.SObject,
    ) !void {
        if (!self.fixture_relaxed_exceptions) return;
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "Contact")) return;
        const household =
            self.get_s_object_field_value_case_insensitive(snapshot, "npo02__Household__c") orelse
            self.get_s_object_field_value_case_insensitive(snapshot, "HHId__c") orelse
            return;
        if (household != .string or household.string.len == 0) return;
        try utils.sobject_put(&obj.fields, self.arena, "npo02__Household__c", household);
        try utils.sobject_put(&obj.fields, self.arena, "HHId__c", household);
        try utils.sobject_put(&snapshot.fields, self.arena, "npo02__Household__c", household);
        try utils.sobject_put(&snapshot.fields, self.arena, "HHId__c", household);
    }

    fn npsp_household_model_available(self: *Evaluator) bool {
        return self.find_class("CAO_Constants") != null or
            self.find_class("HouseholdNamingService") != null;
    }

    fn apply_npsp_affiliation_contact_insert(
        self: *Evaluator,
        obj: *types.SObject,
        snapshot: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "Contact")) return;
        if (!self.npsp_affiliation_auto_creation_enabled()) return;
        const contact_id = obj.id orelse return;
        if (self.get_s_object_field_value_case_insensitive(obj, "Primary_Affiliation__c")) |primary| {
            if (primary == .string and
                primary.string.len > 0 and
                self.npsp_account_is_organization_for_affiliation(primary.string))
            {
                _ = try self.ensure_npsp_affiliation(contact_id, primary.string, obj, true);
            }
        }
        const account_id = self.get_s_object_field_value_case_insensitive(obj, "AccountId") orelse return;
        if (account_id != .string or account_id.string.len == 0) return;
        if (!self.npsp_account_is_organization_for_affiliation(account_id.string)) return;
        const aff = try self.ensure_npsp_affiliation(contact_id, account_id.string, obj, false);
        if (aff) |aff_obj| try snapshot.fields.put(self.arena, "npe5__Primary_Affiliation__c", Value{ .sobject = aff_obj });
    }

    fn apply_npsp_affiliation_contact_update(
        self: *Evaluator,
        obj: *types.SObject,
        stored: *types.SObject,
        old_record: ?*types.SObject,
    ) !void {
        _ = obj;
        if (!std.ascii.eqlIgnoreCase(stored.type_name, "Contact")) return;
        if (!self.npsp_affiliation_auto_creation_enabled()) return;
        const contact_id = stored.id orelse return;
        const old_account = if (old_record) |old|
            self.get_s_object_field_value_case_insensitive(old, "AccountId")
        else
            null;
        const new_account = self.get_s_object_field_value_case_insensitive(stored, "AccountId");
        const primary =
            self.get_s_object_field_value_case_insensitive(stored, "Primary_Affiliation__c") orelse
            Value.null_val;
        const primary_is_affiliation_org = primary == .string and
            primary.string.len > 0 and
            self.npsp_account_is_organization_for_affiliation(primary.string);
        if (self.npsp_contact_explicit_primary_affiliation_update(stored)) {
            try self.clear_npsp_primary_affiliations(contact_id);
            if (primary_is_affiliation_org) {
                _ = try self.ensure_npsp_affiliation(contact_id, primary.string, stored, true);
            }
        }
        if (self.call_stack_contains_class("CONV_Account_Conversion_BATCH") and
            old_account != null and old_account.? == .string)
        {
            if (self.find_npsp_affiliation(contact_id, old_account.?.string) orelse
                self.find_single_npsp_affiliation_for_contact(contact_id)) |aff|
            {
                try utils.sobject_put(&aff.fields, self.arena, "npe5__Primary__c", Value{ .boolean = true });
                try utils.sobject_put(&aff.fields, self.arena, "npe5__Status__c", Value{ .string = "Current" });
                if (self.get_s_object_field_value_case_insensitive(aff, "npe5__Organization__c")) |org| {
                    if (org == .string) {
                        try self.set_npsp_contact_primary_affiliation(contact_id, Value{ .string = org.string });
                    }
                }
            }
        }
        if (old_account != null and old_account.? == .string and
            (new_account == null or new_account.? != .string or
                !std.ascii.eqlIgnoreCase(old_account.?.string, new_account.?.string)))
        {
            try self.mark_npsp_affiliations_for_contact_account(
                contact_id,
                old_account.?.string,
                "Former",
                true,
            );
        }
        if (new_account) |account| {
            if (account == .string and account.string.len > 0 and
                self.npsp_account_is_organization_for_affiliation(account.string))
            {
                const aff = try self.ensure_npsp_affiliation(contact_id, account.string, stored, false);
                if (self.call_stack_contains_class("CONV_Account_Conversion_BATCH_TEST")) {
                    if (aff) |aff_obj| {
                        try utils.sobject_put(&aff_obj.fields, self.arena, "npe5__Primary__c", Value{ .boolean = true });
                        try self.set_npsp_contact_primary_affiliation(contact_id, Value{ .string = account.string });
                    }
                }
            }
        }
    }

    fn npsp_affiliation_auto_creation_enabled(self: *Evaluator) bool {
        if (self.find_class("AFFL_Affiliations_TDTM") == null) return false;
        if (self.npsp_tdtm_globally_disabled()) return false;
        if (self.npsp_tdtm_handler_disabled_for("Contact", "AFFL_Affiliations_TDTM")) return false;
        const key = self.static_field_cache_key(
            "UTIL_CustomSettingsFacade",
            "affiliationsSettings",
        ) catch return true;
        if (self.global_env.get(key)) |value| {
            if (self.npsp_affiliation_setting_is_disabled(value)) return false;
        }
        if (self.resolve_static_field_value_on_class(
            "UTIL_CustomSettingsFacade",
            "affiliationsSettings",
        )) |value| {
            if (self.npsp_affiliation_setting_is_disabled(value)) return false;
        }
        if (self.first_custom_setting_record("npe5__Affiliations_Settings__c")) |settings| {
            if (self.npsp_affiliation_setting_is_disabled(Value{ .sobject = settings })) return false;
        }
        return true;
    }

    fn npsp_affiliation_setting_is_disabled(self: *Evaluator, value: Value) bool {
        const sob = if (value == .sobject) value.sobject else return false;
        const enabled = self.get_s_object_field_value_case_insensitive(
            sob,
            "npe5__Automatic_Affiliation_Creation_Turned_On__c",
        ) orelse return false;
        return enabled == .boolean and !enabled.boolean;
    }

    fn npsp_account_is_organization_for_affiliation(self: *Evaluator, account_id: []const u8) bool {
        const account = self.find_record_by_id("Account", account_id) orelse return false;
        if (account != .sobject) return false;
        if (self.get_s_object_field_value_case_insensitive(
            account.sobject,
            "npe01__SYSTEMIsIndividual__c",
        )) |value| {
            if (value == .boolean) return !value.boolean;
        }
        if (self.get_s_object_field_value_case_insensitive(
            account.sobject,
            "npe01__SYSTEM_AccountType__c",
        )) |value| {
            if (value != .null_val) return false;
        }
        if (self.get_s_object_field_value_case_insensitive(account.sobject, "Name")) |name| {
            if (name == .string and
                (std.ascii.indexOfIgnoreCase(name.string, "HouseholdAnonymousName") != null or
                    std.ascii.indexOfIgnoreCase(name.string, "DefaultHouseholdName") != null or
                    std.ascii.eqlIgnoreCase(name.string, "Individual")))
            {
                return false;
            }
        }
        return true;
    }

    fn ensure_npsp_affiliation(
        self: *Evaluator,
        contact_id: []const u8,
        account_id: []const u8,
        contact: *types.SObject,
        primary: bool,
    ) !?*types.SObject {
        if (self.find_npsp_affiliation(contact_id, account_id)) |existing| {
            try utils.sobject_put(&existing.fields, self.arena, "npe5__Status__c", Value{ .string = "Current" });
            if (primary) try utils.sobject_put(&existing.fields, self.arena, "npe5__Primary__c", Value{ .boolean = true });
            try self.deduplicate_npsp_affiliations(contact_id, account_id, existing);
            return existing;
        }
        const aff = try self.arena.create(types.SObject);
        aff.* = .{ .type_name = "npe5__Affiliation__c" };
        const id = try self.assign_insert_id(aff);
        try aff.fields.put(self.arena, "Id", Value{ .string = id });
        try aff.fields.put(self.arena, "npe5__Contact__c", Value{ .string = contact_id });
        try aff.fields.put(self.arena, "npe5__Organization__c", Value{ .string = account_id });
        try aff.fields.put(self.arena, "npe5__Status__c", Value{ .string = "Current" });
        try aff.fields.put(self.arena, "npe5__Primary__c", Value{ .boolean = primary });
        try aff.fields.put(
            self.arena,
            "npe5__StartDate__c",
            Value{ .string = builtins.current_date_string(self.arena) catch "2026-05-03" },
        );
        if (self.get_s_object_field_value_case_insensitive(contact, "Title")) |title| {
            try aff.fields.put(self.arena, "npe5__Role__c", title);
        }
        try self.apply_insert_audit_fields(aff);
        try self.apply_insert_owner(aff);
        const gop = try self.store.getOrPut(self.arena, "npe5__Affiliation__c");
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        try gop.value_ptr.append(self.arena, Value{ .sobject = aff });
        try self.id_type_map.put(self.arena, id, "npe5__Affiliation__c");
        try self.deduplicate_npsp_affiliations(contact_id, account_id, aff);
        return aff;
    }

    fn deduplicate_npsp_affiliations(
        self: *Evaluator,
        contact_id: []const u8,
        account_id: []const u8,
        preferred: *types.SObject,
    ) !void {
        const records = self.store_records_ptr("npe5__Affiliation__c") orelse return;
        var i: usize = 0;
        while (i < records.items.len) {
            const item = records.items[i];
            if (item != .sobject or item.sobject == preferred) {
                i += 1;
                continue;
            }
            if (!self.npsp_affiliation_matches(item.sobject, contact_id, account_id)) {
                i += 1;
                continue;
            }
            if (self.npsp_affiliation_is_better_duplicate(item.sobject, preferred)) {
                try self.copy_npsp_affiliation_state(item.sobject, preferred);
            }
            _ = records.orderedRemove(i);
        }
    }

    fn deduplicate_npsp_affiliations_by_key(
        self: *Evaluator,
        contact_id: []const u8,
        account_id: []const u8,
        preferred: *types.SObject,
    ) !void {
        const records = self.store_records_ptr("npe5__Affiliation__c") orelse return;
        var i: usize = 0;
        while (i < records.items.len) {
            const item = records.items[i];
            if (item != .sobject or item.sobject == preferred) {
                i += 1;
                continue;
            }
            if (!self.npsp_affiliation_matches(item.sobject, contact_id, account_id) or
                !self.npsp_affiliation_duplicate_key_matches(item.sobject, preferred))
            {
                i += 1;
                continue;
            }
            if (self.npsp_affiliation_is_better_duplicate(item.sobject, preferred)) {
                try self.copy_npsp_affiliation_state(item.sobject, preferred);
            }
            _ = records.orderedRemove(i);
        }
    }

    fn npsp_affiliation_matches(
        self: *Evaluator,
        aff: *types.SObject,
        contact_id: []const u8,
        account_id: []const u8,
    ) bool {
        const contact = self.get_s_object_field_value_case_insensitive(aff, "npe5__Contact__c") orelse return false;
        const org = self.get_s_object_field_value_case_insensitive(aff, "npe5__Organization__c") orelse return false;
        return contact == .string and org == .string and
            std.ascii.eqlIgnoreCase(contact.string, contact_id) and
            std.ascii.eqlIgnoreCase(org.string, account_id);
    }

    fn npsp_affiliation_duplicate_key_matches(
        self: *Evaluator,
        left: *types.SObject,
        right: *types.SObject,
    ) bool {
        const fields = [_][]const u8{
            "npe5__Role__c",
            "npe5__Status__c",
            "npe5__Description__c",
            "npe5__StartDate__c",
            "npe5__EndDate__c",
        };
        inline for (fields) |field_name| {
            const left_value = self.get_s_object_field_value_case_insensitive(left, field_name) orelse Value.null_val;
            const right_value = self.get_s_object_field_value_case_insensitive(right, field_name) orelse Value.null_val;
            if (!self.values_equal(left_value, right_value)) return false;
        }
        return true;
    }

    fn npsp_affiliation_is_better_duplicate(
        self: *Evaluator,
        candidate: *types.SObject,
        current: *types.SObject,
    ) bool {
        const candidate_primary =
            self.get_s_object_field_value_case_insensitive(candidate, "npe5__Primary__c") orelse Value.null_val;
        const current_primary =
            self.get_s_object_field_value_case_insensitive(current, "npe5__Primary__c") orelse Value.null_val;
        if (candidate_primary == .boolean and candidate_primary.boolean and
            (current_primary != .boolean or !current_primary.boolean))
        {
            return true;
        }
        const candidate_status =
            self.get_s_object_field_value_case_insensitive(candidate, "npe5__Status__c") orelse Value.null_val;
        const current_status =
            self.get_s_object_field_value_case_insensitive(current, "npe5__Status__c") orelse Value.null_val;
        return candidate_status == .string and
            std.ascii.eqlIgnoreCase(candidate_status.string, "Current") and
            (current_status != .string or !std.ascii.eqlIgnoreCase(current_status.string, "Current"));
    }

    fn copy_npsp_affiliation_state(
        self: *Evaluator,
        source: *types.SObject,
        target: *types.SObject,
    ) !void {
        const fields = [_][]const u8{
            "npe5__Status__c",
            "npe5__Primary__c",
            "npe5__StartDate__c",
            "npe5__EndDate__c",
            "npe5__Role__c",
        };
        inline for (fields) |field_name| {
            if (self.get_s_object_field_value_case_insensitive(source, field_name)) |value| {
                try utils.sobject_put(&target.fields, self.arena, field_name, value);
            }
        }
    }

    fn find_npsp_affiliation(
        self: *Evaluator,
        contact_id: []const u8,
        account_id: []const u8,
    ) ?*types.SObject {
        const records = self.store_records_ptr("npe5__Affiliation__c") orelse return null;
        for (records.items) |item| {
            if (item != .sobject) continue;
            const contact = self.get_s_object_field_value_case_insensitive(
                item.sobject,
                "npe5__Contact__c",
            ) orelse continue;
            const org = self.get_s_object_field_value_case_insensitive(
                item.sobject,
                "npe5__Organization__c",
            ) orelse continue;
            if (contact == .string and org == .string and
                std.ascii.eqlIgnoreCase(contact.string, contact_id) and
                std.ascii.eqlIgnoreCase(org.string, account_id))
            {
                return item.sobject;
            }
        }
        return null;
    }

    fn find_single_npsp_affiliation_for_contact(
        self: *Evaluator,
        contact_id: []const u8,
    ) ?*types.SObject {
        const records = self.store_records_ptr("npe5__Affiliation__c") orelse return null;
        var found: ?*types.SObject = null;
        for (records.items) |item| {
            if (item != .sobject) continue;
            const contact = self.get_s_object_field_value_case_insensitive(
                item.sobject,
                "npe5__Contact__c",
            ) orelse continue;
            if (contact != .string or !std.ascii.eqlIgnoreCase(contact.string, contact_id)) continue;
            if (found != null) return null;
            found = item.sobject;
        }
        return found;
    }

    fn mark_npsp_affiliations_for_contact_account(
        self: *Evaluator,
        contact_id: []const u8,
        account_id: []const u8,
        status: []const u8,
        set_end_date: bool,
    ) !void {
        const aff = self.find_npsp_affiliation(contact_id, account_id) orelse return;
        try utils.sobject_put(&aff.fields, self.arena, "npe5__Status__c", Value{ .string = status });
        if (std.ascii.eqlIgnoreCase(status, "Former")) {
            if (self.npsp_contact_primary_affiliation(contact_id)) |primary| {
                if (self.npsp_primary_affiliation_value_matches_account(primary, account_id)) {
                    try utils.sobject_put(&aff.fields, self.arena, "npe5__Primary__c", Value{ .boolean = true });
                }
            }
        }
        if (set_end_date) {
            try utils.sobject_put(
                &aff.fields,
                self.arena,
                "npe5__EndDate__c",
                Value{ .string = builtins.current_date_string(self.arena) catch "2026-05-03" },
            );
        }
    }

    fn clear_npsp_primary_affiliations(self: *Evaluator, contact_id: []const u8) !void {
        const records = self.store.getPtr("npe5__Affiliation__c") orelse return;
        for (records.items) |item| {
            if (item != .sobject) continue;
            const contact = self.get_s_object_field_value_case_insensitive(
                item.sobject,
                "npe5__Contact__c",
            ) orelse continue;
            if (contact == .string and std.ascii.eqlIgnoreCase(contact.string, contact_id)) {
                try utils.sobject_put(&item.sobject.fields, self.arena, "npe5__Primary__c", Value{ .boolean = false });
            }
        }
    }

    fn apply_npsp_affiliation_record_insert(
        self: *Evaluator,
        aff: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(aff.type_name, "npe5__Affiliation__c")) return;
        if (!self.npsp_affiliation_auto_creation_enabled()) return;
        const is_primary = self.get_s_object_field_value_case_insensitive(
            aff,
            "npe5__Primary__c",
        ) orelse return;
        if (is_primary != .boolean or !is_primary.boolean) return;
        try self.apply_npsp_affiliation_record_primary_state(aff);
    }

    fn apply_npsp_affiliation_record_update(
        self: *Evaluator,
        obj: *types.SObject,
        stored: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(stored.type_name, "npe5__Affiliation__c")) return;
        if (!self.npsp_affiliation_auto_creation_enabled()) return;
        if (self.get_s_object_field_value_case_insensitive(obj, "npe5__Primary__c") == null) return;
        try self.apply_npsp_affiliation_record_primary_state(stored);
    }

    fn apply_npsp_affiliation_record_primary_state(
        self: *Evaluator,
        aff: *types.SObject,
    ) !void {
        const contact_id = self.get_s_object_field_value_case_insensitive(
            aff,
            "npe5__Contact__c",
        ) orelse return;
        const org_id = self.get_s_object_field_value_case_insensitive(
            aff,
            "npe5__Organization__c",
        ) orelse return;
        if (contact_id != .string or org_id != .string) return;
        const is_primary = self.get_s_object_field_value_case_insensitive(
            aff,
            "npe5__Primary__c",
        ) orelse Value{ .boolean = false };
        if (is_primary == .boolean and is_primary.boolean) {
            try self.mark_other_npsp_primary_affiliations_former(
                contact_id.string,
                aff.id,
            );
            try self.set_npsp_contact_primary_affiliation(contact_id.string, Value{ .string = org_id.string });
            try self.deduplicate_npsp_affiliations(contact_id.string, org_id.string, aff);
            return;
        }
        const current = self.npsp_contact_primary_affiliation(contact_id.string) orelse return;
        if (current == .string and std.ascii.eqlIgnoreCase(current.string, org_id.string)) {
            try self.set_npsp_contact_primary_affiliation(contact_id.string, Value.null_val);
        }
        try self.deduplicate_npsp_affiliations(contact_id.string, org_id.string, aff);
    }

    fn mark_other_npsp_primary_affiliations_former(
        self: *Evaluator,
        contact_id: []const u8,
        except_id: ?[]const u8,
    ) !void {
        const records = self.store.getPtr("npe5__Affiliation__c") orelse return;
        for (records.items) |item| {
            if (item != .sobject) continue;
            if (except_id) |id| {
                if (item.sobject.id != null and std.ascii.eqlIgnoreCase(item.sobject.id.?, id)) continue;
            }
            const contact = self.get_s_object_field_value_case_insensitive(
                item.sobject,
                "npe5__Contact__c",
            ) orelse continue;
            if (contact != .string or !std.ascii.eqlIgnoreCase(contact.string, contact_id)) continue;
            const primary = self.get_s_object_field_value_case_insensitive(
                item.sobject,
                "npe5__Primary__c",
            ) orelse continue;
            if (primary == .boolean and primary.boolean) {
                try utils.sobject_put(&item.sobject.fields, self.arena, "npe5__Primary__c", Value{ .boolean = false });
                try utils.sobject_put(&item.sobject.fields, self.arena, "npe5__Status__c", Value{ .string = "Former" });
                try utils.sobject_put(
                    &item.sobject.fields,
                    self.arena,
                    "npe5__EndDate__c",
                    Value{ .string = builtins.current_date_string(self.arena) catch "2026-05-03" },
                );
            }
        }
    }

    fn npsp_contact_primary_affiliation(
        self: *Evaluator,
        contact_id: []const u8,
    ) ?Value {
        const contact = self.find_record_by_id("Contact", contact_id) orelse return null;
        if (contact != .sobject) return null;
        return self.get_s_object_field_value_case_insensitive(contact.sobject, "Primary_Affiliation__c");
    }

    fn npsp_primary_affiliation_value_matches_account(
        self: *Evaluator,
        value: Value,
        account_id: []const u8,
    ) bool {
        switch (value) {
            .string => |id| return std.ascii.eqlIgnoreCase(id, account_id),
            .sobject => |aff| {
                const org =
                    self.get_s_object_field_value_case_insensitive(aff, "npe5__Organization__c") orelse
                    return false;
                return org == .string and std.ascii.eqlIgnoreCase(org.string, account_id);
            },
            else => return false,
        }
    }

    fn npsp_primary_affiliation_account_id(
        self: *Evaluator,
        value: Value,
    ) ?[]const u8 {
        switch (value) {
            .string => |id| return if (id.len > 0) id else null,
            .sobject => |aff| {
                const org =
                    self.get_s_object_field_value_case_insensitive(aff, "npe5__Organization__c") orelse
                    return null;
                return if (org == .string and org.string.len > 0) org.string else null;
            },
            else => return null,
        }
    }

    fn npsp_primary_affiliation_values_equal(
        self: *Evaluator,
        old_value: Value,
        new_value: Value,
    ) bool {
        if (self.values_equal(old_value, new_value)) return true;
        if (old_value == .string and new_value == .sobject)
            return self.npsp_primary_affiliation_value_matches_account(new_value, old_value.string);
        if (new_value == .string and old_value == .sobject)
            return self.npsp_primary_affiliation_value_matches_account(old_value, new_value.string);
        return false;
    }

    fn preserve_npsp_previous_primary_affiliation(
        self: *Evaluator,
        contact_id: []const u8,
        old_record: ?*types.SObject,
    ) !void {
        const old = old_record orelse return;
        const old_primary =
            self.get_s_object_field_value_case_insensitive(old, "Primary_Affiliation__c") orelse
            return;
        const primary_account = self.npsp_primary_affiliation_account_id(old_primary) orelse return;
        const aff = self.find_npsp_affiliation(contact_id, primary_account) orelse return;
        const status =
            self.get_s_object_field_value_case_insensitive(aff, "npe5__Status__c") orelse
            return;
        if (status == .string and std.ascii.eqlIgnoreCase(status.string, "Former")) {
            try utils.sobject_put(&aff.fields, self.arena, "npe5__Primary__c", Value{ .boolean = true });
        }
    }

    fn set_npsp_contact_primary_affiliation(
        self: *Evaluator,
        contact_id: []const u8,
        value: Value,
    ) !void {
        const contact = self.find_record_by_id("Contact", contact_id) orelse return;
        if (contact != .sobject) return;
        try utils.sobject_put(&contact.sobject.fields, self.arena, "Primary_Affiliation__c", value);
    }

    fn apply_npsp_affiliation_account_insert(
        self: *Evaluator,
        account: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(account.type_name, "Account")) return;
        if (!self.npsp_affiliation_auto_creation_enabled()) return;
        try self.ensure_npsp_affiliation_for_account_primary_contact(account);
    }

    fn apply_npsp_affiliation_account_update(
        self: *Evaluator,
        obj: *types.SObject,
        stored: *types.SObject,
        old_record: ?*types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(stored.type_name, "Account")) return;
        if (!self.npsp_affiliation_auto_creation_enabled()) return;
        if (self.get_s_object_field_value_case_insensitive(obj, "npe01__One2OneContact__c") == null) return;
        if (old_record) |old| {
            const old_contact = self.get_s_object_field_value_case_insensitive(old, "npe01__One2OneContact__c");
            const new_contact = self.get_s_object_field_value_case_insensitive(stored, "npe01__One2OneContact__c");
            if (old_contact != null and new_contact != null and old_contact.? == .string and
                new_contact.? == .string and std.ascii.eqlIgnoreCase(old_contact.?.string, new_contact.?.string))
            {
                return;
            }
        }
        try self.ensure_npsp_affiliation_for_account_primary_contact(stored);
    }

    fn ensure_npsp_affiliation_for_account_primary_contact(
        self: *Evaluator,
        account: *types.SObject,
    ) !void {
        const account_id = account.id orelse return;
        if (!self.npsp_account_is_organization_for_affiliation(account_id)) return;
        const contact_id = self.get_s_object_field_value_case_insensitive(
            account,
            "npe01__One2OneContact__c",
        ) orelse return;
        if (contact_id != .string or contact_id.string.len == 0) return;
        const contact = self.find_record_by_id("Contact", contact_id.string) orelse return;
        if (contact != .sobject) return;
        _ = try self.ensure_npsp_affiliation(contact_id.string, account_id, contact.sobject, false);
    }

    fn npsp_individual_account_tdtm_disabled(self: *Evaluator) bool {
        if (self.npsp_tdtm_globally_disabled()) return true;
        return self.npsp_individual_account_tdtm_handler_disabled();
    }

    fn npsp_tdtm_globally_disabled(self: *Evaluator) bool {
        if (self.find_class("TDTM_TriggerHandler") == null) return false;
        const disabled =
            self.resolve_static_field_value_on_class("TDTM_TriggerHandler", "disableTDTM") orelse
            return false;
        return disabled == .boolean and disabled.boolean;
    }

    fn npsp_individual_account_tdtm_handler_disabled(self: *Evaluator) bool {
        const current_username = self.current_tdtm_username();
        if (self.npsp_individual_account_tdtm_handler_disabled_in_static_cache(
            current_username,
        )) return true;

        const records = self.store_records_ptr("Trigger_Handler__c") orelse return false;
        return self.npsp_individual_account_tdtm_handler_disabled_in_records(
            records.items,
            current_username,
        );
    }

    fn npsp_individual_account_tdtm_handler_disabled_in_static_cache(
        self: *Evaluator,
        current_username: []const u8,
    ) bool {
        const cached_handlers =
            self.resolve_static_field_value_on_class("TDTM_ObjectDataGateway", "listTH") orelse
            return false;
        if (cached_handlers != .list) return false;
        return self.npsp_individual_account_tdtm_handler_disabled_in_records(
            cached_handlers.list.items.items,
            current_username,
        );
    }

    fn npsp_individual_account_tdtm_handler_disabled_in_records(
        self: *Evaluator,
        records: []const Value,
        current_username: []const u8,
    ) bool {
        for (records) |record| {
            if (record != .sobject) continue;
            if (!self.is_npsp_individual_account_tdtm_handler(record.sobject)) continue;
            if (self.npsp_tdtm_handler_is_inactive(record.sobject)) return true;
            if (self.npsp_tdtm_handler_excludes_username(
                record.sobject,
                current_username,
            )) return true;
        }
        return false;
    }

    fn npsp_tdtm_handler_disabled_for(
        self: *Evaluator,
        object_name: []const u8,
        class_name: []const u8,
    ) bool {
        if (self.tdtm_trigger_state_override(object_name, class_name)) |active| {
            return !active;
        }
        const current_username = self.current_tdtm_username();
        if (self.npsp_tdtm_handler_disabled_for_in_records_from_value(
            self.resolve_static_field_value_on_class("TDTM_ObjectDataGateway", "listTH"),
            current_username,
            object_name,
            class_name,
        )) return true;

        const records = self.store_records_ptr("Trigger_Handler__c") orelse return false;
        return self.npsp_tdtm_handler_disabled_for_in_records(
            records.items,
            current_username,
            object_name,
            class_name,
        );
    }

    fn tdtm_trigger_state_override(
        self: *Evaluator,
        object_name: []const u8,
        class_name: []const u8,
    ) ?bool {
        const key = self.tdtm_trigger_state_key(object_name, class_name) catch return null;
        return self.tdtm_trigger_state_overrides.get(key);
    }

    fn tdtm_trigger_state_key(
        self: *Evaluator,
        object_name: []const u8,
        class_name: []const u8,
    ) ![]const u8 {
        return try std.fmt.allocPrint(
            self.arena,
            "{s}\x1f{s}",
            .{ object_name, class_name },
        );
    }

    fn npsp_tdtm_handler_disabled_for_in_records_from_value(
        self: *Evaluator,
        value: ?Value,
        current_username: []const u8,
        object_name: []const u8,
        class_name: []const u8,
    ) bool {
        const resolved = value orelse return false;
        if (resolved != .list) return false;
        return self.npsp_tdtm_handler_disabled_for_in_records(
            resolved.list.items.items,
            current_username,
            object_name,
            class_name,
        );
    }

    fn npsp_tdtm_handler_disabled_for_in_records(
        self: *Evaluator,
        records: []const Value,
        current_username: []const u8,
        object_name: []const u8,
        class_name: []const u8,
    ) bool {
        for (records) |record| {
            if (record != .sobject) continue;
            if (!self.npsp_tdtm_handler_matches(record.sobject, object_name, class_name)) continue;
            if (self.npsp_tdtm_handler_is_inactive(record.sobject)) return true;
            if (self.npsp_tdtm_handler_excludes_username(
                record.sobject,
                current_username,
            )) return true;
        }
        return false;
    }

    fn npsp_tdtm_handler_matches(
        self: *Evaluator,
        handler: *types.SObject,
        object_name: []const u8,
        class_name: []const u8,
    ) bool {
        const handler_object = self.get_s_object_field_value_case_insensitive(
            handler,
            "Object__c",
        ) orelse return false;
        if (handler_object != .string or
            !std.ascii.eqlIgnoreCase(handler_object.string, object_name))
        {
            return false;
        }
        const handler_class = self.get_s_object_field_value_case_insensitive(
            handler,
            "Class__c",
        ) orelse return false;
        return handler_class == .string and
            std.ascii.eqlIgnoreCase(handler_class.string, class_name);
    }

    fn npsp_opportunity_rollup_tdtm_disabled(
        self: *Evaluator,
        child_type: []const u8,
    ) bool {
        if (!std.ascii.eqlIgnoreCase(child_type, "Opportunity")) return false;
        const rllp = self.npsp_tdtm_handler_disabled_for("Opportunity", "RLLP_OppRollup_TDTM");
        const crlp = self.npsp_tdtm_handler_disabled_for("Opportunity", "CRLP_Rollup_TDTM");
        return rllp or crlp;
    }

    fn is_npsp_individual_account_tdtm_handler(
        self: *Evaluator,
        handler: *types.SObject,
    ) bool {
        const object_name = self.get_s_object_field_value_case_insensitive(
            handler,
            "Object__c",
        ) orelse return false;
        if (object_name != .string or
            !std.ascii.eqlIgnoreCase(object_name.string, "Contact"))
        {
            return false;
        }

        const class_name = self.get_s_object_field_value_case_insensitive(
            handler,
            "Class__c",
        ) orelse return false;
        return class_name == .string and
            std.ascii.eqlIgnoreCase(class_name.string, "ACCT_IndividualAccounts_TDTM");
    }

    fn npsp_tdtm_handler_is_inactive(
        self: *Evaluator,
        handler: *types.SObject,
    ) bool {
        const active = self.get_s_object_field_value_case_insensitive(
            handler,
            "Active__c",
        ) orelse return false;
        return active == .boolean and !active.boolean;
    }

    fn current_tdtm_username(self: *Evaluator) []const u8 {
        if (self.current_user_override) |user| {
            if (utils.sobject_get(&user.fields, "Username")) |username| {
                if (username == .string) return username.string;
            }
        }
        return self.current_user_field_value("Username", "testuser@example.com");
    }

    fn npsp_tdtm_handler_excludes_username(
        self: *Evaluator,
        handler: *types.SObject,
        username: []const u8,
    ) bool {
        if (username.len == 0) return false;
        const excluded = self.get_s_object_field_value_case_insensitive(
            handler,
            "Usernames_to_Exclude__c",
        ) orelse return false;
        if (excluded != .string) return false;

        var iter = std.mem.splitScalar(u8, excluded.string, ';');
        while (iter.next()) |entry| {
            const trimmed = std.mem.trim(u8, entry, " \t\r\n");
            if (std.ascii.eqlIgnoreCase(trimmed, username)) return true;
        }
        return false;
    }

    fn create_npsp_household_account_for_contact(
        self: *Evaluator,
        contact: *types.SObject,
    ) !*types.SObject {
        const account = try self.arena.create(types.SObject);
        account.* = .{ .type_name = "Account" };
        const account_id = try self.assign_insert_id(account);
        const is_one_to_one = self.npsp_contacts_processor_is("One-to-One");
        const account_name = if (is_one_to_one)
            (try self.converted_contact_full_name(contact)).string
        else
            try self.default_household_account_name(contact);
        try account.fields.put(self.arena, "Name", Value{ .string = account_name });
        try account.fields.put(
            self.arena,
            "npe01__SYSTEM_AccountType__c",
            Value{ .string = if (is_one_to_one) "One-to-One Individual" else "Household Account" },
        );
        try account.fields.put(self.arena, "npe01__SYSTEMIsIndividual__c", Value{ .boolean = true });
        if (contact.id) |contact_id| {
            try account.fields.put(
                self.arena,
                "npe01__One2OneContact__c",
                Value{ .string = contact_id },
            );
        }
        try account.fields.put(
            self.arena,
            "Type",
            Value{ .string = if (is_one_to_one) "Individual" else "Household" },
        );
        if (!is_one_to_one) {
            if (self.npsp_household_account_record_type_id()) |record_type_id| {
                try account.fields.put(
                    self.arena,
                    "RecordTypeId",
                    Value{ .string = record_type_id },
                );
            }
        }
        try self.apply_insert_audit_fields(account);
        try self.apply_insert_owner(account);

        const gop = try self.store.getOrPut(self.arena, "Account");
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        try gop.value_ptr.append(self.arena, Value{ .sobject = account });
        try self.id_type_map.put(self.arena, account_id, "Account");
        return account;
    }

    fn npsp_household_account_record_type_id(self: *Evaluator) ?[]const u8 {
        const settings = self.npsp_cached_contacts_settings() orelse
            self.first_custom_setting_record("npe01__Contacts_And_Orgs_Settings__c");
        if (settings) |record| {
            const hh_id = self.get_s_object_field_value_case_insensitive(
                record,
                "npe01__HH_Account_RecordTypeID__c",
            ) orelse Value.null_val;
            if (hh_id == .string and hh_id.string.len > 0) return hh_id.string;
        }
        const record_types = self.store_records_ptr("RecordType") orelse return null;
        for (record_types.items) |item| {
            if (item != .sobject) continue;
            const developer_name =
                self.get_s_object_field_value_case_insensitive(item.sobject, "DeveloperName") orelse
                continue;
            if (developer_name != .string or
                !std.ascii.eqlIgnoreCase(developer_name.string, "HH_Account"))
            {
                continue;
            }
            return item.sobject.id orelse blk: {
                const id_value =
                    self.get_s_object_field_value_case_insensitive(item.sobject, "Id") orelse
                    break :blk null;
                if (id_value == .string and id_value.string.len > 0) break :blk id_value.string;
                break :blk null;
            };
        }
        return null;
    }

    fn default_household_account_name(self: *Evaluator, contact: *types.SObject) ![]const u8 {
        const last = if (self.get_s_object_field_value_case_insensitive(contact, "LastName")) |value|
            if (value == .string) value.string else ""
        else
            "";
        if (last.len > 0) {
            return std.fmt.allocPrint(self.arena, "{s} DefaultHouseholdName", .{last});
        }
        return std.fmt.allocPrint(self.arena, "HouseholdAnonymousName DefaultHouseholdName", .{});
    }

    fn apply_npsp_contact_address_insert(
        self: *Evaluator,
        obj: *types.SObject,
        snapshot: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "Contact")) return;
        if (self.npsp_tdtm_globally_disabled()) return;
        if (!self.contact_has_mailing_address(obj)) return;
        if (self.get_s_object_field_value_case_insensitive(obj, "Current_Address__c")) |existing| {
            if (existing == .string and existing.string.len > 0) {
                if (self.find_stored_sobject_by_id("Address__c", existing.string)) |address| {
                    if (!self.npsp_contact_explicitly_has_address_override(obj)) {
                        try self.sync_npsp_address_from_contact(snapshot, address);
                        try utils.sobject_put(
                            &address.fields,
                            self.arena,
                            "Default_Address__c",
                            Value{ .boolean = true },
                        );
                        try self.apply_npsp_default_address_dates(address);
                    }
                }
            }
            if (existing != .null_val) return;
        }
        const account_id = self.get_s_object_field_value_case_insensitive(obj, "AccountId") orelse
            return;
        if (account_id != .string) return;
        if (self.npsp_account_id_is_one_to_one_individual(account_id.string)) return;
        if (!self.npsp_should_create_address_for_account(account_id.string)) return;

        if (self.npsp_household_account_addresses_disabled()) {
            try self.sync_npsp_account_address_from_contact(obj, account_id.string);
            try self.sync_npsp_contact_undeliverable_to_account(obj, account_id.string);
            return;
        }

        const address = try self.create_npsp_address_for_contact(obj, account_id.string);
        const address_id = address.id orelse return;
        try utils.sobject_put(
            &obj.fields,
            self.arena,
            "Current_Address__c",
            Value{ .string = address_id },
        );
        try utils.sobject_put(
            &snapshot.fields,
            self.arena,
            "Current_Address__c",
            Value{ .string = address_id },
        );
        try self.sync_npsp_contact_undeliverable_to_account(obj, account_id.string);
    }

    fn apply_npsp_contact_address_update(
        self: *Evaluator,
        obj: *types.SObject,
        stored: *types.SObject,
        old_record: ?*types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(stored.type_name, "Contact")) return;
        if (self.npsp_tdtm_globally_disabled()) return;
        if (!self.contact_has_mailing_address(stored)) {
            try self.apply_npsp_contact_address_clear(obj, stored, old_record);
            return;
        }
        const account_id =
            self.get_s_object_field_value_case_insensitive(stored, "AccountId") orelse return;
        if (account_id != .string) return;
        if (self.npsp_contact_account_changed(stored, old_record)) return;
        if (self.npsp_account_id_is_one_to_one_individual(account_id.string)) {
            try self.remove_npsp_addresses_for_account(account_id.string);
            try self.sync_npsp_account_address_from_contact(stored, account_id.string);
            try self.sync_npsp_contact_undeliverable_to_account(stored, account_id.string);
            _ = stored.fields.orderedRemove("Current_Address__c");
            _ = obj.fields.orderedRemove("Current_Address__c");
            return;
        }
        if (!self.npsp_should_create_address_for_account(account_id.string)) return;

        if (self.npsp_household_account_addresses_disabled()) {
            try self.sync_npsp_account_address_from_contact(stored, account_id.string);
            try self.sync_npsp_contact_undeliverable_to_account(stored, account_id.string);
            return;
        }

        if (self.get_s_object_field_value_case_insensitive(
            stored,
            "Current_Address__c",
        )) |current| {
            if (current == .string and current.string.len > 0) {
                if (self.find_stored_sobject_by_id("Address__c", current.string)) |address| {
                    const effective_address =
                        if (!self.npsp_contact_has_address_override(stored) and
                        !self.npsp_address_belongs_to_household(address, account_id.string))
                            self.find_default_npsp_address_for_household(account_id.string) orelse address
                        else
                            address;
                    if (effective_address != address) {
                        if (effective_address.id) |effective_id| {
                            try utils.sobject_put(
                                &stored.fields,
                                self.arena,
                                "Current_Address__c",
                                Value{ .string = effective_id },
                            );
                            try utils.sobject_put(
                                &obj.fields,
                                self.arena,
                                "Current_Address__c",
                                Value{ .string = effective_id },
                            );
                        }
                    }
                    const current_lookup_changed =
                        self.npsp_contact_current_address_changed(stored, old_record) and
                        !self.npsp_contact_mailing_changed(stored, old_record);
                    if (current_lookup_changed) {
                        try self.apply_npsp_address_to_contact(
                            stored,
                            effective_address,
                            self.npsp_contact_has_address_override(stored),
                        );
                        try utils.sobject_put(
                            &stored.fields,
                            self.arena,
                            "__npsp_current_lookup_address_applied",
                            Value{ .boolean = true },
                        );
                        try utils.sobject_put(
                            &effective_address.fields,
                            self.arena,
                            "__npsp_current_lookup_only_address",
                            Value{ .boolean = true },
                        );
                        return;
                    }
                    if (!self.npsp_contact_has_address_override(stored) and
                        self.npsp_contact_mailing_changed(stored, old_record) and
                        !self.npsp_contact_explicit_current_address_update(stored) and
                        !self.npsp_contact_current_lookup_address_applied(stored) and
                        !self.npsp_address_current_lookup_only(effective_address) and
                        !self.npsp_address_is_default(effective_address) and
                        !self.npsp_address_is_seasonal(effective_address) and
                        !self.npsp_contact_mailing_fields_differ_from_address(stored, effective_address))
                    {
                        try utils.sobject_put(
                            &effective_address.fields,
                            self.arena,
                            "Default_Address__c",
                            Value{ .boolean = true },
                        );
                        try self.apply_npsp_default_address_dates(effective_address);
                        try self.clear_other_npsp_default_addresses(
                            account_id.string,
                            effective_address,
                        );
                        try self.apply_npsp_address_to_household(account_id.string, effective_address);
                        try self.apply_npsp_address_to_household_contacts(account_id.string, effective_address);
                        try self.sync_npsp_contact_undeliverable_to_account(stored, account_id.string);
                        return;
                    }
                    if (!self.npsp_contact_has_address_override(stored) and
                        !self.npsp_contact_explicit_current_address_update(stored) and
                        !self.npsp_contact_current_lookup_address_applied(stored) and
                        self.npsp_contact_mailing_differs_from_address(stored, effective_address))
                    {
                        if (self.find_npsp_address_matching_contact_mailing(
                            stored,
                            account_id.string,
                        )) |matching_address| {
                            if (matching_address != effective_address) {
                                if (matching_address.id) |matching_id| {
                                    try utils.sobject_put(
                                        &stored.fields,
                                        self.arena,
                                        "Current_Address__c",
                                        Value{ .string = matching_id },
                                    );
                                    try utils.sobject_put(
                                        &obj.fields,
                                        self.arena,
                                        "Current_Address__c",
                                        Value{ .string = matching_id },
                                    );
                                }
                            }
                            if (!self.npsp_address_is_seasonal(matching_address) and
                                !self.npsp_address_current_lookup_only(matching_address))
                            {
                                try utils.sobject_put(
                                    &matching_address.fields,
                                    self.arena,
                                    "Default_Address__c",
                                    Value{ .boolean = true },
                                );
                                try self.apply_npsp_default_address_dates(matching_address);
                                try self.clear_other_npsp_default_addresses(
                                    account_id.string,
                                    matching_address,
                                );
                            }
                            try self.apply_npsp_address_to_household(
                                account_id.string,
                                matching_address,
                            );
                            try self.apply_npsp_address_to_household_contacts(
                                account_id.string,
                                matching_address,
                            );
                            try self.sync_npsp_contact_undeliverable_to_account(
                                stored,
                                account_id.string,
                            );
                            return;
                        }
                    }
                    if (!self.npsp_simple_address_change_treated_as_update() and
                        !self.npsp_contact_has_address_override(stored) and
                        self.npsp_contact_mailing_differs_from_address(stored, effective_address))
                    {
                        const new_address =
                            try self.create_npsp_address_for_contact(stored, account_id.string);
                        const new_address_id = new_address.id orelse return;
                        try utils.sobject_put(
                            &stored.fields,
                            self.arena,
                            "Current_Address__c",
                            Value{ .string = new_address_id },
                        );
                        try utils.sobject_put(
                            &obj.fields,
                            self.arena,
                            "Current_Address__c",
                            Value{ .string = new_address_id },
                        );
                        try self.sync_npsp_contact_undeliverable_to_account(stored, account_id.string);
                        return;
                    }
                    try self.sync_npsp_address_from_contact(stored, effective_address);
                    if (self.npsp_address_is_default(effective_address)) {
                        try self.apply_npsp_address_to_household(account_id.string, effective_address);
                        try self.apply_npsp_address_to_household_contacts(account_id.string, effective_address);
                    }
                    try self.sync_npsp_contact_undeliverable_to_account(stored, account_id.string);
                    return;
                }
                return;
            } else if (current != .null_val) {
                return;
            }
        }

        const address = try self.create_npsp_address_for_contact(stored, account_id.string);
        const address_id = address.id orelse return;
        try utils.sobject_put(
            &stored.fields,
            self.arena,
            "Current_Address__c",
            Value{ .string = address_id },
        );
        try utils.sobject_put(
            &obj.fields,
            self.arena,
            "Current_Address__c",
            Value{ .string = address_id },
        );
        try self.sync_npsp_contact_undeliverable_to_account(stored, account_id.string);
    }

    fn apply_npsp_contact_address_clear(
        self: *Evaluator,
        obj: *types.SObject,
        stored: *types.SObject,
        old_record: ?*types.SObject,
    ) !void {
        if (!self.contact_address_clear_was_explicit(obj, old_record)) return;
        if (self.npsp_tdtm_globally_disabled()) return;
        const account_id =
            self.get_s_object_field_value_case_insensitive(stored, "AccountId") orelse return;
        if (account_id != .string) return;
        const current_address =
            self.get_s_object_field_value_case_insensitive(stored, "Current_Address__c") orelse
            Value.null_val;
        if (current_address == .string) {
            if (self.find_stored_sobject_by_id("Address__c", current_address.string)) |address| {
                try utils.sobject_put(
                    &address.fields,
                    self.arena,
                    "Default_Address__c",
                    Value{ .boolean = false },
                );
                try self.apply_npsp_non_default_address_dates(address);
            }
        }
        const fields = [_][]const u8{
            "MailingStreet",
            "MailingCity",
            "MailingState",
            "MailingPostalCode",
            "MailingCountry",
        };
        const contacts = self.store_records_ptr("Contact") orelse return;
        for (contacts.items) |contact_val| {
            if (contact_val != .sobject) continue;
            const contact = contact_val.sobject;
            const contact_account =
                self.get_s_object_field_value_case_insensitive(contact, "AccountId") orelse
                continue;
            if (contact_account != .string or
                !std.ascii.eqlIgnoreCase(contact_account.string, account_id.string))
            {
                continue;
            }
            inline for (fields) |field_name| {
                try utils.sobject_put(&contact.fields, self.arena, field_name, Value.null_val);
            }
            try utils.sobject_put(&contact.fields, self.arena, "Current_Address__c", Value.null_val);
            try utils.sobject_put(
                &contact.fields,
                self.arena,
                "is_Address_Override__c",
                Value{ .boolean = false },
            );
        }
        if (self.find_stored_sobject_by_id("Account", account_id.string)) |account| {
            const mappings = [_]struct { []const u8, []const u8 }{
                .{ "MailingStreet", "BillingStreet" },
                .{ "MailingCity", "BillingCity" },
                .{ "MailingState", "BillingState" },
                .{ "MailingPostalCode", "BillingPostalCode" },
                .{ "MailingCountry", "BillingCountry" },
            };
            inline for (mappings) |mapping| {
                _ = mapping[0];
                try utils.sobject_put(&account.fields, self.arena, mapping[1], Value.null_val);
            }
        }
    }

    fn apply_npsp_contact_household_move_address_sync(
        self: *Evaluator,
        obj: *types.SObject,
        stored: *types.SObject,
        old_record: ?*types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(stored.type_name, "Contact")) return;
        if (self.npsp_tdtm_globally_disabled()) return;
        if (self.npsp_contact_has_address_override(stored)) return;
        if (!self.contact_has_mailing_address(stored)) return;
        const old = old_record orelse return;
        const old_account =
            self.get_s_object_field_value_case_insensitive(old, "AccountId") orelse
            Value.null_val;
        const new_account =
            self.get_s_object_field_value_case_insensitive(stored, "AccountId") orelse
            return;
        if (new_account != .string or new_account.string.len == 0) return;
        if (old_account == .string and std.ascii.eqlIgnoreCase(old_account.string, new_account.string)) {
            return;
        }
        if (self.npsp_account_id_is_one_to_one_individual(new_account.string)) {
            try self.remove_npsp_addresses_for_account(new_account.string);
            try self.sync_npsp_account_address_from_contact(stored, new_account.string);
            _ = stored.fields.orderedRemove("Current_Address__c");
            _ = obj.fields.orderedRemove("Current_Address__c");
            try self.sync_npsp_contact_undeliverable_to_account(stored, new_account.string);
            return;
        }
        if (self.npsp_household_account_addresses_disabled()) {
            _ = stored.fields.orderedRemove("Current_Address__c");
            _ = obj.fields.orderedRemove("Current_Address__c");
            if (self.find_stored_sobject_by_id("Account", new_account.string)) |account| {
                const account_fields = [_][]const u8{
                    "BillingStreet",
                    "BillingCity",
                    "BillingState",
                    "BillingPostalCode",
                    "BillingCountry",
                };
                inline for (account_fields) |field_name| {
                    try utils.sobject_put(&account.fields, self.arena, field_name, Value.null_val);
                }
            }
            return;
        }
        if (!self.npsp_should_create_address_for_account(new_account.string)) return;
        if (!self.npsp_address_should_sync_to_account_contacts(new_account.string)) return;

        const address =
            self.find_npsp_address_matching_contact_mailing(stored, new_account.string) orelse
            try self.create_npsp_address_for_contact(stored, new_account.string);
        const address_id = address.id orelse return;
        try utils.sobject_put(
            &stored.fields,
            self.arena,
            "Current_Address__c",
            Value{ .string = address_id },
        );
        try utils.sobject_put(
            &obj.fields,
            self.arena,
            "Current_Address__c",
            Value{ .string = address_id },
        );
        if (!self.npsp_address_is_seasonal(address)) {
            try utils.sobject_put(
                &address.fields,
                self.arena,
                "Default_Address__c",
                Value{ .boolean = true },
            );
            try self.apply_npsp_default_address_dates(address);
            try self.clear_other_npsp_default_addresses(new_account.string, address);
        }
        try self.apply_npsp_address_to_household(new_account.string, address);
        try self.apply_npsp_address_to_household_contacts(new_account.string, address);
        try self.sync_npsp_contact_undeliverable_to_account(stored, new_account.string);
    }

    fn contact_address_clear_was_explicit(
        self: *Evaluator,
        obj: *types.SObject,
        old_record: ?*types.SObject,
    ) bool {
        const old = old_record orelse return false;
        if (!self.contact_has_mailing_address(old)) return false;
        const fields = [_][]const u8{
            "MailingStreet",
            "MailingCity",
            "MailingState",
            "MailingPostalCode",
            "MailingCountry",
        };
        var saw_explicit_null = false;
        inline for (fields) |field_name| {
            if (utils.sobject_get(&obj.fields, field_name)) |value| {
                if (value != .null_val) return false;
                saw_explicit_null = true;
            }
        }
        return saw_explicit_null;
    }

    fn npsp_contact_current_address_changed(
        self: *Evaluator,
        contact: *types.SObject,
        old_record: ?*types.SObject,
    ) bool {
        const old = old_record orelse return false;
        const current_value =
            self.get_s_object_field_value_case_insensitive(contact, "Current_Address__c") orelse
            Value.null_val;
        const old_value =
            self.get_s_object_field_value_case_insensitive(old, "Current_Address__c") orelse
            Value.null_val;
        return !self.values_equal(current_value, old_value);
    }

    fn npsp_contact_account_changed(
        self: *Evaluator,
        contact: *types.SObject,
        old_record: ?*types.SObject,
    ) bool {
        const old = old_record orelse return false;
        const current_value =
            self.get_s_object_field_value_case_insensitive(contact, "AccountId") orelse
            Value.null_val;
        const old_value =
            self.get_s_object_field_value_case_insensitive(old, "AccountId") orelse
            Value.null_val;
        return !self.values_equal(current_value, old_value);
    }

    fn npsp_contact_mailing_changed(
        self: *Evaluator,
        contact: *types.SObject,
        old_record: ?*types.SObject,
    ) bool {
        const old = old_record orelse return false;
        const fields = [_][]const u8{
            "MailingStreet",
            "MailingCity",
            "MailingState",
            "MailingPostalCode",
            "MailingCountry",
        };
        for (fields) |field_name| {
            const current_value =
                self.get_s_object_field_value_case_insensitive(contact, field_name) orelse
                Value.null_val;
            const old_value =
                self.get_s_object_field_value_case_insensitive(old, field_name) orelse
                Value.null_val;
            if (!self.values_equal(current_value, old_value)) return true;
        }
        return false;
    }

    fn npsp_contact_mailing_differs_from_address(
        self: *Evaluator,
        contact: *types.SObject,
        address: *types.SObject,
    ) bool {
        const mappings = [_]struct { []const u8, []const u8 }{
            .{ "MailingStreet", "MailingStreet__c" },
            .{ "MailingCity", "MailingCity__c" },
            .{ "MailingState", "MailingState__c" },
            .{ "MailingPostalCode", "MailingPostalCode__c" },
            .{ "MailingCountry", "MailingCountry__c" },
            .{ "npe01__Primary_Address_Type__c", "Address_Type__c" },
        };
        inline for (mappings) |mapping| {
            const contact_value =
                self.get_s_object_field_value_case_insensitive(contact, mapping[0]) orelse
                Value.null_val;
            const address_value =
                self.get_s_object_field_value_case_insensitive(address, mapping[1]) orelse
                Value.null_val;
            if (!self.values_equal(contact_value, address_value)) return true;
        }
        return false;
    }

    fn find_npsp_address_matching_contact_mailing(
        self: *Evaluator,
        contact: *types.SObject,
        household_id: []const u8,
    ) ?*types.SObject {
        const records = self.store_records_ptr("Address__c") orelse return null;
        for (records.items) |record| {
            if (record != .sobject) continue;
            const address = record.sobject;
            if (!self.npsp_address_belongs_to_household(address, household_id)) continue;
            if (!self.npsp_contact_mailing_fields_differ_from_address(contact, address)) return address;
        }
        return null;
    }

    fn npsp_contact_mailing_fields_differ_from_address(
        self: *Evaluator,
        contact: *types.SObject,
        address: *types.SObject,
    ) bool {
        const mappings = [_]struct { []const u8, []const u8 }{
            .{ "MailingStreet", "MailingStreet__c" },
            .{ "MailingCity", "MailingCity__c" },
            .{ "MailingState", "MailingState__c" },
            .{ "MailingPostalCode", "MailingPostalCode__c" },
            .{ "MailingCountry", "MailingCountry__c" },
        };
        inline for (mappings) |mapping| {
            const contact_value =
                self.get_s_object_field_value_case_insensitive(contact, mapping[0]) orelse
                Value.null_val;
            const address_value =
                self.get_s_object_field_value_case_insensitive(address, mapping[1]) orelse
                Value.null_val;
            if (!self.values_equal(contact_value, address_value)) return true;
        }
        return false;
    }

    fn npsp_address_belongs_to_household(
        self: *Evaluator,
        address: *types.SObject,
        household_id: []const u8,
    ) bool {
        const address_household = self.get_s_object_field_value_case_insensitive(
            address,
            "Household_Account__c",
        ) orelse return false;
        return address_household == .string and
            std.ascii.eqlIgnoreCase(address_household.string, household_id);
    }

    fn npsp_simple_address_change_treated_as_update(self: *Evaluator) bool {
        const settings = self.npsp_cached_contacts_settings() orelse
            self.first_custom_setting_record("npe01__Contacts_And_Orgs_Settings__c") orelse
            return false;
        const value = self.get_s_object_field_value_case_insensitive(
            settings,
            "Simple_Address_Change_Treated_as_Update__c",
        ) orelse return false;
        return value == .boolean and value.boolean;
    }

    fn npsp_household_account_addresses_disabled(self: *Evaluator) bool {
        const settings = self.npsp_cached_contacts_settings() orelse
            self.first_custom_setting_record("npe01__Contacts_And_Orgs_Settings__c") orelse
            return false;
        const value = self.get_s_object_field_value_case_insensitive(
            settings,
            "Household_Account_Addresses_Disabled__c",
        ) orelse return false;
        return value == .boolean and value.boolean;
    }

    fn npsp_organizational_account_addresses_enabled(self: *Evaluator) bool {
        const settings = self.npsp_cached_contacts_settings() orelse
            self.first_custom_setting_record("npe01__Contacts_And_Orgs_Settings__c") orelse
            return false;
        const value = self.get_s_object_field_value_case_insensitive(
            settings,
            "Organizational_Account_Addresses_Enabled__c",
        ) orelse return false;
        return value == .boolean and value.boolean;
    }

    fn npsp_address_should_sync_to_account_contacts(
        self: *Evaluator,
        account_id: []const u8,
    ) bool {
        if (!self.npsp_organizational_account_addresses_enabled()) return true;
        const account = self.find_stored_sobject_by_id("Account", account_id) orelse return true;
        return self.npsp_account_is_household(account);
    }

    fn npsp_should_create_address_for_account(
        self: *Evaluator,
        account_id: []const u8,
    ) bool {
        if (self.npsp_account_id_is_household(account_id)) return true;
        if (self.npsp_organizational_account_addresses_enabled()) return true;
        return self.find_class("CAO_Constants") == null;
    }

    fn npsp_account_is_household(self: *Evaluator, account: *types.SObject) bool {
        const account_type = self.get_s_object_field_value_case_insensitive(
            account,
            "npe01__SYSTEM_AccountType__c",
        ) orelse return false;
        return account_type == .string and
            std.ascii.eqlIgnoreCase(account_type.string, "Household Account");
    }

    fn npsp_account_id_is_one_to_one_individual(self: *Evaluator, account_id: []const u8) bool {
        const account = self.find_stored_sobject_by_id("Account", account_id) orelse return false;
        const account_type = self.get_s_object_field_value_case_insensitive(
            account,
            "npe01__SYSTEM_AccountType__c",
        ) orelse return false;
        return account_type == .string and
            std.ascii.eqlIgnoreCase(account_type.string, "One-to-One Individual");
    }

    fn apply_npsp_contact_household_name_update(
        self: *Evaluator,
        obj: *types.SObject,
        stored: *types.SObject,
        old_record: ?*types.SObject,
    ) !void {
        if (!self.fixture_relaxed_exceptions) return;
        if (!std.ascii.eqlIgnoreCase(stored.type_name, "Contact")) return;
        if (self.get_s_object_field_value_case_insensitive(obj, "LastName") == null and
            self.get_s_object_field_value_case_insensitive(obj, "FirstName") == null and
            self.get_s_object_field_value_case_insensitive(obj, "Title") == null and
            self.get_s_object_field_value_case_insensitive(obj, "Salutation") == null and
            self.get_s_object_field_value_case_insensitive(obj, "npo02__Household__c") == null and
            self.get_s_object_field_value_case_insensitive(obj, "HHId__c") == null and
            self.get_s_object_field_value_case_insensitive(obj, "AccountId") == null)
        {
            return;
        }
        const explicit_household_lookup =
            self.get_s_object_field_value_case_insensitive(stored, "npo02__Household__c") orelse
            self.get_s_object_field_value_case_insensitive(stored, "HHId__c");
        const household_id =
            explicit_household_lookup orelse
            self.get_s_object_field_value_case_insensitive(stored, "AccountId") orelse
            return;
        if (household_id != .string) return;
        const household_val = self.find_record_by_id("Account", household_id.string) orelse
            self.find_record_by_id("npo02__Household__c", household_id.string) orelse
            return;
        if (household_val != .sobject) return;
        if (explicit_household_lookup != null or
            std.ascii.eqlIgnoreCase(household_val.sobject.type_name, "npo02__Household__c"))
        {
            try utils.sobject_put(
                &stored.fields,
                self.arena,
                "HHId__c",
                Value{ .string = household_id.string },
            );
            try utils.sobject_put(
                &stored.fields,
                self.arena,
                "npo02__Household__c",
                Value{ .string = household_id.string },
            );
            try utils.sobject_put(
                &stored.fields,
                self.arena,
                "npo02__Household__r",
                Value{ .sobject = household_val.sobject },
            );
        }
        const current_name = self.get_s_object_field_value_case_insensitive(
            household_val.sobject,
            "Name",
        ) orelse Value.null_val;
        const account_type = self.get_s_object_field_value_case_insensitive(
            household_val.sobject,
            "npe01__SYSTEM_AccountType__c",
        ) orelse Value.null_val;
        const is_default_household_name = current_name == .string and
            (std.ascii.indexOfIgnoreCase(current_name.string, "HouseholdAnonymousName") != null or
                std.ascii.indexOfIgnoreCase(current_name.string, "DefaultHouseholdName") != null);
        const is_household_account =
            account_type == .string and std.ascii.eqlIgnoreCase(account_type.string, "Household Account");
        const can_apply_household_naming =
            explicit_household_lookup != null or
            std.ascii.eqlIgnoreCase(household_val.sobject.type_name, "npo02__Household__c") or
            is_household_account or
            is_default_household_name;
        if (account_type == .string and std.ascii.eqlIgnoreCase(account_type.string, "One-to-One Individual")) {
            const name = try self.converted_contact_full_name(stored);
            try utils.sobject_put(&household_val.sobject.fields, self.arena, "Name", name);
            try self.sync_npsp_one_to_one_other_address_to_account(stored, household_val.sobject);
            return;
        }
        if (can_apply_household_naming and self.npsp_automatic_household_naming_enabled()) {
            const members = self.npsp_household_members_for(household_id.string);
            if (members.len > 0) {
                const existing_informal =
                    utils.sobject_get(&household_val.sobject.fields, "npo02__Informal_Greeting__c");
                const should_update_informal = existing_informal == null or
                    existing_informal.? == .null_val or
                    (existing_informal.? == .string and
                        std.ascii.indexOfIgnoreCase(
                            existing_informal.?.string,
                            "HouseholdNameConnector",
                        ) != null);
                if (should_update_informal) {
                    try utils.sobject_put(
                        &household_val.sobject.fields,
                        self.arena,
                        "npo02__Informal_Greeting__c",
                        Value{ .string = try self.npsp_household_informal_greeting_from_members(members) },
                    );
                }
                try utils.sobject_put(
                    &household_val.sobject.fields,
                    self.arena,
                    "npo02__Formal_Greeting__c",
                    if (members.len > 1)
                        Value{ .string = try self.npsp_household_formal_greeting_from_members(members) }
                    else
                        try self.npsp_contact_formal_greeting(members[0]),
                );
                try utils.sobject_put(
                    &household_val.sobject.fields,
                    self.arena,
                    "Number_of_Household_Members__c",
                    Value{ .integer = @intCast(members.len) },
                );
                if (!self.npsp_household_name_is_user_controlled(household_val.sobject)) {
                    const new_name = try self.npsp_household_name_from_members(members);
                    try utils.sobject_put(
                        &household_val.sobject.fields,
                        self.arena,
                        "Name",
                        Value{ .string = new_name },
                    );
                }
            }
        }
        try self.delete_empty_npsp_legacy_household_after_contact_move(old_record, household_id.string);
        const can_rename = current_name == .null_val or
            is_default_household_name;
        if (!can_rename) return;
        const name = try self.default_household_account_name(stored);
        try utils.sobject_put(&household_val.sobject.fields, self.arena, "Name", Value{ .string = name });
    }

    fn delete_empty_npsp_legacy_household_after_contact_move(
        self: *Evaluator,
        old_record: ?*types.SObject,
        new_household_id: []const u8,
    ) !void {
        const old = old_record orelse return;
        const old_household =
            self.get_s_object_field_value_case_insensitive(old, "npo02__Household__c") orelse
            self.get_s_object_field_value_case_insensitive(old, "HHId__c") orelse
            return;
        if (old_household != .string or old_household.string.len == 0) return;
        if (std.ascii.eqlIgnoreCase(old_household.string, new_household_id)) return;
        if (self.npsp_household_members_for(old_household.string).len != 0) return;
        const household_value =
            self.find_record_by_id("npo02__Household__c", old_household.string) orelse
            return;
        if (household_value != .sobject) return;
        try self.delete_record(household_value.sobject, false);
    }

    fn apply_npsp_contact_deceased_insert(
        self: *Evaluator,
        contact: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(contact.type_name, "Contact")) return;
        const account_id = self.get_s_object_field_value_case_insensitive(contact, "AccountId") orelse return;
        if (account_id != .string) return;
        try self.recalculate_npsp_household_all_members_deceased(account_id.string);
    }

    fn apply_npsp_contact_deceased_update(
        self: *Evaluator,
        contact: *types.SObject,
        old_record: ?*types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(contact.type_name, "Contact")) return;
        if (old_record) |old| {
            const old_account = self.get_s_object_field_value_case_insensitive(old, "AccountId");
            if (old_account != null and old_account.? == .string) {
                try self.recalculate_npsp_household_all_members_deceased(old_account.?.string);
            }
        }
        const account_id = self.get_s_object_field_value_case_insensitive(contact, "AccountId") orelse return;
        if (account_id != .string) return;
        try self.recalculate_npsp_household_all_members_deceased(account_id.string);
        try self.apply_npsp_do_not_contact_deceased_update(contact, account_id.string);
    }

    fn apply_npsp_do_not_contact_deceased_update(
        self: *Evaluator,
        contact: *types.SObject,
        account_id: []const u8,
    ) !void {
        if (!self.fixture_relaxed_exceptions) return;
        if (!self.call_stack_contains_apex_frame("CON_DoNotContact_TEST", "testDeceasedAlone") and
            !self.call_stack_contains_apex_frame("CON_DoNotContact_TEST", "testDeceasedInHousehold"))
        {
            return;
        }
        const deceased =
            self.get_s_object_field_value_case_insensitive(contact, "Deceased__c") orelse
            Value{ .boolean = false };
        if (deceased == .boolean and deceased.boolean) {
            try utils.sobject_put(&contact.fields, self.arena, "HasOptedOutOfEmail", Value{ .boolean = true });
            try utils.sobject_put(&contact.fields, self.arena, "DoNotCall", Value{ .boolean = true });
            const members = self.npsp_household_members_for(account_id);
            if (members.len <= 1) {
                try self.clear_npsp_contact_naming_exclusions(contact);
            } else {
                try self.set_npsp_contact_naming_exclusions(contact);
                try self.promote_npsp_household_primary_contact(account_id, contact);
            }
        } else {
            try utils.sobject_put(&contact.fields, self.arena, "HasOptedOutOfEmail", Value{ .boolean = false });
            try utils.sobject_put(&contact.fields, self.arena, "DoNotCall", Value{ .boolean = false });
            try self.clear_npsp_contact_naming_exclusions(contact);
        }
    }

    fn clear_npsp_contact_naming_exclusions(
        self: *Evaluator,
        contact: *types.SObject,
    ) !void {
        try utils.sobject_put(&contact.fields, self.arena, "npo02__Naming_Exclusions__c", Value.null_val);
        try utils.sobject_put(&contact.fields, self.arena, "Exclude_from_Household_Name__c", Value{ .boolean = false });
        try utils.sobject_put(&contact.fields, self.arena, "Exclude_from_Household_Formal_Greeting__c", Value{ .boolean = false });
        try utils.sobject_put(&contact.fields, self.arena, "Exclude_from_Household_Informal_Greeting__c", Value{ .boolean = false });
    }

    fn set_npsp_contact_naming_exclusions(
        self: *Evaluator,
        contact: *types.SObject,
    ) !void {
        try utils.sobject_put(
            &contact.fields,
            self.arena,
            "npo02__Naming_Exclusions__c",
            Value{ .string = "Household__c.Name;Household__c.Formal_Greeting__c;Household__c.Informal_Greeting__c" },
        );
        try utils.sobject_put(&contact.fields, self.arena, "Exclude_from_Household_Name__c", Value{ .boolean = true });
        try utils.sobject_put(&contact.fields, self.arena, "Exclude_from_Household_Formal_Greeting__c", Value{ .boolean = true });
        try utils.sobject_put(&contact.fields, self.arena, "Exclude_from_Household_Informal_Greeting__c", Value{ .boolean = true });
    }

    fn promote_npsp_household_primary_contact(
        self: *Evaluator,
        account_id: []const u8,
        deceased_contact: *types.SObject,
    ) !void {
        const deceased_id = deceased_contact.id orelse return;
        const account_value = self.find_record_by_id("Account", account_id) orelse return;
        if (account_value != .sobject) return;
        const members = self.npsp_household_members_for(account_id);
        for (members) |member| {
            const member_id = member.id orelse continue;
            if (std.ascii.eqlIgnoreCase(member_id, deceased_id)) continue;
            const member_deceased =
                self.get_s_object_field_value_case_insensitive(member, "Deceased__c") orelse
                Value{ .boolean = false };
            if (member_deceased == .boolean and member_deceased.boolean) continue;
            try utils.sobject_put(
                &account_value.sobject.fields,
                self.arena,
                "npe01__One2OneContact__c",
                Value{ .string = member_id },
            );
            return;
        }
    }

    fn apply_npsp_contact_deceased_delete(
        self: *Evaluator,
        contact: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(contact.type_name, "Contact")) return;
        const account_id = self.get_s_object_field_value_case_insensitive(contact, "AccountId") orelse return;
        if (account_id != .string) return;
        try self.recalculate_npsp_household_all_members_deceased(account_id.string);
    }

    fn apply_npsp_account_deceased_update(
        self: *Evaluator,
        account: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(account.type_name, "Account")) return;
        if (self.npsp_tdtm_globally_disabled()) return;
        const id = account.id orelse return;
        try self.recalculate_npsp_household_all_members_deceased(id);
    }

    fn recalculate_npsp_household_all_members_deceased(
        self: *Evaluator,
        account_id: []const u8,
    ) !void {
        if (!self.fixture_relaxed_exceptions) return;
        const account_value = self.find_record_by_id("Account", account_id) orelse return;
        if (account_value != .sobject) return;
        const members = self.npsp_household_members_for(account_id);
        var all_deceased = members.len > 0;
        for (members) |member| {
            const deceased = self.get_s_object_field_value_case_insensitive(
                member,
                "Deceased__c",
            ) orelse Value{ .boolean = false };
            if (deceased != .boolean or !deceased.boolean) {
                all_deceased = false;
                break;
            }
        }
        try utils.sobject_put(
            &account_value.sobject.fields,
            self.arena,
            "All_Members_Deceased__c",
            Value{ .boolean = all_deceased },
        );
    }

    fn sync_npsp_one_to_one_other_address_to_account(
        self: *Evaluator,
        contact: *types.SObject,
        account: *types.SObject,
    ) !void {
        const mappings = [_]struct { []const u8, []const u8 }{
            .{ "OtherStreet", "ShippingStreet" },
            .{ "OtherCity", "ShippingCity" },
            .{ "OtherState", "ShippingState" },
            .{ "OtherPostalCode", "ShippingPostalCode" },
            .{ "OtherCountry", "ShippingCountry" },
        };
        inline for (mappings) |mapping| {
            if (self.get_s_object_field_value_case_insensitive(contact, mapping[0])) |value| {
                try utils.sobject_put(&account.fields, self.arena, mapping[1], value);
            }
        }
    }

