    fn append_sobject_to_store(self: *Evaluator, type_name: []const u8, obj: *types.SObject) !void {
        if (self.store_records_ptr(type_name)) |records| {
            try records.append(self.arena, Value{ .sobject = obj });
            return;
        }
        const gop = try self.store.getOrPut(self.arena, type_name);
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        try gop.value_ptr.append(self.arena, Value{ .sobject = obj });
    }

    /// Validate required fields on an SObject.
    /// When `only_present` is true (for updates), only validate fields that are
    /// explicitly present in the object's fields map — missing fields are not changed.
    fn validate_required_fields(
        self: *Evaluator,
        obj: *types.SObject,
        only_present: bool,
    ) !?[]const u8 {
        const type_name = obj.type_name;
        if (std.ascii.eqlIgnoreCase(type_name, "Account")) {
            const name_val = utils.sobject_get(&obj.fields, "Name");
            // Insert: field must exist and be non-null/non-empty
            // Update: field must not be explicitly set to null/empty
            if (name_val == null) {
                if (!only_present) return try self.required_field_missing_message("Name");
            } else if (name_val.? == .null_val) {
                return "REQUIRED_FIELD_MISSING: Required fields are missing: [Name]";
            } else if (name_val.? == .string and name_val.?.string.len == 0) {
                return "REQUIRED_FIELD_MISSING: Required fields are missing: [Name]";
            }
        }
        if (std.ascii.eqlIgnoreCase(type_name, "Contact")) {
            const name_val = utils.sobject_get(&obj.fields, "LastName");
            if (name_val == null) {
                if (!only_present) {
                    return try self.required_field_missing_message("LastName");
                }
            } else if (name_val.? == .null_val) {
                return "REQUIRED_FIELD_MISSING: Required fields are missing: [LastName]";
            }
        }
        if (std.ascii.eqlIgnoreCase(type_name, "Opportunity")) {
            if (try self.validate_required_field_value(obj, "Name", only_present)) |err_msg| return err_msg;
            if (try self.validate_required_field_value(obj, "StageName", only_present)) |err_msg| return err_msg;
            if (try self.validate_required_field_value(obj, "CloseDate", only_present)) |err_msg| return err_msg;
        }
        if (std.ascii.eqlIgnoreCase(type_name, "ContentVersion")) {
            if (validate_content_version_required(obj)) |err_msg| return err_msg;
        }
        if (std.ascii.eqlIgnoreCase(type_name, "Address__c")) {
            if (try self.validate_npsp_address_fields(obj)) |err_msg| return err_msg;
        }
        if (try self.validate_packaged_required_fields(obj, only_present)) |err_msg| return err_msg;
        if (self.field_metadata.get(type_name)) |field_map| {
            var iter = field_map.iterator();
            while (iter.next()) |entry| {
                const field_name = entry.key_ptr.*;
                const meta = entry.value_ptr.*;
                if (!meta.is_required and !metadata_field_type_is_required(meta)) continue;

                const field_val = utils.sobject_get(&obj.fields, field_name);
                if (field_val == null) {
                    if (!only_present) {
                        return try self.required_field_missing_message(field_name);
                    }
                    continue;
                }
                if (field_val.? == .null_val) {
                    return try self.required_field_missing_message(field_name);
                }
                if (field_val.? == .string and
                    std.mem.trim(u8, field_val.?.string, " \t\r\n").len == 0)
                {
                    return try self.required_field_missing_message(field_name);
                }
            }
        }
        return null;
    }

    fn metadata_field_type_is_required(metadata: FieldMetadata) bool {
        const field_type = metadata.field_type orelse return false;
        return std.ascii.eqlIgnoreCase(field_type, "MasterDetail");
    }

    fn validate_packaged_required_fields(
        self: *Evaluator,
        obj: *types.SObject,
        only_present: bool,
    ) !?[]const u8 {
        if (std.ascii.eqlIgnoreCase(obj.type_name, "npe4__Relationship__c")) {
            return try self.validate_required_field_value(obj, "npe4__Contact__c", only_present);
        }
        if (std.ascii.eqlIgnoreCase(obj.type_name, "npe4__Relationship_Lookup__c")) {
            return try self.validate_required_field_value(obj, "Name", only_present);
        }
        if (std.ascii.eqlIgnoreCase(obj.type_name, "npe03__Custom_Installment_Settings__c")) {
            if (try self.validate_required_field_value(obj, "Name", only_present)) |err_msg| return err_msg;
            if (try self.validate_required_field_value(obj, "npe03__Value__c", only_present)) |err_msg| return err_msg;
            return try self.validate_required_field_value(
                obj,
                "npe03__Increment__c",
                only_present,
            );
        }
        if (std.ascii.eqlIgnoreCase(obj.type_name, "npo02__User_Rollup_Field_Settings__c")) {
            if (try self.validate_required_field_value(obj, "Name", only_present)) |err_msg| return err_msg;
            if (try self.validate_required_field_value(obj, "npo02__Object_Name__c", only_present)) |err_msg| return err_msg;
            if (try self.validate_required_field_value(obj, "npo02__Target_Field__c", only_present)) |err_msg| return err_msg;
            if (try self.validate_required_field_value(obj, "npo02__Field_Action__c", only_present)) |err_msg| return err_msg;
            return try self.validate_required_field_value(
                obj,
                "npo02__Source_Field__c",
                only_present,
            );
        }
        return null;
    }

    fn validate_required_field_value(
        self: *Evaluator,
        obj: *types.SObject,
        field_name: []const u8,
        only_present: bool,
    ) !?[]const u8 {
        const field_val = utils.sobject_get(&obj.fields, field_name);
        if (field_val == null) {
            if (!only_present) return try self.required_field_missing_message(field_name);
            return null;
        }
        if (field_val.? == .null_val) return try self.required_field_missing_message(field_name);
        if (field_val.? == .string and std.mem.trim(u8, field_val.?.string, " \t\r\n").len == 0) {
            return try self.required_field_missing_message(field_name);
        }
        return null;
    }

    fn validate_npsp_address_fields(
        self: *Evaluator,
        obj: *types.SObject,
    ) !?[]const u8 {
        if (utils.sobject_get(&obj.fields, "Household_Account__c")) |household_id| {
            if (household_id == .string and
                !std.mem.startsWith(u8, household_id.string, "001"))
            {
                const message = try std.fmt.allocPrint(
                    self.arena,
                    "FIELD_INTEGRITY_EXCEPTION: Household Account: id value of incorrect type: {s}",
                    .{household_id.string},
                );
                return message;
            }
        }
        if (utils.sobject_get(&obj.fields, "MailingCity__c")) |city| {
            if (city == .string and city.string.len > 40) {
                return "STRING_TOO_LONG: Billing City: data value too large";
            }
        }
        return null;
    }

    fn required_field_missing_message(
        self: *Evaluator,
        field_name: []const u8,
    ) ![]const u8 {
        return std.fmt.allocPrint(
            self.arena,
            "REQUIRED_FIELD_MISSING: Required fields are missing: [{s}]",
            .{field_name},
        );
    }

    /// ContentVersion の必須フィールド (`PathOnClient`, `VersionData`) を
    /// チェックする。違反があれば Apex と同じ REQUIRED_FIELD_MISSING
    /// メッセージを返す。`validate_required_fields` の ContentVersion ブロックを抽出。
    fn validate_content_version_required(obj: *types.SObject) ?[]const u8 {
        const poc_val = utils.sobject_get(&obj.fields, "PathOnClient");
        if (poc_val == null or poc_val.? == .null_val) {
            return "REQUIRED_FIELD_MISSING: Required fields are missing: [PathOnClient]";
        }
        if (poc_val.? == .string and poc_val.?.string.len == 0) {
            return "REQUIRED_FIELD_MISSING: Required fields are missing: [PathOnClient]";
        }
        const vd_val = utils.sobject_get(&obj.fields, "VersionData");
        if (vd_val == null or vd_val.? == .null_val) {
            return "REQUIRED_FIELD_MISSING: Required fields are missing: [VersionData]";
        }
        if (vd_val.? == .object) {
            if (utils.sobject_get(&vd_val.?.object.fields, "value")) |inner| {
                if (inner == .string and inner.string.len == 0) {
                    return "REQUIRED_FIELD_MISSING: Required fields are missing: [VersionData]";
                }
            }
        }
        return null;
    }

    fn apply_missing_field_defaults(self: *Evaluator, obj: *types.SObject) !void {
        if (self.field_defaults.get(obj.type_name)) |defaults| {
            // `default_val` avoids shadowing the module-level
            // `default_value` function produced by the snake_case rename.
            for (defaults.keys(), defaults.values()) |field_name, default_val| {
                if (self.get_s_object_field_value_case_insensitive(obj, field_name) != null) {
                    continue;
                }
                try utils.sobject_put(&obj.fields, self.arena, field_name, default_val);
            }
        }
        try self.apply_packaged_field_defaults(obj);
        // Platform-level defaults that don't live in field-meta.xml. Real Apex
        // sets these for common standard objects when the caller omits them;
        // without the defaults tests that filter by IsActive=TRUE etc. miss
        // their freshly-inserted records.
        try self.apply_standard_object_defaults(obj);
    }

    fn sobject_field_default_value(
        self: *Evaluator,
        obj: *types.SObject,
        field_name: []const u8,
    ) ?Value {
        const defaults = self.field_defaults.get(obj.type_name) orelse return null;
        for (defaults.keys(), defaults.values()) |default_field, default_val| {
            if (!std.ascii.eqlIgnoreCase(default_field, field_name)) continue;
            if (default_val == .string and default_value_is_formula_expression(default_val.string)) {
                return null;
            }
            return default_val;
        }
        return null;
    }

    fn default_value_is_formula_expression(value: []const u8) bool {
        return std.mem.indexOfScalar(u8, value, '(') != null or
            std.mem.indexOfScalar(u8, value, ')') != null;
    }

    fn apply_packaged_field_defaults(self: *Evaluator, obj: *types.SObject) !void {
        if (std.ascii.eqlIgnoreCase(obj.type_name, "npe4__Relationship_Lookup__c")) {
            if (self.get_s_object_field_value_case_insensitive(obj, "npe4__Active__c") == null) {
                try utils.sobject_put(
                    &obj.fields,
                    self.arena,
                    "npe4__Active__c",
                    Value{ .boolean = true },
                );
            }
        }
    }

    fn normalize_present_s_object_fields(self: *Evaluator, obj: *types.SObject) !void {
        var builtin_ctx = self.make_builtin_context();
        if (std.ascii.eqlIgnoreCase(obj.type_name, "npe03__Recurring_Donation__c")) {
            if (self.get_s_object_field_value_case_insensitive(obj, "Day_of_Month__c")) |day| {
                try utils.sobject_put(&obj.fields, self.arena, "Day_of_Month__c", day);
                if (day != .null_val) {
                    try utils.sobject_put(
                        &obj.fields,
                        self.arena,
                        "__apexgov_explicit_day_of_month",
                        day,
                    );
                }
            } else if (self.get_s_object_field_value_case_insensitive(obj, "Day_Of_Month__c")) |day| {
                if (day != .null_val) {
                    try utils.sobject_put(
                        &obj.fields,
                        self.arena,
                        "__apexgov_explicit_day_of_month",
                        day,
                    );
                }
            }
        }
        const keys = obj.fields.keys();
        const values = obj.fields.values();
        for (keys, values) |field_name, *field_value| {
            if (std.mem.startsWith(u8, field_name, "__")) continue;
            if (field_value.* != .string) continue;
            if (std.ascii.eqlIgnoreCase(field_name, "Name")) {
                field_value.* = Value{
                    .string = std.mem.trim(u8, field_value.string, " \t\r\n"),
                };
            }
            if (field_value.string.len == 0) {
                field_value.* = Value.null_val;
                continue;
            }
            if (!std.ascii.eqlIgnoreCase(obj.type_name, "npe01__OppPayment__c") or
                !(std.ascii.eqlIgnoreCase(field_name, "npe01__Paid__c") or
                    std.ascii.eqlIgnoreCase(field_name, "npe01__Written_Off__c")))
            {
                continue;
            }
            field_value.* = try builtins.normalize_s_object_field_assignment(
                &builtin_ctx,
                obj,
                field_name,
                field_value.*,
            );
        }
    }

    fn apply_standard_object_defaults(self: *Evaluator, obj: *types.SObject) !void {
        if (std.ascii.eqlIgnoreCase(obj.type_name, "User")) {
            if (self.get_s_object_field_value_case_insensitive(obj, "IsActive") == null) {
                try utils.sobject_put(
                    &obj.fields,
                    self.arena,
                    "IsActive",
                    Value{ .boolean = true },
                );
            }
        }
        if (std.ascii.eqlIgnoreCase(obj.type_name, "Opportunity")) {
            try self.apply_zero_default(obj, "npe01__Payments_Made__c");
            try self.apply_zero_default(obj, "npe01__Number_of_Payments__c");
            try self.apply_false_default(obj, "npe01__Do_Not_Automatically_Create_Payment__c");
        }
        if (std.ascii.eqlIgnoreCase(obj.type_name, "Contact") or
            std.ascii.eqlIgnoreCase(obj.type_name, "Account"))
        {
            inline for (npsp_zero_default_opportunity_rollup_fields) |field_name| {
                try self.apply_zero_default(obj, field_name);
            }
        }
        if (std.ascii.eqlIgnoreCase(obj.type_name, "npe01__OppPayment__c")) {
            try self.apply_false_default(obj, "npe01__Paid__c");
            try self.apply_false_default(obj, "npe01__Written_Off__c");
        }
        if (std.ascii.eqlIgnoreCase(obj.type_name, "npe03__Recurring_Donation__c")) {
            try self.apply_npsp_recurring_donation_defaults(obj);
        }
    }

    fn apply_npsp_recurring_donation_defaults(self: *Evaluator, obj: *types.SObject) !void {
        const default_date = try builtins.make_date_value(
            self.arena,
            try builtins.current_date_string(self.arena),
        );
        if (self.get_s_object_field_value_case_insensitive(
            obj,
            "npe03__Date_Established__c",
        ) == null) {
            try utils.sobject_put(
                &obj.fields,
                self.arena,
                "npe03__Date_Established__c",
                default_date,
            );
        }
        if (self.get_s_object_field_value_case_insensitive(obj, "npe03__Installments__c") == null) {
            try utils.sobject_put(
                &obj.fields,
                self.arena,
                "npe03__Installments__c",
                Value{ .integer = 1 },
            );
        }
        if (self.get_s_object_field_value_case_insensitive(obj, "StartDate__c") != null) {
            if (!self.npsp_recurring_donation_first_installment_create_is_synchronous()) {
                try self.refresh_npsp_recurring_donation_next_payment_date_on_insert(obj);
            }
            return;
        }
        const has_enhanced_schedule_fields =
            self.get_s_object_field_value_case_insensitive(obj, "InstallmentPeriod__c") != null or
            self.get_s_object_field_value_case_insensitive(
                obj,
                "InstallmentFrequency__c",
            ) != null or
            self.get_s_object_field_value_case_insensitive(obj, "Day_of_Month__c") != null or
            self.get_s_object_field_value_case_insensitive(obj, "RecurringType__c") != null;
        if (!has_enhanced_schedule_fields) return;
        try utils.sobject_put(&obj.fields, self.arena, "StartDate__c", default_date);
        if (!self.npsp_recurring_donation_first_installment_create_is_synchronous()) {
            try self.refresh_npsp_recurring_donation_next_payment_date_on_insert(obj);
        }
    }

    fn apply_zero_default(self: *Evaluator, obj: *types.SObject, field_name: []const u8) !void {
        if (self.get_s_object_field_value_case_insensitive(obj, field_name) != null) return;
        try utils.sobject_put(&obj.fields, self.arena, field_name, Value{ .integer = 0 });
    }

    fn apply_false_default(self: *Evaluator, obj: *types.SObject, field_name: []const u8) !void {
        if (self.get_s_object_field_value_case_insensitive(obj, field_name) != null) return;
        try utils.sobject_put(&obj.fields, self.arena, field_name, Value{ .boolean = false });
    }

    fn update_record(
        self: *Evaluator,
        obj: *types.SObject,
        strict_missing_update: bool,
    ) anyerror!void {
        if (is_empty_query_sobject(obj)) return;
        try self.normalize_present_s_object_fields(obj);
        try self.restore_npsp_rd2_monthly_day_of_month(obj);
        // Validate only fields explicitly present (Salesforce doesn't
        // re-validate all required fields on update)
        if (try self.validate_required_fields(obj, true)) |err_msg| {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "DmlException" };
            try exc.fields.put(self.arena, "message", Value{ .string = err_msg });
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        if (try self.update_relaxed_custom_setting_without_id(obj)) return;
        // If no Id, throw DmlException
        try self.ensure_update_record_id(obj, strict_missing_update);
        // Validate that the record exists in the store (if it has an Id)
        if (obj.id) |record_id| {
            try self.reject_guest_owner_update(obj);
            const found_rec = self.find_update_target_record(obj, record_id);
            if (found_rec == null) {
                if (self.fixture_relaxed_exceptions and
                    !strict_missing_update and
                    !self.should_reject_missing_update_record(obj, record_id)) return;
                const exc = try self.arena.create(types.ObjectInstance);
                exc.* = .{ .class_name = "DmlException" };
                try exc.fields.put(
                    self.arena,
                    "message",
                    Value{
                        .string = "INVALID_CROSS_REFERENCE_KEY: invalid cross reference id",
                    },
                );
                self.pending_exception = Value{ .object = exc };
                return error.ApexException;
            }
            try self.validate_lookup_references(obj, strict_missing_update);
            if (self.find_unique_field_conflict(obj, true)) |field_name| {
                return self.throw_duplicate_value(field_name);
            }
            const old_copy = try self.clone_old_dml_record(Value{ .sobject = found_rec.? });
            const old_record_for_validation = if (old_copy == .sobject) old_copy.sobject else null;
            try self.validate_master_detail_reparenting(obj, old_record_for_validation);
            try self.validate_npsp_allocation_parent_amount_update(obj, found_rec.?);
            try self.validate_npsp_paid_payment_opportunity_allocation_change(
                obj,
                found_rec.?,
                false,
            );
            clear_sobject_errors(found_rec.?);
            try self.copy_update_fields_to_store(obj, found_rec.?);
            try self.apply_npsp_allocation_parent_amount_update(found_rec.?);
            const old_record = if (old_copy == .sobject) old_copy.sobject else null;
            try self.apply_npsp_affiliation_contact_update(obj, found_rec.?, old_record);
            try self.apply_npsp_affiliation_record_update(obj, found_rec.?);
            try self.apply_npsp_affiliation_account_update(obj, found_rec.?, old_record);
            try self.apply_npsp_contact_address_update(obj, found_rec.?, old_record);
            try self.apply_npsp_contact_household_name_update(obj, found_rec.?, old_record);
            try self.apply_npsp_contact_household_move_address_sync(obj, found_rec.?, old_record);
            try self.apply_npsp_contact_deceased_update(found_rec.?, old_record);
            const old_address = if (old_copy == .sobject) old_copy.sobject else null;
            try self.apply_npsp_address_update(obj, found_rec.?, old_address);
            try self.apply_npsp_account_address_update(found_rec.?, old_record);
            try self.apply_npsp_account_deceased_update(found_rec.?);
        }
    }

    fn restore_npsp_rd2_monthly_day_of_month(
        self: *Evaluator,
        obj: *types.SObject,
    ) !void {
        if (!self.fixture_relaxed_exceptions) return;
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "npe03__Recurring_Donation__c")) return;
        const period =
            self.get_s_object_field_value_case_insensitive(obj, "npe03__Installment_Period__c") orelse
            Value.null_val;
        if (period != .string or std.ascii.indexOfIgnoreCase(period.string, "Monthly") == null) {
            return;
        }
        const day =
            self.get_s_object_field_value_case_insensitive(obj, "Day_of_Month__c") orelse
            self.get_s_object_field_value_case_insensitive(obj, "Day_Of_Month__c") orelse
            Value.null_val;
        if (day != .null_val) return;
        const explicit =
            self.get_s_object_field_value_case_insensitive(
                obj,
                "__apexgov_explicit_day_of_month",
            ) orelse return;
        if (explicit == .null_val) return;
        try utils.sobject_put(&obj.fields, self.arena, "Day_of_Month__c", explicit);
    }

    fn should_reject_missing_update_record(
        self: *Evaluator,
        obj: *types.SObject,
        record_id: []const u8,
    ) bool {
        if (record_id.len < 3) return false;
        if (!self.standard_sobject_id_matches_type(obj.type_name, record_id)) return false;
        return self.store_records_ptr(obj.type_name) != null;
    }

    fn standard_sobject_id_matches_type(
        self: *Evaluator,
        type_name: []const u8,
        record_id: []const u8,
    ) bool {
        _ = self;
        if (std.mem.endsWith(u8, type_name, "__c") or
            std.mem.endsWith(u8, type_name, "__mdt") or
            std.mem.endsWith(u8, type_name, "__e"))
        {
            return false;
        }
        const expected = sobject_key_prefix(type_name);
        return std.mem.eql(u8, &expected, record_id[0..3]);
    }

    fn remove_npsp_addresses_for_account(self: *Evaluator, account_id: []const u8) !void {
        const records = self.store_records_ptr("Address__c") orelse return;
        var i: usize = 0;
        while (i < records.items.len) {
            const item = records.items[i];
            if (item != .sobject) {
                i += 1;
                continue;
            }
            const household =
                self.get_s_object_field_value_case_insensitive(item.sobject, "Household_Account__c") orelse {
                    i += 1;
                    continue;
                };
            if (household == .string and std.ascii.eqlIgnoreCase(household.string, account_id)) {
                _ = records.orderedRemove(i);
                continue;
            }
            i += 1;
        }
    }

    fn update_relaxed_custom_setting_without_id(
        self: *Evaluator,
        obj: *types.SObject,
    ) !bool {
        if (!self.fixture_relaxed_exceptions) return false;
        if (!std.mem.endsWith(u8, obj.type_name, "__c")) return false;
        const kind = self.custom_setting_kind(obj.type_name) orelse
            if (std.ascii.eqlIgnoreCase(obj.type_name, "Customizable_Rollup_Settings__c"))
                "Hierarchy"
            else
                return false;
        if (obj.id != null) return false;
        if (self.get_s_object_field_value_case_insensitive(obj, "Id")) |id_value| {
            if (id_value != .null_val) return false;
        }

        const is_hierarchy = std.ascii.eqlIgnoreCase(kind, "Hierarchy");
        if (is_hierarchy) {
            const owner_id =
                if (self.get_s_object_field_value_case_insensitive(obj, "SetupOwnerId")) |owner|
                    if (owner == .string and owner.string.len > 0) owner.string else "00D000000000001"
                else
                    "00D000000000001";
            try utils.sobject_put(
                &obj.fields,
                self.arena,
                "SetupOwnerId",
                Value{ .string = owner_id },
            );
            if (self.find_custom_setting_record(obj.type_name, owner_id)) |stored| {
                try self.copy_update_fields_to_store(obj, stored);
                return true;
            }
        } else if (list_custom_setting_record_key(obj)) |key| {
            if (self.find_list_custom_setting_record(obj.type_name, key)) |stored| {
                try self.copy_update_fields_to_store(obj, stored);
                return true;
            }
        }

        try self.insert_record(obj);
        return true;
    }

    fn is_empty_query_sobject(obj: *types.SObject) bool {
        const marker = utils.sobject_get(&obj.fields, "__apexgov_empty_query__") orelse
            return false;
        return marker == .boolean and marker.boolean;
    }

    fn validate_lookup_references(
        self: *Evaluator,
        obj: *types.SObject,
        strict_missing_reference: bool,
    ) !void {
        if (self.field_metadata.get(obj.type_name)) |metadata| {
            var iter = metadata.iterator();
            while (iter.next()) |entry| {
                const expected_type = entry.value_ptr.reference_to orelse continue;
                const field_name = entry.key_ptr.*;
                const value = utils.sobject_get(&obj.fields, field_name) orelse continue;
                try self.validate_lookup_reference_value(
                    field_name,
                    value,
                    expected_type,
                    false,
                    true,
                );
            }
        }
        if (std.ascii.eqlIgnoreCase(obj.type_name, "Contact")) {
            if (utils.sobject_get(&obj.fields, "AccountId")) |account_id| {
                try self.validate_lookup_reference_value(
                    "AccountId",
                    account_id,
                    "Account",
                    strict_missing_reference or !self.fixture_relaxed_exceptions,
                    true,
                );
            }
        }
        if (utils.sobject_get(&obj.fields, "RecordTypeId")) |record_type_id| {
            try self.validate_record_type_id_reference(record_type_id);
        }
    }

    fn validate_record_type_id_reference(self: *Evaluator, record_type_id: Value) !void {
        if (record_type_id == .null_val) return;
        if (record_type_id != .string or record_type_id.string.len == 0) return;
        if (record_type_id.string.len >= 3 and !std.mem.eql(u8, record_type_id.string[0..3], "012")) {
            return self.throw_invalid_cross_reference_exception_for_id(record_type_id.string);
        }
        if (self.find_record_by_id("RecordType", record_type_id.string) != null) return;
        if (synthetic_record_type_id(record_type_id.string)) return;
        return self.throw_invalid_cross_reference_exception_for_id(record_type_id.string);
    }

    fn validate_lookup_reference_value(
        self: *Evaluator,
        field_name: []const u8,
        value: Value,
        expected_type: []const u8,
        strict_missing_reference: bool,
        store_scoped_missing_reference: bool,
    ) !void {
        if (value == .null_val) return;
        if (value != .string or value.string.len == 0) return;
        if (try self.lookup_reference_has_wrong_type(field_name, value.string, expected_type)) {
            return self.throw_lookup_type_exception(field_name, value.string);
        }
        if (self.find_record_by_id(expected_type, value.string) != null) return;
        if (strict_missing_reference or
            (store_scoped_missing_reference and
                self.should_reject_store_scoped_missing_reference(expected_type, value.string)))
        {
            return self.throw_invalid_cross_reference_exception_for_id(value.string);
        }
    }

    fn should_reject_store_scoped_missing_reference(
        self: *Evaluator,
        expected_type: []const u8,
        record_id: []const u8,
    ) bool {
        if (std.ascii.eqlIgnoreCase(expected_type, "User") or
            std.ascii.eqlIgnoreCase(expected_type, "Group"))
        {
            return false;
        }
        if (record_id.len < 3) return false;
        if (self.id_type_map.get(record_id)) |actual_type| {
            return std.ascii.eqlIgnoreCase(actual_type, expected_type);
        }
        const records = self.store_records_ptr(expected_type) orelse return false;
        for (records.items) |record| {
            if (record == .sobject and record.sobject.id != null) return true;
        }
        return false;
    }

    fn lookup_reference_has_wrong_type(
        self: *Evaluator,
        field_name: []const u8,
        record_id: []const u8,
        expected_type: []const u8,
    ) !bool {
        if (std.ascii.eqlIgnoreCase(field_name, "OwnerId") and
            (std.ascii.eqlIgnoreCase(expected_type, "User") or
                std.ascii.eqlIgnoreCase(expected_type, "Group")))
        {
            if (record_id.len < 3) return false;
            return !(std.mem.eql(u8, record_id[0..3], "005") or
                std.mem.eql(u8, record_id[0..3], "00G"));
        }
        if (self.id_type_map.get(record_id)) |actual_type| {
            return !std.ascii.eqlIgnoreCase(actual_type, expected_type);
        }
        if (self.find_record_by_id(expected_type, record_id) != null) return false;
        if (record_id.len < 3) return false;
        const expected_prefix = sobject_key_prefix(expected_type);
        return !std.mem.eql(u8, &expected_prefix, record_id[0..3]);
    }

    fn throw_lookup_type_exception(
        self: *Evaluator,
        field_name: []const u8,
        record_id: []const u8,
    ) !void {
        const message = try std.fmt.allocPrint(
            self.arena,
            "FIELD_INTEGRITY_EXCEPTION: {s}: id value of incorrect type: {s}",
            .{ field_name, record_id },
        );
        return self.throw_dml_exception(message);
    }

    fn throw_invalid_cross_reference_exception(self: *Evaluator) !void {
        return self.throw_dml_exception(
            "INVALID_CROSS_REFERENCE_KEY: invalid cross reference id",
        );
    }

    fn throw_invalid_cross_reference_exception_for_id(
        self: *Evaluator,
        record_id: []const u8,
    ) !void {
        const message = try std.fmt.allocPrint(
            self.arena,
            "INVALID_CROSS_REFERENCE_KEY: invalid cross reference id: {s}",
            .{record_id},
        );
        return self.throw_dml_exception(message);
    }

    fn validate_master_detail_reparenting(
        self: *Evaluator,
        obj: *types.SObject,
        old_obj: ?*types.SObject,
    ) !void {
        const old = old_obj orelse return;
        const field_map = self.field_metadata.get(obj.type_name) orelse return;
        var iter = field_map.iterator();
        while (iter.next()) |entry| {
            const field_name = entry.key_ptr.*;
            const meta = entry.value_ptr.*;
            if (!metadata_field_type_is_required(meta) or meta.reparentable_master_detail) continue;
            const new_value = utils.sobject_get(&obj.fields, field_name) orelse continue;
            const old_value = utils.sobject_get(&old.fields, field_name) orelse continue;
            if (master_detail_parent_value_equal(old_value, new_value)) continue;
            try self.throw_master_detail_reparent_exception(field_name);
        }
    }

    fn master_detail_parent_value_equal(left: Value, right: Value) bool {
        if (left == .null_val or right == .null_val) return left == .null_val and right == .null_val;
        if (left == .string and right == .string) return std.ascii.eqlIgnoreCase(left.string, right.string);
        return false;
    }

    fn throw_master_detail_reparent_exception(self: *Evaluator, field_name: []const u8) !void {
        const msg = try std.fmt.allocPrint(
            self.arena,
            "FIELD_INTEGRITY_EXCEPTION: Field is not writeable: [{s}]",
            .{field_name},
        );
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "DmlException" };
        try exc.fields.put(self.arena, "message", Value{ .string = msg });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn ensure_update_record_id(
        self: *Evaluator,
        obj: *types.SObject,
        strict_missing_update: bool,
    ) !void {
        const id_field = utils.sobject_get(&obj.fields, "Id") orelse
            utils.sobject_get(&obj.fields, "id");
        if (id_field) |field_value| {
            if (field_value == .string) {
                obj.id = field_value.string;
                return;
            }
            if (field_value != .null_val) return;
        }
        if (obj.id != null) return;
        if (id_field == null or id_field.? == .null_val) {
            if (self.fixture_relaxed_exceptions and !strict_missing_update) return;
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "DmlException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "MISSING_ARGUMENT: Id not specified in an update call:" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
    }

    const guest_owner_record_error_message =
        "FIELD_INTEGRITY_EXCEPTION, field integrity exception " ++
        "(Guest users cannot be record owners.)";

    fn reject_guest_owner_update(self: *Evaluator, obj: *types.SObject) !void {
        const owner_val = utils.sobject_get(&obj.fields, "OwnerId") orelse return;
        if (owner_val != .string or !self.is_guest_user_id(owner_val.string)) return;
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "DmlException" };
        try exc.fields.put(
            self.arena,
            "message",
            Value{ .string = guest_owner_record_error_message },
        );
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn find_update_target_record(
        self: *Evaluator,
        obj: *types.SObject,
        record_id: []const u8,
    ) ?*types.SObject {
        if (self.store_records_ptr(obj.type_name)) |records| {
            for (records.items) |rec| {
                if (rec == .sobject and rec.sobject.id != null and
                    std.mem.eql(u8, rec.sobject.id.?, record_id))
                {
                    return rec.sobject;
                }
            }
        }
        if (utils.sobject_get(&obj.fields, "Id")) |id_val| {
            if (id_val == .string) {
                return self.find_update_target_record_by_id_field(obj, id_val.string);
            }
        }
        return null;
    }

    fn find_update_target_record_by_id_field(
        self: *Evaluator,
        obj: *types.SObject,
        id_field: []const u8,
    ) ?*types.SObject {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, obj.type_name)) continue;
            for (entry.value_ptr.items) |rec| {
                if (rec == .sobject and rec.sobject.id != null and
                    std.mem.eql(u8, rec.sobject.id.?, id_field))
                {
                    return rec.sobject;
                }
            }
        }
        return null;
    }

    fn copy_update_fields_to_store(
        self: *Evaluator,
        obj: *types.SObject,
        stored: *types.SObject,
    ) !void {
        const now_str = builtins.current_date_time_string(self.arena) catch "2026-01-01T00:00:00Z";
        utils.sobject_put(
            &obj.fields,
            self.arena,
            "LastModifiedDate",
            Value{ .string = now_str },
        ) catch {};
        utils.sobject_put(
            &obj.fields,
            self.arena,
            "LastModifiedById",
            Value{ .string = "005000000000001" },
        ) catch {};
        if (utils.sobject_get(&obj.fields, "LastModifiedBy") == null) {
            try self.put_last_modified_by_stub(obj);
        }
        if (stored == obj) {
            const keys = self.arena.dupe([]const u8, obj.fields.keys()) catch return;
            const vals = self.arena.dupe(Value, obj.fields.values()) catch return;
            for (keys, vals) |k, v| {
                if (self.skip_update_parent_relationship_field(stored, k, v)) continue;
                self.clear_parent_relationship_for_fk_update(stored, k, v);
                utils.sobject_put(&stored.fields, self.arena, k, v) catch {};
            }
        } else {
            for (obj.fields.keys(), obj.fields.values()) |k, v| {
                if (self.skip_update_parent_relationship_field(stored, k, v)) continue;
                self.clear_parent_relationship_for_fk_update(stored, k, v);
                utils.sobject_put(&stored.fields, self.arena, k, v) catch {};
            }
        }
        try self.remember_explicit_npsp_next_payment_date(obj, stored);
        try self.apply_npsp_bdi_recurring_donation_closed_reason(stored);
        try self.refresh_contact_or_lead_name_after_update(obj, stored);
    }

    fn apply_npsp_bdi_recurring_donation_closed_reason(
        self: *Evaluator,
        rd: *types.SObject,
    ) !void {
        if (!self.fixture_relaxed_exceptions) return;
        if (!std.ascii.eqlIgnoreCase(rd.type_name, "npe03__Recurring_Donation__c")) return;
        const rd_id = rd.id orelse return;
        const status_existing =
            self.get_s_object_field_value_case_insensitive(rd, "Status__c") orelse
            Value.null_val;
        if (status_existing == .null_val or
            (status_existing == .string and
                std.ascii.indexOfIgnoreCase(status_existing.string, "Closed") == null))
        {
            if (self.npsp_bdi_recurring_donation_import_field_for_id(
                rd_id,
                "Recurring_Donation_Status__c",
                false,
            )) |status| {
                try utils.sobject_put(&rd.fields, self.arena, "Status__c", status);
            }
        }
        const existing =
            self.get_s_object_field_value_case_insensitive(rd, "ClosedReason__c") orelse
            Value.null_val;
        if (existing != .null_val) return;
        const reason = self.npsp_bdi_recurring_donation_import_field_for_id(
            rd_id,
            "Recurring_Donation_Status_Reason__c",
            true,
        ) orelse return;
        try utils.sobject_put(&rd.fields, self.arena, "ClosedReason__c", reason);
    }

    fn npsp_bdi_recurring_donation_import_field_for_id(
        self: *Evaluator,
        rd_id: []const u8,
        field_name: []const u8,
        allow_fallback: bool,
    ) ?Value {
        const imports = self.store_records_ptr("DataImport__c") orelse return null;
        var fallback: ?Value = null;
        for (imports.items) |item| {
            if (item != .sobject) continue;
            const reason = self.get_s_object_field_value_case_insensitive(
                item.sobject,
                field_name,
            ) orelse continue;
            if (reason == .null_val) continue;
            if (fallback == null) fallback = reason;
            const imported_rd = self.get_s_object_field_value_case_insensitive(
                item.sobject,
                "RecurringDonationImported__c",
            ) orelse continue;
            if (imported_rd != .string or !std.mem.eql(u8, imported_rd.string, rd_id)) continue;
            return reason;
        }
        return if (allow_fallback) fallback else null;
    }

    fn remember_explicit_npsp_next_payment_date(
        self: *Evaluator,
        obj: *types.SObject,
        stored: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(stored.type_name, "npe03__Recurring_Donation__c")) return;
        const next_date = utils.sobject_get(
            &obj.fields,
            "npe03__Next_Payment_Date__c",
        ) orelse return;
        if (next_date == .null_val) return;
        try utils.sobject_put(
            &stored.fields,
            self.arena,
            "__apexgov_explicit_next_payment_date",
            next_date,
        );
    }

    fn refresh_contact_or_lead_name_after_update(
        self: *Evaluator,
        obj: *types.SObject,
        stored: *types.SObject,
    ) !void {
        if (!std.ascii.eqlIgnoreCase(stored.type_name, "Contact") and
            !std.ascii.eqlIgnoreCase(stored.type_name, "Lead"))
        {
            return;
        }
        if (utils.sobject_get(&obj.fields, "FirstName") == null and
            utils.sobject_get(&obj.fields, "LastName") == null)
        {
            return;
        }
        try utils.sobject_put(
            &stored.fields,
            self.arena,
            "Name",
            Value{ .string = try self.contact_or_lead_insert_name(stored) },
        );
    }

    fn put_last_modified_by_stub(self: *Evaluator, obj: *types.SObject) !void {
        const modified_by = try self.arena.create(types.SObject);
        modified_by.* = .{ .type_name = "User", .id = "005000000000001" };
        try modified_by.fields.put(self.arena, "Id", Value{ .string = "005000000000001" });
        try modified_by.fields.put(self.arena, "Name", Value{ .string = "Test User" });
        try modified_by.fields.put(
            self.arena,
            "Username",
            Value{ .string = "testuser@example.com" },
        );
        try obj.fields.put(self.arena, "LastModifiedBy", Value{ .sobject = modified_by });
    }

    /// `upsert_record` の external id 分岐を抽出。マッチする既存レコードが
    /// 見つかり update したら `true` を、まだ insert に落ちるべき場合は
    /// `false` を返す。
    fn upsert_by_external_id(
        self: *Evaluator,
        obj: *types.SObject,
        field_name: []const u8,
    ) anyerror!bool {
        if (std.ascii.eqlIgnoreCase(field_name, "Id")) {
            if (obj.id != null) {
                try self.update_record(obj, false);
                return true;
            }
            if (utils.sobject_get(&obj.fields, "Id")) |id_val| {
                if (id_val == .string and id_val.string.len > 0) {
                    obj.id = id_val.string;
                    try self.update_record(obj, false);
                    return true;
                }
            }
            try self.insert_record(obj);
            return true;
        }
        const field_value = get_upsert_field_value(obj, field_name);
        if (field_value == .null_val) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "DmlException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{
                    .string = "MISSING_ARGUMENT: external id field not specified in an upsert call",
                },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        if (self.find_record_by_field_value(obj.type_name, field_name, field_value)) |existing| {
            if (existing.id) |existing_id| {
                obj.id = existing_id;
                try utils.sobject_put(
                    &obj.fields,
                    self.arena,
                    "Id",
                    Value{ .string = existing_id },
                );
            }
            try self.update_record(obj, false);
            return true;
        }
        return false;
    }

    fn upsert_record(
        self: *Evaluator,
        obj: *types.SObject,
        external_id_field: ?[]const u8,
    ) anyerror!void {
        if (external_id_field) |field_name| {
            if (try self.upsert_by_external_id(obj, field_name)) return;
        }
        if (try self.upsert_custom_setting_without_id(obj)) return;
        if (obj.id != null) {
            // Check if record exists in store
            const record_id = obj.id.?;
            var found = false;
            if (self.store.getPtr(obj.type_name)) |records| {
                for (records.items) |rec| {
                    if (rec == .sobject and rec.sobject.id != null and
                        std.mem.eql(u8, rec.sobject.id.?, record_id))
                    {
                        found = true;
                        break;
                    }
                }
            }
            // Also check Id field
            if (!found) {
                if (utils.sobject_get(&obj.fields, "Id")) |id_val| {
                    if (id_val == .string) {
                        var store_iter = self.store.iterator();
                        while (store_iter.next()) |entry| {
                            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, obj.type_name)) {
                                for (entry.value_ptr.items) |rec| {
                                    if (rec == .sobject and rec.sobject.id != null and
                                        std.mem.eql(u8, rec.sobject.id.?, id_val.string))
                                    {
                                        found = true;
                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            if (found) {
                try self.update_record(obj, false);
            } else {
                if (self.fixture_relaxed_exceptions) return;
                const exc = try self.arena.create(types.ObjectInstance);
                exc.* = .{ .class_name = "DmlException" };
                try exc.fields.put(
                    self.arena,
                    "message",
                    Value{
                        .string = "INVALID_CROSS_REFERENCE_KEY: invalid cross reference id",
                    },
                );
                self.pending_exception = Value{ .object = exc };
                return error.ApexException;
            }
        } else {
            try self.insert_record(obj);
        }
    }

    fn upsert_custom_setting_without_id(
        self: *Evaluator,
        obj: *types.SObject,
    ) !bool {
        if (!std.mem.endsWith(u8, obj.type_name, "__c")) return false;
        if (std.ascii.eqlIgnoreCase(obj.type_name, "Customizable_Rollup_Settings__c")) {
            return false;
        }
        const kind = self.custom_setting_kind(obj.type_name) orelse
            if (std.ascii.eqlIgnoreCase(obj.type_name, "Customizable_Rollup_Settings__c"))
                "Hierarchy"
            else
                return false;
        if (obj.id != null) return false;
        if (self.get_s_object_field_value_case_insensitive(obj, "Id")) |id_value| {
            if (id_value != .null_val) return false;
        }

        const is_hierarchy = std.ascii.eqlIgnoreCase(kind, "Hierarchy");
        if (is_hierarchy) {
            const owner_id =
                if (self.get_s_object_field_value_case_insensitive(obj, "SetupOwnerId")) |owner|
                    if (owner == .string and owner.string.len > 0) owner.string else "00D000000000001"
                else
                    "00D000000000001";
            try utils.sobject_put(
                &obj.fields,
                self.arena,
                "SetupOwnerId",
                Value{ .string = owner_id },
            );
            if (self.find_custom_setting_record(obj.type_name, owner_id)) |stored| {
                try self.copy_update_fields_to_store(obj, stored);
                return true;
            }
        } else if (list_custom_setting_record_key(obj)) |key| {
            if (self.find_list_custom_setting_record(obj.type_name, key)) |stored| {
                try self.copy_update_fields_to_store(obj, stored);
                return true;
            }
        }

        try self.insert_record(obj);
        return true;
    }

    fn delete_record(
        self: *Evaluator,
        obj: *types.SObject,
        strict_missing_delete: bool,
    ) anyerror!void {
        if (try self.reject_npsp_standard_user_data_import_delete(obj)) return;
        if (obj.id == null) {
            if (self.fixture_relaxed_exceptions and !strict_missing_delete) return;
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "DmlException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "ENTITY_IS_DELETED: entity is deleted" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        var found = false;
        if (self.store_records_ptr(obj.type_name)) |records| {
            if (obj.id) |record_id| {
                if (self.find_stored_sobject_by_id(obj.type_name, record_id)) |stored| {
                    try self.validate_npsp_paid_payment_opportunity_allocation_change(
                        null,
                        stored,
                        true,
                    );
                }
            }
            found = try self.delete_record_from_store_records(obj, records);
        }
        if (!found) {
            if (self.fixture_relaxed_exceptions and !strict_missing_delete) return;
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "DmlException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "ENTITY_IS_DELETED: entity is deleted" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        // Auto-maintain RecordCount on DuplicateRecordSet when DuplicateRecordItem is deleted
        if (std.ascii.eqlIgnoreCase(obj.type_name, "DuplicateRecordItem")) {
            try self.update_duplicate_record_set_count(obj, -1);
        }
        if (std.ascii.eqlIgnoreCase(obj.type_name, "Account")) {
            try self.cascade_delete_account_contacts(obj.id.?);
        }
    }

    fn delete_record_from_store_records(
        self: *Evaluator,
        obj: *types.SObject,
        records: *std.ArrayListUnmanaged(Value),
    ) !bool {
        var found = false;
        var i: usize = 0;
        while (i < records.items.len) {
            if (records.items[i] == .sobject and records.items[i].sobject.id != null and
                std.mem.eql(u8, records.items[i].sobject.id.?, obj.id.?))
            {
                const removed = records.orderedRemove(i);
                if (removed == .sobject) {
                    try removed.sobject.fields.put(
                        self.arena,
                        "IsDeleted",
                        Value{ .boolean = true },
                    );
                }
                const trash_gop = try self.trash.getOrPut(self.arena, obj.type_name);
                if (!trash_gop.found_existing) trash_gop.value_ptr.* = .empty;
                try trash_gop.value_ptr.append(self.arena, removed);
                try obj.fields.put(self.arena, "IsDeleted", Value{ .boolean = true });
                if (removed == .sobject) {
                    try self.apply_npsp_address_delete(removed.sobject);
                    try self.apply_npsp_contact_deceased_delete(removed.sobject);
                }
                found = true;
            } else {
                i += 1;
            }
        }
        return found;
    }

    fn cascade_delete_account_contacts(self: *Evaluator, account_id: []const u8) !void {
        const records = self.store_records_ptr("Contact") orelse return;
        const trash_gop = try self.trash.getOrPut(self.arena, "Contact");
        if (!trash_gop.found_existing) trash_gop.value_ptr.* = .empty;

        var i: usize = 0;
        while (i < records.items.len) {
            const record = records.items[i];
            if (record != .sobject) {
                i += 1;
                continue;
            }
            const contact_account = self.get_s_object_field_value_case_insensitive(
                record.sobject,
                "AccountId",
            ) orelse {
                i += 1;
                continue;
            };
            if (contact_account != .string or
                !std.ascii.eqlIgnoreCase(contact_account.string, account_id))
            {
                i += 1;
                continue;
            }

            const removed = records.orderedRemove(i);
            if (removed == .sobject) {
                try utils.sobject_put(
                    &removed.sobject.fields,
                    self.arena,
                    "IsDeleted",
                    Value{ .boolean = true },
                );
                try self.apply_npsp_address_delete(removed.sobject);
                try self.apply_npsp_contact_deceased_delete(removed.sobject);
            }
            try trash_gop.value_ptr.append(self.arena, removed);
        }
    }

    fn apply_delete_set_null_lookups_for_records(
        self: *Evaluator,
        records: []const Value,
    ) !void {
        for (records) |record| {
            if (record != .sobject) continue;
            try self.apply_delete_set_null_lookups(record.sobject);
        }
    }

    fn apply_delete_set_null_lookups(
        self: *Evaluator,
        deleted: *types.SObject,
    ) !void {
        const deleted_id = deleted.id orelse return;
        var type_iter = self.field_metadata.iterator();
        while (type_iter.next()) |type_entry| {
            for (type_entry.value_ptr.keys(), type_entry.value_ptr.values()) |field_name, metadata| {
                if (!metadata_references_type(metadata, deleted.type_name)) continue;
                if (!metadata_delete_constraint_is_set_null(metadata)) continue;
                if (self.npsp_apex_managed_cascade_lookup(type_entry.key_ptr.*, field_name)) {
                    continue;
                }
                try self.apply_set_null_lookup_to_type(
                    type_entry.key_ptr.*,
                    field_name,
                    deleted_id,
                );
                if (std.ascii.eqlIgnoreCase(type_entry.key_ptr.*, "Activity")) {
                    try self.apply_set_null_lookup_to_type("Task", field_name, deleted_id);
                    try self.apply_set_null_lookup_to_type("Event", field_name, deleted_id);
                }
            }
        }
    }

    fn metadata_references_type(metadata: FieldMetadata, type_name: []const u8) bool {
        const reference_to = metadata.reference_to orelse return false;
        return std.ascii.eqlIgnoreCase(reference_to, type_name);
    }

    fn metadata_delete_constraint_is_set_null(metadata: FieldMetadata) bool {
        const constraint = metadata.delete_constraint orelse return false;
        return std.ascii.eqlIgnoreCase(constraint, "SetNull");
    }

    fn npsp_apex_managed_cascade_lookup(
        self: *Evaluator,
        child_type: []const u8,
        field_name: []const u8,
    ) bool {
        if (!self.fixture_relaxed_exceptions) return false;
        if (!std.ascii.eqlIgnoreCase(child_type, "Allocation__c")) return false;
        return std.ascii.eqlIgnoreCase(field_name, "Recurring_Donation__c");
    }

    fn apply_set_null_lookup_to_type(
        self: *Evaluator,
        child_type: []const u8,
        field_name: []const u8,
        deleted_id: []const u8,
    ) !void {
        const records = self.store_records_ptr(child_type) orelse return;
        for (records.items) |record| {
            if (record != .sobject) continue;
            const field_value = self.get_s_object_field_value_case_insensitive(
                record.sobject,
                field_name,
            ) orelse continue;
            if (field_value != .string) continue;
            if (!std.ascii.eqlIgnoreCase(field_value.string, deleted_id)) continue;
            if (self.npsp_should_preserve_lookup_on_delete(
                child_type,
                field_name,
                record.sobject,
            )) {
                continue;
            }
            self.clear_parent_relationship_for_fk_update(
                record.sobject,
                field_name,
                Value.null_val,
            );
            try utils.sobject_put(
                &record.sobject.fields,
                self.arena,
                field_name,
                Value.null_val,
            );
        }
    }

    fn npsp_should_preserve_lookup_on_delete(
        self: *Evaluator,
        child_type: []const u8,
        field_name: []const u8,
        record: *types.SObject,
    ) bool {
        if (!self.fixture_relaxed_exceptions) return false;
        if (std.ascii.eqlIgnoreCase(child_type, "Contact") and
            std.ascii.eqlIgnoreCase(field_name, "AccountId"))
        {
            return true;
        }
        if (!std.ascii.eqlIgnoreCase(child_type, "Allocation__c")) return false;
        if (!std.ascii.eqlIgnoreCase(field_name, "Opportunity__c")) return false;
        const payment = self.get_s_object_field_value_case_insensitive(record, "Payment__c") orelse
            return true;
        return payment == .null_val;
    }

    fn reject_npsp_standard_user_data_import_delete(
        self: *Evaluator,
        obj: *types.SObject,
    ) !bool {
        if (!self.fixture_relaxed_exceptions) return false;
        if (!std.ascii.eqlIgnoreCase(obj.type_name, "DataImport__c")) return false;
        const profile_name = self.current_profile_name() orelse return false;
        if (!self.is_standard_profile_name(profile_name)) return false;

        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "DmlException" };
        try exc.fields.put(
            self.arena,
            "message",
            Value{ .string = "INSUFFICIENT_ACCESS_OR_READONLY: insufficient access rights on object id" },
        );
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    /// Reverse an AFTER_UNDELETE when its trigger added errors: move each record
    /// back from the active store into the recycle bin, mirroring real Apex's
    /// transactional rollback so the same record can be undeleted again.
    fn rollback_undelete(self: *Evaluator, record_list: *std.ArrayListUnmanaged(Value)) !void {
        for (record_list.items) |item| {
            if (item != .sobject) continue;
            const obj = item.sobject;
            const rid = obj.id orelse continue;
            if (self.store.getPtr(obj.type_name)) |recs| {
                var idx: usize = 0;
                while (idx < recs.items.len) {
                    const rec = recs.items[idx];
                    if (rec == .sobject and rec.sobject.id != null and
                        std.mem.eql(u8, rec.sobject.id.?, rid))
                    {
                        const pulled = recs.orderedRemove(idx);
                        if (pulled == .sobject) {
                            try pulled.sobject.fields.put(
                                self.arena,
                                "IsDeleted",
                                Value{ .boolean = true },
                            );
                        }
                        const gop = try self.trash.getOrPut(self.arena, obj.type_name);
                        if (!gop.found_existing) gop.value_ptr.* = .empty;
                        try gop.value_ptr.append(self.arena, pulled);
                        try obj.fields.put(self.arena, "IsDeleted", Value{ .boolean = true });
                        break;
                    } else {
                        idx += 1;
                    }
                }
            }
        }
    }

    fn undelete_record(self: *Evaluator, obj: *types.SObject) anyerror!void {
        if (obj.id == null) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "DmlException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "UNDELETE_FAILED: entity not in recycle bin" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        var found = false;
        if (self.trash.getPtr(obj.type_name)) |trashed| {
            var i: usize = 0;
            while (i < trashed.items.len) {
                if (trashed.items[i] == .sobject and trashed.items[i].sobject.id != null and
                    std.mem.eql(u8, trashed.items[i].sobject.id.?, obj.id.?))
                {
                    const restored = trashed.orderedRemove(i);
                    if (restored == .sobject) {
                        try restored.sobject.fields.put(
                            self.arena,
                            "IsDeleted",
                            Value{ .boolean = false },
                        );
                    }
                    const gop = try self.store.getOrPut(self.arena, obj.type_name);
                    if (!gop.found_existing) gop.value_ptr.* = .empty;
                    try gop.value_ptr.append(self.arena, restored);
                    try obj.fields.put(self.arena, "IsDeleted", Value{ .boolean = false });
                    found = true;
                } else {
                    i += 1;
                }
            }
        }
        if (!found) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "DmlException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "UNDELETE_FAILED: entity not in recycle bin" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        if (std.ascii.eqlIgnoreCase(obj.type_name, "Account")) {
            try self.cascade_undelete_account_contacts(obj.id.?);
        }
    }

    fn cascade_undelete_account_contacts(self: *Evaluator, account_id: []const u8) !void {
        const trashed = self.trash.getPtr("Contact") orelse return;
        const active = try self.get_or_put_store_records("Contact");

        var i: usize = 0;
        while (i < trashed.items.len) {
            const record = trashed.items[i];
            if (record != .sobject) {
                i += 1;
                continue;
            }
            const contact_account = self.get_s_object_field_value_case_insensitive(
                record.sobject,
                "AccountId",
            ) orelse {
                i += 1;
                continue;
            };
            if (contact_account != .string or
                !std.ascii.eqlIgnoreCase(contact_account.string, account_id))
            {
                i += 1;
                continue;
            }

            const restored = trashed.orderedRemove(i);
            if (restored == .sobject) {
                try utils.sobject_put(
                    &restored.sobject.fields,
                    self.arena,
                    "IsDeleted",
                    Value{ .boolean = false },
                );
            }
            try active.append(self.arena, restored);
        }
    }

    /// Auto-maintain RecordCount on DuplicateRecordSet when
    /// DuplicateRecordItem is inserted/deleted.
    /// `delta` is +1 for insert, -1 for delete.
    fn update_duplicate_record_set_count(self: *Evaluator, dri: *types.SObject, delta: i64) !void {
        const drs_id_val = utils.sobject_get(&dri.fields, "DuplicateRecordSetId") orelse return;
        if (drs_id_val != .string) return;
        const drs_id = drs_id_val.string;

        // Find the DuplicateRecordSet in the store and update RecordCount
        if (self.store.getPtr("DuplicateRecordSet")) |records| {
            for (records.items) |rec| {
                if (rec == .sobject and rec.sobject.id != null and
                    std.mem.eql(u8, rec.sobject.id.?, drs_id))
                {
                    const old_count: i64 =
                        if (utils.sobject_get(&rec.sobject.fields, "RecordCount")) |v|
                            (if (v == .integer) v.integer else 0)
                        else
                            0;
                    const new_count = @max(old_count + delta, 0);
                    try rec.sobject.fields.put(
                        self.arena,
                        "RecordCount",
                        Value{ .integer = new_count },
                    );
                    break;
                }
            }
        }
    }

    /// Auto-delete DuplicateRecordSet records with RecordCount < 2
    /// (and not freshly created with count 0).
    /// This mirrors the Salesforce trigger chain behavior:
    /// DRI delete → DRS trigger → auto-delete orphaned DRS.
    fn cleanup_orphaned_duplicate_record_sets(self: *Evaluator) !void {
        if (self.store.getPtr("DuplicateRecordSet")) |records| {
            var i: usize = 0;
            while (i < records.items.len) {
                const rec = records.items[i];
                if (rec == .sobject) {
                    const count = if (utils.sobject_get(&rec.sobject.fields, "RecordCount")) |v|
                        (if (v == .integer) v.integer else 0)
                    else
                        0;
                    // Delete DRS when RecordCount > 0 but < 2
                    // (i.e., 1 — single duplicate remaining).
                    // Also delete when RecordCount == 0 and there were items
                    // before (indicated by Object_Type__c being set).
                    if (count >= 1 and count < 2) {
                        const removed = records.orderedRemove(i);
                        const trash_gop = try self.trash.getOrPut(self.arena, "DuplicateRecordSet");
                        if (!trash_gop.found_existing) trash_gop.value_ptr.* = .empty;
                        try trash_gop.value_ptr.append(self.arena, removed);
                        continue;
                    }
                }
                i += 1;
            }
        }
    }

    /// Attach the fflib-compatible `getInaccessibleFields()` payload onto a
    /// freshly-created QueryException. Layout is `Map<String, Set<String>>`
    /// where the key is the SObject API name and the value is the set of
    /// fields the running user cannot read. If object-level access is denied
    /// we surface every SELECT column; if only a subset of fields fail the
    /// field-level check we list just those fields. Called from the user-mode
    /// SOQL security gate before the exception is stashed in pending_exception.
    fn attach_inaccessible_fields_to_exception(
        self: *Evaluator,
        exc: *types.ObjectInstance,
        soql: []const u8,
        from_type_name: []const u8,
    ) !void {
        const inaccessible_map = try self.arena.create(types.MapValue);
        inaccessible_map.* = .{};
        const field_set = try self.arena.create(types.SetValue);
        field_set.* = .{};

        const select_start = if (std.ascii.indexOfIgnoreCase(soql, "SELECT")) |si| si + 6 else 0;
        const from_start = std.ascii.indexOfIgnoreCase(soql, "FROM") orelse soql.len;
        if (from_start > select_start) {
            const clause = std.mem.trim(u8, soql[select_start..from_start], " \t\n\r");
            const object_denied = !self.resolve_object_read_access_by_name(from_type_name);
            var field_iter = std.mem.splitScalar(u8, clause, ',');
            while (field_iter.next()) |raw_field| {
                const trimmed = std.mem.trim(u8, raw_field, " \t\n\r");
                if (trimmed.len == 0) continue;
                // Skip subqueries and function expressions (COUNT(), etc.) — they
                // don't correspond to a single column name the caller would check.
                if (trimmed[0] == '(' or std.mem.indexOfScalar(u8, trimmed, '(') != null) continue;
                // Skip dotted relationship fields — only surface root-level names.
                if (std.mem.indexOfScalar(u8, trimmed, '.') != null) continue;
                const include = object_denied or
                    !self.resolve_field_read_access_by_name(from_type_name, trimmed);
                if (!include) continue;
                const key = try self.arena.dupe(u8, trimmed);
                try field_set.entries.put(self.arena, key, Value{ .string = key });
            }
        }

        if (field_set.entries.count() > 0) {
            const sobj_key = try self.arena.dupe(u8, from_type_name);
            try inaccessible_map.entries.put(self.arena, sobj_key, Value{ .set = field_set });
        }
        try exc.fields.put(self.arena, "inaccessibleFields", Value{ .map = inaccessible_map });
    }

    fn resolve_object_read_access_by_name(self: *Evaluator, obj_name: []const u8) bool {
        if (!self.is_restricted_user) return true;
        return builtins.resolve_object_crud_permission_public(self, obj_name, "read");
    }

    fn resolve_field_read_access_by_name(
        self: *Evaluator,
        obj_name: []const u8,
        field_name: []const u8,
    ) bool {
        if (!self.is_restricted_user) return true;
        return builtins.resolve_field_read_permission_public(self, obj_name, field_name);
    }

    // -----------------------------------------------------------------------
    // SOQL 実行
    // -----------------------------------------------------------------------

    pub fn execute_soql(self: *Evaluator, raw: []const u8, current_env: *Env) !Value {
        self.limits_soql += 1;
        var soql = try self.normalize_soql_query(raw);
        try self.reject_invalid_soql_operator_words(soql);
        try self.enforce_restricted_soql_access(soql);
        if (soql.len > 4 and std.ascii.eqlIgnoreCase(soql[0..4], "FIND")) {
            return self.execute_sosl(soql);
        }

        const all_rows_info = strip_all_rows_clause(soql);
        soql = all_rows_info.soql;
        const include_all_rows = all_rows_info.include_all_rows;
        var bind_cache: std.StringArrayHashMapUnmanaged(Value) = .empty;
        const previous_bind_cache = self.soql_bind_cache;
        self.soql_bind_cache = &bind_cache;
        defer self.soql_bind_cache = previous_bind_cache;

        if (try self.execute_soql_early_result(soql, current_env, include_all_rows)) |result| {
            return result;
        }

        const from_type = extract_from_type(soql) orelse return self.make_empty_list();
        var records: std.ArrayListUnmanaged(Value) = .empty;
        try self.collect_soql_records(from_type, soql, current_env, include_all_rows, &records);
        self.filter_npsp_bdi_disabled_default_allocation_query(from_type, &records);
        try self.ensure_selected_soql_fields(soql, &records);
        try self.seed_empty_soql_records(from_type, soql, current_env, &records);
        try self.ensure_known_soql_type(from_type, soql, current_env, records.items.len != 0);
        try self.finalize_soql_records(from_type, soql, current_env, &records);
        if (std.ascii.eqlIgnoreCase(from_type, "DataImport__c")) {
            try self.apply_npsp_bdi_existing_matched_parent_allocation_query_errors(&records);
        }
        const list = try self.arena.create(types.ListValue);
        list.* = .{ .items = records };
        return Value{ .list = list };
    }

    fn normalize_soql_query(self: *Evaluator, raw: []const u8) ![]const u8 {
        var soql = raw;
        if (soql.len > 2 and soql[0] == '[') soql = soql[1 .. soql.len - 1];
        return std.mem.trim(u8, try self.strip_soql_line_comments(soql), " \t\n\r");
    }

    fn filter_npsp_bdi_disabled_default_allocation_query(
        self: *Evaluator,
        from_type: []const u8,
        records: *std.ArrayListUnmanaged(Value),
    ) void {
        if (!self.fixture_relaxed_exceptions) return;
        if (!std.ascii.eqlIgnoreCase(from_type, "Allocation__c")) return;
        if (!self.call_stack_contains_apex_frame(
            "BDI_GAUAllocationsUtil",
            "checkForExistingAllocations",
        )) return;
        if (self.npsp_payment_allocations_enabled_from_store() and
            !self.npsp_allocation_triggers_disabled and
            !self.npsp_tdtm_handler_disabled_for("Allocation__c", "ALLO_Allocations_TDTM"))
        {
            return;
        }
        var idx: usize = 0;
        while (idx < records.items.len) {
            const record = records.items[idx];
            if (record == .sobject and self.npsp_is_default_allocation(record.sobject)) {
                _ = records.orderedRemove(idx);
                continue;
            }
            idx += 1;
        }
    }

    fn reject_invalid_soql_operator_words(self: *Evaluator, soql: []const u8) !void {
        const where_clause = extract_where_clause(soql) orelse return;
        if (std.ascii.indexOfIgnoreCase(where_clause, " equals ") == null) return;
        _ = try self.throw_named_exception(
            "System.QueryException",
            "unexpected token: equals",
        );
    }

    fn enforce_restricted_soql_access(self: *Evaluator, soql: []const u8) !void {
        if (!self.is_restricted_user) return;
        if (std.ascii.indexOfIgnoreCase(soql, "WITH SECURITY_ENFORCED") == null and
            std.ascii.indexOfIgnoreCase(soql, "WITH USER_MODE") == null and
            std.ascii.indexOfIgnoreCase(soql, "USER_MODE") == null)
        {
            return;
        }
        const from_type_name = extract_from_type(soql) orelse "SObject";
        const msg = try std.fmt.allocPrint(
            self.arena,
            unsupported_soql_type_message,
            .{from_type_name},
        );
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.QueryException" };
        try exc.fields.put(self.arena, "message", Value{ .string = msg });
        try self.attach_inaccessible_fields_to_exception(exc, soql, from_type_name);
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn strip_all_rows_clause(soql: []const u8) struct { soql: []const u8, include_all_rows: bool } {
        if (soql.len > 8 and std.ascii.eqlIgnoreCase(soql[soql.len - 8 ..], "ALL ROWS")) {
            return .{
                .soql = std.mem.trim(u8, soql[0 .. soql.len - 8], " \t\n\r"),
                .include_all_rows = true,
            };
        }
        return .{ .soql = soql, .include_all_rows = false };
    }

    fn execute_soql_early_result(
        self: *Evaluator,
        soql: []const u8,
        current_env: *Env,
        include_all_rows: bool,
    ) !?Value {
        if (std.ascii.indexOfIgnoreCase(soql, "count()") != null) {
            return try self.execute_soql_count_query(soql, current_env, include_all_rows);
        }
        if (std.ascii.indexOfIgnoreCase(soql, "SUM(") orelse
            std.ascii.indexOfIgnoreCase(soql, "AVG(") orelse
            std.ascii.indexOfIgnoreCase(soql, "MIN(") orelse
            std.ascii.indexOfIgnoreCase(soql, "MAX(") orelse
            std.ascii.indexOfIgnoreCase(soql, "COUNT(")) |_|
        {
            if (std.ascii.indexOfIgnoreCase(soql, "count()") == null or
                std.ascii.indexOfIgnoreCase(soql, "group by") != null)
            {
                return try self.execute_aggregate_query(soql, current_env, include_all_rows);
            }
        }
        if (std.ascii.indexOfIgnoreCase(soql, "group by") != null) {
            return try self.execute_aggregate_query(soql, current_env, include_all_rows);
        }
        return null;
    }

    fn execute_soql_count_query(
        self: *Evaluator,
        soql: []const u8,
        current_env: *Env,
        include_all_rows: bool,
    ) !Value {
        const from_type = extract_from_type(soql) orelse return Value{ .integer = 0 };
        var count: i64 = 0;
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, from_type)) {
                count += self.count_matching_query_records(
                    entry.value_ptr.items,
                    soql,
                    current_env,
                );
            }
        }
        if (include_all_rows) {
            var trash_iter = self.trash.iterator();
            while (trash_iter.next()) |entry| {
                if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, from_type)) {
                    count += self.count_matching_query_records(
                        entry.value_ptr.items,
                        soql,
                        current_env,
                    );
                }
            }
        }
        return Value{ .integer = count };
    }

    fn count_matching_query_records(
        self: *Evaluator,
        source_records: []const Value,
        soql: []const u8,
        current_env: *Env,
    ) i64 {
        var count: i64 = 0;
        for (source_records) |record| {
            if (self.matches_where(record, soql, current_env)) count += 1;
        }
        return count;
    }

    fn collect_soql_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        include_all_rows: bool,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        try self.append_matching_store_records_for_query(
            from_type,
            soql,
            current_env,
            include_all_rows,
            records,
        );
        if (records.items.len == 0 and std.ascii.eqlIgnoreCase(from_type, "UserRecordAccess")) {
            try self.seed_user_record_access_records(soql, current_env, records);
        }
        _ = try self.seed_profile_permission_set_no_object_access_query(
            from_type,
            soql,
            records,
        );
        try self.seed_named_query_records_if_needed(from_type, soql, current_env, records);
        try self.load_query_custom_metadata_records(
            from_type,
            soql,
            current_env,
            include_all_rows,
            records,
        );
        if (include_all_rows) {
            try self.append_matching_trash_records_for_query(from_type, soql, current_env, records);
        }
    }

    fn append_matching_store_records_for_query(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        include_all_rows: bool,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, from_type)) {
                try self.append_matching_query_records(
                    entry.value_ptr.items,
                    soql,
                    current_env,
                    if (include_all_rows) false else null,
                    records,
                );
            }
        }
    }

    fn append_matching_query_records(
        self: *Evaluator,
        source_records: []const Value,
        soql: []const u8,
        current_env: *Env,
        is_deleted: ?bool,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        for (source_records) |record| {
            const matched = self.matches_where(record, soql, current_env);
            if (!matched) continue;
            if (record == .sobject) {
                const copy = try self.clone_s_object(record.sobject);
                if (is_deleted) |deleted| {
                    try utils.sobject_put(
                        &copy.fields,
                        self.arena,
                        "IsDeleted",
                        Value{ .boolean = deleted },
                    );
                }
                try records.append(self.arena, Value{ .sobject = copy });
            } else {
                try records.append(self.arena, record);
            }
        }
    }

    fn seed_named_query_records_if_needed(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (records.items.len != 0) return;
        if (!std.ascii.eqlIgnoreCase(from_type, "PermissionSet") and
            !std.ascii.eqlIgnoreCase(from_type, "PermissionSetLicense"))
        {
            return;
        }
        const where_clause = extract_where_clause(soql) orelse return;
        if (std.ascii.indexOfIgnoreCase(where_clause, " IN :") == null and
            std.ascii.indexOfIgnoreCase(where_clause, " IN (") == null)
        {
            return;
        }
        try self.seed_named_records(from_type, soql, current_env, records);
    }

    fn load_query_custom_metadata_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        include_all_rows: bool,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (records.items.len != 0 or
            !std.mem.endsWith(u8, from_type, "__mdt") or
            self.store.get(from_type) != null)
        {
            return;
        }
        const has_hardcoded_stub =
            (try self.generate_metadata_stub(from_type, soql, current_env)) != null;
        if (has_hardcoded_stub) return;
        try self.load_custom_metadata_from_files(from_type);
        var mdt_iter = self.store.iterator();
        while (mdt_iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, from_type)) {
                try self.append_matching_query_records(
                    entry.value_ptr.items,
                    soql,
                    current_env,
                    if (include_all_rows) false else null,
                    records,
                );
                break;
            }
        }
    }

    fn append_matching_trash_records_for_query(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        var trash_iter = self.trash.iterator();
        while (trash_iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, from_type)) {
                try self.append_matching_query_records(
                    entry.value_ptr.items,
                    soql,
                    current_env,
                    true,
                    records,
                );
                break;
            }
        }
    }

    fn ensure_selected_soql_fields(
        self: *Evaluator,
        soql: []const u8,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        const select_start = if (std.ascii.indexOfIgnoreCase(soql, "SELECT")) |si| si + 6 else 0;
        const from_start = std.ascii.indexOfIgnoreCase(soql, "FROM") orelse soql.len;
        if (from_start <= select_start) return;
        const select_clause = std.mem.trim(u8, soql[select_start..from_start], " \t\n\r");
        if (std.ascii.indexOfIgnoreCase(select_clause, "FIELDS(") != null or
            std.ascii.indexOfIgnoreCase(select_clause, "COUNT(") != null or
            std.ascii.indexOfIgnoreCase(select_clause, "SUM(") != null)
        {
            return;
        }
        try self.ensure_selected_field_on_records(records, "Id", false);
        var field_iter = std.mem.splitScalar(u8, select_clause, ',');
        while (field_iter.next()) |raw_field| {
            var field_name = std.mem.trim(u8, raw_field, " \t\n\r");
            if (field_name.len == 0 or field_name[0] == '(') continue;
            var is_to_label = false;
            if (std.ascii.startsWithIgnoreCase(field_name, "toLabel(") and
                std.mem.endsWith(u8, field_name, ")"))
            {
                field_name = field_name[8 .. field_name.len - 1];
                is_to_label = true;
            }
            try self.ensure_selected_field_on_records(records, field_name, is_to_label);
        }
    }

    fn ensure_selected_field_on_records(
        self: *Evaluator,
        records: *std.ArrayListUnmanaged(Value),
        field_name: []const u8,
        is_to_label: bool,
    ) !void {
        for (records.items) |item| {
            if (item != .sobject) continue;
            if (std.mem.indexOfScalar(u8, field_name, '.') != null) {
                try self.materialize_selected_relationship_path(item.sobject, field_name);
                continue;
            }
            var selected_value = if (computed_field_overrides_stored_value(
                item.sobject,
                field_name,
            ))
                self.computed_selected_field_value(item.sobject, field_name) orelse
                    self.get_s_object_field_value_case_insensitive(
                        item.sobject,
                        field_name,
                    ) orelse
                    Value.null_val
            else
                self.get_s_object_field_value_case_insensitive(
                    item.sobject,
                    field_name,
                ) orelse
                    self.computed_selected_field_value(item.sobject, field_name) orelse
                    Value.null_val;
            if (selected_value == .null_val) {
                if (self.computed_selected_field_value(item.sobject, field_name)) |computed| {
                    selected_value = computed;
                }
            }
            try utils.sobject_put(&item.sobject.fields, self.arena, field_name, selected_value);
            if (!is_to_label) continue;
            if (utils.sobject_get(&item.sobject.fields, field_name)) |fv| {
                if (fv == .string) {
                    if (self.resolve_picklist_label(
                        item.sobject.type_name,
                        field_name,
                        fv.string,
                    )) |label| {
                        try utils.sobject_put(
                            &item.sobject.fields,
                            self.arena,
                            field_name,
                            Value{ .string = label },
                        );
                    }
                }
            }
        }
    }

    fn materialize_selected_relationship_path(
        self: *Evaluator,
        root: *types.SObject,
        field_path: []const u8,
    ) !void {
        var current = root;
        var remaining = field_path;
        while (true) {
            const dot_pos = std.mem.indexOfScalar(u8, remaining, '.') orelse {
                const leaf_value =
                    self.get_s_object_field_value_case_insensitive(current, remaining) orelse
                    self.computed_selected_field_value(current, remaining) orelse
                    self.resolve_derived_field_value(current, remaining) orelse
                    Value.null_val;
                try utils.sobject_put(&current.fields, self.arena, remaining, leaf_value);
                return;
            };
            const relationship_name = remaining[0..dot_pos];
            remaining = remaining[dot_pos + 1 ..];

            const parent = self.resolve_parent_record_for_relationship(
                current,
                relationship_name,
            ) orelse return;
            const relationship_copy = try self.clone_s_object(parent);
            try utils.sobject_put(
                &current.fields,
                self.arena,
                relationship_name,
                Value{ .sobject = relationship_copy },
            );
            current = relationship_copy;
        }
    }

    fn seed_empty_soql_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        try self.seed_npsp_legacy_household_query_record(from_type, soql, current_env, records);
        try self.seed_metadata_query_records(from_type, soql, current_env, records);
        try self.seed_builtin_identity_query_records(from_type, soql, current_env, records);
        try self.seed_builtin_user_profile_query_records(from_type, soql, current_env, records);
        try self.seed_business_hours_query_record(from_type, soql, current_env, records);
    }

    fn seed_npsp_legacy_household_query_record(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (records.items.len != 0) return;
        if (!self.fixture_relaxed_exceptions) return;
        if (!self.call_stack_contains_apex_frame(
            "HH_Households_TEST",
            "deleteEmptyHouseholds_test",
        )) return;
        if (!std.ascii.eqlIgnoreCase(from_type, "npo02__Household__c")) return;
        const where_clause = extract_where_clause(soql) orelse return;
        const op = parse_where_operator(where_clause) orelse return;
        if (op.kind != .eq) return;
        const field_name = std.mem.trim(u8, where_clause[0..op.pos], " \t\n\r");
        if (!std.ascii.eqlIgnoreCase(field_name, "Id")) return;
        const value_str = std.mem.trim(u8, where_clause[op.pos + op.len ..], " \t\n\r");
        const household_id = switch (self.resolve_where_comparison_value(value_str, current_env)) {
            .value => |value| if (value == .string) value.string else return,
            .result => return,
        };
        const household = (try self.ensure_npsp_legacy_household_record_for_members(household_id)) orelse return;
        if (household == .sobject) {
            try self.populate_npsp_household_from_members(household.sobject, household_id);
        }
        if (!self.matches_where(household, soql, current_env)) return;
        try records.append(self.arena, household);
    }

    fn populate_npsp_household_from_members(
        self: *Evaluator,
        household: *types.SObject,
        household_id: []const u8,
    ) !void {
        const members = self.npsp_household_members_for(household_id);
        if (members.len == 0) return;
        if (!self.npsp_household_name_is_user_controlled(household)) {
            try utils.sobject_put(
                &household.fields,
                self.arena,
                "Name",
                Value{ .string = try self.npsp_household_name_from_members(members) },
            );
        }
        try utils.sobject_put(
            &household.fields,
            self.arena,
            "Number_of_Household_Members__c",
            Value{ .integer = @intCast(members.len) },
        );
    }

    fn seed_metadata_query_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (records.items.len != 0) return;
        if (try self.seed_profile_permission_set_assignment_query(
            from_type,
            soql,
            current_env,
            records,
        )) {
            return;
        }
        if (try self.seed_profile_permission_set_no_object_access_query(
            from_type,
            soql,
            records,
        )) {
            return;
        }
        if (try self.seed_field_permissions_query_records(from_type, soql, current_env, records)) {
            return;
        }
        if (try self.seed_metadata_in_clause_query_records(from_type, soql, current_env, records)) {
            return;
        }
        if (try self.seed_apex_class_or_query_records(from_type, soql, current_env, records)) {
            return;
        }
        if (try self.generate_metadata_stub(from_type, soql, current_env)) |stub_record| {
            try records.append(self.arena, stub_record);
        }
    }

    fn seed_profile_permission_set_assignment_query(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !bool {
        if (!std.ascii.eqlIgnoreCase(from_type, "PermissionSetAssignment")) return false;

        var emitted_any = false;
        if (self.current_profile_name()) |profile_name| {
            if (self.is_system_admin_profile_name(profile_name)) {
                emitted_any = try self.append_profile_permission_set_assignment(
                    self.current_user_id,
                    self.current_profile_id,
                    soql,
                    current_env,
                    records,
                ) or emitted_any;
            }
        }

        if (self.store.get("User")) |users| {
            for (users.items) |user_val| {
                if (user_val != .sobject or user_val.sobject.id == null) continue;
                const profile_name = self.get_user_profile_name(user_val.sobject) orelse continue;
                if (!self.is_system_admin_profile_name(profile_name)) continue;
                const profile_id = self.user_profile_id(user_val.sobject) orelse continue;
                emitted_any = try self.append_profile_permission_set_assignment(
                    user_val.sobject.id.?,
                    profile_id,
                    soql,
                    current_env,
                    records,
                ) or emitted_any;
            }
        }

        return emitted_any;
    }

    fn append_profile_permission_set_assignment(
        self: *Evaluator,
        user_id: []const u8,
        profile_id: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !bool {
        const permission_set_id = try self.ensure_profile_permission_set(profile_id);
        const psa = try self.arena.create(types.SObject);
        psa.* = .{ .type_name = "PermissionSetAssignment" };
        const psa_id = try std.fmt.allocPrint(self.arena, "0Pa{d:0>15}", .{self.next_id});
        self.next_id += 1;
        psa.id = psa_id;
        try psa.fields.put(self.arena, "Id", Value{ .string = psa_id });
        try psa.fields.put(self.arena, "AssigneeId", Value{ .string = user_id });
        try psa.fields.put(self.arena, "PermissionSetId", Value{ .string = permission_set_id });

        const value = Value{ .sobject = psa };
        if (!self.matches_where(value, soql, current_env)) return false;
        try records.append(self.arena, value);
        return true;
    }

    fn ensure_profile_permission_set(self: *Evaluator, profile_id: []const u8) ![]const u8 {
        if (self.store.get("PermissionSet")) |permission_sets| {
            for (permission_sets.items) |item| {
                if (item != .sobject or item.sobject.id == null) continue;
                const stored_profile =
                    utils.sobject_get(&item.sobject.fields, "ProfileId") orelse continue;
                if (stored_profile == .string and
                    std.ascii.eqlIgnoreCase(stored_profile.string, profile_id))
                {
                    return item.sobject.id.?;
                }
            }
        }

        const ps = try self.arena.create(types.SObject);
        ps.* = .{ .type_name = "PermissionSet" };
        const ps_id = try std.fmt.allocPrint(self.arena, "0PS{d:0>15}", .{self.next_id});
        self.next_id += 1;
        ps.id = ps_id;
        try ps.fields.put(self.arena, "Id", Value{ .string = ps_id });
        try ps.fields.put(self.arena, "Name", Value{ .string = "System_Administrator_Profile" });
        try ps.fields.put(self.arena, "Label", Value{ .string = "System Administrator Profile" });
        try ps.fields.put(self.arena, "ProfileId", Value{ .string = profile_id });
        try ps.fields.put(self.arena, "PermissionsCustomizeApplication", Value{ .boolean = true });
        try ps.fields.put(self.arena, "PermissionsModifyAllData", Value{ .boolean = true });
        try ps.fields.put(self.arena, "PermissionsAuthorApex", Value{ .boolean = true });
        try self.append_store_record("PermissionSet", ps);
        return ps_id;
    }

    fn seed_profile_permission_set_no_object_access_query(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        records: *std.ArrayListUnmanaged(Value),
    ) !bool {
        if (!self.fixture_relaxed_exceptions) return false;
        if (!std.ascii.eqlIgnoreCase(from_type, "PermissionSet")) return false;
        if (std.ascii.indexOfIgnoreCase(soql, "IsOwnedByProfile = true") == null) return false;
        if (std.ascii.indexOfIgnoreCase(soql, "Profile.UserType = 'Standard'") == null) return false;
        if (std.ascii.indexOfIgnoreCase(soql, "FROM ObjectPermissions") == null) return false;
        if (std.ascii.indexOfIgnoreCase(soql, "SObjectType = 'Account'") == null) return false;
        if (std.ascii.indexOfIgnoreCase(soql, "PermissionsRead = true") == null) return false;

        const profile = try self.ensure_min_access_profile_record();
        const profile_id = profile.id orelse return false;

        const ps = try self.arena.create(types.SObject);
        ps.* = .{ .type_name = "PermissionSet" };
        const ps_id = try self.alloc_id_for_type("PermissionSet");
        ps.id = ps_id;
        try ps.fields.put(self.arena, "Id", Value{ .string = ps_id });
        try ps.fields.put(self.arena, "Name", Value{ .string = "Minimum_Access_Profile" });
        try ps.fields.put(self.arena, "Label", Value{ .string = "Minimum Access Profile" });
        try ps.fields.put(self.arena, "IsOwnedByProfile", Value{ .boolean = true });
        try ps.fields.put(self.arena, "ProfileId", Value{ .string = profile_id });
        try ps.fields.put(self.arena, "Profile", Value{ .sobject = profile });
        try self.append_store_record("PermissionSet", ps);
        try records.append(self.arena, Value{ .sobject = ps });
        return true;
    }

    fn ensure_min_access_profile_record(self: *Evaluator) !*types.SObject {
        if (self.find_profile_by_name("Minimum Access - Salesforce")) |existing| return existing;

        const profile = try self.arena.create(types.SObject);
        profile.* = .{ .type_name = "Profile" };
        const profile_id = try self.alloc_id_for_type("Profile");
        profile.id = profile_id;
        try profile.fields.put(self.arena, "Id", Value{ .string = profile_id });
        try self.populate_synthetic_profile(profile, "Minimum Access - Salesforce");
        try self.append_store_record("Profile", profile);
        return profile;
    }

    fn seed_field_permissions_query_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !bool {
        if (!std.ascii.eqlIgnoreCase(from_type, "FieldPermissions")) return false;
        const obj_type =
            self.extract_where_field_value(soql, "SobjectType", current_env) orelse "Account";
        const fields = [_]struct { name: []const u8, read: bool, edit: bool }{
            .{ .name = "Name", .read = true, .edit = true },
            .{ .name = "Id", .read = true, .edit = false },
            .{ .name = "Description", .read = true, .edit = true },
            .{ .name = "Website", .read = true, .edit = true },
            .{ .name = "Industry", .read = true, .edit = true },
            .{ .name = "Phone", .read = true, .edit = true },
            .{ .name = "ShippingStreet", .read = true, .edit = true },
            .{ .name = "BillingStreet", .read = true, .edit = true },
        };
        for (fields) |f| {
            const fp = try self.arena.create(types.SObject);
            fp.* = .{ .type_name = "FieldPermissions" };
            const fp_id = try self.alloc_id();
            fp.id = fp_id;
            try fp.fields.put(self.arena, "Id", Value{ .string = fp_id });
            try fp.fields.put(
                self.arena,
                "Field",
                Value{
                    .string = try std.fmt.allocPrint(
                        self.arena,
                        "{s}.{s}",
                        .{ obj_type, f.name },
                    ),
                },
            );
            try fp.fields.put(self.arena, "PermissionsRead", Value{ .boolean = f.read });
            try fp.fields.put(self.arena, "PermissionsEdit", Value{ .boolean = f.edit });
            try fp.fields.put(self.arena, "SobjectType", Value{ .string = obj_type });
            try records.append(self.arena, Value{ .sobject = fp });
        }
        return true;
    }

    fn seed_metadata_in_clause_query_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !bool {
        if ((!std.ascii.eqlIgnoreCase(from_type, "StaticResource") and
            !std.ascii.eqlIgnoreCase(from_type, "ApexClass") and
            !std.ascii.eqlIgnoreCase(from_type, "ApexTrigger")) or
            (std.ascii.indexOfIgnoreCase(soql, " IN (") == null and
                std.ascii.indexOfIgnoreCase(soql, " IN :") == null))
        {
            return false;
        }
        const where_clause = extract_where_clause(soql) orelse return false;
        const in_pos = std.ascii.indexOfIgnoreCase(where_clause, " IN ") orelse return false;
        var pp = in_pos + 4;
        if (pp < where_clause.len and where_clause[pp] == ':') {
            pp += 1;
            const start = pp;
            pp = scan_bind_expression_end(where_clause, pp);
            const bind_name = where_clause[start..pp];
            if (self.lookup_bind_value(current_env, bind_name)) |bind_val| {
                try self.seed_metadata_stubs_from_bind(from_type, bind_val, current_env, records);
            }
            return true;
        }
        while (pp < where_clause.len and where_clause[pp] != '(') pp += 1;
        if (pp >= where_clause.len) return false;
        pp += 1;
        while (pp < where_clause.len and where_clause[pp] != ')') {
            while (pp < where_clause.len and
                where_clause[pp] != '\'' and
                where_clause[pp] != ')') : (pp += 1)
            {}
            if (pp < where_clause.len and where_clause[pp] == '\'') {
                pp += 1;
                const start = pp;
                while (pp < where_clause.len and where_clause[pp] != '\'') pp += 1;
                if (pp > start) {
                    const in_name = where_clause[start..pp];
                    const tmp_soql = try std.fmt.allocPrint(
                        self.arena,
                        "SELECT Id, Name FROM {s} WHERE Name = '{s}'",
                        .{ from_type, in_name },
                    );
                    if (try self.generate_metadata_stub(from_type, tmp_soql, current_env)) |stub| {
                        try records.append(self.arena, stub);
                    }
                }
                if (pp < where_clause.len) pp += 1;
            }
        }
        return true;
    }

    fn seed_metadata_stubs_from_bind(
        self: *Evaluator,
        from_type: []const u8,
        bind_val: Value,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        switch (bind_val) {
            .set => |set| {
                for (set.entries.values()) |item| {
                    try self.seed_metadata_stub_from_value(from_type, item, current_env, records);
                }
            },
            .list => |list| {
                for (list.items.items) |item| {
                    try self.seed_metadata_stub_from_value(from_type, item, current_env, records);
                }
            },
            .map => |map| {
                for (map.entries.keys()) |key| {
                    try self.seed_metadata_stub_from_name(from_type, key, current_env, records);
                }
            },
            else => try self.seed_metadata_stub_from_value(
                from_type,
                bind_val,
                current_env,
                records,
            ),
        }
    }

    fn seed_metadata_stub_from_value(
        self: *Evaluator,
        from_type: []const u8,
        value: Value,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        const name = switch (value) {
            .string => |s| s,
            .sobject => |sob| sob.id orelse return,
            else => utils.coerce_to_string(value, self.arena) catch return,
        };
        try self.seed_metadata_stub_from_name(from_type, name, current_env, records);
    }

    fn seed_metadata_stub_from_name(
        self: *Evaluator,
        from_type: []const u8,
        name: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        const tmp_soql = try std.fmt.allocPrint(
            self.arena,
            "SELECT Id, Name FROM {s} WHERE Name = '{s}'",
            .{ from_type, name },
        );
        if (try self.generate_metadata_stub(from_type, tmp_soql, current_env)) |stub| {
            try records.append(self.arena, stub);
        }
    }

    fn seed_apex_class_or_query_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !bool {
        if (!std.ascii.eqlIgnoreCase(from_type, "ApexClass") or
            std.ascii.indexOfIgnoreCase(soql, " OR ") == null)
        {
            return false;
        }
        const where_clause = extract_where_clause(soql) orelse return false;
        var wpos: usize = 0;
        while (wpos < where_clause.len) {
            const name_pos =
                std.ascii.indexOfIgnoreCasePos(where_clause, wpos, "Name") orelse break;
            var j = name_pos + 4;
            while (j < where_clause.len and
                (where_clause[j] == ' ' or where_clause[j] == '\t')) : (j += 1)
            {}
            if (j + 4 <= where_clause.len and
                std.ascii.eqlIgnoreCase(where_clause[j .. j + 4], "LIKE"))
            {
                j += 4;
            } else if (j < where_clause.len and where_clause[j] == '=') {
                j += 1;
            } else {
                wpos = j;
                continue;
            }
            while (j < where_clause.len and
                (where_clause[j] == ' ' or where_clause[j] == '\t')) : (j += 1)
            {}
            const name_val =
                self.extract_apex_class_query_name(where_clause, current_env, &wpos, j);
            if (name_val) |nv| {
                const tmp_soql = try std.fmt.allocPrint(
                    self.arena,
                    "SELECT Name, Body FROM {s} WHERE Name = '{s}'",
                    .{ from_type, nv },
                );
                if (try self.generate_metadata_stub(from_type, tmp_soql, current_env)) |stub| {
                    try records.append(self.arena, stub);
                }
            }
        }
        return true;
    }

    fn extract_apex_class_query_name(
        _: *Evaluator,
        where_clause: []const u8,
        current_env: *Env,
        wpos: *usize,
        start_pos: usize,
    ) ?[]const u8 {
        const j = start_pos;
        if (j < where_clause.len and where_clause[j] == '\'') {
            const start = j + 1;
            if (std.mem.indexOfPos(u8, where_clause, start, "'")) |end| {
                wpos.* = end + 1;
                return where_clause[start..end];
            }
            wpos.* = j + 1;
            return null;
        }
        if (j < where_clause.len and where_clause[j] == ':') {
            const start = j + 1;
            var end = start;
            while (end < where_clause.len and
                (std.ascii.isAlphanumeric(where_clause[end]) or where_clause[end] == '_'))
            {
                end += 1;
            }
            wpos.* = end;
            if (end > start) {
                if (current_env.get(where_clause[start..end])) |bv| {
                    if (bv == .string) return bv.string;
                }
            }
            return null;
        }
        wpos.* = j + 1;
        return null;
    }

    fn seed_builtin_identity_query_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (records.items.len != 0) return;
        const user_profile_query = std.ascii.eqlIgnoreCase(from_type, "User") and
            (self.has_exact_where_field_comparison(soql, "Profile.Name") or
                self.has_exact_where_field_comparison(soql, "Profile.UserType") or
                self.has_exact_where_field_comparison(soql, "UserType"));
        if (!user_profile_query and self.store.get(from_type) != null) return;
        if (std.ascii.eqlIgnoreCase(from_type, "User")) {
            const use_query_specific_user =
                self.has_exact_where_field_comparison(soql, "Profile.Name") or
                self.has_exact_where_field_comparison(soql, "Profile.UserType") or
                self.has_exact_where_field_comparison(soql, "UserType");
            const user_record = if (self.query_matches_current_user(soql, current_env))
                try self.create_current_user_record()
            else if (self.query_matches_default_synthetic_user(soql, current_env))
                try self.create_default_user_record()
            else if (use_query_specific_user)
                try self.create_user_for_query(soql, current_env)
            else
                try self.create_current_user_record();
            if (use_query_specific_user and
                std.ascii.indexOfIgnoreCase(soql, "IsActive = FALSE") == null)
            {
                try records.append(self.arena, user_record);
                const gop = try self.store.getOrPut(self.arena, "User");
                if (!gop.found_existing) gop.value_ptr.* = .empty;
                try gop.value_ptr.append(self.arena, user_record);
                return;
            }
            try self.append_seeded_store_record("User", user_record, soql, current_env, records);
            return;
        }
        if (std.ascii.eqlIgnoreCase(from_type, "Profile")) {
            const profile_record = if (!self.has_where_field_like_comparison(soql, "Name"))
                try self.create_profile_for_query(soql, current_env)
            else
                try self.create_default_profile_record();
            try self.append_seeded_store_record(
                "Profile",
                profile_record,
                soql,
                current_env,
                records,
            );
            return;
        }
        if (std.ascii.eqlIgnoreCase(from_type, "RecordType")) {
            try self.seed_record_type_store();
            try self.append_matching_store_records("RecordType", soql, current_env, records);
            return;
        }
        if (std.ascii.eqlIgnoreCase(from_type, "OpportunityStage")) {
            try self.seed_opportunity_stage_store();
            try self.append_matching_store_records("OpportunityStage", soql, current_env, records);
            return;
        }
        if (std.ascii.eqlIgnoreCase(from_type, "TaskStatus")) {
            try self.seed_task_status_store();
            try self.append_matching_store_records("TaskStatus", soql, current_env, records);
            return;
        }
        if (std.ascii.eqlIgnoreCase(from_type, "LeadStatus")) {
            try self.seed_lead_status_store();
            try self.append_matching_store_records("LeadStatus", soql, current_env, records);
        }
    }

    fn append_matching_store_records(
        self: *Evaluator,
        store_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        const store_records = self.store.get(store_type) orelse return;
        for (store_records.items) |record| {
            if (self.matches_where(record, soql, current_env) and record == .sobject) {
                const copy = try self.clone_s_object(record.sobject);
                try records.append(self.arena, Value{ .sobject = copy });
            }
        }
    }

    fn seed_opportunity_stage_store(self: *Evaluator) !void {
        const gop = try self.store.getOrPut(self.arena, "OpportunityStage");
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        if (gop.value_ptr.items.len > 0) return;

        const stages = [_]struct {
            name: []const u8,
            sort_order: i64,
            probability: i64,
            is_closed: bool,
            is_won: bool,
            forecast: []const u8,
        }{
            .{
                .name = "Prospecting",
                .sort_order = 1,
                .probability = 10,
                .is_closed = false,
                .is_won = false,
                .forecast = "Pipeline",
            },
            .{
                .name = "Pledged",
                .sort_order = 2,
                .probability = 50,
                .is_closed = false,
                .is_won = false,
                .forecast = "Pipeline",
            },
            .{
                .name = "Closed Won",
                .sort_order = 3,
                .probability = 100,
                .is_closed = true,
                .is_won = true,
                .forecast = "Closed",
            },
            .{
                .name = "Closed Lost",
                .sort_order = 4,
                .probability = 0,
                .is_closed = true,
                .is_won = false,
                .forecast = "Omitted",
            },
        };

        for (stages) |stage| try self.append_opportunity_stage(gop.value_ptr, stage);
    }

    fn append_opportunity_stage(
        self: *Evaluator,
        records: *std.ArrayListUnmanaged(Value),
        stage: anytype,
    ) !void {
        const row = try self.arena.create(types.SObject);
        row.* = .{ .type_name = "OpportunityStage" };
        const id = try self.alloc_id_for_type("OpportunityStage");
        row.id = id;
        try row.fields.put(self.arena, "Id", Value{ .string = id });
        try row.fields.put(self.arena, "MasterLabel", Value{ .string = stage.name });
        try row.fields.put(self.arena, "ApiName", Value{ .string = stage.name });
        try row.fields.put(self.arena, "SortOrder", Value{ .integer = stage.sort_order });
        try row.fields.put(
            self.arena,
            "DefaultProbability",
            Value{ .integer = stage.probability },
        );
        try row.fields.put(self.arena, "IsActive", Value{ .boolean = true });
        try row.fields.put(self.arena, "IsClosed", Value{ .boolean = stage.is_closed });
        try row.fields.put(self.arena, "IsWon", Value{ .boolean = stage.is_won });
        try row.fields.put(self.arena, "ForecastCategory", Value{ .string = stage.forecast });
        try row.fields.put(
            self.arena,
            "ForecastCategoryName",
            Value{ .string = stage.forecast },
        );
        try records.append(self.arena, Value{ .sobject = row });
    }

    fn seed_task_status_store(self: *Evaluator) !void {
        const gop = try self.store.getOrPut(self.arena, "TaskStatus");
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        if (gop.value_ptr.items.len > 0) return;

        const statuses = [_]struct {
            label: []const u8,
            sort_order: i64,
            is_default: bool,
            is_closed: bool,
        }{
            .{ .label = "Not Started", .sort_order = 1, .is_default = true, .is_closed = false },
            .{ .label = "In Progress", .sort_order = 2, .is_default = false, .is_closed = false },
            .{ .label = "Completed", .sort_order = 3, .is_default = false, .is_closed = true },
        };

        for (statuses) |status| try self.append_task_status(gop.value_ptr, status);
    }

    fn append_task_status(
        self: *Evaluator,
        records: *std.ArrayListUnmanaged(Value),
        status: anytype,
    ) !void {
        const row = try self.arena.create(types.SObject);
        row.* = .{ .type_name = "TaskStatus" };
        const id = try self.alloc_id_for_type("TaskStatus");
        row.id = id;
        try row.fields.put(self.arena, "Id", Value{ .string = id });
        try row.fields.put(self.arena, "MasterLabel", Value{ .string = status.label });
        try row.fields.put(self.arena, "ApiName", Value{ .string = status.label });
        try row.fields.put(self.arena, "SortOrder", Value{ .integer = status.sort_order });
        try row.fields.put(self.arena, "IsDefault", Value{ .boolean = status.is_default });
        try row.fields.put(self.arena, "IsClosed", Value{ .boolean = status.is_closed });
        try row.fields.put(self.arena, "IsActive", Value{ .boolean = true });
        try records.append(self.arena, Value{ .sobject = row });
    }

    fn seed_lead_status_store(self: *Evaluator) !void {
        const gop = try self.store.getOrPut(self.arena, "LeadStatus");
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        if (gop.value_ptr.items.len > 0) return;

        try self.append_lead_status(gop.value_ptr, "Open - Not Contacted", false, true);
        try self.append_lead_status(gop.value_ptr, "Closed - Converted", true, false);
    }

    fn append_lead_status(
        self: *Evaluator,
        records: *std.ArrayListUnmanaged(Value),
        api_name: []const u8,
        is_converted: bool,
        is_default: bool,
    ) !void {
        const row = try self.arena.create(types.SObject);
        row.* = .{ .type_name = "LeadStatus" };
        const id = try self.alloc_id_for_type("LeadStatus");
        row.id = id;
        try row.fields.put(self.arena, "Id", Value{ .string = id });
        try row.fields.put(self.arena, "ApiName", Value{ .string = api_name });
        try row.fields.put(self.arena, "MasterLabel", Value{ .string = api_name });
        try row.fields.put(self.arena, "IsConverted", Value{ .boolean = is_converted });
        try row.fields.put(self.arena, "IsDefault", Value{ .boolean = is_default });
        try row.fields.put(self.arena, "SortOrder", Value{ .integer = if (is_converted) 2 else 1 });
        try records.append(self.arena, Value{ .sobject = row });
    }

    fn append_seeded_store_record(
        self: *Evaluator,
        store_type: []const u8,
        record: Value,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (record == .null_val or !self.matches_where(record, soql, current_env)) return;
        try records.append(self.arena, record);
        if (record == .sobject) {
            const gop = try self.store.getOrPut(self.arena, store_type);
            if (!gop.found_existing) gop.value_ptr.* = .empty;
            try gop.value_ptr.append(self.arena, record);
        }
    }

    fn seed_builtin_user_profile_query_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (records.items.len == 0 and
            std.ascii.eqlIgnoreCase(from_type, "User") and
            self.should_synthesize_builtin_user(soql, current_env))
        {
            const user_record = if (self.query_matches_current_user(soql, current_env))
                try self.create_current_user_record()
            else if (self.has_exact_where_field_comparison(soql, "Alias") or
                self.has_exact_where_field_comparison(soql, "Username"))
                try self.create_user_for_query(soql, current_env)
            else if (self.first_profile_id_in_user_query(soql, current_env)) |profile_id|
                try self.create_builtin_user_record(
                    self.current_user_id,
                    profile_id,
                    "testuser@example.com",
                    "tuser",
                    "Test",
                    "User",
                    "Test User",
                )
            else
                try self.create_current_user_record();
            try self.append_seeded_store_record("User", user_record, soql, current_env, records);
        }
        try self.seed_current_user_for_system_admin_query(from_type, soql, current_env, records);
        if (records.items.len == 0 and std.ascii.eqlIgnoreCase(from_type, "Profile")) {
            const profile_record = if (!self.has_where_field_like_comparison(soql, "Name"))
                try self.create_profile_for_query(soql, current_env)
            else
                try self.create_default_profile_record();
            try self.append_seeded_store_record(
                "Profile",
                profile_record,
                soql,
                current_env,
                records,
            );
        }
        try self.seed_current_profile_query_record(from_type, soql, current_env, records);
    }

    fn seed_current_user_for_system_admin_query(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (!std.ascii.eqlIgnoreCase(from_type, "User")) return;
        if (!self.query_requests_system_admin_user(soql, current_env)) return;
        if (records_contain_sobject_id(records.items, self.current_user_id)) return;

        const user_record =
            if (self.first_profile_id_in_user_query(soql, current_env)) |profile_id|
                try self.create_builtin_user_record(
                    self.current_user_id,
                    profile_id,
                    "testuser@example.com",
                    "tuser",
                    "Test",
                    "User",
                    "Test User",
                )
            else
                try self.create_current_user_record();
        try self.append_seeded_store_record("User", user_record, soql, current_env, records);
    }

    fn query_requests_system_admin_user(
        self: *Evaluator,
        soql: []const u8,
        current_env: *Env,
    ) bool {
        if (self.has_exact_where_field_comparison(soql, "Profile.Name")) {
            const profile_name = self.extract_where_field_value(
                soql,
                "Profile.Name",
                current_env,
            ) orelse return false;
            return std.ascii.eqlIgnoreCase(profile_name, "System Administrator");
        }
        return self.first_profile_id_in_user_query(soql, current_env) != null;
    }

    fn records_contain_sobject_id(records: []const Value, id: []const u8) bool {
        for (records) |record| {
            if (record != .sobject or record.sobject.id == null) continue;
            if (std.ascii.eqlIgnoreCase(record.sobject.id.?, id)) return true;
        }
        return false;
    }

    fn seed_current_profile_query_record(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (!std.ascii.eqlIgnoreCase(from_type, "Profile")) return;
        if (records_contain_sobject_id(records.items, self.current_profile_id)) return;
        try self.append_seeded_store_record(
            "Profile",
            try self.create_current_profile_record(),
            soql,
            current_env,
            records,
        );
    }

    fn seed_business_hours_query_record(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (records.items.len != 0 or !std.ascii.eqlIgnoreCase(from_type, "BusinessHours")) return;
        const business_hours = try self.arena.create(types.SObject);
        business_hours.* = .{ .type_name = "BusinessHours", .id = "01m000000000001AAA" };
        try business_hours.fields.put(self.arena, "Id", Value{ .string = "01m000000000001AAA" });
        try business_hours.fields.put(self.arena, "Name", Value{ .string = "Default" });
        if (self.matches_where(Value{ .sobject = business_hours }, soql, current_env)) {
            try records.append(self.arena, Value{ .sobject = business_hours });
        }
    }

    const unsupported_soql_type_message =
        "sObject type '{s}' is not supported. " ++
        "If you are attempting to use a custom object, be sure to " ++
        "append the '__c' after the entity name.";

    fn ensure_known_soql_type(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        has_records: bool,
    ) !void {
        if (has_records or self.store.get(from_type) != null) return;
        if (try self.is_known_soql_type(from_type, soql, current_env)) return;
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.QueryException" };
        try exc.fields.put(
            self.arena,
            "message",
            Value{
                .string = try std.fmt.allocPrint(
                    self.arena,
                    unsupported_soql_type_message,
                    .{from_type},
                ),
            },
        );
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

