    fn is_known_soql_type(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
    ) !bool {
        for (known_soql_types) |kt| {
            if (std.ascii.eqlIgnoreCase(from_type, kt)) return true;
        }
        if (std.mem.endsWith(u8, from_type, "__c") or
            std.mem.endsWith(u8, from_type, "__e") or
            std.mem.endsWith(u8, from_type, "__mdt") or
            std.mem.endsWith(u8, from_type, "__b") or
            std.mem.endsWith(u8, from_type, "__Share") or
            std.mem.endsWith(u8, from_type, "__History") or
            std.mem.endsWith(u8, from_type, "__ChangeEvent"))
        {
            return true;
        }
        return (try self.generate_metadata_stub(from_type, soql, current_env)) != null;
    }

    fn finalize_soql_records(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        try self.apply_soql_sub_queries(from_type, soql, current_env, records);
        try self.apply_parent_field_lookups(soql, from_type, records);
        try self.resolve_formula_fields(soql, records);
        try self.reorder_soql_records_by_bind(soql, current_env, records);
        self.sort_soql_records(soql, records);
        self.apply_soql_offset(soql, current_env, records);
        self.apply_soql_limit(soql, current_env, records);
    }

    fn apply_soql_sub_queries(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        var search_offset: usize = 0;
        while (extract_sub_query_from(soql, search_offset)) |sub_info| {
            try self.apply_soql_sub_query(from_type, sub_info, current_env, records);
            search_offset = sub_info.next_index;
        }
    }

    fn apply_soql_sub_query(
        self: *Evaluator,
        from_type: []const u8,
        sub_info: SubQueryInfo,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        const rel_name = sub_info.relationship;
        const child_type = self.resolve_child_type(from_type, rel_name);
        for (records.items) |*rec| {
            if (rec.* != .sobject) continue;
            const parent_id = rec.sobject.id orelse continue;
            const parent_developer_name = if (std.mem.endsWith(u8, from_type, "__mdt"))
                self.get_s_object_field_value_case_insensitive(
                    rec.sobject,
                    "DeveloperName",
                )
            else
                null;
            var child_records: std.ArrayListUnmanaged(Value) = .empty;
            if (child_type) |ct| {
                if (std.mem.endsWith(u8, ct, "__mdt")) self.ensure_custom_metadata_loaded(ct);
                var child_iter = self.store.iterator();
                while (child_iter.next()) |child_entry| {
                    if (std.ascii.eqlIgnoreCase(child_entry.key_ptr.*, ct)) {
                        const fk_field = self.resolve_foreign_key(ct, from_type, rel_name);
                        for (child_entry.value_ptr.items) |child_rec| {
                            if (child_rec == .sobject) {
                                if (utils.sobject_get(
                                    &child_rec.sobject.fields,
                                    fk_field,
                                )) |fk_val| {
                                    if (fk_val == .string) {
                                        const matches_id =
                                            std.ascii.eqlIgnoreCase(fk_val.string, parent_id);
                                        const matches_developer_name =
                                            parent_developer_name != null and
                                            parent_developer_name.? == .string and
                                            std.ascii.eqlIgnoreCase(
                                                fk_val.string,
                                                parent_developer_name.?.string,
                                            );
                                        if (matches_id or matches_developer_name) {
                                            if (sub_query_requires_where_filter(sub_info.query) and
                                                !self.matches_where(child_rec, sub_info.query, current_env))
                                            {
                                                continue;
                                            }
                                            try child_records.append(self.arena, child_rec);
                                        }
                                    }
                                }
                            }
                        }
                        break;
                    }
                }
                try self.apply_parent_field_lookups(sub_info.query, ct, &child_records);
                try self.resolve_formula_fields(sub_info.query, &child_records);
            }
            const child_list = try self.arena.create(types.ListValue);
            child_list.* = .{ .items = child_records };
            try rec.sobject.fields.put(self.arena, rel_name, Value{ .list = child_list });
        }
    }

    fn sub_query_requires_where_filter(query: []const u8) bool {
        const where_clause = extract_where_clause(query) orelse return false;
        return std.mem.trim(u8, where_clause, " \t\r\n").len > 0;
    }

    fn reorder_soql_records_by_bind(
        self: *Evaluator,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        if (extract_order_by_field(soql) != null) return;
        if (extract_where_clause(soql)) |where_clause| {
            if (find_logical_op(where_clause, "OR") != null) return;
        }
        if (self.extract_where_in_bind_info(soql)) |bind_info| {
            if (self.lookup_bind_value(current_env, bind_info.bind_name)) |bind_val| {
                try self.reorder_records_by_in_bind(records, bind_info.field_name, bind_val);
            }
        }
    }

    fn sort_soql_records(
        self: *Evaluator,
        soql: []const u8,
        records: *std.ArrayListUnmanaged(Value),
    ) void {
        const order_infos = extract_order_by_fields(soql);
        if (order_infos.len == 0) return;
        const items = records.items;
        var ii: usize = 1;
        while (ii < items.len) : (ii += 1) {
            var jj = ii;
            while (jj > 0) {
                const cmp_result = self.compare_by_order_fields(
                    items[jj - 1],
                    items[jj],
                    order_infos.items[0..order_infos.len],
                );
                const should_swap = cmp_result > 0;
                if (!should_swap) break;
                const tmp = items[jj - 1];
                items[jj - 1] = items[jj];
                items[jj] = tmp;
                jj -= 1;
            }
        }
    }

    fn apply_soql_offset(
        _: *Evaluator,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) void {
        var offset_val_opt = extract_offset(soql);
        if (offset_val_opt == null) {
            if (extract_offset_bind_var(soql)) |bind_name| {
                if (current_env.get(bind_name)) |bv| {
                    if (bv == .integer and bv.integer >= 0) {
                        offset_val_opt = @intCast(bv.integer);
                    }
                }
            }
        }
        if (offset_val_opt) |offset_val| {
            if (offset_val < records.items.len) {
                const remaining = records.items.len - offset_val;
                std.mem.copyForwards(
                    Value,
                    records.items[0..remaining],
                    records.items[offset_val..records.items.len],
                );
                records.items.len = remaining;
            } else {
                records.items.len = 0;
            }
        }
    }

    fn apply_soql_limit(
        self: *Evaluator,
        soql: []const u8,
        current_env: *Env,
        records: *std.ArrayListUnmanaged(Value),
    ) void {
        var limit_val_opt = extract_limit(soql);
        if (limit_val_opt == null) {
            if (extract_limit_bind_var(soql)) |bind_name| {
                if (self.lookup_bind_value(current_env, bind_name)) |bv| {
                    if (bv == .integer and bv.integer > 0) {
                        limit_val_opt = @intCast(bv.integer);
                    }
                }
            }
        }
        if (limit_val_opt) |limit_val| {
            if (records.items.len > limit_val) records.items.len = limit_val;
        }
    }

    fn strip_soql_line_comments(self: *Evaluator, raw: []const u8) ![]const u8 {
        if (std.mem.indexOf(u8, raw, "//") == null) return raw;

        var out: std.ArrayListUnmanaged(u8) = .empty;
        var i: usize = 0;
        var in_string = false;
        while (i < raw.len) {
            const ch = raw[i];
            if (ch == '\'') {
                in_string = !in_string;
                try out.append(self.arena, ch);
                i += 1;
                continue;
            }
            if (!in_string and ch == '/' and i + 1 < raw.len and raw[i + 1] == '/') {
                i += 2;
                while (i < raw.len and raw[i] != '\n' and raw[i] != '\r') : (i += 1) {}
                continue;
            }
            try out.append(self.arena, ch);
            i += 1;
        }
        return out.items;
    }

    /// Generate a stub record for metadata/system types not in the in-memory store.
    /// Returns a dummy SObject with plausible field values, or null if not a metadata type.
    fn generate_metadata_stub(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
    ) !?Value {
        const name_val = self.extract_where_name_value(soql, current_env) orelse "MockRecord";
        if (std.ascii.eqlIgnoreCase(from_type, "ApexClass") or
            std.ascii.eqlIgnoreCase(from_type, "ApexTrigger"))
        {
            return try self.generate_apex_metadata_stub(from_type, name_val);
        }
        if (std.ascii.eqlIgnoreCase(from_type, "FlowDefinitionView")) {
            return try self.generate_flow_definition_view_stub(
                from_type,
                soql,
                current_env,
                name_val,
            );
        }
        if (std.ascii.eqlIgnoreCase(from_type, "FlowVersionView")) {
            return try self.generate_flow_version_view_stub(from_type, soql, current_env);
        }
        if (std.ascii.eqlIgnoreCase(from_type, "PermissionSet")) {
            return try self.generate_permission_set_stub(name_val);
        }
        if (std.ascii.eqlIgnoreCase(from_type, "CustomPermission")) {
            return try self.generate_custom_permission_stub(
                from_type,
                soql,
                current_env,
                name_val,
            );
        }
        return self.generate_metadata_stub_tail(
            from_type,
            soql,
            current_env,
            name_val,
        );
    }

    fn generate_metadata_stub_tail(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        name_val: []const u8,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(from_type, "PermissionSetGroup")) {
            return try self.generate_permission_set_group_stub(name_val);
        }
        if (std.ascii.eqlIgnoreCase(from_type, "Profile")) {
            return try self.generate_profile_stub(soql, current_env);
        }
        if (std.ascii.eqlIgnoreCase(from_type, "ContentVersion")) {
            return try self.generate_content_version_stub(soql);
        }
        if (std.ascii.eqlIgnoreCase(from_type, "CronTrigger")) {
            return try self.generate_cron_trigger_stub(soql, current_env);
        }
        if (std.ascii.eqlIgnoreCase(from_type, "Organization")) {
            return try self.generate_organization_stub();
        }
        if (std.ascii.eqlIgnoreCase(from_type, "AppMenuItem")) {
            return try self.generate_app_menu_item_stub();
        }
        if (std.ascii.eqlIgnoreCase(from_type, "PlatformCachePartition")) {
            return try self.generate_platform_cache_partition_stub();
        }
        if (std.ascii.eqlIgnoreCase(from_type, "DuplicateRule")) {
            return try self.generate_duplicate_rule_stub(name_val);
        }
        if (std.ascii.eqlIgnoreCase(from_type, "StaticResource")) {
            return try self.generate_static_resource_stub(name_val);
        }
        if (std.ascii.eqlIgnoreCase(from_type, "Metadata_Driven_Trigger__mdt")) {
            return null;
        }
        if (std.ascii.eqlIgnoreCase(from_type, "Bucketed_Picklist__mdt")) {
            return try self.generate_bucketed_picklist_stub();
        }
        if (std.ascii.eqlIgnoreCase(from_type, "Picklist_Bucket__mdt")) {
            return try self.generate_picklist_bucket_stub();
        }
        return null;
    }

    fn generate_apex_metadata_stub(
        self: *Evaluator,
        from_type: []const u8,
        name_val: []const u8,
    ) !?Value {
        const metadata_sources = if (std.ascii.eqlIgnoreCase(from_type, "ApexClass"))
            &self.class_sources
        else
            &self.trigger_sources;
        const type_label = if (std.ascii.eqlIgnoreCase(from_type, "ApexClass"))
            "class"
        else
            "trigger";
        if (!self.apex_metadata_exists(from_type, name_val, metadata_sources)) return null;
        if (self.find_metadata_stub_by_name(from_type, name_val)) |record| return record;

        const sob = try self.arena.create(types.SObject);
        sob.* = .{ .type_name = from_type };
        const prefix = if (std.ascii.eqlIgnoreCase(from_type, "ApexClass")) "01p" else "01q";
        const id = try std.fmt.allocPrint(self.arena, "{s}{d:0>15}", .{ prefix, self.next_id });
        self.next_id += 1;
        sob.id = id;
        try sob.fields.put(self.arena, "Id", Value{ .string = id });
        try sob.fields.put(self.arena, "Name", Value{ .string = name_val });
        try sob.fields.put(self.arena, "ApiVersion", Value{ .double = 62.0 });
        try sob.fields.put(self.arena, "LengthWithoutComments", Value{ .integer = 100 });
        try sob.fields.put(self.arena, "NamespacePrefix", Value{ .string = "" });
        try sob.fields.put(self.arena, "CreatedDate", Value{ .string = "2026-01-01T00:00:00Z" });
        try sob.fields.put(
            self.arena,
            "LastModifiedDate",
            Value{ .string = "2026-01-01T00:00:00Z" },
        );
        try sob.fields.put(self.arena, "CreatedById", Value{ .string = "005000000000001" });
        try sob.fields.put(self.arena, "LastModifiedById", Value{ .string = "005000000000001" });
        const metadata_user = try self.create_current_user_record();
        try sob.fields.put(self.arena, "CreatedBy", metadata_user);
        try sob.fields.put(self.arena, "LastModifiedBy", metadata_user);
        const body = try self.apex_metadata_body(metadata_sources, type_label, name_val);
        try sob.fields.put(self.arena, "Body", Value{ .string = body });
        const gop = try self.store.getOrPut(self.arena, from_type);
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        try gop.value_ptr.append(self.arena, Value{ .sobject = sob });
        try self.id_type_map.put(self.arena, id, from_type);
        return Value{ .sobject = sob };
    }

    fn apex_metadata_exists(
        self: *Evaluator,
        from_type: []const u8,
        name_val: []const u8,
        metadata_sources: anytype,
    ) bool {
        var metadata_exists = false;
        if (std.ascii.eqlIgnoreCase(from_type, "ApexClass")) {
            metadata_exists = self.find_class(name_val) != null;
        }
        if (!metadata_exists) {
            for (metadata_sources.keys()) |k| {
                if (std.ascii.eqlIgnoreCase(k, name_val)) {
                    metadata_exists = true;
                    break;
                }
            }
        }
        return metadata_exists;
    }

    fn find_metadata_stub_by_name(
        self: *Evaluator,
        from_type: []const u8,
        name_val: []const u8,
    ) ?Value {
        if (self.store.get(from_type)) |records| {
            for (records.items) |record| {
                if (record != .sobject) continue;
                if (utils.sobject_get(&record.sobject.fields, "Name")) |stored_name| {
                    if (stored_name == .string and
                        std.ascii.eqlIgnoreCase(stored_name.string, name_val))
                    {
                        return record;
                    }
                }
            }
        }
        return null;
    }

    fn apex_metadata_body(
        self: *Evaluator,
        metadata_sources: anytype,
        type_label: []const u8,
        name_val: []const u8,
    ) ![]const u8 {
        if (metadata_sources.get(name_val)) |src| return src;
        for (metadata_sources.keys(), metadata_sources.values()) |k, v| {
            if (std.ascii.eqlIgnoreCase(k, name_val)) return v;
        }
        return std.fmt.allocPrint(
            self.arena,
            "public {s} {s} {{\n    // mock body\n}}",
            .{ type_label, name_val },
        );
    }

    fn generate_flow_definition_view_stub(
        self: *Evaluator,
        from_type: []const u8,
        soql: []const u8,
        current_env: *Env,
        name_val: []const u8,
    ) !?Value {
        const api_name =
            self.extract_where_field_value(soql, "ApiName", current_env) orelse name_val;
        if (std.mem.indexOfScalar(u8, api_name, ' ') != null) return null;
        if (self.find_flow_definition_view_record(from_type, api_name)) |record| return record;
        if (!self.should_synthesize_flow_definition_view(soql, current_env)) return null;

        const durable_id = try std.fmt.allocPrint(self.arena, "300{d:0>15}", .{self.next_id});
        self.next_id += 1;
        const active_version_id =
            try std.fmt.allocPrint(self.arena, "301{d:0>15}", .{self.next_id});
        self.next_id += 1;

        const trigger_object = try self.arena.create(types.SObject);
        trigger_object.* = .{ .type_name = "EntityDefinition" };
        try trigger_object.fields.put(
            self.arena,
            "QualifiedApiName",
            Value{ .string = "Log__c" },
        );

        const sob = try self.arena.create(types.SObject);
        sob.* = .{ .type_name = from_type, .id = durable_id };
        try sob.fields.put(self.arena, "Id", Value{ .string = durable_id });
        try sob.fields.put(self.arena, "ActiveVersionId", Value{ .string = active_version_id });
        try sob.fields.put(self.arena, "ApiName", Value{ .string = api_name });
        try sob.fields.put(
            self.arena,
            "Description",
            Value{ .string = try std.fmt.allocPrint(self.arena, "{s} flow", .{api_name}) },
        );
        try sob.fields.put(self.arena, "DurableId", Value{ .string = durable_id });
        try sob.fields.put(self.arena, "Label", Value{ .string = api_name });
        try sob.fields.put(self.arena, "LastModifiedBy", Value{ .string = "Test User" });
        try sob.fields.put(
            self.arena,
            "LastModifiedDate",
            Value{ .string = "2026-01-01T00:00:00Z" },
        );
        try sob.fields.put(self.arena, "ManageableState", Value{ .string = "unmanaged" });
        try sob.fields.put(self.arena, "ProcessType", Value{ .string = "Flow" });
        try sob.fields.put(self.arena, "RecordTriggerType", Value{ .string = "RecordAfterSave" });
        try sob.fields.put(self.arena, "TriggerObjectOrEvent", Value{ .sobject = trigger_object });
        try sob.fields.put(self.arena, "TriggerOrder", Value{ .integer = 1 });
        try sob.fields.put(self.arena, "TriggerType", Value{ .string = "RecordAfterSave" });
        try sob.fields.put(self.arena, "VersionNumber", Value{ .integer = 1 });
        try sob.fields.put(self.arena, "IsActive", Value{ .boolean = true });

        const gop = try self.store.getOrPut(self.arena, from_type);
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        try gop.value_ptr.append(self.arena, Value{ .sobject = sob });
        try self.id_type_map.put(self.arena, durable_id, from_type);
        return Value{ .sobject = sob };
    }

    fn should_synthesize_flow_definition_view(
        self: *Evaluator,
        soql: []const u8,
        current_env: *Env,
    ) bool {
        const has_active_true_literal =
            std.ascii.indexOfIgnoreCase(soql, "IsActive = TRUE") != null or
            std.ascii.indexOfIgnoreCase(soql, "IsActive=TRUE") != null;
        const is_active_filter = self.extract_where_field_value(soql, "IsActive", current_env);
        return has_active_true_literal or if (is_active_filter) |filter_value|
            std.ascii.eqlIgnoreCase(filter_value, "TRUE")
        else
            false;
    }

    fn find_flow_definition_view_record(
        self: *Evaluator,
        from_type: []const u8,
        api_name: []const u8,
    ) ?Value {
        if (self.store.get(from_type)) |records| {
            for (records.items) |record| {
                if (record != .sobject) continue;
                if (utils.sobject_get(&record.sobject.fields, "ApiName")) |stored_api_name| {
                    if (stored_api_name == .string and
                        std.ascii.eqlIgnoreCase(stored_api_name.string, api_name))
                    {
                        return record;
                    }
                }
            }
        }
        return null;
    }

