    fn npsp_truncated_rollup_text(self: *Evaluator, value: []const u8) ![]const u8 {
        if (value.len <= 20) return value;
        return std.fmt.allocPrint(self.arena, "{s}...", .{value[0..17]});
    }

    fn apply_npsp_user_rollup_fields_to_target(
        self: *Evaluator,
        target: *types.SObject,
        object_name: []const u8,
        target_id: []const u8,
    ) !void {
        const settings = self.store_records_ptr("npo02__User_Rollup_Field_Settings__c") orelse return;
        for (settings.items) |setting_record| {
            if (setting_record != .sobject) continue;
            const configured_object =
                self.get_s_object_field_value_case_insensitive(
                    setting_record.sobject,
                    "npo02__Object_Name__c",
                ) orelse continue;
            if (configured_object != .string or
                !std.ascii.eqlIgnoreCase(configured_object.string, object_name))
            {
                continue;
            }
            const target_field =
                self.get_s_object_field_value_case_insensitive(
                    setting_record.sobject,
                    "npo02__Target_Field__c",
                ) orelse continue;
            const source_field =
                self.get_s_object_field_value_case_insensitive(
                    setting_record.sobject,
                    "npo02__Source_Field__c",
                ) orelse continue;
            const action =
                self.get_s_object_field_value_case_insensitive(
                    setting_record.sobject,
                    "npo02__Field_Action__c",
                ) orelse Value{ .string = "SUM" };
            if (target_field != .string or source_field != .string) continue;
            const aggregate = try self.compute_npsp_user_rollup_value(
                object_name,
                target_id,
                source_field.string,
                if (action == .string) action.string else "SUM",
            );
            if (aggregate) |value| {
                try utils.sobject_put(&target.fields, self.arena, target_field.string, value);
            }
        }
    }

    fn compute_npsp_user_rollup_value(
        self: *Evaluator,
        object_name: []const u8,
        target_id: []const u8,
        source_field: []const u8,
        action: []const u8,
    ) !?Value {
        const opp_records = self.store_records_ptr("Opportunity") orelse return null;
        var aggregate: ?Value = null;
        var sum: f64 = 0;
        var count: i64 = 0;
        for (opp_records.items) |record| {
            if (record != .sobject) continue;
            if (!self.npsp_user_rollup_opportunity_matches_target(record.sobject, object_name, target_id)) {
                continue;
            }
            if (!npsp_opportunity_is_closed(record.sobject) or
                !npsp_opportunity_is_won(record.sobject))
            {
                continue;
            }
            const value = self.npsp_user_rollup_source_value(record.sobject, source_field) orelse continue;
            if (std.ascii.eqlIgnoreCase(action, "SUM")) {
                sum += numeric_value_as_f64(value) orelse 0;
                count += 1;
            } else if (std.ascii.eqlIgnoreCase(action, "COUNT")) {
                count += 1;
            } else if (std.ascii.eqlIgnoreCase(action, "MAX")) {
                if (aggregate == null or self.compare_values(value, aggregate.?) > 0) {
                    aggregate = value;
                }
                count += 1;
            } else if (std.ascii.eqlIgnoreCase(action, "MIN")) {
                if (aggregate == null or self.compare_values(value, aggregate.?) < 0) {
                    aggregate = value;
                }
                count += 1;
            }
        }
        if (std.ascii.eqlIgnoreCase(action, "SUM")) {
            if (count == 0) return null;
            return rollup_decimal_value(sum);
        }
        if (std.ascii.eqlIgnoreCase(action, "COUNT")) {
            return Value{ .integer = count };
        }
        return aggregate;
    }

    fn npsp_user_rollup_opportunity_matches_target(
        self: *Evaluator,
        opp: *types.SObject,
        object_name: []const u8,
        target_id: []const u8,
    ) bool {
        if (std.ascii.eqlIgnoreCase(object_name, "Contact")) {
            const contact_id = self.npsp_opportunity_primary_contact_id(opp) orelse return false;
            return std.ascii.eqlIgnoreCase(contact_id, target_id);
        }
        if (std.ascii.eqlIgnoreCase(object_name, "Account")) {
            return self.npsp_opportunity_belongs_to_account(opp, target_id);
        }
        if (std.ascii.eqlIgnoreCase(object_name, "npo02__Household__c")) {
            const contact_id = self.npsp_opportunity_primary_contact_id(opp) orelse return false;
            const contact_value = self.find_record_by_id("Contact", contact_id) orelse return false;
            return contact_value == .sobject and
                self.npsp_contact_belongs_to_household(contact_value.sobject, target_id);
        }
        return false;
    }

    fn npsp_user_rollup_source_value(
        self: *Evaluator,
        opp: *types.SObject,
        source_field: []const u8,
    ) ?Value {
        if (std.ascii.eqlIgnoreCase(source_field, "FiscalYear")) {
            const close_date =
                self.get_s_object_field_value_case_insensitive(opp, "CloseDate") orelse return null;
            if (npsp_year_from_value(close_date)) |year| {
                return Value{ .integer = year };
            }
            return null;
        }
        return self.get_s_object_field_value_case_insensitive(opp, source_field);
    }

    fn rollup_decimal_value(amount: f64) Value {
        const rounded = @round(amount);
        if (@abs(amount - rounded) < 0.000001) {
            return Value{ .integer = @intFromFloat(rounded) };
        }
        return Value{ .double = amount };
    }

    fn current_npsp_rollup_year(self: *Evaluator) i32 {
        const today = builtins.current_date_string(self.arena) catch return 2026;
        return npsp_year_from_date_string(today) orelse 2026;
    }

    fn npsp_year_from_value(value: Value) ?i32 {
        const date_str = builtins.extract_date_string(value) orelse return null;
        return npsp_year_from_date_string(date_str);
    }

    fn npsp_year_from_date_string(date_str: []const u8) ?i32 {
        if (date_str.len < 4) return null;
        return std.fmt.parseInt(i32, date_str[0..4], 10) catch null;
    }

    fn apply_npsp_payment_auto_close_side_effects(
        self: *Evaluator,
        child_type: []const u8,
        new_records: []const Value,
        old_records: ?std.ArrayListUnmanaged(Value),
    ) !void {
        if (!std.ascii.eqlIgnoreCase(child_type, "npe01__OppPayment__c")) return;

        const impacted_ids = try self.npsp_payment_impacted_opportunity_ids(
            new_records,
            old_records,
        );
        if (impacted_ids.count() == 0) return;

        var rollup_iter = impacted_ids.iterator();
        while (rollup_iter.next()) |entry| {
            try self.refresh_npsp_payment_rollup_fields(entry.key_ptr.*);
        }

        const closed_stage = self.npsp_payment_auto_close_stage_name() orelse return;
        const updates = try self.arena.create(types.ListValue);
        updates.* = .{};
        var old_opps: std.ArrayListUnmanaged(Value) = .empty;

        var impacted_iter = impacted_ids.iterator();
        while (impacted_iter.next()) |entry| {
            try self.append_npsp_payment_auto_close_update(
                entry.key_ptr.*,
                closed_stage,
                updates,
                &old_opps,
            );
        }

        if (updates.items.items.len == 0) return;
        try self.execute_dml_with_external_id_internal(
            .update,
            Value{ .list = updates },
            null,
            false,
            old_opps,
            false,
        );
    }

    fn npsp_payment_impacted_opportunity_ids(
        self: *Evaluator,
        new_records: []const Value,
        old_records: ?std.ArrayListUnmanaged(Value),
    ) !std.StringArrayHashMapUnmanaged(void) {
        var impacted_ids = std.StringArrayHashMapUnmanaged(void).empty;
        try self.collect_summary_impact_ids_from_records(
            &impacted_ids,
            new_records,
            "npe01__Opportunity__c",
        );
        if (old_records) |previous_records| {
            try self.collect_summary_impact_ids_from_records(
                &impacted_ids,
                previous_records.items,
                "npe01__Opportunity__c",
            );
        }
        return impacted_ids;
    }

    fn append_npsp_payment_auto_close_update(
        self: *Evaluator,
        opp_id: []const u8,
        closed_stage: []const u8,
        updates: *types.ListValue,
        old_opps: *std.ArrayListUnmanaged(Value),
    ) !void {
        const opp_record = self.find_record_by_id("Opportunity", opp_id) orelse return;
        if (opp_record != .sobject) return;

        const amount_val =
            self.get_s_object_field_value_case_insensitive(opp_record.sobject, "Amount") orelse
            return;
        const amount = numeric_value_as_f64(amount_val) orelse return;
        if (amount <= 0) return;

        const paid_amount = self.npsp_paid_payment_total_for_opportunity(opp_id);
        if (paid_amount < amount) return;
        if (npsp_opportunity_is_closed(opp_record.sobject)) return;

        if (self.get_s_object_field_value_case_insensitive(
            opp_record.sobject,
            "StageName",
        )) |stage| {
            if (stage == .string and std.ascii.eqlIgnoreCase(stage.string, closed_stage)) {
                return;
            }
        }

        const updated = try self.clone_s_object(opp_record.sobject);
        const old = try self.clone_s_object(opp_record.sobject);
        try updated.fields.put(self.arena, "StageName", Value{ .string = closed_stage });
        try updated.fields.put(self.arena, "IsClosed", Value{ .boolean = true });
        try updated.fields.put(self.arena, "IsWon", Value{ .boolean = true });
        try updates.items.append(self.arena, Value{ .sobject = updated });
        try old_opps.append(self.arena, Value{ .sobject = old });
    }

    fn refresh_npsp_payment_rollup_fields(self: *Evaluator, opp_id: []const u8) !void {
        const opp_record = self.find_record_by_id("Opportunity", opp_id) orelse return;
        if (opp_record != .sobject) return;

        const paid_amount = self.npsp_paid_payment_total_for_opportunity(opp_id);
        const paid_count = self.npsp_paid_payment_count_for_opportunity(opp_id);
        try utils.sobject_put(
            &opp_record.sobject.fields,
            self.arena,
            "npe01__Payments_Made__c",
            rollup_decimal_value(paid_amount),
        );
        const written_off_amount = self.npsp_written_off_payment_total_for_opportunity(opp_id);
        try utils.sobject_put(
            &opp_record.sobject.fields,
            self.arena,
            "npe01__Amount_Written_Off__c",
            rollup_decimal_value(written_off_amount),
        );
        if (self.get_s_object_field_value_case_insensitive(opp_record.sobject, "Amount")) |amount_value| {
            if (numeric_value_as_f64(amount_value)) |amount| {
                try utils.sobject_put(
                    &opp_record.sobject.fields,
                    self.arena,
                    "npe01__Amount_Outstanding__c",
                    rollup_decimal_value(amount - paid_amount - written_off_amount),
                );
            }
        }
        try utils.sobject_put(
            &opp_record.sobject.fields,
            self.arena,
            "npe01__Number_of_Payments__c",
            Value{ .integer = paid_count },
        );
    }

    fn npsp_paid_payment_count_for_opportunity(self: *Evaluator, opp_id: []const u8) i64 {
        var count: i64 = 0;
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, "npe01__OppPayment__c")) continue;
            for (entry.value_ptr.items) |record| {
                if (record != .sobject) continue;
                const payment_opp = self.get_s_object_field_value_case_insensitive(
                    record.sobject,
                    "npe01__Opportunity__c",
                ) orelse continue;
                if (payment_opp != .string or !std.mem.eql(u8, payment_opp.string, opp_id)) {
                    continue;
                }
                const paid = self.get_s_object_field_value_case_insensitive(
                    record.sobject,
                    "npe01__Paid__c",
                ) orelse Value{ .boolean = false };
                if (paid == .boolean and paid.boolean) count += 1;
            }
        }
        return count;
    }

    fn npsp_payment_count_for_opportunity(self: *Evaluator, opp_id: []const u8) i64 {
        var count: i64 = 0;
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, "npe01__OppPayment__c")) continue;
            for (entry.value_ptr.items) |record| {
                if (record != .sobject) continue;
                const payment_opp = self.get_s_object_field_value_case_insensitive(
                    record.sobject,
                    "npe01__Opportunity__c",
                ) orelse continue;
                if (payment_opp != .string or !std.mem.eql(u8, payment_opp.string, opp_id)) {
                    continue;
                }
                count += 1;
            }
        }
        return count;
    }

    fn npsp_payment_auto_close_stage_name(self: *Evaluator) ?[]const u8 {
        if (self.npsp_cached_contacts_settings()) |settings| {
            if (npsp_payment_auto_close_stage_from_settings(settings)) |stage| return stage;
        }
        if (self.first_custom_setting_record("npe01__Contacts_And_Orgs_Settings__c")) |settings| {
            if (npsp_payment_auto_close_stage_from_settings(settings)) |stage| return stage;
        }
        return null;
    }

    fn npsp_cached_contacts_settings(self: *Evaluator) ?*types.SObject {
        const key = self.static_field_cache_key(
            "UTIL_CustomSettingsFacade",
            "contactsSettings",
        ) catch return null;
        if (self.global_env.get(key)) |value| {
            if (value == .sobject) return value.sobject;
        }
        if (self.resolve_static_field_value_on_class(
            "UTIL_CustomSettingsFacade",
            "contactsSettings",
        )) |value| {
            if (value == .sobject) return value.sobject;
        }
        return null;
    }

    fn npsp_payment_auto_close_stage_from_settings(settings: *types.SObject) ?[]const u8 {
        if (utils.sobject_get(&settings.fields, "Payments_Auto_Close_Stage_Name__c")) |stage| {
            if (stage == .string and stage.string.len > 0) return stage.string;
        }
        return null;
    }

    fn npsp_paid_payment_total_for_opportunity(self: *Evaluator, opp_id: []const u8) f64 {
        var total: f64 = 0;
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, "npe01__OppPayment__c")) continue;
            for (entry.value_ptr.items) |record| {
                if (record != .sobject) continue;
                const payment_opp =
                    self.get_s_object_field_value_case_insensitive(
                        record.sobject,
                        "npe01__Opportunity__c",
                    ) orelse continue;
                if (payment_opp != .string or !std.mem.eql(u8, payment_opp.string, opp_id)) {
                    continue;
                }
                const paid =
                    self.get_s_object_field_value_case_insensitive(
                        record.sobject,
                        "npe01__Paid__c",
                    ) orelse Value{ .boolean = false };
                if (paid != .boolean or !paid.boolean) continue;
                const amount =
                    self.get_s_object_field_value_case_insensitive(
                        record.sobject,
                        "npe01__Payment_Amount__c",
                    ) orelse continue;
                total += numeric_value_as_f64(amount) orelse 0;
            }
        }
        return total;
    }

    fn npsp_written_off_payment_total_for_opportunity(self: *Evaluator, opp_id: []const u8) f64 {
        var total: f64 = 0;
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, "npe01__OppPayment__c")) continue;
            for (entry.value_ptr.items) |record| {
                if (record != .sobject) continue;
                const payment_opp =
                    self.get_s_object_field_value_case_insensitive(
                        record.sobject,
                        "npe01__Opportunity__c",
                    ) orelse continue;
                if (payment_opp != .string or !std.mem.eql(u8, payment_opp.string, opp_id)) {
                    continue;
                }
                const written_off =
                    self.get_s_object_field_value_case_insensitive(
                        record.sobject,
                        "npe01__Written_Off__c",
                    ) orelse Value{ .boolean = false };
                if (written_off != .boolean or !written_off.boolean) continue;
                const amount =
                    self.get_s_object_field_value_case_insensitive(
                        record.sobject,
                        "npe01__Payment_Amount__c",
                    ) orelse continue;
                total += numeric_value_as_f64(amount) orelse 0;
            }
        }
        return total;
    }

    /// `apply_rollup_summary_side_effects` から抽出した helper。親レコードの
    /// rollup summary フィールドを再計算し、差分があれば DML update を発行する。
    fn flush_parent_rollup_updates(
        self: *Evaluator,
        parent_type: []const u8,
        child_type: []const u8,
        type_meta: anytype,
        impacted_ids: std.StringArrayHashMapUnmanaged(void),
        new_records: []const Value,
        old_records: ?std.ArrayListUnmanaged(Value),
    ) !void {
        const parent_updates = try self.arena.create(types.ListValue);
        parent_updates.* = .{};
        var parent_old_records: std.ArrayListUnmanaged(Value) = .empty;

        var impacted_iter = impacted_ids.iterator();
        while (impacted_iter.next()) |impacted_entry| {
            const parent_id = impacted_entry.key_ptr.*;
            const parent_record = self.find_record_by_id(parent_type, parent_id) orelse continue;
            if (parent_record != .sobject) continue;

            const updated_parent = try self.clone_s_object(parent_record.sobject);
            const old_parent = try self.clone_s_object(parent_record.sobject);
            var changed = false;

            var summary_iter = type_meta.iterator();
            while (summary_iter.next()) |summary_entry| {
                const field_name = summary_entry.key_ptr.*;
                const metadata = summary_entry.value_ptr.*;
                const summary_fk = metadata.summary_foreign_key orelse continue;
                const dot_idx = std.mem.indexOfScalar(u8, summary_fk, '.') orelse continue;
                if (!std.ascii.eqlIgnoreCase(summary_fk[0..dot_idx], child_type)) continue;

                const new_value =
                    self.compute_summary_field_value(updated_parent, metadata) orelse
                    Value.null_val;
                const old_value =
                    self.compute_summary_field_value_before_delta(
                        parent_record.sobject,
                        metadata,
                        new_records,
                        old_records,
                    ) orelse Value.null_val;
                try old_parent.fields.put(self.arena, field_name, old_value);
                try updated_parent.fields.put(self.arena, field_name, new_value);
                if (utils.value_eql(old_value, new_value)) continue;

                changed = true;
            }

            if (!changed) continue;
            try parent_updates.items.append(self.arena, Value{ .sobject = updated_parent });
            try parent_old_records.append(self.arena, Value{ .sobject = old_parent });
        }

        if (parent_updates.items.items.len > 0) {
            try self.execute_dml_with_external_id_internal(
                .update,
                Value{ .list = parent_updates },
                null,
                false,
                parent_old_records,
                false,
            );
        }
    }

    fn normalize_summary_field_path(
        _: *Evaluator,
        child_type: []const u8,
        field_path: []const u8,
    ) []const u8 {
        if (std.mem.startsWith(u8, field_path, child_type) and
            field_path.len > child_type.len and
            field_path[child_type.len] == '.')
        {
            return field_path[child_type.len + 1 ..];
        }
        return field_path;
    }

    fn summary_filter_matches(
        self: *Evaluator,
        child: *types.SObject,
        child_type: []const u8,
        filter: SummaryFilter,
    ) bool {
        const field_path = self.normalize_summary_field_path(child_type, filter.field_path);
        const field_val = if (std.mem.indexOfScalar(u8, field_path, '.')) |_|
            self.resolve_field_path_value(child, field_path)
        else
            self.get_s_object_field_value_case_insensitive(child, field_path);
        if (field_val == null) return false;

        if (std.ascii.eqlIgnoreCase(filter.operation, "equals")) {
            return switch (field_val.?) {
                .string => std.ascii.eqlIgnoreCase(field_val.?.string, filter.value),
                .integer => blk: {
                    const expected = std.fmt.parseInt(i64, filter.value, 10) catch break :blk false;
                    break :blk field_val.?.integer == expected;
                },
                .double => blk: {
                    const expected = std.fmt.parseFloat(f64, filter.value) catch break :blk false;
                    break :blk field_val.?.double == expected;
                },
                .boolean => if (std.ascii.eqlIgnoreCase(filter.value, "true"))
                    field_val.?.boolean
                else if (std.ascii.eqlIgnoreCase(filter.value, "false"))
                    !field_val.?.boolean
                else
                    false,
                .null_val => std.ascii.eqlIgnoreCase(filter.value, "null"),
                else => {
                    const actual = utils.coerce_to_string(
                        field_val.?,
                        self.arena,
                    ) catch return false;
                    return std.ascii.eqlIgnoreCase(actual, filter.value);
                },
            };
        }

        if (std.ascii.eqlIgnoreCase(filter.operation, "notEqual")) {
            return !self.summary_filter_matches(child, child_type, .{
                .field_path = filter.field_path,
                .operation = "equals",
                .value = filter.value,
            });
        }

        return false;
    }

    fn find_s_object_by_id_in_values(
        _: *Evaluator,
        records: []const Value,
        id: []const u8,
    ) ?*types.SObject {
        for (records) |record| {
            if (record != .sobject or record.sobject.id == null) continue;
            if (std.mem.eql(u8, record.sobject.id.?, id)) return record.sobject;
        }
        return null;
    }

    fn summary_record_matches(
        self: *Evaluator,
        child: *types.SObject,
        child_type: []const u8,
        fk_field: []const u8,
        parent_id: []const u8,
        metadata: FieldMetadata,
    ) bool {
        const fk_val =
            self.get_s_object_field_value_case_insensitive(child, fk_field) orelse
            return false;
        if (fk_val != .string or !std.ascii.eqlIgnoreCase(fk_val.string, parent_id)) return false;

        for (metadata.summary_filters) |filter| {
            if (!self.summary_filter_matches(child, child_type, filter)) return false;
        }
        return true;
    }

    fn accumulate_summary_value(
        self: *Evaluator,
        child: *types.SObject,
        child_type: []const u8,
        metadata: FieldMetadata,
        count: *i64,
        aggregate: *?Value,
    ) void {
        const summary_operation = metadata.summary_operation orelse return;
        if (std.ascii.eqlIgnoreCase(summary_operation, "count")) {
            count.* += 1;
            return;
        }

        const summarized_field = if (metadata.summarized_field) |field_path|
            self.normalize_summary_field_path(child_type, field_path)
        else
            "";
        if (summarized_field.len == 0) return;

        const child_value = blk: {
            if (std.mem.indexOfScalar(u8, summarized_field, '.')) |_| {
                break :blk self.resolve_field_path_value(
                    child,
                    summarized_field,
                ) orelse Value.null_val;
            }
            break :blk self.get_s_object_field_value_case_insensitive(
                child,
                summarized_field,
            ) orelse Value.null_val;
        };
        if (child_value == .null_val) return;

        if (aggregate.* == null) {
            aggregate.* = child_value;
            return;
        }

        const cmp = self.compare_values(aggregate.*.?, child_value);
        if (std.ascii.eqlIgnoreCase(summary_operation, "min")) {
            if (cmp > 0) aggregate.* = child_value;
        } else if (std.ascii.eqlIgnoreCase(summary_operation, "max")) {
            if (cmp < 0) aggregate.* = child_value;
        }
    }

    fn compute_summary_field_value_before_delta(
        self: *Evaluator,
        sob: *types.SObject,
        metadata: FieldMetadata,
        new_records: []const Value,
        old_records: ?std.ArrayListUnmanaged(Value),
    ) ?Value {
        const summary_operation = metadata.summary_operation orelse return null;
        const summary_fk = metadata.summary_foreign_key orelse return null;
        const dot_idx = std.mem.indexOfScalar(u8, summary_fk, '.') orelse return null;
        const child_type = summary_fk[0..dot_idx];
        const fk_field = summary_fk[dot_idx + 1 ..];

        const parent_id = self.summary_parent_id(sob);
        if (parent_id == null) return self.empty_summary_value(summary_operation);

        const child_records = self.store.get(child_type) orelse {
            return self.empty_summary_value(summary_operation);
        };

        var count: i64 = 0;
        var aggregate: ?Value = null;

        for (child_records.items) |record| {
            if (record != .sobject or record.sobject.id == null) continue;
            const record_id = record.sobject.id.?;

            if (old_records) |previous_records| {
                if (self.accumulate_previous_summary_record(
                    previous_records.items,
                    record_id,
                    child_type,
                    fk_field,
                    parent_id.?,
                    metadata,
                    &count,
                    &aggregate,
                )) {
                    continue;
                }
            }

            self.accumulate_current_summary_record_before_delta(
                record.sobject,
                new_records,
                record_id,
                child_type,
                fk_field,
                parent_id.?,
                metadata,
                &count,
                &aggregate,
            );
        }

        if (old_records) |previous_records| {
            self.accumulate_deleted_summary_records(
                previous_records.items,
                child_type,
                fk_field,
                parent_id.?,
                metadata,
                &count,
                &aggregate,
            );
        }

        if (std.ascii.eqlIgnoreCase(summary_operation, "count")) return Value{ .integer = count };
        return aggregate orelse Value.null_val;
    }

    fn summary_parent_id(_: *Evaluator, sob: *types.SObject) ?[]const u8 {
        return sob.id orelse blk: {
            if (utils.sobject_get(&sob.fields, "Id")) |id_val| {
                if (id_val == .string) break :blk id_val.string;
            }
            break :blk null;
        };
    }

    fn empty_summary_value(_: *Evaluator, summary_operation: []const u8) Value {
        if (std.ascii.eqlIgnoreCase(summary_operation, "count")) {
            return Value{ .integer = 0 };
        }
        return Value.null_val;
    }

    fn accumulate_previous_summary_record(
        self: *Evaluator,
        previous_records: []const Value,
        record_id: []const u8,
        child_type: []const u8,
        fk_field: []const u8,
        parent_id: []const u8,
        metadata: FieldMetadata,
        count: *i64,
        aggregate: *?Value,
    ) bool {
        const old_child =
            self.find_s_object_by_id_in_values(previous_records, record_id) orelse
            return false;
        if (self.summary_record_matches(
            old_child,
            child_type,
            fk_field,
            parent_id,
            metadata,
        )) {
            self.accumulate_summary_value(
                old_child,
                child_type,
                metadata,
                count,
                aggregate,
            );
        }
        return true;
    }

    fn accumulate_current_summary_record_before_delta(
        self: *Evaluator,
        record: *types.SObject,
        new_records: []const Value,
        record_id: []const u8,
        child_type: []const u8,
        fk_field: []const u8,
        parent_id: []const u8,
        metadata: FieldMetadata,
        count: *i64,
        aggregate: *?Value,
    ) void {
        const inserted_now =
            self.find_s_object_by_id_in_values(new_records, record_id) != null;
        if (inserted_now) return;
        if (self.summary_record_matches(
            record,
            child_type,
            fk_field,
            parent_id,
            metadata,
        )) {
            self.accumulate_summary_value(
                record,
                child_type,
                metadata,
                count,
                aggregate,
            );
        }
    }

    fn accumulate_deleted_summary_records(
        self: *Evaluator,
        previous_records: []const Value,
        child_type: []const u8,
        fk_field: []const u8,
        parent_id: []const u8,
        metadata: FieldMetadata,
        count: *i64,
        aggregate: *?Value,
    ) void {
        for (previous_records) |record| {
            if (record != .sobject or record.sobject.id == null) continue;
            if (self.find_record_in_store(child_type, record.sobject.id.?)) |_| continue;
            if (self.summary_record_matches(
                record.sobject,
                child_type,
                fk_field,
                parent_id,
                metadata,
            )) {
                self.accumulate_summary_value(
                    record.sobject,
                    child_type,
                    metadata,
                    count,
                    aggregate,
                );
            }
        }
    }

    fn compute_summary_field_value(
        self: *Evaluator,
        sob: *types.SObject,
        metadata: FieldMetadata,
    ) ?Value {
        const summary_operation = metadata.summary_operation orelse return null;
        const summary_fk = metadata.summary_foreign_key orelse return null;
        const dot_idx = std.mem.indexOfScalar(u8, summary_fk, '.') orelse return null;
        const child_type = summary_fk[0..dot_idx];
        const fk_field = summary_fk[dot_idx + 1 ..];

        const parent_id = self.summary_parent_id(sob);

        if (parent_id == null) {
            return self.empty_summary_value(summary_operation);
        }

        const child_records = self.store.get(child_type) orelse {
            return self.empty_summary_value(summary_operation);
        };

        var count: i64 = 0;
        var aggregate: ?Value = null;

        for (child_records.items) |record| {
            if (record != .sobject) continue;
            if (!self.summary_record_matches(
                record.sobject,
                child_type,
                fk_field,
                parent_id.?,
                metadata,
            )) continue;
            self.accumulate_summary_value(record.sobject, child_type, metadata, &count, &aggregate);
        }

        if (std.ascii.eqlIgnoreCase(summary_operation, "count")) return Value{ .integer = count };
        return aggregate orelse Value.null_val;
    }

    fn compute_formula_field_value(
        self: *Evaluator,
        sob: *types.SObject,
        metadata: FieldMetadata,
    ) ?Value {
        const formula = metadata.formula orelse return null;
        const trimmed = std.mem.trim(u8, formula, " \t\n\r");
        if (trimmed.len == 0) return null;
        if (self.compute_active_date_range_formula(sob, trimmed)) |value| return value;

        if (std.mem.indexOfScalar(u8, trimmed, '+')) |_| {
            var total: i64 = 0;
            var term_iter = std.mem.splitScalar(u8, trimmed, '+');
            while (term_iter.next()) |raw_term| {
                const term = std.mem.trim(u8, raw_term, " \t\n\r()");
                if (term.len == 0) continue;
                const term_value =
                    self.get_s_object_field_value_case_insensitive(
                        sob,
                        term,
                    ) orelse Value.null_val;
                switch (term_value) {
                    .integer => |i| total += i,
                    .double => |d| total += @intFromFloat(d),
                    .null_val => {
                        if (!metadata.formula_blank_as_zero) return Value.null_val;
                    },
                    else => return Value.null_val,
                }
            }
            return Value{ .integer = total };
        }

        if (std.mem.indexOfScalar(u8, trimmed, '.')) |_| {
            return self.resolve_field_path_value(sob, trimmed);
        }

        if (std.ascii.indexOfIgnoreCase(trimmed, "!= null")) |idx| {
            const lhs = std.mem.trim(u8, trimmed[0..idx], " \t\n\r");
            const lhs_value =
                self.get_s_object_field_value_case_insensitive(
                    sob,
                    lhs,
                ) orelse Value.null_val;
            return Value{ .boolean = lhs_value != .null_val };
        }

        if (std.ascii.indexOfIgnoreCase(trimmed, "== null")) |idx| {
            const lhs = std.mem.trim(u8, trimmed[0..idx], " \t\n\r");
            const lhs_value =
                self.get_s_object_field_value_case_insensitive(
                    sob,
                    lhs,
                ) orelse Value.null_val;
            return Value{ .boolean = lhs_value == .null_val };
        }

        return self.get_s_object_field_value_case_insensitive(sob, trimmed);
    }

    fn compute_active_date_range_formula(
        self: *Evaluator,
        sob: *types.SObject,
        formula: []const u8,
    ) ?Value {
        if (std.ascii.indexOfIgnoreCase(formula, "OR(") == null or
            std.ascii.indexOfIgnoreCase(formula, "ISBLANK(") == null or
            std.ascii.indexOfIgnoreCase(formula, "TODAY()") == null or
            std.ascii.indexOfIgnoreCase(formula, "AND(") == null or
            std.ascii.indexOfIgnoreCase(formula, "NOT(") == null)
        {
            return null;
        }
        const end_field = formula_arg_after(formula, "ISBLANK(") orelse return null;
        const end_value =
            self.get_s_object_field_value_case_insensitive(sob, end_field) orelse Value.null_val;
        if (end_value == .null_val) return Value{ .boolean = true };
        const end_date = builtins.extract_date_string(end_value) orelse return null;
        const today = builtins.current_date_string(self.arena) catch return null;
        if (std.mem.order(u8, end_date, today) == .lt) return Value{ .boolean = false };

        const not_expr = formula_arg_after(formula, "NOT(") orelse return Value{ .boolean = true };
        const gt_pos = std.mem.indexOfScalar(u8, not_expr, '>') orelse return Value{ .boolean = true };
        const start_field = std.mem.trim(u8, not_expr[0..gt_pos], " \t\n\r");
        const end_check_field = std.mem.trim(u8, not_expr[gt_pos + 1 ..], " \t\n\r");
        const start_value =
            self.get_s_object_field_value_case_insensitive(sob, start_field) orelse Value.null_val;
        const end_check_value =
            self.get_s_object_field_value_case_insensitive(sob, end_check_field) orelse end_value;
        const start_date = builtins.extract_date_string(start_value) orelse
            return Value{ .boolean = true };
        const compared_end_date = builtins.extract_date_string(end_check_value) orelse
            return Value{ .boolean = true };
        return Value{ .boolean = std.mem.order(u8, start_date, compared_end_date) != .gt };
    }

    fn formula_arg_after(formula: []const u8, needle: []const u8) ?[]const u8 {
        const start = std.ascii.indexOfIgnoreCase(formula, needle) orelse return null;
        const arg_start = start + needle.len;
        var depth: usize = 1;
        var idx = arg_start;
        while (idx < formula.len) : (idx += 1) {
            switch (formula[idx]) {
                '(' => depth += 1,
                ')' => {
                    depth -= 1;
                    if (depth == 0) return std.mem.trim(u8, formula[arg_start..idx], " \t\n\r");
                },
                else => {},
            }
        }
        return null;
    }

    /// Create a shallow clone of an SObject (copies the fields map).
    fn clone_s_object(self: *Evaluator, src: *types.SObject) !*types.SObject {
        const copy = try self.arena.create(types.SObject);
        copy.* = .{ .type_name = src.type_name, .id = src.id };
        for (src.fields.keys(), src.fields.values()) |k, v| {
            try copy.fields.put(self.arena, k, v);
        }
        return copy;
    }

    fn default_custom_setting_record(
        self: *Evaluator,
        class_name: []const u8,
        setup_owner_id: ?[]const u8,
    ) !Value {
        const sob = try self.arena.create(types.SObject);
        sob.* = .{ .type_name = class_name };
        if (self.field_defaults.get(class_name)) |defaults| {
            for (defaults.keys(), defaults.values()) |fk, fv| {
                try sob.fields.put(self.arena, fk, fv);
            }
        }
        if (setup_owner_id) |owner_id| {
            try sob.fields.put(self.arena, "SetupOwnerId", Value{ .string = owner_id });
        }
        return Value{ .sobject = sob };
    }

    fn put_default_sobject_field(
        self: *Evaluator,
        sob: *types.SObject,
        field_name: []const u8,
        value: Value,
    ) !void {
        if (utils.sobject_get(&sob.fields, field_name)) |existing| {
            if (existing != .null_val) return;
        }
        try sob.fields.put(self.arena, field_name, value);
    }

    fn clone_custom_setting_record(
        self: *Evaluator,
        record: *types.SObject,
        setup_owner_id: ?[]const u8,
        clear_id: bool,
    ) !Value {
        const copy = try self.clone_s_object(record);
        if (clear_id) {
            copy.id = null;
            try copy.fields.put(self.arena, "Id", Value.null_val);
        }
        if (setup_owner_id) |owner_id| {
            try copy.fields.put(self.arena, "SetupOwnerId", Value{ .string = owner_id });
        }
        return Value{ .sobject = copy };
    }

    fn find_custom_setting_record(
        self: *Evaluator,
        class_name: []const u8,
        owner_id: []const u8,
    ) ?*types.SObject {
        var cs_iter = self.store.iterator();
        while (cs_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item != .sobject) continue;
                if (utils.sobject_get(&item.sobject.fields, "SetupOwnerId")) |stored_owner| {
                    if (stored_owner == .string and
                        std.ascii.eqlIgnoreCase(stored_owner.string, owner_id))
                    {
                        return item.sobject;
                    }
                }
            }
        }
        return null;
    }

    fn first_custom_setting_record(self: *Evaluator, class_name: []const u8) ?*types.SObject {
        var cs_iter = self.store.iterator();
        while (cs_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item == .sobject) return item.sobject;
            }
        }
        return null;
    }

    fn list_custom_setting_record_key(record: *types.SObject) ?[]const u8 {
        if (utils.sobject_get(&record.fields, "Name")) |name| {
            if (name == .string and name.string.len > 0) return name.string;
        }
        if (utils.sobject_get(&record.fields, "DeveloperName")) |dev_name| {
            if (dev_name == .string and dev_name.string.len > 0) return dev_name.string;
        }
        return record.id;
    }

    fn find_list_custom_setting_record(
        self: *Evaluator,
        class_name: []const u8,
        name: []const u8,
    ) ?*types.SObject {
        var cs_iter = self.store.iterator();
        while (cs_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item != .sobject) continue;
                const key = list_custom_setting_record_key(item.sobject) orelse continue;
                if (std.ascii.eqlIgnoreCase(key, name)) return item.sobject;
            }
        }
        return null;
    }

    fn list_custom_setting_get_all(self: *Evaluator, class_name: []const u8) !Value {
        const map = try self.arena.create(types.MapValue);
        map.* = .{};
        var cs_iter = self.store.iterator();
        while (cs_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item != .sobject) continue;
                const key = list_custom_setting_record_key(item.sobject) orelse continue;
                try map.entries.put(
                    self.arena,
                    key,
                    try self.clone_custom_setting_record(item.sobject, null, false),
                );
            }
        }
        return Value{ .map = map };
    }

    fn custom_setting_kind(self: *Evaluator, class_name: []const u8) ?[]const u8 {
        if (self.custom_setting_kinds.get(class_name)) |kind| return kind;
        if (self.custom_setting_types.get(class_name) != null) return "Hierarchy";
        return null;
    }

    fn resolve_bare_static_value(self: *Evaluator, current_env: *Env, name: []const u8) ?Value {
        if (current_env.get_this()) |this_val| {
            if (this_val == .object) {
                const this_cn = this_val.object.class_name;
                if (self.resolve_static_field_value_on_class(this_cn, name)) |val| return val;
                if (self.find_class(this_cn)) |cd| {
                    if (cd.super_class) |sc| {
                        if (self.resolve_static_field_value_on_class(sc.name, name)) |val| {
                            return val;
                        }
                    }
                }
                if (self.resolve_outer_static_field(this_cn, name)) |val| return val;
            }
        }

        if (self.current_class) |cc| {
            if (self.resolve_static_field_value_on_class(cc, name)) |val| return val;
            if (self.find_class(cc)) |cd| {
                if (cd.super_class) |sc| {
                    if (self.resolve_static_field_value_on_class(sc.name, name)) |val| return val;
                }
            }
            if (self.resolve_outer_static_field(cc, name)) |val| return val;
        }

        return null;
    }

    fn handle_custom_setting_static_method(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) !?Value {
        if (!std.mem.endsWith(u8, class_name, "__c")) return null;

        const kind = self.custom_setting_kind(class_name);
        const is_hierarchy = kind != null and std.ascii.eqlIgnoreCase(kind.?, "Hierarchy");

        if (std.ascii.eqlIgnoreCase(method_name, "getOrgDefaults")) {
            return try self.custom_setting_get_org_defaults(class_name, is_hierarchy);
        }

        if (std.ascii.eqlIgnoreCase(method_name, "getInstance")) {
            if (is_hierarchy) {
                return try self.hierarchy_custom_setting_get_instance(class_name, args);
            }

            return try self.handle_list_custom_setting_static_method(
                class_name,
                method_name,
                args,
            );
        }

        if (!is_hierarchy) {
            return try self.handle_list_custom_setting_static_method(
                class_name,
                method_name,
                args,
            );
        }

        if (std.ascii.eqlIgnoreCase(method_name, "getValues") and
            args.len > 0 and
            args[0] == .string)
        {
            if (self.find_custom_setting_record(class_name, args[0].string)) |found| {
                return try self.clone_custom_setting_record(found, null, false);
            }
            return Value.null_val;
        }

        return null;
    }

    fn handle_tdtm_process_control_static_method(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) !?Value {
        if (!self.fixture_relaxed_exceptions) return null;
        if (!std.ascii.eqlIgnoreCase(class_name, "TDTM_ProcessControl")) return null;
        if (!std.ascii.eqlIgnoreCase(method_name, "toggleTriggerState")) return null;
        if (args.len < 3 or args[0] != .string or args[1] != .string or args[2] != .boolean) {
            return Value.void_val;
        }
        try self.set_tdtm_trigger_handler_active(args[0].string, args[1].string, args[2].boolean);
        return Value.void_val;
    }

    fn handle_npsp_allocations_util_static_method(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) ?Value {
        if (!self.fixture_relaxed_exceptions) return null;
        if (!std.ascii.eqlIgnoreCase(class_name, "ALLO_AllocationsUtil")) return null;
        if (std.ascii.eqlIgnoreCase(method_name, "disableAllocationTriggers")) {
            self.npsp_allocation_triggers_disabled = true;
            return Value.void_val;
        }
        if (std.ascii.eqlIgnoreCase(method_name, "enableAllocationTriggers")) {
            self.npsp_allocation_triggers_disabled = false;
            return Value.void_val;
        }
        if (std.ascii.eqlIgnoreCase(method_name, "updateAllocationTriggersState")) {
            if (args.len >= 1 and args[0] == .boolean) {
                self.npsp_allocation_triggers_disabled = !args[0].boolean;
            }
            return Value.void_val;
        }
        return null;
    }

    fn set_tdtm_trigger_handler_active(
        self: *Evaluator,
        object_name: []const u8,
        class_name: []const u8,
        active: bool,
    ) !void {
        const override_key = try self.tdtm_trigger_state_key(object_name, class_name);
        try self.tdtm_trigger_state_overrides.put(self.arena, override_key, active);

        var list_value = self.resolve_static_field_value_on_class(
            "TDTM_ObjectDataGateway",
            "listTH",
        ) orelse Value.null_val;
        if (list_value != .list) {
            const list = try self.arena.create(types.ListValue);
            list.* = .{};
            list_value = Value{ .list = list };
            try self.set_static_field_if_present(
                "TDTM_ObjectDataGateway",
                "listTH",
                list_value,
            );
        }

        for (list_value.list.items.items) |record| {
            if (record != .sobject) continue;
            if (!self.npsp_tdtm_handler_matches(record.sobject, object_name, class_name)) continue;
            try utils.sobject_put(
                &record.sobject.fields,
                self.arena,
                "Active__c",
                Value{ .boolean = active },
            );
            return;
        }
        const handler = try self.arena.create(types.SObject);
        handler.* = .{ .type_name = "Trigger_Handler__c" };
        try handler.fields.put(self.arena, "Object__c", Value{ .string = object_name });
        try handler.fields.put(self.arena, "Class__c", Value{ .string = class_name });
        try handler.fields.put(self.arena, "Active__c", Value{ .boolean = active });
        try list_value.list.items.append(self.arena, Value{ .sobject = handler });
    }

    fn custom_setting_get_org_defaults(
        self: *Evaluator,
        class_name: []const u8,
        is_hierarchy: bool,
    ) !Value {
        if (is_hierarchy) {
            if (self.find_custom_setting_record(class_name, "00D000000000001")) |record| {
                return try self.clone_custom_setting_record(record, null, false);
            }
            return try self.default_custom_setting_record(class_name, "00D000000000001");
        }
        if (self.first_custom_setting_record(class_name)) |record| {
            return try self.clone_custom_setting_record(record, null, false);
        }
        return try self.default_custom_setting_record(class_name, null);
    }

    fn hierarchy_custom_setting_get_instance(
        self: *Evaluator,
        class_name: []const u8,
        args: []const Value,
    ) !Value {
        const owner_id = if (args.len > 0 and args[0] == .string and args[0].string.len > 0)
            args[0].string
        else
            self.current_user_id;
        const profile_id = self.current_profile_id;
        const org_id = "00D000000000001";

        if (self.find_custom_setting_record(class_name, owner_id)) |user_record| {
            return try self.clone_custom_setting_record(user_record, owner_id, false);
        }
        if (self.find_custom_setting_record(class_name, profile_id)) |profile_record| {
            return try self.clone_custom_setting_record(profile_record, owner_id, true);
        }
        if (self.find_custom_setting_record(class_name, org_id)) |org_defaults| {
            return try self.clone_custom_setting_record(org_defaults, owner_id, true);
        }
        return try self.default_custom_setting_record(class_name, owner_id);
    }

    fn handle_list_custom_setting_static_method(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method_name, "getAll")) {
            return try self.list_custom_setting_get_all(class_name);
        }
        if (std.ascii.eqlIgnoreCase(method_name, "getInstance")) {
            if (args.len > 0 and args[0] == .string) {
                if (self.find_list_custom_setting_record(class_name, args[0].string)) |record| {
                    return try self.clone_custom_setting_record(record, null, false);
                }
                return Value.null_val;
            }
            if (self.first_custom_setting_record(class_name)) |record| {
                return try self.clone_custom_setting_record(record, null, false);
            }
            return try self.default_custom_setting_record(class_name, null);
        }
        if (std.ascii.eqlIgnoreCase(method_name, "getValues") and
            args.len > 0 and
            args[0] == .string)
        {
            if (self.find_list_custom_setting_record(class_name, args[0].string)) |record| {
                return try self.clone_custom_setting_record(record, null, false);
            }
            return Value.null_val;
        }
        return null;
    }

    fn handle_crlp_rollup_svc_static_method(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) !?Value {
        if (!std.ascii.eqlIgnoreCase(class_name, "CRLP_Rollup_SVC") or
            !std.ascii.eqlIgnoreCase(method_name, "getSObjectFieldDescribe") or
            args.len < 2 or args[0] != .string or args[1] != .string)
        {
            return null;
        }

        const dfr = try self.arena.create(types.ObjectInstance);
        dfr.* = .{ .class_name = "Schema.DescribeFieldResult" };
        try dfr.fields.put(self.arena, "objectType", args[0]);
        try dfr.fields.put(self.arena, "fieldName", args[1]);
        try dfr.fields.put(self.arena, "name", args[1]);
        const soap_type = if (crlp_rollup_numeric_field(args[1].string)) "DOUBLE" else "STRING";
        try dfr.fields.put(self.arena, "soapType", Value{ .string = soap_type });
        try dfr.fields.put(self.arena, "type", Value{ .string = soap_type });
        try dfr.fields.put(self.arena, "isAccessible", Value{ .boolean = true });
        try dfr.fields.put(self.arena, "isUpdateable", Value{ .boolean = true });
        try dfr.fields.put(self.arena, "isCreateable", Value{ .boolean = true });
        return Value{ .object = dfr };
    }

    fn crlp_rollup_numeric_field(field_name: []const u8) bool {
        return std.ascii.indexOfIgnoreCase(field_name, "Amount") != null or
            std.ascii.indexOfIgnoreCase(field_name, "Total") != null or
            std.ascii.indexOfIgnoreCase(field_name, "Count") != null or
            std.ascii.indexOfIgnoreCase(field_name, "Number") != null;
    }

    /// Find the type name of a record by its Id, searching all types in store.
    fn find_record_type_by_id(self: *Evaluator, id: []const u8) ?[]const u8 {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            for (entry.value_ptr.items) |record| {
                if (record == .sobject) {
                    if (record.sobject.id) |rec_id| {
                        if (std.ascii.eqlIgnoreCase(rec_id, id)) return entry.key_ptr.*;
                    }
                }
            }
        }
        return null;
    }

