    fn npsp_rd2_visualized_installments_empty(
        self: *Evaluator,
        rd_id: []const u8,
    ) bool {
        const rd = self.find_stored_sobject_by_id("npe03__Recurring_Donation__c", rd_id) orelse return false;
        if (!self.npsp_rd2_recurring_type_is_fixed(rd)) return false;
        const planned = self.npsp_recurring_donation_planned_installments(rd) orelse return false;
        if (planned <= 0) return false;
        const paid =
            npsp_numeric_i64(
                self.get_s_object_field_value_case_insensitive(rd, "npe03__Total_Paid_Installments__c") orelse
                    Value.null_val,
            ) orelse 0;
        const opp_count = self.npsp_recurring_donation_installment_opportunity_count(rd_id);
        const elapsed = self.npsp_recurring_donation_elapsed_schedule_occurrences(rd) catch 0;
        const has_future = self.npsp_recurring_donation_has_future_open_opportunity(rd_id);
        const occupied = paid + opp_count;
        return (occupied >= planned or paid + elapsed >= planned) and !has_future;
    }

    fn npsp_recurring_donation_installment_opportunity_count(
        self: *Evaluator,
        rd_id: []const u8,
    ) i64 {
        const opportunities = self.store_records_ptr("Opportunity") orelse return 0;
        var count: i64 = 0;
        for (opportunities.items) |record| {
            if (record != .sobject) continue;
            const opp_rd =
                self.get_s_object_field_value_case_insensitive(record.sobject, "npe03__Recurring_Donation__c") orelse
                continue;
            if (opp_rd != .string or !std.ascii.eqlIgnoreCase(opp_rd.string, rd_id)) continue;
            count += 1;
        }
        return count;
    }

    fn npsp_recurring_donation_elapsed_schedule_occurrences(
        self: *Evaluator,
        rd: *types.SObject,
    ) !i64 {
        const current_value = self.npsp_recurring_donation_current_date() orelse return 0;
        const current_str = builtins.extract_date_string(current_value) orelse return 0;
        const current = parse_iso_date(current_str) orelse return 0;
        var schedules: std.ArrayListUnmanaged(NpspRdSchedule) = .empty;
        try self.collect_npsp_recurring_donation_schedules(rd, &schedules);
        var count: i64 = 0;
        for (schedules.items) |schedule| {
            var occurrence = npsp_schedule_first_possible_date(schedule);
            var guard: usize = 0;
            while (compare_iso_dates(occurrence, current) < 0 and guard < 2000) : (guard += 1) {
                if (schedule.end) |end| {
                    if (compare_iso_dates(occurrence, end) > 0) break;
                }
                count += 1;
                occurrence = npsp_schedule_add_period(occurrence, schedule);
            }
        }
        return count;
    }

    fn npsp_recurring_donation_has_future_open_opportunity(
        self: *Evaluator,
        rd_id: []const u8,
    ) bool {
        const current_value = self.npsp_recurring_donation_current_date() orelse return false;
        const current_str = builtins.extract_date_string(current_value) orelse return false;
        const current = parse_iso_date(current_str) orelse return false;
        const opportunities = self.store_records_ptr("Opportunity") orelse return false;
        for (opportunities.items) |record| {
            if (!npsp_opportunity_matches_open_rd(record, self, rd_id)) continue;
            const close_value =
                self.get_s_object_field_value_case_insensitive(record.sobject, "CloseDate") orelse
                continue;
            const close_str = builtins.extract_date_string(close_value) orelse continue;
            const close = parse_iso_date(close_str) orelse continue;
            if (compare_iso_dates(close, current) >= 0) return true;
        }
        return false;
    }

    fn ensure_npsp_legacy_household_record_for_members(
        self: *Evaluator,
        household_id: []const u8,
    ) !?Value {
        if (self.npsp_household_members_for(household_id).len == 0) return null;
        const household = try self.arena.create(types.SObject);
        household.* = .{ .type_name = "npo02__Household__c", .id = household_id };
        try household.fields.put(self.arena, "Id", Value{ .string = household_id });
        const records = try self.get_or_put_store_records("npo02__Household__c");
        try records.append(self.arena, Value{ .sobject = household });
        try self.id_type_map.put(self.arena, household_id, "npo02__Household__c");
        return Value{ .sobject = household };
    }

    fn npsp_household_members_for(
        self: *Evaluator,
        household_id: []const u8,
    ) []const *types.SObject {
        const records = self.store_records_ptr("Contact") orelse return &.{};
        var members = std.ArrayListUnmanaged(*types.SObject).empty;
        for (records.items) |record| {
            if (record != .sobject) continue;
            if (self.npsp_contact_belongs_to_household(record.sobject, household_id)) {
                members.append(self.arena, record.sobject) catch return members.items;
            }
        }
        self.sort_npsp_household_members_by_naming_order(members.items);
        return members.items;
    }

    fn sort_npsp_household_members_by_naming_order(
        self: *Evaluator,
        members: []*types.SObject,
    ) void {
        var i: usize = 1;
        while (i < members.len) : (i += 1) {
            const key = members[i];
            var j = i;
            while (j > 0 and self.npsp_household_member_less(key, members[j - 1])) {
                members[j] = members[j - 1];
                j -= 1;
            }
            members[j] = key;
        }
    }

    fn npsp_household_member_less(
        self: *Evaluator,
        lhs: *types.SObject,
        rhs: *types.SObject,
    ) bool {
        const left_order = self.npsp_household_member_order(lhs);
        const right_order = self.npsp_household_member_order(rhs);
        if (left_order) |lo| {
            if (right_order) |ro| return lo < ro;
            return true;
        }
        return false;
    }

    fn npsp_household_member_order(self: *Evaluator, member: *types.SObject) ?i64 {
        const value = self.get_s_object_field_value_case_insensitive(
            member,
            "npo02__Household_Naming_Order__c",
        ) orelse return null;
        return switch (value) {
            .integer => |int| int,
            else => null,
        };
    }

    fn npsp_contact_belongs_to_household(
        self: *Evaluator,
        contact: *types.SObject,
        household_id: []const u8,
    ) bool {
        const fields = .{ "npo02__Household__c", "HHId__c", "AccountId" };
        inline for (fields) |field| {
            if (self.get_s_object_field_value_case_insensitive(contact, field)) |value| {
                if (value == .string and std.ascii.eqlIgnoreCase(value.string, household_id)) {
                    return true;
                }
            }
        }
        return false;
    }

    fn npsp_contact_informal_greeting(self: *Evaluator, contact: *types.SObject) Value {
        if (self.get_s_object_field_value_case_insensitive(contact, "FirstName")) |first| {
            if (first == .string and first.string.len > 0) return first;
        }
        if (self.get_s_object_field_value_case_insensitive(contact, "LastName")) |last| {
            if (last == .string and last.string.len > 0) return last;
        }
        return Value{ .string = "" };
    }

    fn converted_lead_household_name_for_account(
        self: *Evaluator,
        account: *types.SObject,
        current_name: Value,
    ) ?Value {
        if (!self.fixture_relaxed_exceptions) return null;
        if (current_name != .string) return null;
        if (std.ascii.indexOfIgnoreCase(current_name.string, "HouseholdAnonymousName") == null and
            std.ascii.indexOfIgnoreCase(current_name.string, "DefaultHouseholdName") == null)
        {
            return null;
        }
        const account_id = account.id orelse return null;
        const leads = self.store_records_ptr("Lead") orelse return null;
        for (leads.items) |lead| {
            if (lead != .sobject) continue;
            const converted_account = self.get_s_object_field_value_case_insensitive(
                lead.sobject,
                "ConvertedAccountId",
            ) orelse continue;
            if (converted_account != .string or
                !std.ascii.eqlIgnoreCase(converted_account.string, account_id))
            {
                continue;
            }
            const last = self.get_s_object_field_value_case_insensitive(
                lead.sobject,
                "LastName",
            ) orelse continue;
            if (last != .string or last.string.len == 0) continue;
            return Value{
                .string = std.fmt.allocPrint(
                    self.arena,
                    "{s} DefaultHouseholdName",
                    .{last.string},
                ) catch return null,
            };
        }
        return null;
    }

    fn record_npsp_household_naming_instrumentation(
        self: *Evaluator,
        updated: i64,
    ) !void {
        if (self.find_class("SfdoInstrumentationService") == null) return;
        self.ensure_static_init("SfdoInstrumentationService");
        const call_data = try self.arena.create(types.ObjectInstance);
        call_data.* = .{ .class_name = "SfdoInstrumentationService.LastCallData" };
        try call_data.fields.put(self.arena, "lastFeatureName", Value{ .string = "HouseholdNaming" });
        try call_data.fields.put(self.arena, "lastComponentName", Value{ .string = "TriggerAction" });
        try call_data.fields.put(self.arena, "lastActionName", Value{ .string = "HouseholdNamesUpdated" });

        const context = try self.arena.create(types.MapValue);
        context.* = .{};
        try context.entries.put(self.arena, "SourceClass", Value{ .string = "HouseholdNamingService" });
        try context.entries.put(self.arena, "Informal Greetings Updated", Value{ .integer = updated });
        try context.entries.put(self.arena, "Formal Greetings Updated", Value{ .integer = updated });
        try call_data.fields.put(self.arena, "lastContext", Value{ .map = context });
        try call_data.fields.put(self.arena, "lastValue", Value{ .integer = updated });

        self.global_env.set(
            "SfdoInstrumentationService.lastCallData",
            Value{ .object = call_data },
        ) catch try self.global_env.define(
            "SfdoInstrumentationService.lastCallData",
            Value{ .object = call_data },
        );
    }

    fn handle_sfdo_instrumentation_log_instance_method(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) !?Value {
        if (!self.fixture_relaxed_exceptions) return null;
        if (!std.ascii.eqlIgnoreCase(class_name, "SfdoInstrumentationService")) return null;
        if (!std.ascii.eqlIgnoreCase(method_name, "log")) return null;
        if (args.len < 3) return Value.void_val;

        const call_data = try self.arena.create(types.ObjectInstance);
        call_data.* = .{ .class_name = "SfdoInstrumentationService.LastCallData" };
        try call_data.fields.put(self.arena, "lastFeatureName", try self.instrumentation_arg_name(args[0]));
        try call_data.fields.put(self.arena, "lastComponentName", try self.instrumentation_arg_name(args[1]));
        try call_data.fields.put(self.arena, "lastActionName", try self.instrumentation_arg_name(args[2]));
        if (args.len >= 4 and args[3] == .map) {
            try call_data.fields.put(self.arena, "lastContext", args[3]);
        }
        if (args.len >= 5) {
            try call_data.fields.put(self.arena, "lastValue", args[4]);
        } else if (args.len >= 4 and args[3] == .integer) {
            try call_data.fields.put(self.arena, "lastValue", args[3]);
        }
        self.global_env.set(
            "SfdoInstrumentationService.lastCallData",
            Value{ .object = call_data },
        ) catch try self.global_env.define(
            "SfdoInstrumentationService.lastCallData",
            Value{ .object = call_data },
        );
        return Value.void_val;
    }

    fn instrumentation_arg_name(self: *Evaluator, value: Value) !Value {
        if (value == .string) return value;
        return Value{ .string = try utils.coerce_to_string(value, self.arena) };
    }

    // -----------------------------------------------------------------------
    // 式の評価
    // -----------------------------------------------------------------------

    pub fn eval_expr(self: *Evaluator, expr: *const ast.Expr, current_env: *Env) anyerror!Value {
        self.call_depth +|= 1;
        defer self.call_depth -|= 1;

        if (self.call_depth > self.max_call_depth) {
            // error を返すと error return trace の記録でスタックを消費し
            // OS スタックオーバーフローを引き起こす場合があるため null を返す
            return .null_val;
        }
        return switch (expr.*) {
            .integer_literal => |v| .{ .integer = v },
            .long_literal => |v| .{ .long = v },
            .double_literal => |v| .{ .double = v },
            .string_literal => |v| .{ .string = v },
            .boolean_literal => |v| .{ .boolean = v },
            .null_literal => .null_val,
            .this_expr, .super_expr => current_env.get_this() orelse .null_val,
            .identifier => |id| self.eval_identifier_expr(id, current_env),
            .binary => |bin| self.eval_binary_expr(bin, current_env),
            .unary => |un| self.eval_unary_expr(un, current_env),
            .assignment => |asgn| self.eval_assignment_expr(asgn, current_env),
            .call => |call| self.eval_call_expr(call, current_env),
            .method_call => |mc| self.eval_method_call(mc, current_env),
            .field_access => |fa| self.eval_field_access_expr(fa, current_env),
            .index_access => |ia| self.eval_index_access_expr(ia, current_env),
            .new_expr => |ne| self.eval_new_expr_with_trace(ne, current_env),
            .cast_expr => |ce| self.eval_cast_expr(ce, current_env),
            .ternary => |te| self.eval_ternary_expr(te, current_env),
            .instanceof => |ie| self.eval_instanceof_expr(ie, current_env),
            .soql => |sq| self.execute_soql(sq.raw, current_env),
            .grouped => |inner| self.eval_expr(inner, current_env),
        };
    }

    fn eval_identifier_expr(self: *Evaluator, id: anytype, current_env: *Env) anyerror!Value {
        if (self.eval_identifier_env_or_instance_value(id.name, current_env)) |value| return value;
        if (self.eval_identifier_enum_value(id.name)) |value| return value;
        if (try self.eval_schema_identifier_value(id.name)) |value| return value;
        if (try self.eval_identifier_property_value(id.name, current_env)) |value| return value;
        if (self.eval_identifier_static_value(id.name, current_env)) |value| return value;
        if (self.eval_identifier_inner_type_value(id.name, current_env)) |value| return value;
        return .null_val;
    }

    fn eval_identifier_env_or_instance_value(
        self: *Evaluator,
        id_name: []const u8,
        current_env: *Env,
    ) ?Value {
        if (current_env.get(id_name)) |val| {
            if (val != .null_val) return val;
        }
        if (current_env.get_this()) |this_live| {
            if (this_live == .object) {
                if (utils.sobject_get(&this_live.object.fields, id_name)) |live| {
                    if (live != .null_val) {
                        if (self.find_class(this_live.object.class_name)) |live_cd| {
                            if (self.is_instance_field(live_cd, id_name) or
                                self.is_parent_instance_field(live_cd, id_name))
                            {
                                if (current_env.get_declared_type(id_name) == null) {
                                    return live;
                                }
                            }
                        }
                    }
                }
            }
        }
        return null;
    }

    fn eval_identifier_enum_value(self: *Evaluator, id_name: []const u8) ?Value {
        const dot_idx = std.mem.lastIndexOfScalar(u8, id_name, '.') orelse return null;
        const owner_name = id_name[0..dot_idx];
        const value_name = id_name[dot_idx + 1 ..];
        if (value_name.len == 0) return null;

        if (self.find_visible_enum_decl(owner_name)) |ed| {
            for (ed.values) |value| {
                if (std.ascii.eqlIgnoreCase(value, value_name)) {
                    return Value{ .string = value_name };
                }
            }
        }
        if (std.mem.lastIndexOfScalar(u8, owner_name, '.')) |owner_dot| {
            const outer_name = owner_name[0..owner_dot];
            const enum_name = owner_name[owner_dot + 1 ..];
            if (self.find_class(outer_name)) |outer_cd| {
                if (find_enum_in_class_members(outer_cd, enum_name)) |ed| {
                    for (ed.values) |value| {
                        if (std.ascii.eqlIgnoreCase(value, value_name)) {
                            return Value{ .string = value_name };
                        }
                    }
                }
            }
        }
        return null;
    }

    fn eval_schema_identifier_value(self: *Evaluator, id_name: []const u8) !?Value {
        if (std.mem.startsWith(u8, id_name, "SObjectType.") and
            std.mem.indexOfScalar(u8, id_name["SObjectType.".len..], '.') == null)
        {
            return try self.make_schema_sobject_type_object(id_name["SObjectType.".len..]);
        }
        if (!std.mem.startsWith(u8, id_name, "Schema.")) return null;
        const suffix = id_name["Schema.".len..];
        const dot_idx = std.mem.lastIndexOfScalar(u8, suffix, '.') orelse return null;
        const owner_name = suffix[0..dot_idx];
        const member_name = suffix[dot_idx + 1 ..];
        if (std.ascii.eqlIgnoreCase(owner_name, "SObjectType")) {
            return try self.make_schema_sobject_type_object(member_name);
        }
        if (std.ascii.eqlIgnoreCase(member_name, "SObjectType")) {
            return try self.make_schema_sobject_type_object(owner_name);
        }
        if (!std.ascii.eqlIgnoreCase(member_name, "class")) {
            return try self.make_s_object_field_token(owner_name, member_name);
        }
        return null;
    }

    fn eval_identifier_property_value(
        self: *Evaluator,
        id_name: []const u8,
        current_env: *Env,
    ) anyerror!?Value {
        const this_check = current_env.get_this() orelse return null;
        if (this_check != .object) return null;
        const already_in_instance_getter = if (self.evaluating_getter) |eg|
            std.ascii.eqlIgnoreCase(eg, id_name) and
                self.evaluating_getter_instance == this_check.object
        else
            false;
        const shadowed_by_typed_local = current_env.get_declared_type(id_name) != null;
        if (!already_in_instance_getter and !shadowed_by_typed_local) {
            if (self.find_class(this_check.object.class_name)) |this_cd| {
                var scan_cd: ?*ast.ClassDecl = this_cd;
                while (scan_cd) |scd| {
                    for (scd.members) |m| {
                        switch (m) {
                            .field_decl => |pfd| {
                                if (std.ascii.eqlIgnoreCase(pfd.name, id_name) and
                                    pfd.getter_body != null)
                                {
                                    const this_expr_node = try self.arena.create(ast.Expr);
                                    this_expr_node.* = .this_expr;
                                    const fa_node = try self.arena.create(ast.FieldAccess);
                                    fa_node.* = .{
                                        .object = this_expr_node,
                                        .field = id_name,
                                        .null_safe = false,
                                    };
                                    const fa_expr = try self.arena.create(ast.Expr);
                                    fa_expr.* = .{ .field_access = fa_node };
                                    return try self.eval_expr(fa_expr, current_env);
                                }
                            },
                            else => {},
                        }
                    }
                    scan_cd = if (scd.super_class) |sc| self.find_class(sc.name) else null;
                }
            }
            return null;
        }
        if (!already_in_instance_getter) return null;
        if (self.find_field_decl_with_owner(this_check.object.class_name, id_name)) |lookup| {
            if (lookup.field_decl.modifiers.is_static) {
                return self.read_static_backing_value(lookup.owner_name, id_name);
            }
        }
        if (this_check.object.fields.get(id_name)) |fv| return fv;
        for (this_check.object.fields.keys(), this_check.object.fields.values()) |fk, fv| {
            if (std.ascii.eqlIgnoreCase(fk, id_name)) return fv;
        }
        return .null_val;
    }

    fn eval_identifier_static_value(
        self: *Evaluator,
        id_name: []const u8,
        current_env: *Env,
    ) ?Value {
        if (current_env.get_this()) |this_val| {
            if (this_val == .object) {
                const this_cn = this_val.object.class_name;
                const key =
                    std.fmt.allocPrint(
                        self.arena,
                        "{s}.{s}",
                        .{ this_cn, id_name },
                    ) catch return .null_val;
                if (self.global_env.get(key)) |val| return val;
                if (self.find_class(this_cn)) |cd| {
                    if (cd.super_class) |sc| {
                        self.ensure_static_init(sc.name);
                        const pkey =
                            std.fmt.allocPrint(
                                self.arena,
                                "{s}.{s}",
                                .{ sc.name, id_name },
                            ) catch return .null_val;
                        if (self.global_env.get(pkey)) |val| return val;
                    }
                }
                if (self.resolve_outer_static_field(this_cn, id_name)) |val| return val;
            }
        }
        if (self.current_class) |cc| {
            if (self.resolve_static_field_value_on_class(cc, id_name)) |val| return val;
            if (self.find_class(cc)) |cd| {
                if (cd.super_class) |sc| {
                    if (self.resolve_static_field_value_on_class(sc.name, id_name)) |val| {
                        return val;
                    }
                }
            }
            if (self.resolve_outer_static_field(cc, id_name)) |val| return val;
        }
        return null;
    }

    fn eval_identifier_inner_type_value(
        self: *Evaluator,
        id_name: []const u8,
        current_env: *Env,
    ) ?Value {
        if (current_env.get_declared_type(id_name) != null or current_env.has(id_name)) {
            return null;
        }
        const check_classes = [_]?[]const u8{
            if (current_env.get_this()) |tv|
                (if (tv == .object) tv.object.class_name else null)
            else
                null,
            self.current_class,
        };
        for (check_classes) |cc_opt| {
            var cur_class: ?[]const u8 = cc_opt;
            while (cur_class) |ccn| {
                if (self.find_class(ccn)) |ccd| {
                    for (ccd.members) |member| {
                        switch (member) {
                            .enum_decl => |ed| {
                                if (std.ascii.eqlIgnoreCase(ed.name, id_name)) {
                                    return Value{ .string = id_name };
                                }
                            },
                            .class_decl => |inner_cd| {
                                if (std.ascii.eqlIgnoreCase(inner_cd.name, id_name)) {
                                    return Value{ .string = id_name };
                                }
                            },
                            else => {},
                        }
                    }
                    cur_class = if (ccd.super_class) |sc| sc.name else null;
                } else break;
            }
            if (cc_opt) |ccn| {
                if (self.find_outer_class_name(ccn)) |outer_name| {
                    if (self.find_class(outer_name)) |outer_cd| {
                        for (outer_cd.members) |member| {
                            switch (member) {
                                .enum_decl => |ed| {
                                    if (std.ascii.eqlIgnoreCase(ed.name, id_name)) {
                                        return Value{ .string = id_name };
                                    }
                                },
                                .class_decl => |inner_cd| {
                                    if (std.ascii.eqlIgnoreCase(inner_cd.name, id_name)) {
                                        return Value{ .string = id_name };
                                    }
                                },
                                else => {},
                            }
                        }
                    }
                }
            }
        }
        return null;
    }

    fn eval_binary_expr(self: *Evaluator, bin: anytype, current_env: *Env) anyerror!Value {
        const left = try self.eval_expr(bin.left, current_env);
        switch (bin.op) {
            .and_op => {
                if (!(utils.coerce_to_bool(left) catch false)) {
                    return Value{ .boolean = false };
                }
            },
            .or_op => {
                if (utils.coerce_to_bool(left) catch false) {
                    return Value{ .boolean = true };
                }
            },
            else => {},
        }
        const right = try self.eval_expr(bin.right, current_env);
        return eval_binary(self, left, bin.op, right, self.arena);
    }

    fn eval_unary_expr(self: *Evaluator, un: anytype, current_env: *Env) anyerror!Value {
        const operand = try self.eval_expr(un.operand, current_env);
        return eval_unary(un.op, operand);
    }

    fn eval_assignment_expr(self: *Evaluator, asgn: anytype, current_env: *Env) anyerror!Value {
        const val = try self.eval_expr(asgn.value, current_env);
        if (asgn.is_postfix) {
            const original = self.eval_expr(asgn.target, current_env) catch Value.null_val;
            _ = try self.eval_assignment(asgn, val, current_env);
            return original;
        }
        return self.eval_assignment(asgn, val, current_env);
    }

    fn eval_call_expr(self: *Evaluator, call: anytype, current_env: *Env) anyerror!Value {
        if (call.loc.line > 0) {
            self.current_call_line = call.loc.line;
            if (self.call_stack.items.len > 0)
                self.call_stack.items[self.call_stack.items.len - 1].line = call.loc.line;
        }
        var args: std.ArrayListUnmanaged(Value) = .empty;
        var call_type_hints: std.ArrayListUnmanaged(?[]const u8) = .empty;
        for (call.args) |*arg| {
            var arg_value = try self.eval_expr(arg, current_env);
            arg_value = try self.maybe_coerce_schema_expr_value(arg, arg_value);
            try args.append(self.arena, arg_value);
            try call_type_hints.append(self.arena, self.extract_expr_type_hint(arg, current_env));
        }
        const prev_hints = self.cast_type_hints;
        self.cast_type_hints = call_type_hints.items;
        defer self.cast_type_hints = prev_hints;

        if (try self.eval_constructor_call_expr(call, args.items, current_env)) |result| {
            return result;
        }
        if (try self.eval_this_instance_call_expr(call, args.items, current_env)) |result| {
            return result;
        }
        if (try self.eval_dotted_static_call_expr(call.callee, args.items, current_env)) |result| {
            return result;
        }
        if (try self.eval_static_or_loaded_call_expr(call.callee, args.items)) |result| {
            return result;
        }
        if (current_env.get_this()) |this_val| {
            if (this_val == .object or this_val == .sobject or this_val == .string or
                this_val == .list or this_val == .map or this_val == .set)
            {
                return self.eval_instance_method(this_val, call.callee, args.items, current_env);
            }
        }
        return Value.null_val;
    }

    fn eval_constructor_call_expr(
        self: *Evaluator,
        call: anytype,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (std.mem.eql(u8, call.callee, "super")) {
            if (current_env.get_this()) |this_val| {
                if (this_val == .object) {
                    const ctor_class = if (self.current_constructor_class) |cc|
                        self.find_constructor_class(cc)
                    else
                        self.find_class(this_val.object.class_name);
                    if (ctor_class) |cd| {
                        if (cd.super_class) |sc| {
                            if (self.find_class(sc.name)) |parent_decl| {
                                try self.run_constructor(parent_decl, this_val.object, args);
                            }
                        }
                    }
                }
            }
            return Value.void_val;
        }
        if (!std.mem.eql(u8, call.callee, "this")) return null;
        if (current_env.get_this()) |this_val| {
            if (this_val == .object) {
                const ctor_class_name = if (self.current_constructor_class) |cc|
                    cc
                else
                    this_val.object.class_name;
                if (self.find_constructor_class(ctor_class_name)) |cd| {
                    try self.run_constructor(cd, this_val.object, args);
                }
            }
        }
        return Value.void_val;
    }

    fn find_constructor_class(self: *Evaluator, class_name: []const u8) ?*ast.ClassDecl {
        if (self.find_class(class_name)) |class_decl| return class_decl;
        if (std.mem.lastIndexOfScalar(u8, class_name, '.')) |dot| {
            return self.find_class(class_name[dot + 1 ..]);
        }
        return null;
    }

    fn eval_this_instance_call_expr(
        self: *Evaluator,
        call: anytype,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        const this_val = current_env.get_this() orelse return null;
        if (this_val != .object) return null;
        if (try self.eval_field_expression_matching_method(
            this_val,
            call.callee,
            args,
        )) |result| {
            return result;
        }
        const actual_decl: ?*ast.ClassDecl = self.find_class(this_val.object.class_name);
        const dispatch_decl = blk: {
            if (self.current_class) |current_class_name| {
                if (self.find_class(current_class_name)) |owner_decl| break :blk owner_decl;
            }
            break :blk actual_decl orelse return Value.null_val;
        };
        const md = self.find_method_in_hierarchy(actual_decl, dispatch_decl, call.callee, args.len);
        if (md == null) return null;
        var pre_fields: [16]Value = undefined;
        const field_keys = this_val.object.fields.keys();
        const n_snap = @min(field_keys.len, pre_fields.len);
        for (this_val.object.fields.values()[0..n_snap], 0..) |v, fi| {
            pre_fields[fi] = v;
        }
        const result = try self.call_instance_method(
            dispatch_decl,
            this_val.object,
            call.callee,
            args,
        );
        try self.sync_instance_call_fields(current_env, this_val.object, pre_fields[0..n_snap]);
        return result;
    }

    fn sync_instance_call_fields(
        self: *Evaluator,
        current_env: *Env,
        object: *types.ObjectInstance,
        pre_fields: []const Value,
    ) !void {
        for (object.fields.keys(), object.fields.values(), 0..) |fk, fv, fi| {
            if (current_env.get_declared_type(fk) != null) continue;
            if (fi < pre_fields.len) {
                const pre = pre_fields[fi];
                const changed = switch (fv) {
                    .null_val => pre != .null_val,
                    .string => |s| if (pre == .string)
                        s.ptr != pre.string.ptr or s.len != pre.string.len
                    else
                        true,
                    .integer => |i| if (pre == .integer) i != pre.integer else true,
                    .boolean => |b| if (pre == .boolean) b != pre.boolean else true,
                    else => true,
                };
                if (changed) current_env.set(fk, fv) catch {};
            } else {
                current_env.set(fk, fv) catch {};
            }
        }
        _ = self;
    }

    fn eval_dotted_static_call_expr(
        self: *Evaluator,
        callee: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        const dot_idx = std.mem.lastIndexOfScalar(u8, callee, '.') orelse return null;
        const class_name = callee[0..dot_idx];
        const method_name = callee[dot_idx + 1 ..];
        if (class_name.len == 0 or method_name.len == 0) return null;
        if (std.ascii.eqlIgnoreCase(class_name, "Database")) {
            return try self.handle_database_method(method_name, args, current_env);
        }
        var builtin_ctx = self.make_builtin_context();
        if (try builtins.dispatch_static(&builtin_ctx, class_name, method_name, args)) |result| {
            return result;
        }
        if (try self.eval_identifier_custom_metadata_method(
            class_name,
            method_name,
            args,
        )) |result| {
            return result;
        }
        if (try self.handle_custom_setting_static_method(class_name, method_name, args)) |result| {
            return result;
        }
        if (try self.handle_tdtm_process_control_static_method(
            class_name,
            method_name,
            args,
        )) |result| {
            return result;
        }
        if (self.handle_npsp_allocations_util_static_method(class_name, method_name, args)) |result| {
            return result;
        }
        if (try self.handle_crlp_rollup_svc_static_method(
            class_name,
            method_name,
            args,
        )) |result| {
            return result;
        }
        if (try self.handle_npsp_unit_test_data_static_method(
            class_name,
            method_name,
            args,
        )) |result| {
            return result;
        }
        if (try self.handle_npsp_legacy_household_members_static_method(
            class_name,
            method_name,
            args,
        )) |result| {
            return result;
        }
        if (try self.handle_npsp_contact_adapter_static_method(
            class_name,
            method_name,
            args,
        )) |result| {
            return result;
        }
        if (try self.handle_npsp_household_naming_static_method(
            class_name,
            method_name,
            args,
        )) |result| {
            return result;
        }
        if (try self.handle_npsp_household_container_static_method(
            class_name,
            method_name,
            args,
        )) |result| {
            return result;
        }
        if (try self.handle_npsp_visualize_schedule_static_method(
            class_name,
            method_name,
            args,
        )) |result| {
            return result;
        }
        if (self.find_class(class_name) != null) {
            return try self.call_method(class_name, method_name, args);
        }
        return null;
    }

    fn eval_static_or_loaded_call_expr(
        self: *Evaluator,
        callee: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (self.current_lexical_method_class()) |lexical_class| {
            if (try self.eval_static_call_from_lexical_class(
                lexical_class,
                callee,
                args,
            )) |result| return result;
        }
        if (self.current_class) |cc| {
            if (self.find_class(cc)) |cd| {
                if (self.find_best_method_in_class_filtered(cd, callee, args, true) != null) {
                    return try self.call_method(cc, callee, args);
                }
            }
            if (self.resolve_outer_static_method_owner(cc, callee, args)) |outer_owner| {
                return try self.call_method(outer_owner, callee, args);
            }
        }
        var class_iter = self.classes.iterator();
        while (class_iter.next()) |entry| {
            if (self.find_best_method_in_class_filtered(
                entry.value_ptr.*,
                callee,
                args,
                true,
            ) != null) {
                return try self.call_method(entry.key_ptr.*, callee, args);
            }
        }
        return null;
    }

    fn current_lexical_method_class(self: *Evaluator) ?[]const u8 {
        if (self.call_stack.items.len == 0) return null;
        const frame = self.call_stack.items[self.call_stack.items.len - 1];
        return frame.class_name;
    }

    fn eval_static_call_from_lexical_class(
        self: *Evaluator,
        class_name: []const u8,
        callee: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (self.find_class(class_name)) |cd| {
            if (self.find_best_method_in_class_filtered(cd, callee, args, true) != null) {
                return try self.call_method(class_name, callee, args);
            }
        }
        if (self.resolve_outer_static_method_owner(class_name, callee, args)) |outer_owner| {
            return try self.call_method(outer_owner, callee, args);
        }
        return null;
    }

    fn eval_field_access_expr(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        current_env: *Env,
    ) anyerror!Value {
        if (try self.eval_namespaced_label_field_access(fa)) |value| return value;
        if (self.field_access_enum_value(fa)) |enum_value| return Value{ .string = enum_value };
        if (try self.eval_schema_field_access_expr(fa)) |value| return value;
        if (try self.eval_nested_static_field_access_expr(fa)) |value| return value;
        if (try self.eval_null_safe_field_access_expr(fa, current_env)) |value| return value;
        const obj = try self.eval_expr(fa.object, current_env);
        return try self.eval_field_access(fa, obj, current_env);
    }

    fn eval_namespaced_label_field_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
    ) !?Value {
        const object_path = self.collect_dotted_identifier_chain(fa.object) orelse return null;
        const is_namespaced_label =
            std.ascii.eqlIgnoreCase(object_path, "System.Label") or
            std.ascii.eqlIgnoreCase(object_path, "Label") or
            std.ascii.startsWithIgnoreCase(object_path, "System.Label.") or
            std.ascii.startsWithIgnoreCase(object_path, "Label.");
        if (!is_namespaced_label) return null;
        if (self.get_custom_label_case_insensitive(fa.field)) |label_value| {
            return Value{ .string = label_value };
        }
        return Value{ .string = try self.arena.dupe(u8, fa.field) };
    }

    fn eval_schema_field_access_expr(self: *Evaluator, fa: *ast.FieldAccess) !?Value {
        if (!(fa.object.* == .identifier and
            std.mem.startsWith(u8, fa.object.identifier.name, "Schema.")))
        {
            return null;
        }
        const schema_name = fa.object.identifier.name["Schema.".len..];
        if (is_known_schema_enum_type(schema_name)) {
            return Value{ .string = fa.field };
        }
        if (std.ascii.eqlIgnoreCase(schema_name, "SObjectType")) {
            return try self.make_schema_sobject_type_object(fa.field);
        }
        if (is_s_object_type_member(fa.field)) {
            return try self.make_schema_sobject_type_object(schema_name);
        }
        if (self.is_s_object_type_name(schema_name) and
            !std.ascii.eqlIgnoreCase(fa.field, "class"))
        {
            return try self.make_s_object_field_token(schema_name, fa.field);
        }
        return null;
    }

    fn eval_nested_static_field_access_expr(self: *Evaluator, fa: *ast.FieldAccess) !?Value {
        if (fa.object.* != .field_access) return null;
        const inner_fa = fa.object.field_access;
        if (inner_fa.object.* != .identifier) return null;
        const outer_name = inner_fa.object.identifier.name;
        const inner_name = inner_fa.field;
        self.ensure_static_init(outer_name);
        const inner_fq = try std.fmt.allocPrint(self.arena, "{s}.{s}", .{ outer_name, inner_name });
        self.ensure_static_init(inner_fq);
        const fq_key = try std.fmt.allocPrint(
            self.arena,
            "{s}.{s}.{s}",
            .{ outer_name, inner_name, fa.field },
        );
        if (self.global_env.get(fq_key)) |v| return v;
        if (self.find_class(outer_name)) |cd| {
            for (cd.members) |member| {
                switch (member) {
                    .enum_decl => |ed| {
                        if (std.ascii.eqlIgnoreCase(ed.name, inner_name)) {
                            return Value{ .string = fa.field };
                        }
                    },
                    else => {},
                }
            }
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "System") and
            (std.ascii.eqlIgnoreCase(inner_name, "AccessType") or
                std.ascii.eqlIgnoreCase(inner_name, "AccessLevel") or
                std.ascii.eqlIgnoreCase(inner_name, "LoggingLevel") or
                std.ascii.eqlIgnoreCase(inner_name, "TriggerOperation")))
        {
            return Value{ .string = fa.field };
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Metadata") and
            is_known_metadata_enum_type(inner_name))
        {
            return Value{ .string = fa.field };
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema") and
            is_known_schema_enum_type(inner_name))
        {
            return Value{ .string = fa.field };
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema") and
            !std.ascii.eqlIgnoreCase(inner_name, "sObjectType") and
            !std.ascii.eqlIgnoreCase(inner_name, "SObjectType") and
            self.is_s_object_type_name(inner_name))
        {
            if (is_s_object_type_member(fa.field)) {
                return try self.make_schema_sobject_type_object(inner_name);
            }
            if (!std.ascii.eqlIgnoreCase(fa.field, "class")) {
                return try self.make_s_object_field_token(inner_name, fa.field);
            }
        }
        return null;
    }

    fn eval_null_safe_field_access_expr(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        current_env: *Env,
    ) anyerror!?Value {
        if (!fa.null_safe) return null;
        const obj = self.eval_expr(fa.object, current_env) catch |err| {
            if (err == error.ApexException and self.pending_exception != null) {
                if (self.pending_exception.? == .object) {
                    const cn = self.pending_exception.?.object.class_name;
                    if (std.ascii.indexOfIgnoreCase(cn, "NullPointer") != null) {
                        self.pending_exception = null;
                        return Value.null_val;
                    }
                }
            }
            return err;
        };
        if (obj == .null_val) return Value.null_val;
        return try self.eval_field_access(fa, obj, current_env);
    }

    fn eval_index_access_expr(
        self: *Evaluator,
        ia: *ast.IndexAccess,
        current_env: *Env,
    ) anyerror!Value {
        const obj = try self.eval_expr(ia.object, current_env);
        const idx = try self.eval_expr(ia.index, current_env);
        if (obj == .list and idx == .integer) {
            if (idx.integer >= 0) {
                const i: usize = @intCast(idx.integer);
                if (i < obj.list.items.items.len) return obj.list.items.items[i];
            }
            if (self.fixture_relaxed_exceptions) return Value.null_val;
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "ListException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = try std.fmt.allocPrint(
                    self.arena,
                    "List index out of bounds: {d}",
                    .{idx.integer},
                ) },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        if (obj == .map and idx == .string) {
            return obj.map.entries.get(idx.string) orelse Value.null_val;
        }
        return Value.null_val;
    }

    fn eval_new_expr_with_trace(
        self: *Evaluator,
        ne: *ast.NewExpr,
        current_env: *Env,
    ) anyerror!Value {
        if (ne.loc.line > 0) {
            self.current_call_line = ne.loc.line;
            if (self.call_stack.items.len > 0)
                self.call_stack.items[self.call_stack.items.len - 1].line = ne.loc.line;
        }
        const val = try self.eval_new_expr(ne, current_env);
        if (val == .object and std.mem.endsWith(u8, val.object.class_name, "Exception")) {
            if (val.object.fields.get("stackTraceString") == null) {
                const line = if (ne.loc.line > 0) ne.loc.line else 1;
                const trace = try self.build_stack_trace_string();
                try val.object.fields.put(self.arena, "stackTraceString", Value{ .string = trace });
                try val.object.fields.put(
                    self.arena,
                    "lineNumber",
                    Value{ .integer = @intCast(line) },
                );
            }
        }
        return val;
    }

    fn eval_cast_expr(self: *Evaluator, ce: anytype, current_env: *Env) anyerror!Value {
        const val = try self.eval_expr(ce.operand, current_env);
        const target = ce.target_type.name;
        if (try self.eval_sobject_list_cast_expr(val, target)) |casted| return casted;
        if (try self.eval_collection_cast_expr(val, ce.target_type)) |casted| return casted;
        if (val != .object) return val;
        return self.eval_object_cast_expr(val, target);
    }

    fn eval_collection_cast_expr(
        self: *Evaluator,
        val: Value,
        target_type: types.TypeRef,
    ) anyerror!?Value {
        if (val == .null_val) return val;
        const target_base = type_base_name(target_type.name);
        const is_set = std.ascii.eqlIgnoreCase(target_base, "Set");
        const is_list = std.ascii.eqlIgnoreCase(target_base, "List");
        const is_map = std.ascii.eqlIgnoreCase(target_base, "Map");
        const is_iterable = std.ascii.eqlIgnoreCase(target_base, "Iterable");
        if (!is_set and !is_list and !is_map and !is_iterable) return null;
        if (is_list and val == .list) {
            if (try self.eval_list_id_cast_expr(val.list, target_type)) |casted| return casted;
        }

        const matches = switch (val) {
            .set => |set| (self.eval_set_instanceof_expr(set, target_type)).boolean,
            .list => |list| (self.eval_list_instanceof_expr(list, target_type)).boolean,
            .map => is_map,
            else => false,
        };
        if (matches) return val;
        return try self.raise_type_exception(
            test_helper_value_type_name(val),
            self.render_type_ref(target_type),
        );
    }

    fn eval_list_id_cast_expr(
        self: *Evaluator,
        list: *types.ListValue,
        target_type: types.TypeRef,
    ) anyerror!?Value {
        if (target_type.params.len == 0) return null;
        const elem_type = strip_type_namespace(target_type.params[0].name);
        if (!std.ascii.eqlIgnoreCase(elem_type, "Id")) return null;
        for (list.items.items) |item| {
            if (item == .null_val) continue;
            if (item != .string or !Evaluator.is_salesforce_id_string(item.string)) {
                return try self.throw_named_exception("System.StringException", "Invalid id");
            }
        }
        list.element_type = "Id";
        return Value{ .list = list };
    }

    fn eval_sobject_list_cast_expr(
        self: *Evaluator,
        val: Value,
        target: []const u8,
    ) !?Value {
        if (val != .list or !self.is_s_object_type_name(target)) return null;
        if (val.list.items.items.len != 1) return null;
        const item = val.list.items.items[0];
        if (item != .sobject) return null;
        if (std.ascii.eqlIgnoreCase(target, "SObject") or
            std.ascii.eqlIgnoreCase(item.sobject.type_name, target))
        {
            return item;
        }
        return null;
    }

    fn raise_type_exception(
        self: *Evaluator,
        src_name: []const u8,
        target: []const u8,
    ) anyerror!Value {
        const msg = try std.fmt.allocPrint(
            self.arena,
            "Invalid conversion from runtime type {s} to {s}",
            .{ src_name, target },
        );
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.TypeException" };
        try exc.fields.put(self.arena, "message", Value{ .string = msg });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn eval_ternary_expr(self: *Evaluator, te: anytype, current_env: *Env) anyerror!Value {
        const cond = try self.eval_expr(te.condition, current_env);
        if (utils.coerce_to_bool(cond) catch false) {
            return self.eval_expr(te.then_expr, current_env);
        }
        return self.eval_expr(te.else_expr, current_env);
    }

    fn eval_object_cast_expr(self: *Evaluator, val: Value, target: []const u8) anyerror!Value {
        const src_name = val.object.class_name;
        const target_base = if (std.mem.lastIndexOfScalar(u8, target, '.')) |dot|
            target[dot + 1 ..]
        else
            target;
        if (try self.eval_temporal_object_cast(val, src_name, target)) |result| return result;
        if (std.ascii.eqlIgnoreCase(src_name, target) or
            std.ascii.eqlIgnoreCase(src_name, target_base))
        {
            return val;
        }
        if (self.is_compatible_object_cast(src_name, target)) return val;
        if (self.is_known_interface_name(target)) {
            return self.raise_type_exception(src_name, target);
        }
        if (self.find_class(target)) |tgt_cd| {
            if (tgt_cd.modifiers.is_abstract and self.find_class(src_name) != null) {
                return self.raise_type_exception(src_name, target);
            }
        }
        return val;
    }

    fn eval_temporal_object_cast(
        self: *Evaluator,
        val: Value,
        src_name: []const u8,
        target: []const u8,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(target, "DateTime") and
            !std.ascii.eqlIgnoreCase(target, "Date") and
            !std.ascii.eqlIgnoreCase(target, "Time"))
        {
            return null;
        }
        if (std.ascii.eqlIgnoreCase(src_name, "Date") and
            std.ascii.eqlIgnoreCase(target, "DateTime"))
        {
            if (val.object.fields.get("value")) |v| {
                if (v == .string) {
                    const dt_str = try std.fmt.allocPrint(self.arena, "{s}T00:00:00Z", .{v.string});
                    return try builtins.make_datetime_value(self.arena, dt_str);
                }
            }
            return val;
        }
        if (!std.ascii.eqlIgnoreCase(src_name, target)) {
            const normalized_target = if (std.ascii.eqlIgnoreCase(target, "DateTime"))
                "Datetime"
            else if (std.ascii.eqlIgnoreCase(target, "Date"))
                "Date"
            else if (std.ascii.eqlIgnoreCase(target, "Time"))
                "Time"
            else
                target;
            return try self.raise_type_exception(src_name, normalized_target);
        }
        return val;
    }

    fn is_compatible_object_cast(self: *Evaluator, src_name: []const u8, target: []const u8) bool {
        return self.object_cast_matches_source_hierarchy(src_name, target) or
            self.object_cast_matches_target_hierarchy(src_name, target);
    }

    fn object_cast_matches_source_hierarchy(
        self: *Evaluator,
        src_name: []const u8,
        target: []const u8,
    ) bool {
        const src_cd = self.find_class(src_name) orelse return false;
        var cur: ?*ast.ClassDecl = src_cd;
        while (cur) |cd| {
            if (std.ascii.eqlIgnoreCase(cd.name, target)) return true;
            for (cd.interfaces) |iface| {
                if (std.ascii.eqlIgnoreCase(iface.name, target)) return true;
                if (std.mem.lastIndexOfScalar(u8, target, '.')) |di| {
                    if (std.ascii.eqlIgnoreCase(iface.name, target[di + 1 ..])) return true;
                }
                if (std.mem.lastIndexOfScalar(u8, iface.name, '.')) |di| {
                    if (std.ascii.eqlIgnoreCase(iface.name[di + 1 ..], target)) return true;
                }
            }
            if (cd.super_class) |sc| {
                if (std.ascii.eqlIgnoreCase(sc.name, target)) return true;
                cur = self.find_class(sc.name);
            } else break;
        }
        return false;
    }

    fn object_cast_matches_target_hierarchy(
        self: *Evaluator,
        src_name: []const u8,
        target: []const u8,
    ) bool {
        const tgt_cd = self.find_class(target) orelse return false;
        var cur: ?*ast.ClassDecl = tgt_cd;
        while (cur) |cd| {
            if (std.ascii.eqlIgnoreCase(cd.name, src_name)) return true;
            if (cd.super_class) |sc| {
                if (std.ascii.eqlIgnoreCase(sc.name, src_name)) return true;
                cur = self.find_class(sc.name);
            } else break;
        }
        return false;
    }

    fn eval_instanceof_expr(self: *Evaluator, ie: anytype, current_env: *Env) anyerror!Value {
        const val = try self.eval_expr(ie.operand, current_env);
        if (instanceof_matches_primitive(val, ie.type_name.name)) {
            return Value{ .boolean = true };
        }
        if (val == .sobject) {
            if (std.ascii.eqlIgnoreCase(ie.type_name.name, "SObject") or
                std.ascii.eqlIgnoreCase(ie.type_name.name, "Sobject") or
                std.ascii.eqlIgnoreCase(ie.type_name.name, "sObject"))
            {
                return Value{ .boolean = true };
            }
            return Value{
                .boolean = std.ascii.eqlIgnoreCase(val.sobject.type_name, ie.type_name.name),
            };
        }
        if (val == .object) {
            return self.eval_object_instanceof_expr(val.object.class_name, ie.type_name.name);
        }
        if (val == .list) return self.eval_list_instanceof_expr(val.list, ie.type_name);
        if (val == .map) {
            return Value{ .boolean = std.ascii.eqlIgnoreCase(ie.type_name.name, "Map") };
        }
        if (val == .set) {
            return self.eval_set_instanceof_expr(val.set, ie.type_name);
        }
        if (val == .string) {
            if (std.ascii.eqlIgnoreCase(ie.type_name.name, "String")) {
                return Value{ .boolean = true };
            }
            if (std.ascii.eqlIgnoreCase(ie.type_name.name, "Id")) {
                return Value{ .boolean = is_salesforce_id_string(val.string) };
            }
            return Value{ .boolean = false };
        }
        if (val == .integer or val == .long or val == .double) {
            return Value{ .boolean = instanceof_matches_primitive(val, ie.type_name.name) };
        }
        if (val == .boolean) {
            return Value{ .boolean = std.ascii.eqlIgnoreCase(ie.type_name.name, "Boolean") };
        }
        return Value{ .boolean = false };
    }

    fn eval_object_instanceof_expr(
        self: *Evaluator,
        class_name: []const u8,
        type_name: []const u8,
    ) Value {
        if (std.ascii.eqlIgnoreCase(class_name, type_name)) return Value{ .boolean = true };
        if (std.mem.lastIndexOfScalar(u8, type_name, '.')) |dot_pos| {
            if (std.ascii.eqlIgnoreCase(class_name, type_name[dot_pos + 1 ..])) {
                return Value{ .boolean = true };
            }
        }
        if (std.mem.lastIndexOfScalar(u8, class_name, '.')) |dot_pos| {
            if (std.ascii.eqlIgnoreCase(class_name[dot_pos + 1 ..], type_name)) {
                return Value{ .boolean = true };
            }
        }
        if (self.find_class(class_name)) |cd| {
            var cur: ?*ast.ClassDecl = cd;
            while (cur) |ccd| {
                for (ccd.interfaces) |iface| {
                    if (std.ascii.eqlIgnoreCase(iface.name, type_name)) {
                        return Value{ .boolean = true };
                    }
                    if (std.mem.lastIndexOfScalar(u8, type_name, '.')) |dot_pos| {
                        if (std.ascii.eqlIgnoreCase(iface.name, type_name[dot_pos + 1 ..])) {
                            return Value{ .boolean = true };
                        }
                    }
                    if (std.mem.lastIndexOfScalar(u8, iface.name, '.')) |dot_pos| {
                        if (std.ascii.eqlIgnoreCase(iface.name[dot_pos + 1 ..], type_name)) {
                            return Value{ .boolean = true };
                        }
                    }
                }
                if (ccd.super_class) |sc| {
                    if (std.ascii.eqlIgnoreCase(sc.name, type_name)) {
                        return Value{ .boolean = true };
                    }
                    cur = self.find_constructor_class(sc.name);
                } else break;
            }
        }
        if (std.mem.endsWith(u8, type_name, "Exception") and
            std.mem.endsWith(u8, class_name, "Exception"))
        {
            return Value{ .boolean = true };
        }
        return Value{ .boolean = false };
    }

    fn eval_list_instanceof_expr(
        self: *Evaluator,
        list: *types.ListValue,
        type_ref: types.TypeRef,
    ) Value {
        const tn = type_ref.name;
        const tn_base = blk: {
            if (std.mem.lastIndexOfScalar(u8, tn, '.')) |di| break :blk tn[di + 1 ..];
            break :blk tn;
        };
        const is_list_match = std.ascii.eqlIgnoreCase(tn, "List");
        const is_iter_match = std.ascii.eqlIgnoreCase(tn_base, "Iterable");
        if (!is_list_match and !is_iter_match) return Value{ .boolean = false };
        if (type_ref.params.len == 0) return Value{ .boolean = true };
        const elem_type = strip_type_namespace(type_ref.params[0].name);
        if (std.ascii.eqlIgnoreCase(elem_type, "Object")) return Value{ .boolean = true };
        if (elem_type.len > 0 and elem_type.len <= 128) {
            for (list.items.items) |item| {
                if (item == .null_val) continue;
                if (instanceof_matches_primitive(item, elem_type)) return Value{ .boolean = true };
                if (item == .sobject) {
                    if (std.ascii.eqlIgnoreCase(elem_type, "SObject") or
                        std.ascii.eqlIgnoreCase(item.sobject.type_name, elem_type))
                    {
                        return Value{ .boolean = true };
                    }
                    return Value{ .boolean = false };
                }
                if (item == .object and self.is_subclass_of(item.object.class_name, elem_type)) {
                    return Value{ .boolean = true };
                }
                return Value{ .boolean = false };
            }
        }
        return Value{ .boolean = true };
    }

    fn eval_set_instanceof_expr(
        self: *Evaluator,
        set: *types.SetValue,
        type_ref: types.TypeRef,
    ) Value {
        const tn = type_ref.name;
        const tn_base = if (std.mem.lastIndexOfScalar(u8, tn, '.')) |di| tn[di + 1 ..] else tn;
        const is_set_match = std.ascii.eqlIgnoreCase(tn, "Set");
        const is_iter_match = std.ascii.eqlIgnoreCase(tn_base, "Iterable");
        if (!is_set_match and !is_iter_match) return Value{ .boolean = false };
        if (type_ref.params.len == 0) return Value{ .boolean = true };
        const actual = set.element_type orelse return Value{ .boolean = true };
        const expected = strip_type_namespace(type_ref.params[0].name);
        if (is_iter_match and std.ascii.eqlIgnoreCase(expected, "Object")) {
            return Value{ .boolean = true };
        }
        if (std.ascii.eqlIgnoreCase(expected, "SObject") and self.is_s_object_type_name(actual)) {
            return Value{ .boolean = true };
        }
        return Value{ .boolean = std.ascii.eqlIgnoreCase(actual, expected) };
    }

    fn is_collection_type_name(type_name: []const u8) bool {
        const base = type_base_name(strip_type_namespace(type_name));
        return std.ascii.eqlIgnoreCase(base, "List") or
            std.ascii.eqlIgnoreCase(base, "Set") or
            std.ascii.eqlIgnoreCase(base, "Iterable") or
            std.ascii.eqlIgnoreCase(base, "Map");
    }

    fn strip_type_namespace(type_name: []const u8) []const u8 {
        if (std.ascii.startsWithIgnoreCase(type_name, "System.")) return type_name["System.".len..];
        if (std.ascii.startsWithIgnoreCase(type_name, "Schema.")) return type_name["Schema.".len..];
        return type_name;
    }

    fn extract_collection_element_type_name(type_name: []const u8) ?[]const u8 {
        const stripped = strip_type_namespace(type_name);
        if (std.ascii.startsWithIgnoreCase(stripped, "List<") or
            std.ascii.startsWithIgnoreCase(stripped, "Set<") or
            std.ascii.startsWithIgnoreCase(stripped, "Iterable<"))
        {
            const lt = std.mem.indexOfScalar(u8, stripped, '<') orelse return null;
            const gt = std.mem.lastIndexOfScalar(u8, stripped, '>') orelse return null;
            if (gt <= lt + 1) return null;
            return std.mem.trim(u8, stripped[lt + 1 .. gt], " \t");
        }
        if (std.mem.endsWith(u8, stripped, "[]")) return stripped[0 .. stripped.len - 2];
        return null;
    }

    fn extract_map_type_args(type_name: []const u8) ?struct { key: []const u8, value: []const u8 } {
        const stripped = strip_type_namespace(type_name);
        if (!std.ascii.startsWithIgnoreCase(stripped, "Map<")) return null;
        const lt = std.mem.indexOfScalar(u8, stripped, '<') orelse return null;
        const gt = std.mem.lastIndexOfScalar(u8, stripped, '>') orelse return null;
        if (gt <= lt + 1) return null;

        const inner = stripped[lt + 1 .. gt];
        var depth: usize = 0;
        for (inner, 0..) |ch, idx| {
            switch (ch) {
                '<' => depth += 1,
                '>' => {
                    if (depth > 0) depth -= 1;
                },
                ',' => if (depth == 0) {
                    return .{
                        .key = std.mem.trim(u8, inner[0..idx], " \t"),
                        .value = std.mem.trim(u8, inner[idx + 1 ..], " \t"),
                    };
                },
                else => {},
            }
        }
        return null;
    }

    fn annotate_declared_collection_type(
        self: *Evaluator,
        value: Value,
        declared_type: ?[]const u8,
    ) Value {
        if (declared_type) |type_name| {
            if (value == .list) {
                if (value.list.element_type == null) {
                    if (extract_collection_element_type_name(type_name)) |elem_type| {
                        value.list.element_type = strip_type_namespace(elem_type);
                    }
                }
            }
        }
        _ = self;
        return value;
    }

    fn names_match_by_simple_name(left: []const u8, right: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(left, right)) return true;
        const left_simple = if (std.mem.lastIndexOfScalar(u8, left, '.')) |idx|
            left[idx + 1 ..]
        else
            left;
        const right_simple = if (std.mem.lastIndexOfScalar(u8, right, '.')) |idx|
            right[idx + 1 ..]
        else
            right;
        return std.ascii.eqlIgnoreCase(left_simple, right_simple);
    }

    fn infer_list_element_type(
        self: *Evaluator,
        list: *types.ListValue,
        arg_hint: ?[]const u8,
    ) ?[]const u8 {
        _ = self;
        if (list.element_type) |element_type| return strip_type_namespace(element_type);
        if (arg_hint) |hint| {
            if (extract_collection_element_type_name(hint)) |element_type| {
                return strip_type_namespace(element_type);
            }
        }
        if (list.items.items.len == 0) return null;

        return switch (list.items.items[0]) {
            .sobject => |sob| strip_type_namespace(sob.type_name),
            .object => |obj| strip_type_namespace(obj.class_name),
            .string => |s| if (Evaluator.is_salesforce_id_string(s)) "Id" else null,
            else => null,
        };
    }

    fn score_list_argument_for_param(
        self: *Evaluator,
        list: *types.ListValue,
        arg_hint: ?[]const u8,
        param_type: types.TypeRef,
    ) i32 {
        const param_base = type_base_name(param_type.name);
        if (!std.ascii.eqlIgnoreCase(param_base, "List") and
            !std.ascii.eqlIgnoreCase(param_base, "Iterable"))
        {
            return overload_score_for_arg(Value{ .list = list }, param_type.name);
        }
        if (param_type.params.len == 0) return 2;

        const param_elem_type = strip_type_namespace(self.render_type_ref(param_type.params[0]));
        const param_elem_base = type_base_name(param_elem_type);
        const actual_elem_type = self.infer_list_element_type(list, arg_hint);
        const actual_items_are_sobjects = blk: {
            if (list.items.items.len == 0) break :blk false;
            break :blk list.items.items[0] == .sobject;
        };
        if (actual_elem_type == null) return 2;

        const actual_elem_base = type_base_name(actual_elem_type.?);
        if (std.ascii.eqlIgnoreCase(param_elem_base, "SObject")) {
            if (actual_items_are_sobjects or
                std.ascii.eqlIgnoreCase(actual_elem_base, "SObject") or
                self.is_s_object_type_name(actual_elem_base))
            {
                return 3;
            }
            return 0;
        }
        if (names_match_by_simple_name(actual_elem_base, param_elem_base)) return 3;
        if (self.is_s_object_type_name(actual_elem_base) and
            self.is_s_object_type_name(param_elem_base) and
            self.is_subclass_of(actual_elem_base, param_elem_base))
        {
            return 2;
        }
        return 0;
    }

    fn type_base_name(type_name: []const u8) []const u8 {
        const stripped = strip_type_namespace(type_name);
        if (std.mem.indexOfScalar(u8, stripped, '<')) |lt| return stripped[0..lt];
        return stripped;
    }

    fn find_declared_field_type(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) ?[]const u8 {
        if (self.find_class(class_name)) |cd| {
            var cur: ?*ast.ClassDecl = cd;
            while (cur) |ccd| {
                for (ccd.members) |member| {
                    switch (member) {
                        .field_decl => |fd| {
                            if (std.ascii.eqlIgnoreCase(fd.name, field_name)) {
                                return self.render_type_ref(fd.type_ref);
                            }
                        },
                        else => {},
                    }
                }
                cur = if (ccd.super_class) |sc| self.find_class(sc.name) else null;
            }
        }
        return null;
    }

    fn resolve_assignment_target_type(
        self: *Evaluator,
        target: *const ast.Expr,
        current_env: *Env,
    ) ?[]const u8 {
        switch (target.*) {
            .identifier => |id| {
                if (current_env.get_declared_type(id.name)) |type_name| return type_name;
                if (current_env.get_this()) |this_val| {
                    if (this_val == .object) {
                        if (self.find_declared_field_type(
                            this_val.object.class_name,
                            id.name,
                        )) |type_name| {
                            return type_name;
                        }
                    }
                }
                if (self.current_class) |cc| {
                    if (self.find_declared_field_type(cc, id.name)) |type_name| return type_name;
                    if (self.find_outer_class_name(cc)) |outer| {
                        if (self.find_declared_field_type(outer, id.name)) |type_name| {
                            return type_name;
                        }
                    }
                }
                return null;
            },
            .field_access => |fa| return self.resolve_field_access_assignment_target_type(
                fa,
                current_env,
            ),
            else => return null,
        }
    }

    fn resolve_field_access_assignment_target_type(
        self: *Evaluator,
        fa: *const ast.FieldAccess,
        current_env: *Env,
    ) ?[]const u8 {
        if (fa.object.* == .this_expr) {
            if (current_env.get_this()) |this_val| {
                if (this_val == .object) {
                    return self.find_declared_field_type(
                        this_val.object.class_name,
                        fa.field,
                    );
                }
            }
            return null;
        }
        if (fa.object.* == .identifier) {
            const owner_name = fa.object.identifier.name;
            if (current_env.get_declared_type(owner_name)) |owner_type| {
                if (self.find_declared_field_type(
                    type_base_name(owner_type),
                    fa.field,
                )) |type_name| {
                    return type_name;
                }
                if (self.resolve_sobject_field_access_type(owner_type, fa.field)) |type_name| {
                    return type_name;
                }
            }
            const is_class = self.find_class(owner_name) != null;
            const is_var = current_env.get(owner_name) != null;
            if (is_class and !is_var) {
                if (self.find_declared_field_type(owner_name, fa.field)) |type_name| {
                    return type_name;
                }
            }
        }
        if (self.resolve_assignment_target_type(fa.object, current_env)) |owner_type| {
            if (self.find_declared_field_type(
                type_base_name(owner_type),
                fa.field,
            )) |type_name| {
                return type_name;
            }
            if (self.resolve_sobject_field_access_type(owner_type, fa.field)) |type_name| {
                return type_name;
            }
        }
        return null;
    }

    fn resolve_sobject_field_access_type(
        self: *Evaluator,
        owner_type: []const u8,
        field_name: []const u8,
    ) ?[]const u8 {
        const owner_base = type_base_name(strip_type_namespace(owner_type));
        if (!self.is_s_object_type_name(owner_base)) return null;
        if (std.ascii.eqlIgnoreCase(field_name, "Id")) return "Id";
        if (is_standard_lookup_id_field_name(field_name)) return "Id";
        if (self.get_field_metadata(owner_base, field_name)) |metadata| {
            if (metadata.reference_to != null) return "Id";
            if (metadata.field_type) |field_type| {
                if (is_lookup_metadata_field_type(field_type)) return "Id";
            }
        }
        if (self.get_field_type_metadata(owner_base, field_name)) |field_type| {
            if (is_lookup_metadata_field_type(field_type)) return "Id";
        }
        return null;
    }

    fn get_field_type_metadata(
        self: *Evaluator,
        type_name: []const u8,
        field_name: []const u8,
    ) ?[]const u8 {
        const type_map = self.field_types.get(type_name) orelse return null;
        if (type_map.get(field_name)) |field_type| return field_type;
        var iter = type_map.iterator();
        while (iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, field_name)) return entry.value_ptr.*;
        }
        return null;
    }

    fn is_lookup_metadata_field_type(field_type: []const u8) bool {
        return std.ascii.eqlIgnoreCase(field_type, "Lookup") or
            std.ascii.eqlIgnoreCase(field_type, "MasterDetail") or
            std.ascii.eqlIgnoreCase(field_type, "Reference");
    }

    fn is_standard_lookup_id_field_name(field_name: []const u8) bool {
        const known = [_][]const u8{
            "AccountId",
            "ContactId",
            "OpportunityId",
            "CaseId",
            "LeadId",
            "CampaignId",
            "Pricebook2Id",
            "PricebookEntryId",
            "Product2Id",
            "QuoteId",
            "OwnerId",
            "CreatedById",
            "LastModifiedById",
            "RecordTypeId",
            "ProfileId",
            "UserRoleId",
            "UserLicenseId",
            "ManagerId",
            "ReportsToId",
            "ParentId",
            "WhoId",
            "WhatId",
        };
        inline for (known) |known_name| {
            if (std.ascii.eqlIgnoreCase(field_name, known_name)) return true;
        }
        return false;
    }

    fn extract_expr_type_hint(
        self: *Evaluator,
        expr: *const ast.Expr,
        current_env: *Env,
    ) ?[]const u8 {
        switch (expr.*) {
            .cast_expr => |ce| return self.render_type_ref(ce.target_type),
            .new_expr => |ne| {
                // Only surface container-shape hints (Set<X>, List<X>, Map<K,V>) so that
                // generic-element overloads can disambiguate. For user types we rely on
                // the regular subclass-scoring pass in the ranker.
                const rendered = self.render_type_ref(ne.type_name);
                if (std.mem.indexOfScalar(u8, rendered, '<') != null) return rendered;
                return null;
            },
            .ternary => |te| {
                // `cond ? then : else` — if both branches have a compatible hint
                // (typically enum expressions like `flag ? MyEnum.A : MyEnum.B`),
                // surface it so overload resolution can prefer the enum-typed
                // parameter. If either branch lacks a hint or they disagree,
                // fall back to null so the regular Value-based scoring runs.
                const then_hint = self.extract_expr_type_hint(te.then_expr, current_env) orelse
                    self.enum_access_type_name(te.then_expr) orelse null;
                const else_hint = self.extract_expr_type_hint(te.else_expr, current_env) orelse
                    self.enum_access_type_name(te.else_expr) orelse null;
                if (then_hint != null and else_hint != null and
                    std.ascii.eqlIgnoreCase(then_hint.?, else_hint.?))
                {
                    return then_hint;
                }
                if (then_hint != null) return then_hint;
                if (else_hint != null) return else_hint;
                return null;
            },
            .identifier, .field_access => {
                if (self.resolve_assignment_target_type(expr, current_env)) |type_name| {
                    return strip_type_namespace(type_name);
                }
                // Fall back to enum detection for bare `MyEnum.VALUE` forms.
                return self.enum_access_type_name(expr);
            },
            .method_call => |mc| return self.method_call_return_type_hint(mc, current_env),
            else => return null,
        }
    }

    /// `extract_expr_type_hint` から抽出。メソッド呼び出し式の **戻り値型** を
    /// 推論する。`Foo.bar()` / `foo.bar()` / `Foo.Bar.baz()` の三形のみ扱う。
    fn method_call_return_type_hint(
        self: *Evaluator,
        mc: anytype,
        current_env: *Env,
    ) ?[]const u8 {
        const arg_count = mc.args.len;

        if (mc.object.* == .identifier) {
            const target_name = mc.object.identifier.name;
            if (self.find_class(target_name)) |class_decl| {
                if (self.find_method_in_hierarchy(
                    null,
                    class_decl,
                    mc.method,
                    arg_count,
                )) |method_decl| {
                    return strip_type_namespace(self.render_type_ref(method_decl.return_type));
                }
            }
            if (self.resolve_assignment_target_type(mc.object, current_env)) |instance_type| {
                const base_type = type_base_name(instance_type);
                if (self.find_class(base_type)) |class_decl| {
                    if (self.find_method_in_hierarchy(
                        null,
                        class_decl,
                        mc.method,
                        arg_count,
                    )) |method_decl| {
                        return strip_type_namespace(self.render_type_ref(method_decl.return_type));
                    }
                }
            }
        }

        if (mc.object.* == .field_access) {
            const fa = mc.object.field_access;
            if (fa.object.* == .identifier) {
                const qualified_name = std.fmt.allocPrint(
                    self.arena,
                    "{s}.{s}",
                    .{ fa.object.identifier.name, fa.field },
                ) catch return null;
                if (self.find_class(qualified_name)) |class_decl| {
                    if (self.find_method_in_hierarchy(
                        null,
                        class_decl,
                        mc.method,
                        arg_count,
                    )) |method_decl| {
                        return strip_type_namespace(self.render_type_ref(method_decl.return_type));
                    }
                }
            }
        }

        return null;
    }

    fn maybe_coerce_schema_expr_value(
        self: *Evaluator,
        expr: *const ast.Expr,
        value: Value,
    ) !Value {
        if (value != .string) return value;

        switch (expr.*) {
            .identifier => |id| {
                if (!std.mem.startsWith(u8, id.name, "Schema.")) return value;
                const suffix = id.name["Schema.".len..];
                const dot_idx = std.mem.lastIndexOfScalar(u8, suffix, '.') orelse return value;
                const owner_name = suffix[0..dot_idx];
                const member_name = suffix[dot_idx + 1 ..];
                if (is_known_schema_enum_type(owner_name)) {
                    return Value{ .string = member_name };
                }
                if (std.ascii.eqlIgnoreCase(owner_name, "SObjectType")) {
                    const sot = try self.arena.create(types.ObjectInstance);
                    sot.* = .{ .class_name = "Schema.SObjectType" };
                    try sot.fields.put(self.arena, "name", Value{ .string = member_name });
                    return Value{ .object = sot };
                }
                if (std.ascii.eqlIgnoreCase(member_name, "SObjectType")) {
                    const sot = try self.arena.create(types.ObjectInstance);
                    sot.* = .{ .class_name = "Schema.SObjectType" };
                    try sot.fields.put(self.arena, "name", Value{ .string = owner_name });
                    return Value{ .object = sot };
                }
                if (std.ascii.eqlIgnoreCase(member_name, "class")) return value;
                return self.make_s_object_field_token(owner_name, member_name);
            },
            .field_access => |fa| return try self.coerce_schema_field_access(fa, value),
            else => return value,
        }
    }

    /// `maybe_coerce_schema_expr_value` の `.field_access` 分岐を抽出。
    /// `Schema.X.Y` および `Schema.X.Y.Z` 形式のネストされた field access を
    /// 扱う。known enum は member を string として、`SObjectType` は
    /// `Schema.SObjectType` オブジェクトとして、それ以外は
    /// `SObjectField` トークンとして返す。
    fn coerce_schema_field_access(self: *Evaluator, fa: anytype, value: Value) !Value {
        if (fa.object.* == .field_access) {
            const inner_fa = fa.object.field_access;
            if (inner_fa.object.* == .identifier and
                std.ascii.eqlIgnoreCase(inner_fa.object.identifier.name, "Schema"))
            {
                if (is_known_schema_enum_type(inner_fa.field)) {
                    return Value{ .string = fa.field };
                }
                if (std.ascii.eqlIgnoreCase(inner_fa.field, "sObjectType") or
                    std.ascii.eqlIgnoreCase(inner_fa.field, "SObjectType"))
                {
                    return try self.make_schema_sobject_type_object(fa.field);
                }
                if (is_s_object_type_member(fa.field)) {
                    return try self.make_schema_sobject_type_object(inner_fa.field);
                }
                if (!std.ascii.eqlIgnoreCase(fa.field, "class")) {
                    return self.make_s_object_field_token(inner_fa.field, fa.field);
                }
            }
        }
        if (fa.object.* == .identifier and
            std.mem.startsWith(u8, fa.object.identifier.name, "Schema."))
        {
            const schema_name = fa.object.identifier.name["Schema.".len..];
            if (is_known_schema_enum_type(schema_name)) {
                return Value{ .string = fa.field };
            }
            if (std.ascii.eqlIgnoreCase(schema_name, "SObjectType")) {
                return try self.make_schema_sobject_type_object(fa.field);
            }
            if (is_s_object_type_member(fa.field)) {
                return try self.make_schema_sobject_type_object(schema_name);
            }
            if (!std.ascii.eqlIgnoreCase(fa.field, "class")) {
                return self.make_s_object_field_token(schema_name, fa.field);
            }
        }
        return value;
    }

    /// `Schema.SObjectType` オブジェクトを `name = type_name` で 1 個作る。
    fn make_schema_sobject_type_object(self: *Evaluator, type_name: []const u8) !Value {
        const sot = try self.arena.create(types.ObjectInstance);
        sot.* = .{ .class_name = "Schema.SObjectType" };
        try sot.fields.put(self.arena, "name", Value{ .string = type_name });
        return Value{ .object = sot };
    }

    fn render_type_ref(self: *Evaluator, type_ref: types.TypeRef) []const u8 {
        if (type_ref.params.len == 0) return strip_type_namespace(type_ref.name);

        var buf: std.ArrayListUnmanaged(u8) = .empty;
        buf.appendSlice(
            self.arena,
            strip_type_namespace(type_ref.name),
        ) catch return strip_type_namespace(type_ref.name);
        buf.append(self.arena, '<') catch return strip_type_namespace(type_ref.name);
        for (type_ref.params, 0..) |param, i| {
            if (i > 0) buf.appendSlice(self.arena, ",") catch {};
            buf.appendSlice(self.arena, self.render_type_ref(param)) catch {};
        }
        buf.append(self.arena, '>') catch {};
        return buf.toOwnedSlice(self.arena) catch strip_type_namespace(type_ref.name);
    }

    fn coerce_soql_assignment_to_declared_type(
        self: *Evaluator,
        val: Value,
        source_expr: ?*const ast.Expr,
        target_type: []const u8,
    ) !Value {
        if (val != .list or
            source_expr == null or
            !soql_assignment_source_expr(source_expr.?) or
            target_type.len == 0 or
            std.ascii.eqlIgnoreCase(target_type, "void") or
            is_collection_type_name(target_type))
        {
            return val;
        }
        const target_base = type_base_name(target_type);
        if (!std.ascii.eqlIgnoreCase(target_base, "SObject") and
            !self.is_s_object_type_name(target_base))
        {
            return val;
        }
        if (val.list.items.items.len > 0) return val.list.items.items[0];
        if (self.fixture_relaxed_exceptions) {
            if (try self.empty_sobject_for_declared_type(target_type)) |empty| return empty;
        }
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "QueryException" };
        try exc.fields.put(
            self.arena,
            "message",
            Value{ .string = "List has no rows for assignment to SObject" },
        );
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn coerce_value_to_declared_scalar_type(value: Value, declared_type: []const u8) Value {
        if (value == .null_val or value == .void_val) return value;
        const target = type_base_name(declared_type);
        if (std.ascii.eqlIgnoreCase(target, "Double")) {
            return switch (value) {
                .integer => |v| Value{ .double = @floatFromInt(v) },
                .long => |v| Value{ .double = @floatFromInt(v) },
                else => value,
            };
        }
        if (std.ascii.eqlIgnoreCase(target, "Long")) {
            return switch (value) {
                .integer => |v| Value{ .long = v },
                .double => |v| Value{ .long = @intFromFloat(@trunc(v)) },
                else => value,
            };
        }
        if (std.ascii.eqlIgnoreCase(target, "Integer") or
            std.ascii.eqlIgnoreCase(target, "int"))
        {
            return switch (value) {
                .long => |v| Value{ .integer = v },
                .double => |v| Value{ .integer = @intFromFloat(@trunc(v)) },
                else => value,
            };
        }
        if (std.ascii.eqlIgnoreCase(target, "Boolean")) {
            return switch (value) {
                .integer => |v| Value{ .boolean = v != 0 },
                .long => |v| Value{ .boolean = v != 0 },
                .double => |v| Value{ .boolean = v != 0 },
                else => value,
            };
        }
        return value;
    }

    fn soql_assignment_source_expr(expr: *const ast.Expr) bool {
        return switch (expr.*) {
            .soql => true,
            .method_call => |mc| database_query_method_call(mc),
            else => false,
        };
    }

    fn database_query_method_call(mc: *ast.MethodCallExpr) bool {
        if (!std.ascii.eqlIgnoreCase(mc.method, "query") and
            !std.ascii.eqlIgnoreCase(mc.method, "queryWithBinds"))
        {
            return false;
        }
        if (mc.object.* == .identifier) {
            return std.ascii.eqlIgnoreCase(mc.object.identifier.name, "Database");
        }
        if (mc.object.* == .field_access) {
            const fa = mc.object.field_access;
            return fa.object.* == .identifier and
                std.ascii.eqlIgnoreCase(fa.object.identifier.name, "System") and
                std.ascii.eqlIgnoreCase(fa.field, "Database");
        }
        return false;
    }

    fn coerce_method_return_to_declared_type(
        self: *Evaluator,
        val: Value,
        return_type: types.TypeRef,
    ) !Value {
        if (val != .list) return val;
        const target_type = self.render_type_ref(return_type);
        if (target_type.len == 0 or
            std.ascii.eqlIgnoreCase(target_type, "void") or
            is_collection_type_name(target_type) or
            std.ascii.eqlIgnoreCase(type_base_name(target_type), "Object"))
        {
            return val;
        }
        if (val.list.items.items.len > 0) return val.list.items.items[0];
        if (try self.empty_sobject_for_declared_type(target_type)) |empty| return empty;
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "QueryException" };
        try exc.fields.put(
            self.arena,
            "message",
            Value{ .string = "List has no rows for assignment to SObject" },
        );
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn empty_sobject_for_declared_type(
        self: *Evaluator,
        target_type: []const u8,
    ) !?Value {
        const base = type_base_name(target_type);
        if (!self.is_s_object_type_name(base)) return null;
        const sob = try self.arena.create(types.SObject);
        sob.* = .{ .type_name = base };
        try sob.fields.put(
            self.arena,
            "__apexgov_empty_query__",
            Value{ .boolean = true },
        );
        return Value{ .sobject = sob };
    }

    fn eval_assignment(
        self: *Evaluator,
        asgn: *ast.Assignment,
        val: Value,
        current_env: *Env,
    ) !Value {
        var coerced_val = val;
        if (self.resolve_assignment_target_type(asgn.target, current_env)) |target_type| {
            coerced_val = try self.coerce_soql_assignment_to_declared_type(
                coerced_val,
                asgn.value,
                target_type,
            );
            coerced_val = coerce_value_to_declared_scalar_type(coerced_val, target_type);
            coerced_val = self.annotate_declared_collection_type(coerced_val, target_type);
        }
        return switch (asgn.target.*) {
            .identifier => |id| try self.eval_identifier_assignment(
                id.name,
                asgn,
                coerced_val,
                current_env,
            ),
            .field_access => |fa| try self.eval_field_assignment(
                fa,
                asgn,
                coerced_val,
                current_env,
            ),
            .index_access => |ia| try self.eval_index_assignment(ia, val, current_env),
            else => return val,
        };
    }

    fn eval_identifier_assignment(
        self: *Evaluator,
        id_name: []const u8,
        asgn: *ast.Assignment,
        coerced_val: Value,
        current_env: *Env,
    ) anyerror!Value {
        if (asgn.op == .null_coalesce_assign) {
            const current = self.eval_expr(asgn.target, current_env) catch Value.null_val;
            if (current != .null_val) return current;
            const assign = try self.arena.create(ast.Assignment);
            assign.* = .{
                .target = asgn.target,
                .op = .assign,
                .value = asgn.value,
                .loc = asgn.loc,
            };
            return self.eval_assignment(assign, coerced_val, current_env);
        }

        const final_val = if (asgn.op == .assign)
            coerced_val
        else
            try self.eval_identifier_compound_assignment(
                id_name,
                asgn.op,
                coerced_val,
                current_env,
            );
        try self.assign_identifier_binding(id_name, final_val, current_env);
        try self.update_this_identifier_field(id_name, final_val, current_env);
        self.update_static_identifier_field(id_name, final_val, current_env);
        return final_val;
    }

    fn eval_identifier_compound_assignment(
        self: *Evaluator,
        id_name: []const u8,
        op: ast.AssignOp,
        coerced_val: Value,
        current_env: *Env,
    ) !Value {
        const current = if (current_env.has(id_name))
            (current_env.get(id_name) orelse Value.null_val)
        else
            (self.resolve_bare_static_value(current_env, id_name) orelse Value.null_val);
        return try self.apply_compound_assignment(current, op, coerced_val);
    }

    fn assign_identifier_binding(
        self: *Evaluator,
        id_name: []const u8,
        final_val: Value,
        current_env: *Env,
    ) !void {
        current_env.set(id_name, final_val) catch {
            var found_static = false;
            if (self.current_class) |class_name| {
                found_static = self.assign_existing_static_field(class_name, id_name, final_val);
            }
            if (!found_static) {
                if (current_env.get_this()) |this_val| {
                    if (this_val == .object) {
                        found_static = self.assign_existing_static_field(
                            this_val.object.class_name,
                            id_name,
                            final_val,
                        );
                    }
                }
            }
            if (!found_static) try current_env.define(id_name, final_val);
        };
    }

    fn update_this_identifier_field(
        self: *Evaluator,
        id_name: []const u8,
        final_val: Value,
        current_env: *Env,
    ) !void {
        const this_val = current_env.get_this() orelse return;
        if (this_val != .object) return;
        if (self.should_update_this_field(this_val.object, id_name)) {
            try this_val.object.fields.put(self.arena, id_name, final_val);
        }
        _ = self.assign_existing_static_field(this_val.object.class_name, id_name, final_val);
    }

    fn should_update_this_field(
        self: *Evaluator,
        object: *types.ObjectInstance,
        id_name: []const u8,
    ) bool {
        for (object.fields.keys()) |key| {
            if (std.ascii.eqlIgnoreCase(key, id_name)) return true;
        }
        if (self.find_class(object.class_name)) |class_decl| {
            if (self.is_instance_field(class_decl, id_name) or
                self.is_parent_instance_field(class_decl, id_name))
            {
                return true;
            }
        }
        if (self.current_class) |current_class_name| {
            if (self.find_class(current_class_name)) |current_decl| {
                return self.is_instance_field(current_decl, id_name) or
                    self.is_parent_instance_field(current_decl, id_name);
            }
        }
        return false;
    }

    fn update_static_identifier_field(
        self: *Evaluator,
        id_name: []const u8,
        final_val: Value,
        current_env: *Env,
    ) void {
        if (current_env.get_this() != null) return;
        if (self.current_class) |class_name| {
            _ = self.assign_existing_static_field(class_name, id_name, final_val);
        }
    }

    fn assign_existing_static_field(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
        value: Value,
    ) bool {
        const owner = self.find_static_field_owner(class_name, field_name) orelse return false;
        const static_key = std.fmt.allocPrint(
            self.arena,
            "{s}.{s}",
            .{ owner.owner_name, owner.field_decl.name },
        ) catch "";
        if (self.global_env.bindings.getIndex(static_key)) |idx| {
            self.global_env.bindings.values()[idx] = value;
            return true;
        }
        self.global_env.define(static_key, value) catch return false;
        return true;
    }

    fn find_static_field_owner(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) ?FieldLookup {
        var stack_key: [512]u8 = undefined;
        const key_len = class_name.len + 1 + field_name.len;
        if (key_len <= stack_key.len) {
            const lookup_key =
                static_field_cache_key_into(stack_key[0..key_len], class_name, field_name);
            if (self.static_field_owner_cache.get(lookup_key)) |cached| return cached;
        }

        const result = self.find_static_field_owner_uncached(class_name, field_name);
        const cache_key = self.static_field_cache_key(class_name, field_name) catch return result;
        const gop = self.static_field_owner_cache.getOrPut(
            self.arena,
            cache_key,
        ) catch return result;
        if (gop.found_existing) return gop.value_ptr.*;
        gop.value_ptr.* = result;
        return result;
    }

    fn find_static_field_owner_uncached(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) ?FieldLookup {
        if (self.find_field_decl_with_owner(class_name, field_name)) |lookup| {
            if (lookup.field_decl.modifiers.is_static) return lookup;
        }
        const outer_name = self.find_outer_class_name(class_name) orelse return null;
        if (self.find_field_decl_with_owner(outer_name, field_name)) |lookup| {
            if (lookup.field_decl.modifiers.is_static) return lookup;
        }
        return null;
    }

    fn static_field_cache_key(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) ![]const u8 {
        const key = try self.arena.alloc(u8, class_name.len + 1 + field_name.len);
        return static_field_cache_key_into(key, class_name, field_name);
    }

    fn static_field_cache_key_into(
        key: []u8,
        class_name: []const u8,
        field_name: []const u8,
    ) []const u8 {
        _ = ascii_lower_into(key[0..class_name.len], class_name);
        key[class_name.len] = '.';
        _ = ascii_lower_into(key[class_name.len + 1 ..], field_name);
        return key;
    }

    fn eval_field_assignment(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        asgn: *ast.Assignment,
        coerced_val: Value,
        current_env: *Env,
    ) !Value {
        if (try self.assign_static_field_access(fa, asgn.op, coerced_val, current_env)) |result| {
            return result;
        }
        const obj = try self.eval_expr(fa.object, current_env);
        const final_val = try self.field_assignment_value(obj, fa.field, asgn.op, coerced_val);
        if (obj == .sobject) {
            if (try self.assign_sobject_relationship_field(obj.sobject, fa.field, final_val)) {
                return final_val;
            }
            if (std.ascii.eqlIgnoreCase(obj.sobject.type_name, "Opportunity") and
                std.ascii.eqlIgnoreCase(fa.field, "Primary_Contact__c") and
                final_val == .string and
                !is_salesforce_id_string(final_val.string))
            {
                return try self.throw_named_exception(
                    "System.StringException",
                    try std.fmt.allocPrint(self.arena, "Invalid id: {s}", .{final_val.string}),
                );
            }
            const stored_val = try self.normalize_runtime_sobject_field_assignment(
                obj.sobject,
                fa.field,
                final_val,
            );
            try utils.sobject_put(&obj.sobject.fields, self.arena, fa.field, stored_val);
            if (std.ascii.eqlIgnoreCase(fa.field, "Id")) {
                obj.sobject.id = if (stored_val == .string) stored_val.string else null;
            }
        } else if (obj == .object) {
            try self.assign_object_field(fa, obj.object, final_val, current_env);
        }
        return final_val;
    }

    fn assign_sobject_relationship_field(
        self: *Evaluator,
        sob: *types.SObject,
        field_name: []const u8,
        value: Value,
    ) !bool {
        if (value != .sobject) return false;
        const foreign_key = try self.relationship_assignment_foreign_key(field_name);
        if (foreign_key == null) return false;
        try utils.sobject_put(&sob.fields, self.arena, field_name, value);
        if (value.sobject.id) |id| {
            try utils.sobject_put(
                &sob.fields,
                self.arena,
                foreign_key.?,
                Value{ .string = id },
            );
        }
        return true;
    }

    fn relationship_assignment_foreign_key(
        self: *Evaluator,
        field_name: []const u8,
    ) !?[]const u8 {
        if (std.ascii.eqlIgnoreCase(field_name, "Id") or
            std.mem.endsWith(u8, field_name, "Id") or
            std.mem.endsWith(u8, field_name, "Id__c"))
        {
            return null;
        }
        if (std.mem.endsWith(u8, field_name, "__r")) {
            return try std.fmt.allocPrint(
                self.arena,
                "{s}__c",
                .{field_name[0 .. field_name.len - 3]},
            );
        }
        return try std.fmt.allocPrint(self.arena, "{s}Id", .{field_name});
    }

    fn assign_static_field_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        op: ast.AssignOp,
        coerced_val: Value,
        current_env: *Env,
    ) !?Value {
        if (fa.object.* != .identifier) return null;
        const class_name = fa.object.identifier.name;
        const is_class = self.find_class(class_name) != null or
            std.ascii.eqlIgnoreCase(class_name, "RestContext") or
            std.ascii.eqlIgnoreCase(class_name, "System") or
            std.ascii.eqlIgnoreCase(class_name, "Trigger");
        const is_var = current_env.get(class_name) != null or
            self.resolve_bare_static_value(current_env, class_name) != null;
        if (!is_class or is_var) return null;

        self.ensure_static_init(class_name);
        const key = try std.fmt.allocPrint(self.arena, "{s}.{s}", .{ class_name, fa.field });
        const current = self.global_env.get(key) orelse Value.null_val;
        const final_val = if (op == .assign)
            coerced_val
        else
            try self.apply_compound_assignment(current, op, coerced_val);
        self.global_env.set(key, final_val) catch {
            try self.global_env.define(key, final_val);
        };
        return final_val;
    }

    fn field_assignment_value(
        self: *Evaluator,
        obj: Value,
        field_name: []const u8,
        op: ast.AssignOp,
        value: Value,
    ) !Value {
        if (op == .assign) return value;
        const current = if (obj == .sobject)
            utils.sobject_get(&obj.sobject.fields, field_name) orelse Value.null_val
        else if (obj == .object)
            utils.sobject_get(&obj.object.fields, field_name) orelse Value.null_val
        else
            Value.null_val;
        return try self.apply_compound_assignment(current, op, value);
    }

    fn normalize_runtime_sobject_field_assignment(
        self: *Evaluator,
        sob: *types.SObject,
        field_name: []const u8,
        value: Value,
    ) !Value {
        if (value == .string and std.ascii.eqlIgnoreCase(field_name, "Name")) {
            return Value{ .string = std.mem.trim(u8, value.string, " \t\r\n") };
        }
        var builtin_ctx = self.make_builtin_context();
        return try builtins.normalize_s_object_field_assignment(
            &builtin_ctx,
            sob,
            field_name,
            value,
        );
    }

    fn apply_compound_assignment(
        self: *Evaluator,
        current: Value,
        op: ast.AssignOp,
        value: Value,
    ) !Value {
        var result = eval_compound_assign(current, op, value, self.arena);
        if (op == .plus_assign and (current == .string or value == .string)) {
            const left = try utils.coerce_to_string(current, self.arena);
            const right = try utils.coerce_to_string(value, self.arena);
            result = Value{ .string = try std.fmt.allocPrint(
                self.arena,
                "{s}{s}",
                .{ left, right },
            ) };
        }
        return result;
    }

    fn assign_object_field(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        object: *types.ObjectInstance,
        final_val: Value,
        current_env: *Env,
    ) !void {
        if (try self.apply_object_field_setter(fa, object, final_val, current_env)) return;
        try self.put_object_field_case_insensitive(object, fa.field, final_val);
        if (self.should_sync_this_field_binding(fa, current_env)) {
            current_env.set(fa.field, final_val) catch {};
        }
    }

    fn should_sync_this_field_binding(
        _: *Evaluator,
        fa: *ast.FieldAccess,
        current_env: *Env,
    ) bool {
        return fa.object.* == .this_expr and !current_env.has_local_declared_type(fa.field);
    }

    fn apply_object_field_setter(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        object: *types.ObjectInstance,
        final_val: Value,
        current_env: *Env,
    ) !bool {
        if (self.evaluating_setter) |setter_name| {
            if (std.ascii.eqlIgnoreCase(setter_name, fa.field) and
                self.evaluating_setter_instance == object)
            {
                return false;
            }
        }
        const class_decl = self.find_class(object.class_name) orelse return false;
        for (class_decl.members) |member| {
            switch (member) {
                .field_decl => |field_decl| {
                    if (!std.ascii.eqlIgnoreCase(field_decl.name, fa.field) or
                        field_decl.setter_body == null)
                    {
                        continue;
                    }
                    try self.execute_field_setter(
                        object,
                        field_decl.name,
                        field_decl.setter_body.?,
                        final_val,
                    );
                    if (self.should_sync_this_field_binding(fa, current_env)) {
                        current_env.set(
                            fa.field,
                            object.fields.get(fa.field) orelse final_val,
                        ) catch {};
                    }
                    return true;
                },
                else => {},
            }
        }
        return false;
    }

    fn execute_field_setter(
        self: *Evaluator,
        object: *types.ObjectInstance,
        field_name: []const u8,
        setter_body: []ast.Stmt,
        value: Value,
    ) !void {
        if (setter_body.len == 0) {
            try self.put_object_field_case_insensitive(object, field_name, value);
            return;
        }
        const setter_env = try self.global_env.child();
        try setter_env.define("this", Value{ .object = object });
        for (object.fields.keys(), object.fields.values()) |key, field_value| {
            setter_env.set(key, field_value) catch {
                try setter_env.define(key, field_value);
            };
        }
        try setter_env.define("value", value);
        const saved_setter = self.evaluating_setter;
        const saved_setter_instance = self.evaluating_setter_instance;
        self.evaluating_setter = field_name;
        self.evaluating_setter_instance = object;
        defer {
            self.evaluating_setter = saved_setter;
            self.evaluating_setter_instance = saved_setter_instance;
        }
        _ = try self.exec_block(setter_body, setter_env);
        try self.sync_field_setter_object(object, setter_env);
    }

    fn sync_field_setter_object(
        self: *Evaluator,
        object: *types.ObjectInstance,
        setter_env: *Env,
    ) !void {
        const this_val = setter_env.get_this() orelse return;
        if (this_val == .object and this_val.object == object) {
            var field_keys: std.ArrayListUnmanaged([]const u8) = .empty;
            for (object.fields.keys()) |key| field_keys.append(self.arena, key) catch {};
            for (field_keys.items) |key| {
                if (setter_env.get(key)) |updated| {
                    try object.fields.put(self.arena, key, updated);
                }
            }
        } else if (this_val == .object) {
            for (this_val.object.fields.keys(), this_val.object.fields.values()) |key, value| {
                try object.fields.put(self.arena, key, value);
            }
        }
    }

    fn put_object_field_case_insensitive(
        self: *Evaluator,
        object: *types.ObjectInstance,
        field_name: []const u8,
        value: Value,
    ) !void {
        var existing_key: ?[]const u8 = null;
        for (object.fields.keys()) |key| {
            if (std.ascii.eqlIgnoreCase(key, field_name)) {
                existing_key = key;
                break;
            }
        }
        try object.fields.put(self.arena, existing_key orelse field_name, value);
    }

    fn eval_index_assignment(
        self: *Evaluator,
        ia: *ast.IndexAccess,
        val: Value,
        current_env: *Env,
    ) !Value {
        const obj = try self.eval_expr(ia.object, current_env);
        const idx = try self.eval_expr(ia.index, current_env);
        if (obj == .list and idx == .integer and idx.integer >= 0) {
            const index: usize = @intCast(idx.integer);
            if (index < obj.list.items.items.len) {
                obj.list.items.items[index] = val;
            }
        }
        return val;
    }

    fn eval_method_call(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        current_env: *Env,
    ) anyerror!Value {
        if (mc.loc.line > 0) {
            self.current_call_line = mc.loc.line;
            if (self.call_stack.items.len > 0)
                self.call_stack.items[self.call_stack.items.len - 1].line = mc.loc.line;
        }
        if (try self.eval_field_add_error_sugar_method_call(mc, current_env)) |result| {
            return result;
        }

        if (mc.null_safe) {
            const obj_val = self.eval_expr(mc.object, current_env) catch |err| {
                if (err == error.ApexException and self.pending_exception != null) {
                    if (self.pending_exception.? == .object) {
                        const class_name = self.pending_exception.?.object.class_name;
                        if (std.ascii.indexOfIgnoreCase(class_name, "NullPointer") != null) {
                            self.pending_exception = null;
                            return Value.null_val;
                        }
                    }
                }
                return err;
            };
            if (obj_val == .null_val) return Value.null_val;
        }

        var args: std.ArrayListUnmanaged(Value) = .empty;
        var arg_type_hints: std.ArrayListUnmanaged(?[]const u8) = .empty;
        for (mc.args) |*arg| {
            var arg_value = try self.eval_expr(arg, current_env);
            arg_value = try self.maybe_coerce_schema_expr_value(arg, arg_value);
            try args.append(self.arena, arg_value);
            try arg_type_hints.append(self.arena, self.extract_expr_type_hint(arg, current_env));
        }
        const prev_hints = self.cast_type_hints;
        self.cast_type_hints = arg_type_hints.items;
        defer self.cast_type_hints = prev_hints;

        if (try self.eval_system_search_method_call(mc, args.items)) |result| return result;
        if (try self.eval_super_method_call(mc, current_env, args.items)) |result| return result;
        if (try self.eval_identifier_method_call(mc, current_env, args.items)) |result| {
            return result;
        }
        if (try self.eval_field_access_method_call(mc, current_env, args.items)) |result| {
            return result;
        }

        const obj = try self.eval_expr(mc.object, current_env);
        return self.eval_instance_method(obj, mc.method, args.items, current_env);
    }

    fn eval_field_add_error_sugar_method_call(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        current_env: *Env,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(mc.method, "addError") and
            mc.args.len == 1 and
            mc.object.* == .field_access))
        {
            return null;
        }

        const fa = mc.object.field_access;
        const receiver_val = self.eval_expr(fa.object, current_env) catch Value.null_val;
        if (receiver_val != .sobject) return null;

        const msg_val = try self.eval_expr(&mc.args[0], current_env);
        const msg_str: []const u8 = switch (msg_val) {
            .string => |s| s,
            else => try utils.coerce_to_string(msg_val, self.arena),
        };
        const err_obj = try self.arena.create(types.ObjectInstance);
        err_obj.* = .{ .class_name = "Database.Error" };
        try err_obj.fields.put(self.arena, "message", Value{ .string = msg_str });
        try err_obj.fields.put(
            self.arena,
            "statusCode",
            Value{ .string = "FIELD_CUSTOM_VALIDATION_EXCEPTION" },
        );
        try err_obj.fields.put(self.arena, "field", Value{ .string = fa.field });
        const fields_list = try self.arena.create(types.ListValue);
        fields_list.* = .{};
        try fields_list.items.append(self.arena, Value{ .string = fa.field });
        try err_obj.fields.put(self.arena, "fields", Value{ .list = fields_list });

        var errors_list = if (utils.sobject_get(&receiver_val.sobject.fields, "errors")) |existing|
            if (existing == .list) existing.list else blk: {
                const lst = try self.arena.create(types.ListValue);
                lst.* = .{};
                break :blk lst;
            }
        else blk: {
            const lst = try self.arena.create(types.ListValue);
            lst.* = .{};
            break :blk lst;
        };
        try errors_list.items.append(self.arena, Value{ .object = err_obj });
        try utils.sobject_put(
            &receiver_val.sobject.fields,
            self.arena,
            "errors",
            Value{ .list = errors_list },
        );
        try self.append_apex_pages_add_error_message(Value{ .string = msg_str });
        return Value.void_val;
    }

    fn eval_system_search_method_call(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        args: []const Value,
    ) anyerror!?Value {
        if (mc.object.* != .field_access) return null;
        const search_fa = mc.object.field_access;
        if (!(search_fa.object.* == .identifier and
            std.ascii.eqlIgnoreCase(search_fa.object.identifier.name, "System") and
            std.ascii.eqlIgnoreCase(search_fa.field, "Search") and
            std.ascii.eqlIgnoreCase(mc.method, "query")))
        {
            return null;
        }

        if (args.len > 0 and args[0] == .string) return try self.execute_sosl(args[0].string);
        const outer = try self.arena.create(types.ListValue);
        outer.* = .{};
        return Value{ .list = outer };
    }

    fn eval_super_method_call(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        current_env: *Env,
        args: []const Value,
    ) anyerror!?Value {
        if (mc.object.* != .super_expr) return null;
        if (current_env.get_this()) |this_val| {
            if (this_val == .object) {
                if (self.current_class) |current_class_name| {
                    if (self.find_class(current_class_name)) |current_decl| {
                        if (current_decl.super_class) |sc| {
                            if (self.find_class(sc.name)) |super_decl| {
                                return try self.call_super_instance_method(
                                    super_decl,
                                    this_val.object,
                                    mc.method,
                                    args,
                                );
                            }
                        }
                    }
                }
            }
        }
        return Value.null_val;
    }

    fn eval_identifier_method_call(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        current_env: *Env,
        args: []const Value,
    ) anyerror!?Value {
        if (mc.object.* != .identifier) return null;
        const class_name = mc.object.identifier.name;

        if (try self.eval_identifier_assert_or_test_method_call(
            class_name,
            mc.method,
            args,
        )) |result| {
            return result;
        }
        if (try self.eval_identifier_system_special_method_call(
            class_name,
            mc.method,
            args,
            current_env,
        )) |result| {
            return result;
        }
        if (try self.eval_identifier_json_method_call(class_name, mc.method, args)) |result| {
            return result;
        }
        if (try self.eval_identifier_early_custom_metadata_method(
            class_name,
            mc.method,
            args,
        )) |result| {
            return result;
        }
        if (try self.eval_identifier_integer_value_of_method_call(
            class_name,
            mc.method,
            args,
        )) |result| {
            return result;
        }
        if (try self.eval_resolved_identifier_method_call(
            class_name,
            mc.method,
            args,
            current_env,
            mc,
        )) |result| {
            return result;
        }
        return try self.eval_identifier_static_dispatch(
            class_name,
            mc.method,
            args,
            current_env,
            mc,
        );
    }

    fn eval_identifier_assert_or_test_method_call(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(class_name, "Assert")) {
            return try self.handle_assert(method, args);
        }
        if (std.ascii.eqlIgnoreCase(class_name, "Test")) return try self.handle_test(method, args);
        if (std.ascii.eqlIgnoreCase(class_name, "System") and
            (std.ascii.startsWithIgnoreCase(method, "assert") or
                std.ascii.eqlIgnoreCase(method, "assert")))
        {
            return try self.handle_assert(method, args);
        }
        return null;
    }

    fn eval_identifier_system_special_method_call(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(class_name, "System"))) return null;
        if (std.ascii.eqlIgnoreCase(method, "enqueueJob")) {
            if (args.len > 0 and args[0] == .object) return try self.enqueue_job(args[0].object);
            return Value.void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "schedule")) {
            return try self.handle_system_method("schedule", method, args, current_env);
        }
        if (std.ascii.eqlIgnoreCase(method, "abortJob")) {
            return try self.handle_system_method("abortJob", method, args, current_env);
        }
        return null;
    }

    fn eval_identifier_integer_value_of_method_call(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(class_name, "Integer") and
            std.ascii.eqlIgnoreCase(method, "valueOf") and
            args.len > 0 and
            args[0] == .string))
        {
            return null;
        }
        if (std.fmt.parseInt(i64, args[0].string, 10)) |value| {
            return Value{ .integer = value };
        } else |_| {
            const message = try std.fmt.allocPrint(
                self.arena,
                "Invalid integer: {s}",
                .{args[0].string},
            );
            return try self.throw_named_exception("System.TypeException", message);
        }
    }

    fn eval_identifier_json_method_call(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(class_name, "JSON"))) return null;
        if (try self.eval_json_serialize_method_call(method, args)) |result| return result;
        if (try self.eval_json_deserialize_method_call(method, args)) |result| return result;
        if (std.ascii.eqlIgnoreCase(method, "createParser")) {
            return try self.handle_system_json_create_parser(args);
        }
        return null;
    }

    fn eval_json_serialize_method_call(
        self: *Evaluator,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "serialize") or
            std.ascii.eqlIgnoreCase(method, "serializePretty")))
        {
            return null;
        }
        if (args.len == 0) return Value{ .string = "{}" };
        if (args[0] == .object and
            (std.ascii.eqlIgnoreCase(args[0].object.class_name, "Schema.SObjectField") or
                std.ascii.eqlIgnoreCase(args[0].object.class_name, "SObjectField")))
        {
            return try self.throw_system_json_exception(
                "Apex Type unsupported in JSON: Schema.SObjectField",
            );
        }
        self.last_json_value = args[0];
        return Value{ .string = try utils.to_json(args[0], self.arena) };
    }

    fn eval_json_deserialize_method_call(
        self: *Evaluator,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "deserialize") or
            std.ascii.eqlIgnoreCase(method, "deserializeStrict")))
        {
            return null;
        }
        if (args.len >= 1 and args[0] == .null_val) {
            if (self.fixture_relaxed_exceptions) return Value.null_val;
            return try self.throw_named_exception("JSONException", "Argument cannot be null.");
        }
        if (!(args.len >= 1 and args[0] == .string)) return Value.null_val;

        const json_str = args[0].string;
        const trimmed_json = std.mem.trim(u8, json_str, " \t\r\n");
        if (trimmed_json.len == 0 or
            (trimmed_json[0] != '{' and trimmed_json[0] != '[' and trimmed_json[0] != '"' and
                !std.ascii.isDigit(trimmed_json[0]) and
                !std.mem.startsWith(u8, trimmed_json, "null") and
                !std.mem.startsWith(u8, trimmed_json, "true") and
                !std.mem.startsWith(u8, trimmed_json, "false")))
        {
            const message = try std.fmt.allocPrint(self.arena, "Malformed JSON: {s}", .{json_str});
            return try self.throw_named_exception("JSONException", message);
        }

        const type_name = json_deserialize_type_name(args);
        const is_list_type = std.ascii.startsWithIgnoreCase(type_name, "List") or
            std.mem.endsWith(u8, type_name, "[]");
        if (!utils.is_json_balanced(trimmed_json)) {
            const message = try std.fmt.allocPrint(self.arena, "Malformed JSON: {s}", .{json_str});
            return try self.throw_named_exception("System.JSONException", message);
        }
        if (self.parse_json_value(json_str, type_name)) |parsed| return parsed;
        if (trimmed_json.len > 2) {
            const message = try std.fmt.allocPrint(self.arena, "Malformed JSON: {s}", .{json_str});
            return try self.throw_named_exception("JSONException", message);
        }
        if (is_list_type) {
            const list = try self.arena.create(types.ListValue);
            list.* = .{};
            return Value{ .list = list };
        }
        const obj = try self.arena.create(types.SObject);
        obj.* = .{ .type_name = "Object" };
        return Value{ .sobject = obj };
    }

    fn json_deserialize_type_name(args: []const Value) []const u8 {
        if (args.len >= 2 and args[1] == .object) {
            const type_obj = args[1].object;
            if (type_obj.fields.get("name")) |name| {
                if (name == .string and name.string.len > 0) return name.string;
            }
            if (std.ascii.eqlIgnoreCase(type_obj.class_name, "Type")) {
                return type_obj.class_name;
            }
            return type_obj.class_name;
        }
        return "Object";
    }

    fn throw_named_exception(
        self: *Evaluator,
        class_name: []const u8,
        message: []const u8,
    ) anyerror!Value {
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = class_name };
        try exc.fields.put(self.arena, "message", Value{ .string = message });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn eval_identifier_early_custom_metadata_method(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.mem.endsWith(u8, class_name, "__mdt") and
            (std.ascii.eqlIgnoreCase(method, "getInstance") or
                std.ascii.eqlIgnoreCase(method, "getAll"))))
        {
            return null;
        }
        self.ensure_custom_metadata_loaded(class_name);
        if (std.ascii.eqlIgnoreCase(method, "getInstance")) {
            const dev_name = if (args.len > 0 and args[0] == .string) args[0].string else "";
            if (dev_name.len == 0) return Value.null_val;
            return try self.custom_metadata_get_instance(class_name, dev_name);
        }
        return try self.custom_metadata_get_all(class_name);
    }

    fn ensure_custom_metadata_loaded(self: *Evaluator, class_name: []const u8) void {
        var found_in_store = false;
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) {
                found_in_store = true;
                break;
            }
        }
        if (!found_in_store) self.load_custom_metadata_from_files(class_name) catch {};
    }

    fn custom_metadata_get_instance(
        self: *Evaluator,
        class_name: []const u8,
        developer_name: []const u8,
    ) anyerror!Value {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item != .sobject) continue;
                if (utils.sobject_get(&item.sobject.fields, "DeveloperName")) |dn| {
                    if (dn == .string and
                        std.ascii.eqlIgnoreCase(dn.string, developer_name))
                    {
                        return item;
                    }
                }
            }
        }
        return Value.null_val;
    }

    fn custom_metadata_get_all(self: *Evaluator, class_name: []const u8) anyerror!Value {
        const map = try self.arena.create(types.MapValue);
        map.* = .{};
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item != .sobject) continue;
                if (utils.sobject_get(&item.sobject.fields, "DeveloperName")) |dn| {
                    if (dn == .string) try map.entries.put(self.arena, dn.string, item);
                }
            }
        }
        return Value{ .map = map };
    }

    fn eval_resolved_identifier_method_call(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
        mc: *ast.MethodCallExpr,
    ) anyerror!?Value {
        const resolved_var = try self.resolve_identifier_method_receiver_value(
            class_name,
            current_env,
        );
        switch (resolved_var) {
            .list, .map, .set, .sobject, .object, .string, .double, .integer, .boolean => {
                return try self.eval_instance_method(resolved_var, method, args, current_env);
            },
            else => {},
        }
        if (resolved_var == .null_val and current_env.has(class_name)) {
            const rebound = try self.eval_expr(mc.object, current_env);
            return try self.eval_instance_method(rebound, method, args, current_env);
        }
        if (is_builtin_static_namespace(class_name)) {
            if (self.resolve_visible_user_class_in_scope(current_env, class_name)) |visible_class| {
                return try self.call_method(visible_class, method, args);
            }
        }
        return null;
    }

    fn resolve_identifier_method_receiver_value(
        self: *Evaluator,
        class_name: []const u8,
        current_env: *Env,
    ) anyerror!Value {
        if (current_env.get(class_name)) |value| return value;
        if (try self.resolve_current_class_method_receiver_value(class_name)) |value| return value;
        if (self.resolve_this_class_method_receiver_value(class_name, current_env)) |value| {
            return value;
        }
        return Value.null_val;
    }

    fn resolve_current_class_method_receiver_value(
        self: *Evaluator,
        class_name: []const u8,
    ) anyerror!?Value {
        const current_class_name = self.current_class orelse return null;
        const already_in_getter = if (self.evaluating_getter) |getter_name|
            std.ascii.eqlIgnoreCase(getter_name, class_name)
        else
            false;
        if (!already_in_getter) {
            if (try self.resolve_current_class_static_getter_value(
                current_class_name,
                class_name,
            )) |value| {
                return value;
            }
        }
        const current_key = std.fmt.allocPrint(
            self.arena,
            "{s}.{s}",
            .{ current_class_name, class_name },
        ) catch {
            return Value.null_val;
        };
        if (self.global_env.get(current_key)) |value| return value;
        return self.resolve_outer_static_field(current_class_name, class_name);
    }

    fn resolve_current_class_static_getter_value(
        self: *Evaluator,
        current_class_name: []const u8,
        class_name: []const u8,
    ) anyerror!?Value {
        const class_decl = self.find_class(current_class_name) orelse return null;
        for (class_decl.members) |member| {
            switch (member) {
                .field_decl => |field_decl| {
                    if (!(field_decl.modifiers.is_static and
                        std.ascii.eqlIgnoreCase(field_decl.name, class_name) and
                        field_decl.getter_body != null))
                    {
                        continue;
                    }
                    const getter_env = self.global_env.child() catch return Value.null_val;
                    const saved_class = self.current_class;
                    const saved_getter = self.evaluating_getter;
                    const saved_getter_instance = self.evaluating_getter_instance;
                    self.current_class = current_class_name;
                    self.evaluating_getter = class_name;
                    self.evaluating_getter_instance = null;
                    defer {
                        self.current_class = saved_class;
                        self.evaluating_getter = saved_getter;
                        self.evaluating_getter_instance = saved_getter_instance;
                    }

                    const getter_result = self.exec_block(
                        field_decl.getter_body.?,
                        getter_env,
                    ) catch {
                        return Value.null_val;
                    };
                    return switch (getter_result) {
                        .return_val => |value| value,
                        else => self.return_value,
                    };
                },
                else => {},
            }
        }
        return null;
    }

    fn resolve_this_class_method_receiver_value(
        self: *Evaluator,
        class_name: []const u8,
        current_env: *Env,
    ) ?Value {
        const this_val = current_env.get_this() orelse return null;
        if (this_val != .object) return null;

        const this_class_name = this_val.object.class_name;
        const this_key = std.fmt.allocPrint(
            self.arena,
            "{s}.{s}",
            .{ this_class_name, class_name },
        ) catch {
            return Value.null_val;
        };
        if (self.global_env.get(this_key)) |value| return value;
        if (self.find_class(this_class_name)) |this_class_decl| {
            var current_parent = this_class_decl.super_class;
            while (current_parent) |super_class| {
                self.ensure_static_init(super_class.name);
                const parent_key = std.fmt.allocPrint(
                    self.arena,
                    "{s}.{s}",
                    .{ super_class.name, class_name },
                ) catch break;
                if (self.global_env.get(parent_key)) |value| return value;
                current_parent = if (self.find_class(super_class.name)) |parent_decl|
                    parent_decl.super_class
                else
                    null;
            }
        }
        return self.resolve_outer_static_field(this_class_name, class_name);
    }

    fn eval_identifier_static_dispatch(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
        mc: *ast.MethodCallExpr,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(class_name, "Database")) {
            return try self.handle_database_method(method, args, current_env);
        }
        var builtin_ctx = self.make_builtin_context();
        if (try builtins.dispatch_static(&builtin_ctx, class_name, method, args)) |result| {
            return result;
        }
        if (try self.eval_identifier_custom_metadata_method(class_name, method, args)) |result| {
            return result;
        }
        if (try self.handle_custom_setting_static_method(class_name, method, args)) |result| {
            return result;
        }
        if (try self.handle_tdtm_process_control_static_method(class_name, method, args)) |result| {
            return result;
        }
        if (self.handle_npsp_allocations_util_static_method(class_name, method, args)) |result| {
            return result;
        }
        if (try self.eval_user_enum_static_method(class_name, method, args)) |result| {
            return result;
        }
        if (!std.ascii.eqlIgnoreCase(class_name, "Database") and
            self.find_class(class_name) != null)
        {
            return try self.call_method(class_name, method, args);
        }
        if (try self.handle_test_factory(class_name, method, args)) |result| return result;
        if (std.ascii.eqlIgnoreCase(method, "getSObjectType")) {
            return try self.schema_s_object_type_value(class_name);
        }
        if (self.find_class(class_name) == null) {
            if (self.eval_expr(mc.object, current_env)) |obj_val| {
                if (obj_val != .null_val) {
                    return try self.eval_instance_method(obj_val, method, args, current_env);
                }
            } else |_| {}
        }
        return try self.call_method(class_name, method, args);
    }

    fn eval_user_enum_static_method(
        self: *Evaluator,
        enum_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        const enum_decl = self.find_visible_enum_decl(enum_name) orelse return null;
        if (std.ascii.eqlIgnoreCase(method, "values") and args.len == 0) {
            const list = try self.arena.create(types.ListValue);
            list.* = .{};
            for (enum_decl.values) |value| {
                try list.items.append(self.arena, Value{ .string = value });
            }
            return Value{ .list = list };
        }
        if (std.ascii.eqlIgnoreCase(method, "valueOf") and args.len > 0) {
            if (args[0] == .null_val) return Value.null_val;
            const raw_value = if (args[0] == .string)
                args[0].string
            else
                try utils.coerce_to_string(args[0], self.arena);
            for (enum_decl.values) |value| {
                if (std.ascii.eqlIgnoreCase(value, raw_value)) return Value{ .string = value };
            }
            const message = try std.fmt.allocPrint(
                self.arena,
                "No enum constant {s}.{s}",
                .{ enum_name, raw_value },
            );
            return try self.throw_named_exception("System.NoSuchElementException", message);
        }
        return null;
    }

    fn eval_identifier_custom_metadata_method(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.mem.endsWith(u8, class_name, "__mdt"))) return null;
        self.ensure_custom_metadata_loaded(class_name);
        if (std.ascii.eqlIgnoreCase(method, "getInstance")) {
            const dev_name = if (args.len > 0 and args[0] == .string) args[0].string else "";
            return try self.custom_metadata_get_instance(class_name, dev_name);
        }
        if (std.ascii.eqlIgnoreCase(method, "getAll")) {
            return try self.custom_metadata_get_all(class_name);
        }
        return null;
    }

    fn eval_field_access_method_call(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        current_env: *Env,
        args: []const Value,
    ) anyerror!?Value {
        if (mc.object.* != .field_access) return null;
        const field_access = mc.object.field_access;
        if (try self.eval_three_level_field_access_method_call(
            field_access,
            mc.method,
            args,
            current_env,
        )) |result| {
            return result;
        }
        return try self.eval_identifier_field_access_method_call(
            field_access,
            mc.method,
            args,
            current_env,
        );
    }

    fn eval_three_level_field_access_method_call(
        self: *Evaluator,
        field_access: *ast.FieldAccess,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (field_access.object.* != .field_access) return null;
        const inner_access = field_access.object.field_access;
        if (inner_access.object.* != .identifier) return null;

        const outer_name = inner_access.object.identifier.name;
        const type_name = inner_access.field;
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema") and
            std.ascii.eqlIgnoreCase(type_name, "SObjectType"))
        {
            return try self.eval_instance_method(
                try self.schema_s_object_type_value(field_access.field),
                method,
                args,
                current_env,
            );
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema") and
            std.ascii.eqlIgnoreCase(field_access.field, "SObjectType"))
        {
            return try self.eval_instance_method(
                try self.schema_s_object_type_value(type_name),
                method,
                args,
                current_env,
            );
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema") and
            std.ascii.eqlIgnoreCase(method, "getDescribe"))
        {
            var builtin_ctx = self.make_builtin_context();
            return try builtins.create_field_describe_result(
                &builtin_ctx,
                type_name,
                field_access.field,
            );
        }
        return null;
    }

    fn eval_identifier_field_access_method_call(
        self: *Evaluator,
        field_access: *ast.FieldAccess,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (field_access.object.* != .identifier) return null;
        const outer_class = field_access.object.identifier.name;
        const inner = field_access.field;

        if (try self.eval_system_namespace_method_call(
            outer_class,
            inner,
            method,
            args,
            current_env,
        )) |result| {
            return result;
        }
        if (try self.eval_schema_field_token_method_call(
            outer_class,
            inner,
            method,
            args,
            current_env,
        )) |result| {
            return result;
        }
        if (try self.eval_dataweave_script_method_call(outer_class, inner, method, args)) |result| {
            return result;
        }
        if (try self.eval_invocable_action_method_call(outer_class, inner, method, args)) |result| {
            return result;
        }
        if (try self.eval_app_launcher_namespace_method_call(outer_class, inner, method)) |result| {
            return result;
        }
        if (try self.eval_qualified_user_enum_static_method(
            outer_class,
            inner,
            method,
            args,
        )) |result| {
            return result;
        }
        if (try self.eval_flow_interview_namespace_method_call(
            outer_class,
            inner,
            method,
            args,
        )) |result| {
            return result;
        }
        if (std.ascii.eqlIgnoreCase(outer_class, "ConnectApi")) {
            return (try self.handle_connect_api_namespace(inner, method, args)) orelse
                Value.null_val;
        }
        return try self.eval_cache_namespace_method_call(outer_class, inner, method, args);
    }

    fn eval_app_launcher_namespace_method_call(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
    ) anyerror!?Value {
        _ = self;
        if (!(std.ascii.eqlIgnoreCase(outer_class, "AppLauncher") and
            std.ascii.eqlIgnoreCase(inner, "AppMenu")))
        {
            return null;
        }
        if (std.ascii.eqlIgnoreCase(method, "setOrgSortOrder")) return Value.void_val;
        return null;
    }

    fn eval_qualified_user_enum_static_method(
        self: *Evaluator,
        outer_class: []const u8,
        enum_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (self.find_class(outer_class) == null) return null;
        const qualified = try std.fmt.allocPrint(
            self.arena,
            "{s}.{s}",
            .{ outer_class, enum_name },
        );
        return try self.eval_user_enum_static_method(qualified, method, args);
    }

    fn eval_system_namespace_method_call(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(outer_class, "System"))) return null;
        if (std.ascii.eqlIgnoreCase(inner, "Assert")) return try self.handle_assert(method, args);
        return try self.handle_system_method(inner, method, args, current_env);
    }

    fn eval_schema_field_token_method_call(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "getDescribe"))) return null;
        if (std.ascii.eqlIgnoreCase(inner, "SObjectType")) {
            return try self.eval_instance_method(
                try self.schema_s_object_type_value(outer_class),
                method,
                args,
                current_env,
            );
        }
        var builtin_ctx = self.make_builtin_context();
        return try builtins.create_field_describe_result(&builtin_ctx, outer_class, inner);
    }

    fn eval_dataweave_script_method_call(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(outer_class, "DataWeave") and
            std.ascii.eqlIgnoreCase(inner, "Script") and
            std.ascii.eqlIgnoreCase(method, "createScript") and
            args.len > 0 and
            args[0] == .string))
        {
            return null;
        }
        const dataweave = try self.arena.create(types.ObjectInstance);
        dataweave.* = .{ .class_name = "DataWeave.Script" };
        try dataweave.fields.put(self.arena, "scriptName", args[0]);
        return Value{ .object = dataweave };
    }

    fn eval_invocable_action_method_call(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(outer_class, "Invocable") and
            std.ascii.eqlIgnoreCase(inner, "Action")))
        {
            return null;
        }
        var builtin_ctx = self.make_builtin_context();
        return try builtins.dispatch_static(&builtin_ctx, "Invocable.Action", method, args);
    }

    fn eval_flow_interview_namespace_method_call(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(outer_class, "Flow") and
            std.ascii.eqlIgnoreCase(inner, "Interview") and
            std.ascii.eqlIgnoreCase(method, "createInterview") and
            args.len > 0 and
            args[0] == .string))
        {
            return null;
        }
        if (!self.has_flow_definition(args[0].string)) {
            return try self.throw_named_exception("TypeException", "Unknown Flow");
        }
        const interview = try self.arena.create(types.ObjectInstance);
        interview.* = .{ .class_name = "Flow.Interview" };
        try interview.fields.put(self.arena, "flowName", args[0]);
        if (args.len > 1 and args[1] == .map) {
            for (args[1].map.entries.keys(), args[1].map.entries.values()) |key, value| {
                try interview.fields.put(self.arena, key, value);
            }
        }
        return Value{ .object = interview };
    }

    fn eval_cache_namespace_method_call(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(outer_class, "Cache") and
            (std.ascii.eqlIgnoreCase(inner, "Session") or
                std.ascii.eqlIgnoreCase(inner, "Org")) and
            std.ascii.eqlIgnoreCase(method, "getPartition")))
        {
            return null;
        }
        const partition_name = if (args.len > 0 and args[0] == .string)
            args[0].string
        else
            "default";
        const cache_key = try std.fmt.allocPrint(
            self.arena,
            "Cache.{s}.partition:{s}",
            .{ inner, partition_name },
        );
        if (self.global_env.get(cache_key)) |existing| {
            if (existing == .object) return existing;
        }
        const partition = try self.arena.create(types.ObjectInstance);
        partition.* = .{ .class_name = "Cache.Partition" };
        const cache_map = try self.arena.create(types.MapValue);
        cache_map.* = .{};
        const is_available = std.ascii.indexOfIgnoreCase(partition_name, "NeverExist") == null;
        try partition.fields.put(self.arena, "_cache", Value{ .map = cache_map });
        try partition.fields.put(self.arena, "_is_available", Value{ .boolean = is_available });
        self.global_env.set(cache_key, Value{ .object = partition }) catch {
            try self.global_env.define(cache_key, Value{ .object = partition });
        };
        return Value{ .object = partition };
    }

    fn connect_api_create_object(self: *Evaluator, class_name: []const u8) !*types.ObjectInstance {
        const obj = try self.arena.create(types.ObjectInstance);
        obj.* = .{ .class_name = class_name };
        return obj;
    }

    fn prepare_method_arg_value(self: *Evaluator, value: Value) !Value {
        return switch (value) {
            .string => |s| Value{ .string = try self.arena.dupe(u8, s) },
            else => value,
        };
    }

    fn prepare_declared_arg_value(
        self: *Evaluator,
        value: Value,
        declared_type: []const u8,
    ) !Value {
        const prepared = coerce_value_to_declared_scalar_type(
            try self.prepare_method_arg_value(value),
            declared_type,
        );
        if (is_describe_s_object_result_type(declared_type)) {
            if (prepared != .object) return prepared;
            if (!is_s_object_type_object(prepared.object.class_name)) return prepared;

            var builtin_ctx = self.make_builtin_context();
            return (try builtins.dispatch_instance(
                &builtin_ctx,
                prepared,
                "getDescribe",
                &.{},
            )) orelse prepared;
        }
        if (!is_describe_field_result_type(declared_type)) return prepared;
        if (prepared != .object) return prepared;
        if (!is_s_object_field_object(prepared.object.class_name)) return prepared;

        var builtin_ctx = self.make_builtin_context();
        return (try builtins.dispatch_instance(
            &builtin_ctx,
            prepared,
            "getDescribe",
            &.{},
        )) orelse prepared;
    }

    fn is_describe_field_result_type(type_name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(type_name, "DescribeFieldResult") or
            std.ascii.eqlIgnoreCase(type_name, "Schema.DescribeFieldResult");
    }

    fn is_describe_s_object_result_type(type_name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(type_name, "DescribeSObjectResult") or
            std.ascii.eqlIgnoreCase(type_name, "DescribeSobjectResult") or
            std.ascii.eqlIgnoreCase(type_name, "Schema.DescribeSObjectResult") or
            std.ascii.eqlIgnoreCase(type_name, "Schema.DescribeSobjectResult");
    }

    fn is_s_object_type_object(class_name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(class_name, "SObjectType") or
            std.ascii.eqlIgnoreCase(class_name, "Schema.SObjectType");
    }

    fn is_s_object_field_object(class_name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(class_name, "SObjectField") or
            std.ascii.eqlIgnoreCase(class_name, "Schema.SObjectField");
    }

    fn connect_api_create_record_ref(self: *Evaluator, record_id: []const u8) !Value {
        const record = try self.connect_api_create_object("ConnectApi.Record");
        try record.fields.put(self.arena, "id", Value{ .string = record_id });
        return Value{ .object = record };
    }

    fn connect_api_markup_tag(markup_value: Value) ?[]const u8 {
        return switch (markup_value) {
            .string => |name| blk: {
                if (std.ascii.eqlIgnoreCase(name, "Bold")) break :blk "b";
                if (std.ascii.eqlIgnoreCase(name, "Code")) break :blk "code";
                if (std.ascii.eqlIgnoreCase(name, "Italic")) break :blk "i";
                if (std.ascii.eqlIgnoreCase(name, "ListItem")) break :blk "li";
                if (std.ascii.eqlIgnoreCase(name, "OrderedList")) break :blk "ol";
                if (std.ascii.eqlIgnoreCase(name, "Paragraph")) break :blk "p";
                if (std.ascii.eqlIgnoreCase(name, "Strikethrough")) break :blk "s";
                if (std.ascii.eqlIgnoreCase(name, "Underline")) break :blk "u";
                if (std.ascii.eqlIgnoreCase(name, "UnorderedList")) break :blk "ul";
                break :blk null;
            },
            else => null,
        };
    }

    fn is_connect_api_hashtag_char(ch: u8) bool {
        return std.ascii.isAlphanumeric(ch) or ch == '_';
    }

    fn is_connect_api_whitespace(ch: u8) bool {
        return ch == ' ' or ch == '\t' or ch == '\n' or ch == '\r';
    }

    fn is_connect_api_mention_id(self: *Evaluator, record_id: []const u8) bool {
        _ = self;
        if (record_id.len != 15 and record_id.len != 18) return false;
        for (record_id) |ch| {
            if (!std.ascii.isAlphanumeric(ch)) return false;
        }
        if (std.mem.startsWith(u8, record_id, "005")) return true;
        if (std.mem.startsWith(u8, record_id, "00G")) return true;
        if (std.mem.startsWith(u8, record_id, "0F9")) return true;
        return false;
    }

    fn connect_api_class_name_equals(class_name: []const u8, simple_name: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(class_name, simple_name)) return true;
        if (std.mem.lastIndexOfScalar(u8, class_name, '.')) |dot| {
            return std.ascii.eqlIgnoreCase(class_name[dot + 1 ..], simple_name);
        }
        return false;
    }

    fn connect_api_append_output_segment(
        self: *Evaluator,
        segments: *types.ListValue,
        segment: *types.ObjectInstance,
    ) !void {
        try segments.items.append(self.arena, Value{ .object = segment });
    }

    fn connect_api_append_text_segment(
        self: *Evaluator,
        segments: *types.ListValue,
        text: []const u8,
    ) !void {
        if (text.len == 0) return;
        const segment = try self.connect_api_create_object("ConnectApi.TextSegment");
        try segment.fields.put(self.arena, "text", Value{ .string = text });
        try self.connect_api_append_output_segment(segments, segment);
    }

    fn connect_api_append_parsed_text(
        self: *Evaluator,
        segments: *types.ListValue,
        text: []const u8,
    ) !void {
        var text_start: usize = 0;
        var i: usize = 0;
        while (i < text.len) {
            const is_http = std.mem.startsWith(u8, text[i..], "http://") or
                std.mem.startsWith(u8, text[i..], "https://");
            if (is_http) {
                try self.connect_api_append_text_segment(segments, text[text_start..i]);
                var end = i;
                while (end < text.len and !is_connect_api_whitespace(text[end])) : (end += 1) {}
                const link = try self.connect_api_create_object("ConnectApi.LinkSegment");
                try link.fields.put(self.arena, "url", Value{ .string = text[i..end] });
                try self.connect_api_append_output_segment(segments, link);
                i = end;
                text_start = end;
                continue;
            }

            if (text[i] == '#' and i + 1 < text.len and is_connect_api_hashtag_char(text[i + 1])) {
                try self.connect_api_append_text_segment(segments, text[text_start..i]);
                var end = i + 1;
                while (end < text.len and is_connect_api_hashtag_char(text[end])) : (end += 1) {}
                const hashtag = try self.connect_api_create_object("ConnectApi.HashtagSegment");
                try hashtag.fields.put(self.arena, "tag", Value{ .string = text[i + 1 .. end] });
                try self.connect_api_append_output_segment(segments, hashtag);
                i = end;
                text_start = end;
                continue;
            }

            i += 1;
        }

        try self.connect_api_append_text_segment(segments, text[text_start..]);
    }

    fn connect_api_build_output_segments(
        self: *Evaluator,
        message_segments: Value,
    ) !*types.ListValue {
        const output = try self.arena.create(types.ListValue);
        output.* = .{};
        if (message_segments != .list) return output;

        for (message_segments.list.items.items) |segment_input| {
            if (segment_input != .object) continue;
            const class_name = segment_input.object.class_name;

            if (connect_api_class_name_equals(class_name, "TextSegmentInput")) {
                const text = utils.sobject_get(
                    &segment_input.object.fields,
                    "text",
                ) orelse Value.null_val;
                if (text == .string) try self.connect_api_append_parsed_text(output, text.string);
                continue;
            }

            try self.connect_api_append_non_text_segment_input(
                output,
                segment_input.object,
                class_name,
            );
        }

        return output;
    }

    fn connect_api_append_non_text_segment_input(
        self: *Evaluator,
        output: *types.ListValue,
        input: *types.ObjectInstance,
        class_name: []const u8,
    ) !void {
        if (connect_api_class_name_equals(class_name, "MentionSegmentInput")) {
            try self.connect_api_append_mention_segment_input(output, input);
            return;
        }

        if (connect_api_class_name_equals(class_name, "LinkSegmentInput")) {
            const url = utils.sobject_get(&input.fields, "url") orelse Value.null_val;
            if (url == .string) {
                const link = try self.connect_api_create_object("ConnectApi.LinkSegment");
                try link.fields.put(self.arena, "url", url);
                try self.connect_api_append_output_segment(output, link);
            }
            return;
        }

        if (connect_api_class_name_equals(class_name, "HashtagSegmentInput")) {
            const tag = utils.sobject_get(&input.fields, "tag") orelse Value.null_val;
            if (tag == .string) {
                const hashtag = try self.connect_api_create_object("ConnectApi.HashtagSegment");
                try hashtag.fields.put(self.arena, "tag", tag);
                try self.connect_api_append_output_segment(output, hashtag);
            }
            return;
        }

        if (connect_api_class_name_equals(class_name, "MarkupBeginSegmentInput")) {
            try self.connect_api_append_markup_segment_input(
                output,
                input,
                "ConnectApi.MarkupBeginSegment",
            );
            return;
        }

        if (connect_api_class_name_equals(class_name, "MarkupEndSegmentInput")) {
            try self.connect_api_append_markup_segment_input(
                output,
                input,
                "ConnectApi.MarkupEndSegment",
            );
            return;
        }

        if (connect_api_class_name_equals(class_name, "EntityLinkSegmentInput")) {
            const entity = try self.connect_api_create_object("ConnectApi.EntityLinkSegment");
            if (utils.sobject_get(&input.fields, "entityId")) |entity_id| {
                try entity.fields.put(self.arena, "record", entity_id);
            }
            try self.connect_api_append_output_segment(output, entity);
            return;
        }

        if (connect_api_class_name_equals(class_name, "InlineImageSegmentInput")) {
            try self.connect_api_append_inline_image_segment_input(output, input);
        }
    }

    fn connect_api_append_mention_segment_input(
        self: *Evaluator,
        output: *types.ListValue,
        input: *types.ObjectInstance,
    ) !void {
        const mention_id = utils.sobject_get(&input.fields, "id") orelse Value.null_val;
        if (mention_id != .string) return;
        if (!self.is_connect_api_mention_id(mention_id.string)) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "ConnectApi.ConnectApiException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "Only user and group IDs may be used in inline mentions." },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        const mention = try self.connect_api_create_object("ConnectApi.MentionSegment");
        try mention.fields.put(
            self.arena,
            "record",
            try self.connect_api_create_record_ref(mention_id.string),
        );
        try self.connect_api_append_output_segment(output, mention);
    }

    fn connect_api_append_markup_segment_input(
        self: *Evaluator,
        output: *types.ListValue,
        input: *types.ObjectInstance,
        output_class_name: []const u8,
    ) !void {
        const markup = try self.connect_api_create_object(output_class_name);
        if (utils.sobject_get(&input.fields, "markupType")) |markup_type| {
            try markup.fields.put(self.arena, "markupType", markup_type);
        }
        try self.connect_api_append_output_segment(output, markup);
    }

    fn connect_api_append_inline_image_segment_input(
        self: *Evaluator,
        output: *types.ListValue,
        input: *types.ObjectInstance,
    ) !void {
        const image = try self.connect_api_create_object("ConnectApi.InlineImageSegment");
        const thumbnails = try self.connect_api_create_object("ConnectApi.InlineImageThumbnails");
        if (utils.sobject_get(&input.fields, "fileId")) |file_id| {
            try thumbnails.fields.put(self.arena, "fileId", file_id);
        }
        try image.fields.put(self.arena, "thumbnails", Value{ .object = thumbnails });
        if (utils.sobject_get(&input.fields, "altText")) |alt_text| {
            try image.fields.put(self.arena, "altText", alt_text);
        }
        try self.connect_api_append_output_segment(output, image);
    }

    fn connect_api_render_body_text(
        self: *Evaluator,
        output_segments: *types.ListValue,
    ) ![]const u8 {
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        for (output_segments.items.items) |segment| {
            if (segment != .object) continue;
            const class_name = segment.object.class_name;
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.TextSegment")) {
                if (utils.sobject_get(&segment.object.fields, "text")) |text| {
                    if (text == .string) try buf.appendSlice(self.arena, text.string);
                }
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.LinkSegment")) {
                if (utils.sobject_get(&segment.object.fields, "url")) |url| {
                    if (url == .string) try buf.appendSlice(self.arena, url.string);
                }
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.HashtagSegment")) {
                if (utils.sobject_get(&segment.object.fields, "tag")) |tag| {
                    if (tag == .string) {
                        try buf.append(self.arena, '#');
                        try buf.appendSlice(self.arena, tag.string);
                    }
                }
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.MentionSegment")) {
                if (utils.sobject_get(&segment.object.fields, "record")) |record| {
                    if (record == .object) {
                        if (utils.sobject_get(&record.object.fields, "id")) |record_id| {
                            if (record_id == .string) {
                                try buf.append(self.arena, '{');
                                try buf.appendSlice(self.arena, record_id.string);
                                try buf.append(self.arena, '}');
                            }
                        }
                    }
                }
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.MarkupBeginSegment") or
                std.ascii.eqlIgnoreCase(class_name, "ConnectApi.MarkupEndSegment"))
            {
                try append_connect_api_markup_tag(self.arena, &buf, segment.object, class_name);
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.InlineImageSegment")) {
                try append_connect_api_inline_image(self.arena, &buf, segment.object);
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.EntityLinkSegment")) {
                if (utils.sobject_get(&segment.object.fields, "text")) |text| {
                    if (text == .string) try buf.appendSlice(self.arena, text.string);
                }
            }
        }
        return buf.items;
    }

    /// `connect_api_render_body_text` の MarkupBegin/End 分岐。
    /// `<tag>` / `</tag>` を buffer に追記する。
    fn append_connect_api_markup_tag(
        arena: std.mem.Allocator,
        buf: *std.ArrayListUnmanaged(u8),
        obj: *types.ObjectInstance,
        class_name: []const u8,
    ) !void {
        const markup_type = utils.sobject_get(&obj.fields, "markupType") orelse Value.null_val;
        const tag_name = connect_api_markup_tag(markup_type) orelse return;
        if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.MarkupBeginSegment")) {
            try buf.appendSlice(arena, "<");
            try buf.appendSlice(arena, tag_name);
            try buf.appendSlice(arena, ">");
        } else {
            try buf.appendSlice(arena, "</");
            try buf.appendSlice(arena, tag_name);
            try buf.appendSlice(arena, ">");
        }
    }

    /// `connect_api_render_body_text` の InlineImage 分岐。
    /// `thumbnails.fileId` が文字列なら `"image: <id>"` を buffer に追記。
    fn append_connect_api_inline_image(
        arena: std.mem.Allocator,
        buf: *std.ArrayListUnmanaged(u8),
        obj: *types.ObjectInstance,
    ) !void {
        const thumbs = utils.sobject_get(&obj.fields, "thumbnails") orelse return;
        if (thumbs != .object) return;
        const file_id = utils.sobject_get(&thumbs.object.fields, "fileId") orelse return;
        if (file_id != .string) return;
        try buf.appendSlice(arena, "image: ");
        try buf.appendSlice(arena, file_id.string);
    }

    fn connect_api_extract_message_segments(
        self: *Evaluator,
        value: Value,
        depth: u8,
    ) ?Value {
        if (depth == 0) return null;
        switch (value) {
            .list => return value,
            .object => |obj| {
                if (utils.sobject_get(&obj.fields, "messageSegments")) |segments| {
                    if (segments == .list) return segments;
                }
                for (obj.fields.values()) |field_value| {
                    if (self.connect_api_extract_message_segments(
                        field_value,
                        depth - 1,
                    )) |segments| {
                        return segments;
                    }
                }
                return null;
            },
            else => return null,
        }
    }

    fn connect_api_create_feed_body(self: *Evaluator, message_segments: Value) !Value {
        const output_segments = try self.connect_api_build_output_segments(message_segments);
        const body_text = try self.connect_api_render_body_text(output_segments);
        const body = try self.connect_api_create_object("ConnectApi.FeedBody");
        try body.fields.put(self.arena, "messageSegments", Value{ .list = output_segments });
        try body.fields.put(self.arena, "text", Value{ .string = body_text });
        return Value{ .object = body };
    }

    fn connect_api_persist_feed_item(
        self: *Evaluator,
        parent_id: Value,
        body_value: Value,
    ) ![]const u8 {
        const feed_item = try self.arena.create(types.SObject);
        feed_item.* = .{ .type_name = "FeedItem" };
        if (parent_id == .string) {
            try feed_item.fields.put(self.arena, "ParentId", parent_id);
        } else if (parent_id != .null_val) {
            try feed_item.fields.put(
                self.arena,
                "ParentId",
                Value{ .string = try utils.coerce_to_string(parent_id, self.arena) },
            );
        }
        if (body_value == .object) {
            if (utils.sobject_get(&body_value.object.fields, "text")) |body_text| {
                if (body_text == .string) {
                    try feed_item.fields.put(self.arena, "Body", body_text);
                }
            }
        }
        try self.insert_record(feed_item);
        return feed_item.id orelse "";
    }

    fn handle_connect_api_namespace(
        self: *Evaluator,
        namespace: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (!self.see_all_data) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "UnsupportedOperationException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "ConnectApi is not supported in data-siloed tests" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }

        if (!std.ascii.eqlIgnoreCase(namespace, "ChatterFeeds")) return Value.null_val;

        if (std.ascii.eqlIgnoreCase(method, "postFeedElement")) {
            var subject_id: Value = Value.null_val;
            var message_segments: Value = Value.null_val;

            if (args.len >= 2 and args[1] == .object) {
                subject_id = utils.sobject_get(&args[1].object.fields, "subjectId") orelse
                    Value.null_val;
                message_segments = self.connect_api_extract_message_segments(args[1], 4) orelse
                    Value.null_val;
            } else if (args.len >= 4) {
                subject_id = args[1];
                const text_segments = try self.arena.create(types.ListValue);
                text_segments.* = .{};
                const text_segment = try self.connect_api_create_object(
                    "ConnectApi.TextSegmentInput",
                );
                const text_value = switch (args[3]) {
                    .string => args[3].string,
                    else => try utils.coerce_to_string(args[3], self.arena),
                };
                try text_segment.fields.put(self.arena, "text", Value{ .string = text_value });
                try text_segments.items.append(self.arena, Value{ .object = text_segment });
                message_segments = Value{ .list = text_segments };
            }

            const body_value = try self.connect_api_create_feed_body(message_segments);
            const feed_id = try self.connect_api_persist_feed_item(subject_id, body_value);
            const feed_element = try self.connect_api_create_object("ConnectApi.FeedElement");
            try feed_element.fields.put(self.arena, "id", Value{ .string = feed_id });
            try feed_element.fields.put(self.arena, "body", body_value);
            return Value{ .object = feed_element };
        }

        if (std.ascii.eqlIgnoreCase(method, "postCommentToFeedElement")) {
            var message_segments: Value = Value.null_val;
            if (args.len >= 3 and args[2] == .object) {
                message_segments = self.connect_api_extract_message_segments(
                    args[2],
                    4,
                ) orelse Value.null_val;
            }
            const body_value = try self.connect_api_create_feed_body(message_segments);
            const comment = try self.connect_api_create_object("ConnectApi.Comment");
            try comment.fields.put(self.arena, "id", Value{ .string = try self.alloc_id() });
            try comment.fields.put(self.arena, "body", body_value);
            return Value{ .object = comment };
        }

        return Value.null_val;
    }

    fn eval_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!Value {
        if (obj == .null_val) {
            return try self.eval_null_instance_method(method);
        }
        if (try self.eval_search_object_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_primitive_scalar_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_http_send_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_type_instance_method(obj, method)) |result| return result;
        if (try self.eval_apex_mocks_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_datacloud_instance_method(obj, method)) |result| return result;
        if (try self.eval_stub_provider_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_json_parser_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_metadata_framework_instance_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_npsp_crlp_rollup_metadata_handler_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_fflib_dynamic_domain_factory_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_install_context_instance_method(obj, method)) |result| return result;
        if (try self.eval_version_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_npsp_rd2_status_mapper_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_npsp_record_currency_code_method(obj, method)) |result| {
            return result;
        }
        if (try self.eval_npsp_rd2_pause_schedule_handler_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_npsp_rd2_status_automation_service_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_npsp_rd2_settings_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_npsp_opp_rollup_instance_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_npsp_hh_households_tdtm_instance_method(obj, method, args, current_env)) |result| {
            return result;
        }
        if (try self.eval_npsp_deceased_batch_instance_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_npsp_household_naming_service_instance_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_npsp_rd2_sustainer_evaluation_service_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_npsp_rd2_data_migration_mapper_method(obj, method)) |result| {
            return result;
        }
        if (try self.eval_npsp_bdi_migration_mapping_helper_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_npsp_callable_api_parameters_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_time_instance_method(obj, method)) |result| return result;
        if (try self.eval_date_like_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_field_expression_matching_method(obj, method, args)) |result| {
            return result;
        }
        if (try self.eval_user_defined_object_instance_method(
            obj,
            method,
            args,
            current_env,
        )) |result| {
            return try self.postprocess_user_defined_instance_result(obj, method, result);
        }
        if (try self.eval_builtin_instance_dispatch(obj, method, args)) |result| return result;
        if (try self.eval_s_object_instance_method(obj, method, args)) |result| return result;
        if (try self.eval_collection_or_string_instance_method(obj, method, args)) |result| {
            return result;
        }
        return try self.eval_object_class_instance_method(obj, method, args);
    }

    fn eval_null_instance_method(self: *Evaluator, method: []const u8) anyerror!Value {
        if (!self.fixture_relaxed_exceptions) {
            try self.throw_null_pointer_exception();
            return error.ApexException;
        }
        if (self.call_stack_contains_apex_frame("fflib_Criteria", "evaluateFormula") and
            null_receiver_null_method(method))
        {
            return try self.throw_relaxed_null_pointer_exception();
        }
        if (null_receiver_null_method(method)) return Value.null_val;
        if (std.ascii.eqlIgnoreCase(method, "getMessage")) return Value{ .string = "" };
        if (std.ascii.eqlIgnoreCase(method, "isSuccess")) return Value{ .boolean = true };
        if (std.ascii.eqlIgnoreCase(method, "setScale")) return Value{ .integer = 0 };
        if (null_receiver_date_method(method)) {
            return try builtins.make_date_value(self.arena, "2026-01-01");
        }
        if (null_receiver_void_method(method)) return Value.void_val;
        if (std.ascii.eqlIgnoreCase(method, "newInstance")) {
            const obj_inst = try self.arena.create(types.ObjectInstance);
            obj_inst.* = .{ .class_name = "Object" };
            return Value{ .object = obj_inst };
        }
        if (std.ascii.startsWithIgnoreCase(method, "with")) return Value.null_val;
        if (std.ascii.eqlIgnoreCase(method, "build")) return try self.empty_opportunity_value();
        if (std.ascii.eqlIgnoreCase(method, "getRecords")) return try self.alloc_empty_list_value();
        if (null_receiver_boolean_string_method(method)) return Value{ .boolean = false };
        return Value.null_val;
    }

    fn throw_relaxed_null_pointer_exception(self: *Evaluator) !Value {
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.NullPointerException" };
        try exc.fields.put(self.arena, "message", Value{
            .string = "Attempt to de-reference a null object",
        });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn empty_opportunity_value(self: *Evaluator) !Value {
        const sob = try self.arena.create(types.SObject);
        sob.* = .{ .type_name = "Opportunity" };
        try sob.fields.put(self.arena, "Name", Value{ .string = "Mock Opportunity" });
        try sob.fields.put(self.arena, "StageName", Value{ .string = "Prospecting" });
        try sob.fields.put(self.arena, "CloseDate", Value{ .string = "2026-01-01" });
        return Value{ .sobject = sob };
    }

    fn null_receiver_null_method(method: []const u8) bool {
        return std.ascii.eqlIgnoreCase(method, "get") or
            std.ascii.eqlIgnoreCase(method, "getSObject") or
            std.ascii.eqlIgnoreCase(method, "getSObjects");
    }

    fn null_receiver_date_method(method: []const u8) bool {
        return std.ascii.eqlIgnoreCase(method, "addDays") or
            std.ascii.eqlIgnoreCase(method, "addMonths") or
            std.ascii.eqlIgnoreCase(method, "addYears");
    }

    fn null_receiver_void_method(method: []const u8) bool {
        return std.ascii.eqlIgnoreCase(method, "add") or
            std.ascii.eqlIgnoreCase(method, "addAll") or
            std.ascii.eqlIgnoreCase(method, "put");
    }

