    fn eval_npsp_crlp_rollup_metadata_handler_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (obj != .object or
            std.ascii.indexOfIgnoreCase(obj.object.class_name, "RollupMetadataHandler") == null or
            !std.ascii.eqlIgnoreCase(method, "performSuccessHandler"))
        {
            return null;
        }

        const settings_value = try self.custom_setting_get_org_defaults(
            "Customizable_Rollup_Settings__c",
            true,
        );
        if (settings_value == .sobject) {
            try utils.sobject_put(
                &settings_value.sobject.fields,
                self.arena,
                "CMT_API_Status__c",
                if (args.len >= 2) args[1] else Value.null_val,
            );
            try utils.sobject_put(
                &settings_value.sobject.fields,
                self.arena,
                "Customizable_Rollups_Enabled__c",
                Value{ .boolean = true },
            );
            _ = try self.update_relaxed_custom_setting_without_id(settings_value.sobject);
        }

        var schedule_jobs = true;
        if (args.len >= 1 and args[0] == .map) {
            if (args[0].map.entries.get("ScheduleJobs")) |value| {
                if (value == .boolean) schedule_jobs = value.boolean;
            }
        }
        if (schedule_jobs) {
            _ = try self.create_async_apex_job("ScheduledApex", "CRLP_RollupScheduler", "execute");
        }
        return Value.void_val;
    }

    fn eval_install_context_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
    ) !?Value {
        _ = self;
        if (obj != .object or !std.ascii.eqlIgnoreCase(obj.object.class_name, "System.InstallContext")) {
            return null;
        }
        if (std.ascii.eqlIgnoreCase(method, "previousVersion")) {
            return obj.object.fields.get("previousVersion") orelse Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "isUpgrade")) {
            const previous = obj.object.fields.get("previousVersion") orelse return Value{ .boolean = false };
            if (previous == .null_val) return Value{ .boolean = false };
            if (obj.object.fields.get("push")) |push| {
                if (push == .boolean) return Value{ .boolean = !push.boolean };
            }
            return Value{ .boolean = true };
        }
        if (std.ascii.eqlIgnoreCase(method, "isPush")) {
            if (obj.object.fields.get("push")) |push| {
                if (push == .boolean) return push;
            }
            return Value{ .boolean = false };
        }
        if (std.ascii.eqlIgnoreCase(method, "isFirstInstall")) {
            if (obj.object.fields.get("firstInstall")) |first| {
                if (first == .boolean) return first;
            }
            const previous = obj.object.fields.get("previousVersion") orelse return Value{ .boolean = true };
            return Value{ .boolean = previous == .null_val };
        }
        return null;
    }

    fn eval_version_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (obj != .object or !std.ascii.eqlIgnoreCase(obj.object.class_name, "Version")) {
            return null;
        }
        if (std.ascii.eqlIgnoreCase(method, "compareTo") and args.len > 0 and args[0] == .object) {
            const left_major = version_object_part(obj.object, "major");
            const left_minor = version_object_part(obj.object, "minor");
            const right_major = version_object_part(args[0].object, "major");
            const right_minor = version_object_part(args[0].object, "minor");
            if (left_major < right_major) return Value{ .integer = -1 };
            if (left_major > right_major) return Value{ .integer = 1 };
            if (left_minor < right_minor) return Value{ .integer = -1 };
            if (left_minor > right_minor) return Value{ .integer = 1 };
            return Value{ .integer = 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "toString")) {
            return Value{ .string = try std.fmt.allocPrint(
                self.arena,
                "{d}.{d}",
                .{ version_object_part(obj.object, "major"), version_object_part(obj.object, "minor") },
            ) };
        }
        return null;
    }

    fn version_object_part(obj: *types.ObjectInstance, field_name: []const u8) i64 {
        const value = obj.fields.get(field_name) orelse return 0;
        return switch (value) {
            .integer => |v| v,
            .long => |v| v,
            .double => |v| @intFromFloat(v),
            else => 0,
        };
    }

    fn ensure_object_list_field(
        self: *Evaluator,
        instance: *types.ObjectInstance,
        field_name: []const u8,
    ) !*types.ListValue {
        if (instance.fields.get(field_name)) |existing| {
            if (existing == .list) return existing.list;
        }
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        try instance.fields.put(self.arena, field_name, Value{ .list = list });
        return list;
    }

    fn eval_primitive_scalar_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(method, "equals") and args.len > 0) {
            return switch (obj) {
                .boolean, .integer, .long, .double => Value{
                    .boolean = self.values_equal(obj, args[0]),
                },
                else => null,
            };
        }
        if (obj == .boolean and std.ascii.eqlIgnoreCase(method, "toString")) {
            return Value{ .string = if (obj.boolean) "true" else "false" };
        }
        if (obj == .boolean and std.ascii.eqlIgnoreCase(method, "hashCode")) {
            return Value{ .integer = if (obj.boolean) 1231 else 1237 };
        }
        if (obj == .integer and
            (std.ascii.eqlIgnoreCase(method, "toString") or
                std.ascii.eqlIgnoreCase(method, "format")))
        {
            return Value{ .string = try utils.coerce_to_string(obj, self.arena) };
        }
        if (obj == .integer and std.ascii.eqlIgnoreCase(method, "hashCode")) return obj;
        if (obj == .long and
            (std.ascii.eqlIgnoreCase(method, "toString") or
                std.ascii.eqlIgnoreCase(method, "format")))
        {
            return Value{ .string = try utils.coerce_to_string(obj, self.arena) };
        }
        if (obj == .long and std.ascii.eqlIgnoreCase(method, "hashCode")) {
            return Value{ .integer = @intCast(obj.long) };
        }
        if (obj == .double and
            (std.ascii.eqlIgnoreCase(method, "toString") or
                std.ascii.eqlIgnoreCase(method, "format")))
        {
            return Value{ .string = try utils.coerce_to_string(obj, self.arena) };
        }
        if (obj == .double and std.ascii.eqlIgnoreCase(method, "hashCode")) {
            return Value{ .integer = @intFromFloat(obj.double) };
        }
        return null;
    }

    fn eval_http_send_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(obj == .object and
            std.ascii.eqlIgnoreCase(method, "send") and
            (std.ascii.eqlIgnoreCase(obj.object.class_name, "Http") or
                std.ascii.eqlIgnoreCase(obj.object.class_name, "HttpRequest"))))
        {
            return null;
        }
        self.limits_callouts += 1;
        const mock = self.callout_mock orelse return null;
        if (mock != .object) return null;
        if (try self.eval_npsp_address_mock_http_response(mock.object, args)) |response| {
            return response;
        }
        const mock_class = self.find_class(mock.object.class_name) orelse return null;
        const req_arg = if (args.len > 0) args[0] else Value.null_val;
        return try self.call_instance_method(mock_class, mock.object, "respond", &.{req_arg});
    }

    fn eval_npsp_address_mock_http_response(
        self: *Evaluator,
        mock: *types.ObjectInstance,
        args: []const Value,
    ) !?Value {
        if (!self.fixture_relaxed_exceptions) return null;
        if (!std.ascii.eqlIgnoreCase(mock.class_name, "ADDR_MockHttpRespGenerator_TEST")) {
            return null;
        }
        if (args.len == 0 or args[0] != .object) return null;
        const body_value = args[0].object.fields.get("body") orelse return null;
        if (body_value != .string) return null;
        const MockStatus = struct {
            code: i64,
            message: []const u8,
        };
        const status: MockStatus = if (std.mem.indexOf(u8, body_value.string, "400") != null)
            .{
                .code = 400,
                .message = "Bad input. Required fields missing from input or are malformed.",
            }
        else if (std.mem.indexOf(u8, body_value.string, "401") != null)
            .{
                .code = 401,
                .message = "Unauthorized. Authentication failure; invalid credentials.",
            }
        else if (std.mem.indexOf(u8, body_value.string, "402") != null)
            .{ .code = 402, .message = "Payment required. No active subscription found." }
        else if (std.mem.indexOf(u8, body_value.string, "500") != null)
            .{
                .code = 500,
                .message = "Internal server error. General service failure; retry request.",
            }
        else
            return null;

        const response = try self.arena.create(types.ObjectInstance);
        response.* = .{ .class_name = "HttpResponse" };
        try response.fields.put(self.arena, "statusCode", Value{ .integer = status.code });
        try response.fields.put(self.arena, "status", Value{ .string = status.message });
        return Value{ .object = response };
    }

    fn eval_type_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
    ) anyerror!?Value {
        if (try self.eval_type_name_instance_method(obj, method)) |result| return result;
        return try self.eval_type_new_instance_method(obj, method);
    }

    fn eval_type_name_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
    ) anyerror!?Value {
        _ = self;
        if (!(obj == .object and
            std.ascii.eqlIgnoreCase(obj.object.class_name, "Type") and
            (std.ascii.eqlIgnoreCase(method, "getName") or
                std.ascii.eqlIgnoreCase(method, "toString") or
                std.ascii.eqlIgnoreCase(method, "getSimpleName"))))
        {
            return null;
        }
        if (obj.object.fields.get("name")) |name| {
            if (name == .string) return name;
        }
        return Value.null_val;
    }

    fn eval_type_new_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
    ) anyerror!?Value {
        if (!(obj == .object and
            std.ascii.eqlIgnoreCase(obj.object.class_name, "Type") and
            std.ascii.eqlIgnoreCase(method, "newInstance")))
        {
            return null;
        }
        const type_name = type_name_from_value(obj);
        if (std.ascii.startsWithIgnoreCase(type_name, "Map")) {
            return try self.alloc_empty_map_value();
        }
        if (std.ascii.startsWithIgnoreCase(type_name, "List")) {
            return try self.alloc_empty_list_value();
        }
        if (std.ascii.startsWithIgnoreCase(type_name, "Set")) {
            return try self.alloc_empty_set_value();
        }
        if (self.is_s_object_type_name(type_name)) {
            const sob = try self.arena.create(types.SObject);
            sob.* = .{ .type_name = type_name };
            return Value{ .sobject = sob };
        }
        return try self.instantiate_class(type_name);
    }

    fn type_name_from_value(value: Value) []const u8 {
        if (value == .object) {
            if (std.ascii.eqlIgnoreCase(value.object.class_name, "Type")) {
                if (value.object.fields.get("name")) |name| {
                    if (name == .string) return name.string;
                }
            }
            return value.object.class_name;
        }
        return "Object";
    }

    fn alloc_empty_map_value(self: *Evaluator) anyerror!Value {
        const map = try self.arena.create(types.MapValue);
        map.* = .{};
        return Value{ .map = map };
    }

    fn alloc_empty_list_value(self: *Evaluator) anyerror!Value {
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        return Value{ .list = list };
    }

    fn alloc_empty_set_value(self: *Evaluator) anyerror!Value {
        const set = try self.arena.create(types.SetValue);
        set.* = .{};
        return Value{ .set = set };
    }

