    fn eval_fflib_dynamic_domain_factory_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (obj != .object or
            !std.ascii.eqlIgnoreCase(obj.object.class_name, "fflib_DynamicDomainFactory"))
        {
            return null;
        }
        if (std.ascii.eqlIgnoreCase(method, "setMock") and args.len >= 1) {
            const domain_type = if (args.len >= 2)
                args[0]
            else
                try self.eval_instance_method(args[0], "getType", &.{}, self.global_env);
            const mock_value = if (args.len >= 2) args[1] else args[0];
            try self.fflib_dynamic_factory_put_mock(obj.object, domain_type, mock_value);
            return Value.void_val;
        }
        if (!std.ascii.eqlIgnoreCase(method, "newInstance") or args.len == 0) return null;

        const object_type = if (args.len >= 2)
            args[1]
        else
            try self.fflib_domain_object_type_from_records_arg(args[0]);
        if (try self.fflib_dynamic_factory_get_mock(obj.object, object_type)) |mock| return mock;

        const records = try self.fflib_domain_records_from_arg(args[0], object_type);
        return try self.make_fflib_sobjects_domain(records, object_type);
    }

    fn fflib_domain_object_type_from_records_arg(self: *Evaluator, arg: Value) !Value {
        if (arg == .list) return try self.eval_list_s_object_type(arg.list);
        if (arg == .set) {
            for (arg.set.entries.values()) |item| {
                if (item == .string) {
                    const type_name = self.find_record_type_by_id(item.string) orelse
                        sobject_type_from_prefix(if (item.string.len >= 3) item.string[0..3] else item.string);
                    return try self.schema_s_object_type_value(type_name);
                }
            }
        }
        return Value.null_val;
    }

    fn fflib_domain_records_from_arg(self: *Evaluator, arg: Value, object_type: Value) !*types.ListValue {
        if (arg == .list) return arg.list;
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        const type_name = self.schema_object_type_name_from_value(object_type) orelse "SObject";
        if (arg == .set) {
            for (arg.set.entries.values()) |item| {
                if (item != .string) continue;
                const sob = try self.arena.create(types.SObject);
                sob.* = .{ .type_name = type_name, .id = item.string };
                try sob.fields.put(self.arena, "Id", item);
                try list.items.append(self.arena, Value{ .sobject = sob });
            }
        }
        return list;
    }

    fn schema_object_type_name_from_value(_: *Evaluator, object_type: Value) ?[]const u8 {
        if (object_type == .object and
            std.ascii.eqlIgnoreCase(object_type.object.class_name, "Schema.SObjectType"))
        {
            const name = object_type.object.fields.get("name") orelse return null;
            if (name == .string) return name.string;
        }
        return null;
    }

    fn make_fflib_sobjects_domain(
        self: *Evaluator,
        records: *types.ListValue,
        object_type: Value,
    ) !Value {
        const domain = try self.arena.create(types.ObjectInstance);
        domain.* = .{ .class_name = "fflib_SObjects" };
        try domain.fields.put(self.arena, "objects", Value{ .list = records });
        const type_name = self.schema_object_type_name_from_value(object_type) orelse blk: {
            if (records.items.items.len > 0 and records.items.items[0] == .sobject) {
                break :blk records.items.items[0].sobject.type_name;
            }
            break :blk "SObject";
        };
        const describe = try self.arena.create(types.ObjectInstance);
        describe.* = .{ .class_name = "DescribeSObjectResult" };
        try describe.fields.put(self.arena, "name", Value{ .string = type_name });
        try domain.fields.put(self.arena, "SObjectDescribe", Value{ .object = describe });
        return Value{ .object = domain };
    }

    fn fflib_dynamic_factory_mock_map(self: *Evaluator, factory: *types.ObjectInstance) !*types.MapValue {
        if (factory.fields.get("mockImplByObjectType")) |existing| {
            if (existing == .map) return existing.map;
        }
        const map = try self.arena.create(types.MapValue);
        map.* = .{};
        try factory.fields.put(self.arena, "mockImplByObjectType", Value{ .map = map });
        return map;
    }

    fn fflib_dynamic_factory_put_mock(
        self: *Evaluator,
        factory: *types.ObjectInstance,
        object_type: Value,
        mock_value: Value,
    ) !void {
        const map = try self.fflib_dynamic_factory_mock_map(factory);
        _ = try self.eval_map_method(map, "put", &.{ object_type, mock_value });
    }

    fn fflib_dynamic_factory_get_mock(
        self: *Evaluator,
        factory: *types.ObjectInstance,
        object_type: Value,
    ) !?Value {
        const map = try self.fflib_dynamic_factory_mock_map(factory);
        if (!self.eval_map_contains_key(map, object_type)) return null;
        return try self.eval_map_get(map, object_type);
    }

    fn eval_stub_provider_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (obj != .object) return null;
        const provider = obj.object.fields.get("__stubProvider__") orelse return null;
        if (provider != .object) return null;
        const provider_class = self.find_class(provider.object.class_name) orelse return null;
        const stub_method = self.resolve_stub_provider_method_decl(
            obj.object.class_name,
            method,
            args,
        );
        if (stub_uses_default_object_method(method, args.len) and stub_method == null) {
            return null;
        }
        const handle_args = try self.build_stub_provider_handle_method_args(
            obj,
            method,
            args,
            stub_method,
        );
        return try self.call_instance_method(
            provider_class,
            provider.object,
            "handleMethodCall",
            &handle_args,
        );
    }

    fn resolve_stub_provider_method_decl(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) ?*ast.MethodDecl {
        const stub_class = self.find_class(class_name) orelse return null;
        return self.find_method_in_hierarchy_typed(null, stub_class, method, args) orelse
            self.find_method_in_hierarchy(null, stub_class, method, args.len);
    }

    fn stub_uses_default_object_method(method: []const u8, arg_len: usize) bool {
        if (arg_len == 0) {
            return std.ascii.eqlIgnoreCase(method, "toString") or
                std.ascii.eqlIgnoreCase(method, "hashCode");
        }
        return arg_len == 1 and std.ascii.eqlIgnoreCase(method, "equals");
    }

    fn build_stub_provider_handle_method_args(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
        stub_method: ?*ast.MethodDecl,
    ) anyerror![6]Value {
        const args_list = try self.arena.create(types.ListValue);
        args_list.* = .{};
        for (args) |arg| try args_list.items.append(self.arena, arg);

        const type_list = try self.arena.create(types.ListValue);
        type_list.* = .{};
        for (args, 0..) |arg, index| {
            const type_obj = try self.arena.create(types.ObjectInstance);
            type_obj.* = .{ .class_name = "Type" };
            try type_obj.fields.put(
                self.arena,
                "name",
                Value{ .string = self.stub_provider_arg_type_name(arg, index, stub_method) },
            );
            try type_list.items.append(self.arena, Value{ .object = type_obj });
        }

        const name_list = try self.arena.create(types.ListValue);
        name_list.* = .{};
        if (stub_method) |method_decl| {
            for (method_decl.params) |param| {
                try name_list.items.append(self.arena, Value{ .string = param.name });
            }
        }

        return .{
            obj,
            Value{ .string = method },
            Value.null_val,
            Value{ .list = type_list },
            Value{ .list = name_list },
            Value{ .list = args_list },
        };
    }

    fn stub_provider_arg_type_name(
        self: *Evaluator,
        arg: Value,
        index: usize,
        stub_method: ?*ast.MethodDecl,
    ) []const u8 {
        if (stub_method) |method_decl| {
            if (index < method_decl.params.len) {
                return self.render_type_ref(method_decl.params[index].type_ref);
            }
        }
        return switch (arg) {
            .string => "String",
            .integer => "Integer",
            .double => "Double",
            .boolean => "Boolean",
            .list => "List",
            .map => "Map",
            .set => "Set",
            .sobject => "SObject",
            .object => |object| object.class_name,
            .null_val => "Object",
            else => "Object",
        };
    }

    fn eval_json_parser_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(obj == .object and
            std.ascii.eqlIgnoreCase(obj.object.class_name, "JSONParser")))
        {
            return null;
        }
        const body = json_parser_body(obj.object);
        if (std.ascii.eqlIgnoreCase(method, "nextToken")) {
            return try self.eval_json_parser_next_token(obj.object, body);
        }
        if (std.ascii.eqlIgnoreCase(method, "getCurrentToken")) {
            return obj.object.fields.get("__token__") orelse Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "getCurrentName")) {
            const token_value = obj.object.fields.get("__token__") orelse Value.null_val;
            if (token_value == .string and
                std.ascii.eqlIgnoreCase(token_value.string, "FIELD_NAME"))
            {
                return obj.object.fields.get("__text__") orelse Value.null_val;
            }
            return Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "getText")) {
            return obj.object.fields.get("__text__") orelse Value{ .string = "" };
        }
        if (std.ascii.eqlIgnoreCase(method, "getIntegerValue")) {
            const text = obj.object.fields.get("__text__") orelse return Value.null_val;
            if (text != .string) return Value.null_val;
            const parsed = std.fmt.parseInt(i64, text.string, 10) catch return Value.null_val;
            return Value{ .integer = parsed };
        }
        if (std.ascii.eqlIgnoreCase(method, "readValueAs")) {
            return try self.eval_json_parser_read_value_as(obj.object, body, args);
        }
        return null;
    }

    fn json_parser_body(parser: *types.ObjectInstance) ?[]const u8 {
        const body_value = parser.fields.get("__json_body__") orelse return null;
        return if (body_value == .string) body_value.string else null;
    }

    fn stored_json_parser_position(parser: *types.ObjectInstance, require_positive: bool) usize {
        const pos_value = parser.fields.get("__pos__") orelse return 0;
        if (pos_value != .integer) return 0;
        if (require_positive and pos_value.integer <= 0) return 0;
        return @intCast(@as(u64, @bitCast(pos_value.integer)));
    }

    fn skip_json_parser_trivia(body: []const u8, start: usize) usize {
        var pos = start;
        while (pos < body.len and
            (body[pos] == ' ' or
                body[pos] == '\t' or
                body[pos] == '\n' or
                body[pos] == '\r' or
                body[pos] == ','))
        {
            pos += 1;
        }
        return pos;
    }

    fn set_json_parser_token(
        self: *Evaluator,
        parser: *types.ObjectInstance,
        token_name: []const u8,
        text: []const u8,
    ) anyerror!void {
        try parser.fields.put(self.arena, "__token__", Value{ .string = token_name });
        try parser.fields.put(self.arena, "__text__", Value{ .string = text });
    }

    fn advance_json_parser_string_token(
        self: *Evaluator,
        parser: *types.ObjectInstance,
        body: []const u8,
        start: usize,
    ) anyerror!usize {
        var pos = start + 1;
        while (pos < body.len and body[pos] != '"') : (pos += 1) {
            if (body[pos] == '\\') pos += 1;
        }
        const text = body[start + 1 .. pos];
        if (pos < body.len) pos += 1;
        var peek = pos;
        while (peek < body.len and (body[peek] == ' ' or body[peek] == '\t')) : (peek += 1) {}
        if (peek < body.len and body[peek] == ':') {
            try self.set_json_parser_token(parser, "FIELD_NAME", text);
            return peek + 1;
        }
        try self.set_json_parser_token(parser, "VALUE_STRING", text);
        return pos;
    }

    fn advance_json_parser_boolean_token(
        self: *Evaluator,
        parser: *types.ObjectInstance,
        body: []const u8,
        start: usize,
    ) anyerror!usize {
        if (std.mem.startsWith(u8, body[start..], "true")) {
            try self.set_json_parser_token(parser, "VALUE_TRUE", "true");
            return start + 4;
        }
        try self.set_json_parser_token(parser, "VALUE_FALSE", "false");
        return start + 5;
    }

    fn advance_json_parser_number_token(
        self: *Evaluator,
        parser: *types.ObjectInstance,
        body: []const u8,
        start: usize,
    ) anyerror!usize {
        var pos = start;
        while (pos < body.len and
            (std.ascii.isDigit(body[pos]) or
                body[pos] == '.' or
                body[pos] == '-' or
                body[pos] == 'e' or
                body[pos] == 'E' or
                body[pos] == '+'))
        {
            pos += 1;
        }
        const number_text = body[start..pos];
        const token_name = if (std.mem.indexOfAny(u8, number_text, ".eE") != null)
            "VALUE_NUMBER_FLOAT"
        else
            "VALUE_NUMBER_INT";
        try self.set_json_parser_token(parser, token_name, number_text);
        return pos;
    }

    fn eval_json_parser_next_token(
        self: *Evaluator,
        parser: *types.ObjectInstance,
        body: ?[]const u8,
    ) anyerror!Value {
        const json_body = body orelse return Value.null_val;
        var pos = skip_json_parser_trivia(json_body, stored_json_parser_position(parser, false));
        if (pos >= json_body.len) {
            try parser.fields.put(self.arena, "__token__", Value.null_val);
            return Value.null_val;
        }
        switch (json_body[pos]) {
            '{' => {
                try self.set_json_parser_token(parser, "START_OBJECT", "{");
                pos += 1;
            },
            '}' => {
                try self.set_json_parser_token(parser, "END_OBJECT", "}");
                pos += 1;
            },
            '[' => {
                try self.set_json_parser_token(parser, "START_ARRAY", "[");
                pos += 1;
            },
            ']' => {
                try self.set_json_parser_token(parser, "END_ARRAY", "]");
                pos += 1;
            },
            '"' => pos = try self.advance_json_parser_string_token(parser, json_body, pos),
            't', 'f' => pos = try self.advance_json_parser_boolean_token(parser, json_body, pos),
            'n' => {
                try self.set_json_parser_token(parser, "VALUE_NULL", "null");
                pos += 4;
            },
            else => {
                if (std.ascii.isDigit(json_body[pos]) or json_body[pos] == '-') {
                    pos = try self.advance_json_parser_number_token(parser, json_body, pos);
                } else {
                    pos += 1;
                }
            },
        }
        try parser.fields.put(self.arena, "__pos__", Value{ .integer = @intCast(pos) });
        return parser.fields.get("__token__") orelse Value.null_val;
    }

    fn eval_json_parser_read_value_as(
        self: *Evaluator,
        parser: *types.ObjectInstance,
        body: ?[]const u8,
        args: []const Value,
    ) anyerror!Value {
        const json_body = body orelse return Value.null_val;
        const pos = stored_json_parser_position(parser, true);
        const start = if (pos > 0) pos - 1 else 0;
        const type_name = if (args.len >= 1) type_name_from_value(args[0]) else "Object";
        if (self.parse_json_value(json_body[start..], type_name)) |value| return value;
        return Value.null_val;
    }

    fn eval_npsp_rd2_status_mapper_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (!(obj == .object and
            std.ascii.eqlIgnoreCase(obj.object.class_name, "RD2_StatusMapper")))
        {
            return null;
        }
        if (std.ascii.eqlIgnoreCase(method, "getState")) {
            if (args.len == 0) return Value.null_val;
            if (args[0] == .null_val) return Value{ .string = "Active" };
            if (args[0] != .string) return Value.null_val;
            if (npsp_rd2_status_state(args[0].string)) |state| return Value{ .string = state };
            if (self.get_object_field_case_insensitive(obj.object, "gateway") != null or
                self.get_object_field_case_insensitive(obj.object, "statusLabelByValue") != null)
            {
                return null;
            }
            return Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "getActiveStatusValues")) {
            return try self.npsp_rd2_status_set(&.{ "Active", "Paused", "Failing" });
        }
        if (std.ascii.eqlIgnoreCase(method, "getClosedStatusValues")) {
            return try self.npsp_rd2_status_set(&.{"Closed"});
        }
        if (std.ascii.eqlIgnoreCase(method, "getLapsedStatusValues")) {
            return try self.npsp_rd2_status_set(&.{"Lapsed"});
        }
        return null;
    }

    fn npsp_rd2_status_set(self: *Evaluator, values: []const []const u8) !Value {
        const set = try self.arena.create(types.SetValue);
        set.* = .{};
        for (values) |status| {
            const value = Value{ .string = status };
            try set.entries.put(self.arena, try self.set_entry_key(value), value);
        }
        return Value{ .set = set };
    }

    fn npsp_rd2_status_state(status: []const u8) ?[]const u8 {
        if (std.ascii.eqlIgnoreCase(status, "Active")) return "Active";
        if (std.ascii.eqlIgnoreCase(status, "Paused")) return "Active";
        if (std.ascii.eqlIgnoreCase(status, "Failing")) return "Active";
        if (std.ascii.eqlIgnoreCase(status, "Lapsed")) return "Lapsed";
        if (std.ascii.eqlIgnoreCase(status, "Closed")) return "Closed";
        return null;
    }

